unsafe extern "C" fn parse_counters_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut tb: *mut *const nlattr = (data as *mut *const nlattr);
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    if (unsafe { mnl_attr_type_valid(attr, CTA_COUNTERS_MAX) }) < 0 {
        return MNL_CB_OK as i32;
    }
    match type_ {
        CTA_COUNTERS_PACKETS | CTA_COUNTERS_BYTES => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U64) }) < 0 {
                unsafe { perror(c"mnl_attr_validate".as_ptr()) };
                return MNL_CB_ERROR as i32;
            }
        }
        _ => {}
    }
    (*tb.offset(type_ as isize)) = attr;
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn parse_ip_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut tb: *mut *const nlattr = (data as *mut *const nlattr);
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    if (unsafe { mnl_attr_type_valid(attr, CTA_IP_MAX) }) < 0 {
        return MNL_CB_OK as i32;
    }
    match type_ {
        CTA_IP_V4_SRC | CTA_IP_V4_DST => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U32) }) < 0 {
                unsafe { perror(c"mnl_attr_validate".as_ptr()) };
                return MNL_CB_ERROR as i32;
            }
        }
        CTA_IP_V6_SRC | CTA_IP_V6_DST => {
            if (unsafe { mnl_attr_validate2(attr, MNL_TYPE_BINARY, core::mem::size_of::<in6_addr>()) }) < 0 {
                unsafe { perror(c"mnl_attr_validate2".as_ptr()) };
                return MNL_CB_ERROR as i32;
            }
        }
        _ => {}
    }
    (*tb.offset(type_ as isize)) = attr;
    return MNL_CB_OK as i32;
}

