unsafe extern "C" fn parse_proto_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut tb: *mut *const nlattr = (data as *mut *const nlattr);
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    if (unsafe { mnl_attr_type_valid(attr, CTA_PROTO_MAX) }) < 0 {
        return MNL_CB_OK as i32;
    }
    match type_ {
        CTA_PROTO_NUM | CTA_PROTO_ICMP_TYPE | CTA_PROTO_ICMP_CODE => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U8) }) < 0 {
                unsafe { perror(c"mnl_attr_validate".as_ptr()) };
                return MNL_CB_ERROR as i32;
            }
        }
        CTA_PROTO_SRC_PORT | CTA_PROTO_DST_PORT | CTA_PROTO_ICMP_ID => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U16) }) < 0 {
                unsafe { perror(c"mnl_attr_validate".as_ptr()) };
                return MNL_CB_ERROR as i32;
            }
        }
        _ => {}
    }
    (*tb.offset(type_ as isize)) = attr;
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn print_proto(mut nest: *const nlattr) {
    let mut tb: [*mut nlattr; 10] = [unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];
    unsafe { mnl_attr_parse_nested(nest, Some(parse_proto_cb), tb.as_mut_ptr()) };
    if !tb[CTA_PROTO_NUM as usize].is_null() {
        unsafe { printf(c"proto=%u ".as_ptr(), unsafe { mnl_attr_get_u8(tb[CTA_PROTO_NUM as usize]) }) };
    }
    if !tb[CTA_PROTO_SRC_PORT as usize].is_null() {
        unsafe { printf(c"sport=%u ".as_ptr(), (unsafe { ntohs((unsafe { mnl_attr_get_u16(tb[CTA_PROTO_SRC_PORT as usize]) }) as u16) } as i32)) };
    }
    if !tb[CTA_PROTO_DST_PORT as usize].is_null() {
        unsafe { printf(c"dport=%u ".as_ptr(), (unsafe { ntohs((unsafe { mnl_attr_get_u16(tb[CTA_PROTO_DST_PORT as usize]) }) as u16) } as i32)) };
    }
    if !tb[CTA_PROTO_ICMP_ID as usize].is_null() {
        unsafe { printf(c"id=%u ".as_ptr(), (unsafe { ntohs((unsafe { mnl_attr_get_u16(tb[CTA_PROTO_ICMP_ID as usize]) }) as u16) } as i32)) };
    }
    if !tb[CTA_PROTO_ICMP_TYPE as usize].is_null() {
        unsafe { printf(c"type=%u ".as_ptr(), unsafe { mnl_attr_get_u8(tb[CTA_PROTO_ICMP_TYPE as usize]) }) };
    }
    if !tb[CTA_PROTO_ICMP_CODE as usize].is_null() {
        unsafe { printf(c"code=%u ".as_ptr(), unsafe { mnl_attr_get_u8(tb[CTA_PROTO_ICMP_CODE as usize]) }) };
    }
}

unsafe extern "C" fn parse_tuple_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut tb: *mut *const nlattr = (data as *mut *const nlattr);
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    if (unsafe { mnl_attr_type_valid(attr, CTA_TUPLE_MAX) }) < 0 {
        return MNL_CB_OK as i32;
    }
    match type_ {
        CTA_TUPLE_IP => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_NESTED) }) < 0 {
                unsafe { perror(c"mnl_attr_validate".as_ptr()) };
                return MNL_CB_ERROR as i32;
            }
        }
        CTA_TUPLE_PROTO => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_NESTED) }) < 0 {
                unsafe { perror(c"mnl_attr_validate".as_ptr()) };
                return MNL_CB_ERROR as i32;
            }
        }
        _ => {}
    }
    (*tb.offset(type_ as isize)) = attr;
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn print_tuple(mut nest: *const nlattr) {
    let mut tb: [*mut nlattr; 4] = [unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];
    unsafe { mnl_attr_parse_nested(nest, Some(parse_tuple_cb), tb.as_mut_ptr()) };
    if !tb[CTA_TUPLE_IP as usize].is_null() {
        unsafe { print_ip((tb[CTA_TUPLE_IP as usize] as *const nlattr)) };
    }
    if !tb[CTA_TUPLE_PROTO as usize].is_null() {
        unsafe { print_proto((tb[CTA_TUPLE_PROTO as usize] as *const nlattr)) };
    }
}

