// ######## shared, from /home/matt/.c2r/tree/libnetfilter_conntrack/tests/test_filter.c

unsafe extern "C" fn event_cb(mut type_: nf_conntrack_msg_type, mut ct: *mut nf_conntrack, mut data: *mut core::ffi::c_void) -> i32 {
    static mut n: i32 = 0;
    let mut buf: [core::ffi::c_char; 1024] = [0; 1024];
    unsafe { nfct_snprintf(buf.as_mut_ptr(), core::mem::size_of::<[core::ffi::c_char; 1024]>(), ct, type_, NFCT_O_PLAIN, NFCT_OF_TIME) };
    unsafe { printf(c"%s\n".as_ptr(), buf.as_mut_ptr()) };
    if ({ n += 1; n }) == 10 {
        return NFCT_CB_STOP as i32;
    }
    return NFCT_CB_CONTINUE as i32;
}

