// ######## shared, from /home/matt/.c2r/tree/libnftnl/examples/nft-ct-expectation-add.c

unsafe extern "C" fn parse_family(mut str: *mut core::ffi::c_char, mut option: *const core::ffi::c_char) -> u16 {
    if (unsafe { strcmp((str as *const core::ffi::c_char), c"ip".as_ptr()) }) == 0 {
        return 2u16;
    } else if (unsafe { strcmp((str as *const core::ffi::c_char), c"ip6".as_ptr()) }) == 0 {
        return 10u16;
    } else if (unsafe { strcmp((str as *const core::ffi::c_char), c"inet".as_ptr()) }) == 0 {
        return 1u16;
    } else if (unsafe { strcmp((str as *const core::ffi::c_char), c"arp".as_ptr()) }) == 0 {
        return 1u16;
    }
    unsafe { fprintf(stderr, c"Unknown %s: ip, ip6, inet, arp\n".as_ptr(), option) };
    unsafe { exit(1) };
    unsafe { core::mem::zeroed() }
}

unsafe extern "C" fn parse_l4proto(mut str: *mut core::ffi::c_char) -> u8 {
    if (unsafe { strcmp((str as *const core::ffi::c_char), c"udp".as_ptr()) }) == 0 {
        return 17u8;
    } else if (unsafe { strcmp((str as *const core::ffi::c_char), c"tcp".as_ptr()) }) == 0 {
        return 6u8;
    } else {
        unsafe { fprintf(stderr, c"Unknown l4proto: tcp, udp\n".as_ptr()) };
        unsafe { exit(1) };
    }
    return 6u8;
}

// ######## shared, from /home/matt/.c2r/tree/libnftnl/examples/nft-ct-helper-get.c

unsafe extern "C" fn obj_cb(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut t: *mut nftnl_obj = core::ptr::null_mut();
    let mut buf: [core::ffi::c_char; 4096] = [0; 4096];
    let mut type_: *mut u32 = (data as *mut u32);
    t = unsafe { nftnl_obj_alloc() };
    'g_err: {
        if t.is_null() {
            unsafe { perror(c"OOM".as_ptr()) };
            break 'g_err;
        }
        'g_err_free: {
            if (unsafe { nftnl_obj_nlmsg_parse(nlh, t) }) < 0 {
                unsafe { perror(c"nftnl_obj_nlmsg_parse".as_ptr()) };
                break 'g_err_free;
            }
            unsafe { nftnl_obj_snprintf((buf.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 4096]>(), (t as *const nftnl_obj), *type_, 0u32) };
            unsafe { printf(c"%s\n".as_ptr(), buf.as_mut_ptr()) };
        }
        unsafe { nftnl_obj_free((t as *const nftnl_obj)) };
    }
    return MNL_CB_OK as i32;
}

