unsafe extern "C" fn nftnl_hooknum2str(mut family: i32, mut hooknum: i32) -> *const core::ffi::c_char {
    match family {
        NFPROTO_IPV4 | NFPROTO_IPV6 | NFPROTO_INET | NFPROTO_BRIDGE => {
            match hooknum {
                NF_INET_PRE_ROUTING => {
                    return c"prerouting".as_ptr();
                }
                NF_INET_LOCAL_IN => {
                    return c"input".as_ptr();
                }
                NF_INET_FORWARD => {
                    return c"forward".as_ptr();
                }
                NF_INET_LOCAL_OUT => {
                    return c"output".as_ptr();
                }
                NF_INET_POST_ROUTING => {
                    return c"postrouting".as_ptr();
                }
                _ => {}
            }
        }
        NFPROTO_ARP => {
            match hooknum {
                0 => {
                    return c"input".as_ptr();
                }
                1 => {
                    return c"output".as_ptr();
                }
                2 => {
                    return c"forward".as_ptr();
                }
                _ => {}
            }
        }
        NFPROTO_NETDEV => {
            match hooknum {
                NF_NETDEV_INGRESS => {
                    return c"ingress".as_ptr();
                }
                _ => {}
            }
        }
        _ => {}
    }
    return c"unknown".as_ptr();
}

unsafe extern "C" fn djb_hash(mut key: *const core::ffi::c_char) -> u32 {
    let mut i: u32 = 0;
    let mut hash: u32 = 5381u32;
    {
        i = 0u32;
        while (i as usize) < unsafe { strlen(key) } {
            hash = ((hash << (5 as u32)) + hash) + ((*key.offset(i as isize)) as u32);
            i += 1;
        }
    }
    return hash;
}

