unsafe extern "C" fn __expr_set_context(mut ctx: *mut expr_ctx, mut dtype: *const datatype, mut byteorder: byteorder, mut len: u32, mut maxval: u32) {
    (*ctx).dtype = dtype;
    (*ctx).byteorder = byteorder;
    (*ctx).len = len;
    (*ctx).maxval = maxval;
    (*ctx).key = core::ptr::null();
}

unsafe extern "C" fn expr_set_context(mut ctx: *mut expr_ctx, mut dtype: *const datatype, mut len: u32) {
    unsafe { __expr_set_context(ctx, dtype, (if !dtype.is_null() { (*dtype).byteorder() } else { 0 }), len, 0u32) };
}

unsafe extern "C" fn expr_is_constant(mut expr: *const expr) -> bool {
    return (if (((*expr).flags & (EXPR_F_CONSTANT as u32)) != 0) { true } else { false });
}

unsafe extern "C" fn expr_is_singleton(mut expr: *const expr) -> bool {
    return (if (((*expr).flags & (EXPR_F_SINGLETON as u32)) != 0) { true } else { false });
}

unsafe extern "C" fn symbol_expr_set_type(mut expr: *mut expr, mut dtype: *const datatype) {
    if (*expr).etype() == EXPR_SYMBOL {
        unsafe { datatype_set(expr, dtype) };
    }
}

