unsafe extern "C" fn json_incref(mut json: *mut json_t) -> *mut json_t {
    if !json.is_null() && ((*json).refcount != 18446744073709551615usize) {
        unsafe { __atomic_add_fetch(&raw mut (*json).refcount, 1, __ATOMIC_ACQUIRE) };
    }
    return json;
}

unsafe extern "C" fn json_decref(mut json: *mut json_t) {
    if (!json.is_null() && ((*json).refcount != 18446744073709551615usize)) && ((unsafe { __atomic_sub_fetch(&raw mut (*json).refcount, 1, __ATOMIC_RELEASE) }) == 0) {
        unsafe { json_delete(json) };
    }
}

unsafe extern "C" fn json_decrefp(mut json: *mut *mut json_t) {
    if !json.is_null() {
        unsafe { json_decref((*json)) };
        (*json) = core::ptr::null_mut();
    }
}

unsafe extern "C" fn json_error_code(mut e: *const json_error_t) -> json_error_code {
    return (*e).text[159] as json_error_code;
}

unsafe extern "C" fn json_object_set(mut object: *mut json_t, mut key: *const core::ffi::c_char, mut value: *mut json_t) -> i32 {
    return unsafe { json_object_set_new(object, key, unsafe { json_incref(value) }) };
}

unsafe extern "C" fn json_object_setn(mut object: *mut json_t, mut key: *const core::ffi::c_char, mut key_len: usize, mut value: *mut json_t) -> i32 {
    return unsafe { json_object_setn_new(object, key, key_len, unsafe { json_incref(value) }) };
}

