#[repr(C)]
#[derive(Copy, Clone, PartialEq, Eq)]
pub struct pollfd {
    pub fd: i32,
    pub events: i16,
    pub revents: i16,
}

unsafe extern "C" fn c_main() -> i32 {
    let mut nl: *mut mnl_socket = core::ptr::null_mut();
    let mut __buf_storage: Vec<core::ffi::c_char> = vec![unsafe { core::mem::zeroed() }; (MNL_SOCKET_BUFFER_SIZE) as usize];
    let buf: *mut core::ffi::c_char = __buf_storage.as_mut_ptr();
    let mut ret: i32 = 0;
    nl = (unsafe { mnl_socket_open(12) } as *mut mnl_socket);
    if nl.is_null() {
        unsafe { perror(c"mnl_socket_open".as_ptr()) };
        unsafe { exit(1) };
    }
    if (unsafe { mnl_socket_bind(nl, 7, MNL_SOCKET_AUTOPID) }) < 0 {
        unsafe { perror(c"mnl_socket_bind".as_ptr()) };
        unsafe { exit(1) };
    }
    loop {
        ret = (unsafe { mnl_socket_recvfrom(nl, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
        if ret == -1 {
            unsafe { perror(c"mnl_socket_recvfrom".as_ptr()) };
            unsafe { exit(1) };
        }
        ret = (unsafe { mnl_cb_run(buf, ret, 0, 0, Some(data_cb), core::ptr::null_mut()) }) as i32;
        if ret == -1 {
            unsafe { perror(c"mnl_cb_run".as_ptr()) };
            unsafe { exit(1) };
        }
    }
    unsafe { mnl_socket_close(nl) };
    return 0;
}

