unsafe extern "C" fn c_main() -> i32 {
    let mut __buf_storage: Vec<core::ffi::c_char> = vec![unsafe { core::mem::zeroed() }; (MNL_SOCKET_DUMP_SIZE) as usize];
    let buf: *mut core::ffi::c_char = __buf_storage.as_mut_ptr();
    let mut seq: u32 = 0;
    let mut portid: u32 = 0;
    let mut nl: *mut mnl_socket = core::ptr::null_mut();
    let mut ifm: *mut ifinfomsg = core::ptr::null_mut();
    let mut nlh: *mut nlmsghdr = core::ptr::null_mut();
    let mut ret: i32 = 0;
    nlh = (unsafe { mnl_nlmsg_put_header(buf) } as *mut nlmsghdr);
    (*nlh).nlmsg_type = 18u16;
    (*nlh).nlmsg_flags = 769u16;
    (*nlh).nlmsg_seq = { let __v = (unsafe { time(core::ptr::null_mut()) }) as u32; seq = __v; __v };
    ifm = (unsafe { mnl_nlmsg_put_extra_header(nlh, core::mem::size_of::<ifinfomsg>()) } as *mut ifinfomsg);
    (*ifm).ifi_family = 0u8;
    nl = (unsafe { mnl_socket_open(NETLINK_ROUTE) } as *mut mnl_socket);
    if nl.is_null() {
        unsafe { perror(c"mnl_socket_open".as_ptr()) };
        unsafe { exit(1) };
    }
    if (unsafe { mnl_socket_bind(nl, 0, MNL_SOCKET_AUTOPID) }) < 0 {
        unsafe { perror(c"mnl_socket_bind".as_ptr()) };
        unsafe { exit(1) };
    }
    portid = (unsafe { mnl_socket_get_portid(nl) }) as u32;
    if (unsafe { mnl_socket_sendto(nl, nlh, (*nlh).nlmsg_len) }) < 0 {
        unsafe { perror(c"mnl_socket_sendto".as_ptr()) };
        unsafe { exit(1) };
    }
    ret = (unsafe { mnl_socket_recvfrom(nl, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
    while ret > 0 {
        ret = (unsafe { mnl_cb_run(buf, ret, seq, portid, Some(data_cb), core::ptr::null_mut()) }) as i32;
        if ret <= MNL_CB_STOP {
            break;
        }
        ret = (unsafe { mnl_socket_recvfrom(nl, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
    }
    if ret == -1 {
        unsafe { perror(c"error".as_ptr()) };
        unsafe { exit(1) };
    }
    unsafe { mnl_socket_close(nl) };
    return 0;
}

