    let mut tb: [*mut nlattr; 11] = [unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];
