unsafe extern "C" fn c_main(mut argc: i32, mut argv: *mut *mut core::ffi::c_char) -> i32 {
    let mut nl: *mut mnl_socket = core::ptr::null_mut();
    let mut __buf_storage: Vec<core::ffi::c_char> = vec![unsafe { core::mem::zeroed() }; (MNL_SOCKET_BUFFER_SIZE) as usize];
    let buf: *mut core::ffi::c_char = __buf_storage.as_mut_ptr();
    let mut ret: i32 = 0;
    nl = (unsafe { mnl_socket_open(NETLINK_KOBJECT_UEVENT) } as *mut mnl_socket);
    if nl.is_null() {
        unsafe { perror(c"mnl_socket_open".as_ptr()) };
        unsafe { exit(1) };
    }
    /* There is one single group in kobject over netlink */
    if (unsafe { mnl_socket_bind(nl, 1, MNL_SOCKET_AUTOPID) }) < 0 {
        unsafe { perror(c"mnl_socket_bind".as_ptr()) };
        unsafe { exit(1) };
    }
    ret = (unsafe { mnl_socket_recvfrom(nl, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
    while ret > 0 {
        let mut i: i32 = 0;
        /* kobject uses a string based protocol, with no initial
        		 * netlink header.
        		 */
        {
            i = 0;
            while i < ret {
                unsafe { printf(c"%c".as_ptr(), ((*buf.offset(i as isize)) as i32)) };
                i += 1;
            }
        }
        unsafe { printf(c"\n".as_ptr()) };
        ret = (unsafe { mnl_socket_recvfrom(nl, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
    }
    if ret == -1 {
        unsafe { perror(c"error".as_ptr()) };
        unsafe { exit(1) };
    }
    unsafe { mnl_socket_close(nl) };
    return 0;
}

