unsafe extern "C" fn parse_attr_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut tb: *mut *const nlattr = (data as *mut *const nlattr);
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    /* skip unsupported attribute in user-space */
    if (unsafe { mnl_attr_type_valid(attr, NFULA_MAX) }) < 0 {
        return MNL_CB_OK as i32;
    }
    match type_ {
        NFULA_MARK | NFULA_IFINDEX_INDEV | NFULA_IFINDEX_OUTDEV | NFULA_IFINDEX_PHYSINDEV | NFULA_IFINDEX_PHYSOUTDEV => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U32) }) < 0 {
                unsafe { perror(c"mnl_attr_validate".as_ptr()) };
                return MNL_CB_ERROR as i32;
            }
        }
        NFULA_TIMESTAMP => {
            if (unsafe { mnl_attr_validate2(attr, MNL_TYPE_UNSPEC, core::mem::size_of::<nfulnl_msg_packet_timestamp>()) }) < 0 {
                unsafe { perror(c"mnl_attr_validate2".as_ptr()) };
                return MNL_CB_ERROR as i32;
            }
        }
        NFULA_HWADDR => {
            if (unsafe { mnl_attr_validate2(attr, MNL_TYPE_UNSPEC, core::mem::size_of::<nfulnl_msg_packet_hw>()) }) < 0 {
                unsafe { perror(c"mnl_attr_validate2".as_ptr()) };
                return MNL_CB_ERROR as i32;
            }
        }
        NFULA_PREFIX => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_NUL_STRING) }) < 0 {
                unsafe { perror(c"mnl_attr_validate".as_ptr()) };
                return MNL_CB_ERROR as i32;
            }
        }
        NFULA_PAYLOAD => {
        }
        _ => {}
    }
    (*tb.offset(type_ as isize)) = attr;
    return MNL_CB_OK as i32;
}

