static mut default_cb_array: [mnl_cb_t; 16] = [unsafe { core::mem::zeroed() }, mnl_cb_noop, mnl_cb_error, mnl_cb_stop, mnl_cb_noop, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];

unsafe extern "C" fn mnl_cb_noop(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> i32 {
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn mnl_cb_error(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut err: *const nlmsgerr = (unsafe { mnl_nlmsg_get_payload(nlh) } as *const nlmsgerr);
    if (*nlh).nlmsg_len < unsafe { mnl_nlmsg_size(core::mem::size_of::<nlmsgerr>()) } {
        (*unsafe { __errno_location() }) = 74;
        return MNL_CB_ERROR as i32;
    }
    /* Netlink subsystems returns the errno value with different signess */
    if (*err).error < 0 {
        (*unsafe { __errno_location() }) = -(*err).error;
    } else {
        (*unsafe { __errno_location() }) = (*err).error;
    }
    return (if ((*err).error == 0) { MNL_CB_STOP as i32 } else { MNL_CB_ERROR as i32 });
}

unsafe extern "C" fn mnl_cb_stop(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> i32 {
    return MNL_CB_STOP as i32;
}

unsafe extern "C" fn __mnl_cb_run(mut buf: *const core::ffi::c_void, mut numbytes: usize, mut seq: u32, mut portid: u32, mut cb_data: mnl_cb_t, mut data: *mut core::ffi::c_void, mut cb_ctl_array: *const core::ffi::c_void, mut cb_ctl_array_len: u32) -> i32 {
    let mut ret: i32 = MNL_CB_OK as i32;
    let mut len: i32 = numbytes as i32;
    let mut nlh: *const nlmsghdr = (buf as *const nlmsghdr);
    'g_out: {
        while unsafe { mnl_nlmsg_ok(nlh, len) } != 0 {
            /* check message source */
            if !(unsafe { mnl_nlmsg_portid_ok(nlh, portid) } != 0) {
                (*unsafe { __errno_location() }) = 3;
                return -1;
            }
            /* perform sequence tracking */
            if !(unsafe { mnl_nlmsg_seq_ok(nlh, seq) } != 0) {
                (*unsafe { __errno_location() }) = 71;
                return -1;
            }
            /* dump was interrupted */
            if (((*nlh).nlmsg_flags as i32) & 16) != 0 {
                (*unsafe { __errno_location() }) = 4;
                return -1;
            }
            /* netlink data message handling */
            if ((*nlh).nlmsg_type as i32) >= 16 {
                if cb_data != 0 {
                    ret = (unsafe { (cb_data.unwrap())(nlh, data) }) as i32;
                    if ret <= MNL_CB_STOP {
                        break 'g_out;
                    }
                }
            } else if ((*nlh).nlmsg_type as u32) < cb_ctl_array_len {
                if !cb_ctl_array.is_null() && ((*cb_ctl_array.offset((*nlh).nlmsg_type as isize)) != 0) {
                    ret = (unsafe { ((*cb_ctl_array.offset((*nlh).nlmsg_type as isize)).unwrap())(nlh, data) }) as i32;
                    if ret <= MNL_CB_STOP {
                        break 'g_out;
                    }
                }
            } else if default_cb_array[(*nlh).nlmsg_type as usize] != 0 {
                ret = (unsafe { (default_cb_array[(*nlh).nlmsg_type as usize].unwrap())(nlh, data) }) as i32;
                if ret <= MNL_CB_STOP {
                    break 'g_out;
                }
            }
            nlh = (unsafe { mnl_nlmsg_next(nlh, &raw mut len) } as *const nlmsghdr);
        }
    }
    return ret;
}

