    unsafe { nfct_set_attr_u16(ct, ATTR_PORT_DST, (unsafe { htons(10u16) } as i32)) };
    unsafe { nfct_setobjopt(ct, NFCT_SOPT_SETUP_REPLY) };
    unsafe { nfct_set_attr_u8(ct, ATTR_TCP_STATE, TCP_CONNTRACK_SYN_SENT) };
    unsafe { nfct_set_attr_u32(ct, ATTR_TIMEOUT, 100) };
