unsafe extern "C" fn print_label(mut ct: *mut nf_conntrack, mut map: *mut nfct_labelmap) {
    let mut i: u32 = 0;
    let mut max: u32 = 0;
    let mut b: *const nfct_bitmask = (unsafe { nfct_get_attr(ct, ATTR_CONNLABELS) } as *const nfct_bitmask);
    if b.is_null() {
        return;
    }
    unsafe { puts(c"labels:".as_ptr()) };
    max = (unsafe { nfct_bitmask_maxbit(b) }) as u32;
    {
        i = 0u32;
        while i <= max {
            if unsafe { nfct_bitmask_test_bit(b, i) } != 0 {
                unsafe { printf(c"\t'%s' (%d)\n".as_ptr(), (if !map.is_null() { unsafe { nfct_labelmap_get_name(map, i) } } else { c"".as_ptr() }), i) };
            }
            i += 1;
        }
    }
}

unsafe extern "C" fn data_cb(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut ct: *mut nf_conntrack = core::ptr::null_mut();
    let mut buf: [core::ffi::c_char; 4096] = [0; 4096];
    ct = (unsafe { nfct_new() } as *mut nf_conntrack);
    if ct.is_null() {
        return MNL_CB_OK as i32;
    }
    unsafe { nfct_nlmsg_parse(nlh, ct) };
    unsafe { nfct_snprintf(buf.as_mut_ptr(), core::mem::size_of::<[core::ffi::c_char; 4096]>(), ct, NFCT_T_UNKNOWN, NFCT_O_DEFAULT, 0) };
    unsafe { printf(c"%s\n".as_ptr(), buf.as_mut_ptr()) };
    unsafe { print_label(ct, (data as *mut nfct_labelmap)) };
    unsafe { nfct_destroy(ct) };
    return MNL_CB_OK as i32;
}

