#[repr(C)]
#[derive(Copy, Clone, PartialEq, Eq)]
pub struct callback_args {
    pub nl: *mut mnl_socket,
    pub seq: u32,
    pub bit: i32,
}

unsafe extern "C" fn set_label(mut ct: *mut nf_conntrack, mut cbargs: *mut callback_args) {
    let mut b: *mut nfct_bitmask = ((unsafe { nfct_get_attr(ct, ATTR_CONNLABELS) } as *mut core::ffi::c_void) as *mut nfct_bitmask);
    let mut bit: i32 = (*cbargs).bit;
    let mut __buf_storage: Vec<core::ffi::c_char> = vec![unsafe { core::mem::zeroed() }; (MNL_SOCKET_BUFFER_SIZE) as usize];
    let buf: *mut core::ffi::c_char = __buf_storage.as_mut_ptr();
    let mut nlh: *mut nlmsghdr = core::ptr::null_mut();
    let mut nfh: *mut nfgenmsg = core::ptr::null_mut();
    let mut ret: i32 = 0;
    if !b.is_null() {
        if bit < 0 {
            b = (unsafe { nfct_bitmask_new(0) } as *mut nfct_bitmask);
        } else if unsafe { nfct_bitmask_test_bit(b, bit) } != 0 {
            return;
        }
    } else {
        b = (unsafe { nfct_bitmask_new(0) } as *mut nfct_bitmask);
    }
    if b.is_null() {
        return;
    }
    if bit >= 0 {
        unsafe { nfct_bitmask_set_bit(b, bit) };
    }
    unsafe { nfct_set_attr(ct, ATTR_CONNLABELS, b) };
    if bit >= 0 {
        b = (unsafe { nfct_bitmask_new(bit) } as *mut nfct_bitmask);
        if !b.is_null() {
            unsafe { nfct_bitmask_set_bit(b, bit) };
            unsafe { nfct_set_attr(ct, ATTR_CONNLABELS_MASK, b) };
        }
    }
    (*cbargs).seq += 1;
    nlh = (unsafe { mnl_nlmsg_put_header(buf) } as *mut nlmsghdr);
    (*nlh).nlmsg_type = (256 | IPCTNL_MSG_CT_NEW) as u16;
    (*nlh).nlmsg_flags = 1025u16;
    (*nlh).nlmsg_seq = (*cbargs).seq;
    nfh = (unsafe { mnl_nlmsg_put_extra_header(nlh, core::mem::size_of::<nfgenmsg>()) } as *mut nfgenmsg);
    (*nfh).nfgen_family = unsafe { nfct_get_attr_u8(ct, ATTR_L3PROTO) };
    (*nfh).version = 0;
    (*nfh).res_id = 0;
    ret = (unsafe { nfct_nlmsg_build(nlh, ct) }) as i32;
    if ret == -1 {
        unsafe { perror(c"nfct_nlmsg_build".as_ptr()) };
        unsafe { exit(1) };
    }
    if (unsafe { mnl_socket_sendto((*cbargs).nl, nlh, (*nlh).nlmsg_len) }) < 0 {
        unsafe { perror(c"mnl_socket_sendto".as_ptr()) };
    }
}

unsafe extern "C" fn data_cb(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut ct: *mut nf_conntrack = core::ptr::null_mut();
    let mut buf: [core::ffi::c_char; 4096] = [0; 4096];
    ct = (unsafe { nfct_new() } as *mut nf_conntrack);
    if ct.is_null() {
        return MNL_CB_OK as i32;
    }
    unsafe { nfct_nlmsg_parse(nlh, ct) };
    unsafe { nfct_snprintf(buf.as_mut_ptr(), core::mem::size_of::<[core::ffi::c_char; 4096]>(), ct, NFCT_T_UNKNOWN, NFCT_O_DEFAULT, 0) };
    unsafe { printf(c"%s\n".as_ptr(), buf.as_mut_ptr()) };
    unsafe { set_label(ct, (data as *mut callback_args)) };
    unsafe { nfct_destroy(ct) };
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn show_labels(mut l: *mut nfct_labelmap) {
    let mut i: u32 = 0u32;
    let mut name: *const core::ffi::c_char = core::ptr::null();
    if !l.is_null() {
        unsafe { fputs(c"usage: program label, configured labels are:\n".as_ptr(), stderr) };
        while !{ let __v = (unsafe { nfct_labelmap_get_name(l, i) } as *const core::ffi::c_char); name = __v; __v }.is_null() {
            if (*name) != 0 {
                unsafe { fprintf(stderr, c"%s -> bit %d\n".as_ptr(), name, i) };
            }
            i += 1;
        }
    } else {
        unsafe { fputs(c"no labels configured, usage: program bit\n".as_ptr(), stderr) };
    }
    unsafe { exit(1) };
}

unsafe extern "C" fn sock_nl_create() -> *mut mnl_socket {
    let mut nl: *mut mnl_socket = core::ptr::null_mut();
    nl = (unsafe { mnl_socket_open(12) } as *mut mnl_socket);
    if nl.is_null() {
        unsafe { perror(c"mnl_socket_open".as_ptr()) };
        unsafe { exit(1) };
    }
    if (unsafe { mnl_socket_bind(nl, 0, MNL_SOCKET_AUTOPID) }) < 0 {
        unsafe { perror(c"mnl_socket_bind".as_ptr()) };
        unsafe { exit(1) };
    }
    return nl;
}

unsafe extern "C" fn c_main(mut argc: i32, mut argv: *mut *mut core::ffi::c_char) -> i32 {
    let mut nl: *mut mnl_socket = core::ptr::null_mut();
    let mut nlh: *mut nlmsghdr = core::ptr::null_mut();
    let mut nfh: *mut nfgenmsg = core::ptr::null_mut();
    let mut __buf_storage: Vec<core::ffi::c_char> = vec![unsafe { core::mem::zeroed() }; (MNL_SOCKET_BUFFER_SIZE) as usize];
    let buf: *mut core::ffi::c_char = __buf_storage.as_mut_ptr();
    let mut seq: u32 = 0;
    let mut portid: u32 = 0;
    let mut cbargs: callback_args = unsafe { core::mem::zeroed() };
    let mut ret: i32 = 0;
    let mut l: *mut nfct_labelmap = (unsafe { nfct_labelmap_new(core::ptr::null_mut()) } as *mut nfct_labelmap);
    if argc < 2 {
        unsafe { show_labels(l) };
    }
    cbargs.bit = (if !l.is_null() { (unsafe { nfct_labelmap_get_bit(l, (*argv.offset(1))) }) as i32 } else { -1 });
    if cbargs.bit < 0 {
        cbargs.bit = unsafe { atoi(((*argv.offset(1)) as *const core::ffi::c_char)) };
        if (cbargs.bit == 0) && (((*(*argv.offset(1)).offset(0)) as i32) != 48) {
            unsafe { show_labels(l) };
        }
    }
    if cbargs.bit < 0 {
        unsafe { puts(c"will clear all labels".as_ptr()) };
    } else {
        unsafe { printf(c"will set label bit %d\n".as_ptr(), cbargs.bit) };
    }
    nl = unsafe { sock_nl_create() };
    portid = (unsafe { mnl_socket_get_portid(nl) }) as u32;
    nlh = (unsafe { mnl_nlmsg_put_header(buf) } as *mut nlmsghdr);
    (*nlh).nlmsg_type = (256 | IPCTNL_MSG_CT_GET) as u16;
    (*nlh).nlmsg_flags = 769u16;
    (*nlh).nlmsg_seq = { let __v = (unsafe { time(core::ptr::null_mut()) }) as u32; seq = __v; __v };
    nfh = (unsafe { mnl_nlmsg_put_extra_header(nlh, core::mem::size_of::<nfgenmsg>()) } as *mut nfgenmsg);
    (*nfh).nfgen_family = 0;
    (*nfh).version = 0;
    (*nfh).res_id = 0;
    ret = (unsafe { mnl_socket_sendto(nl, nlh, (*nlh).nlmsg_len) }) as i32;
    if ret == -1 {
        unsafe { perror(c"mnl_socket_sendto".as_ptr()) };
        unsafe { exit(1) };
    }
    ret = (unsafe { mnl_socket_recvfrom(nl, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
    cbargs.nl = unsafe { sock_nl_create() };
    cbargs.seq = seq;
    while ret > 0 {
        ret = (unsafe { mnl_cb_run(buf, ret, seq, portid, Some(data_cb), &raw mut cbargs) }) as i32;
        if ret <= MNL_CB_STOP {
            break;
        }
        ret = (unsafe { mnl_socket_recvfrom(nl, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
    }
    if ret == -1 {
        unsafe { perror(c"mnl_socket_recvfrom".as_ptr()) };
        unsafe { exit(1) };
    }
    if !l.is_null() {
        unsafe { nfct_labelmap_destroy(l) };
    }
    unsafe { mnl_socket_close(nl) };
    return 0;
}

