/* This function uses libmnl helpers, the nfa[] array is intentionally not used
 * since it has a different layout.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __callback(mut nlh: *mut nlmsghdr, mut nfa: *mut *mut nfattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut ret: i32 = NFNL_CB_STOP as i32;
    let mut type_: u32 = 0;
    let mut ct: *mut nf_conntrack = core::ptr::null_mut();
    let mut exp: *mut nf_expect = core::ptr::null_mut();
    let mut container: *mut __data_container = (data as *mut __data_container);
    let mut subsys: u8 = (unsafe { NFNL_SUBSYS_ID(((*nlh).nlmsg_type as i32)) }) as u8;
    if (*nlh).nlmsg_len < unsafe { NLMSG_LENGTH(core::mem::size_of::<nfgenmsg>()) } {
        errno = 22;
        return NFNL_CB_FAILURE as i32;
    }
    type_ = (unsafe { __parse_message((nlh as *const nlmsghdr)) }) as u32;
    if !((type_ & (*container).type_) != 0) {
        return NFNL_CB_CONTINUE as i32;
    }
    match (subsys as i32) {
        1 => {
            ct = (unsafe { nfct_new() } as *mut nf_conntrack);
            if ct.is_null() {
                return NFNL_CB_FAILURE as i32;
            }
            unsafe { nfct_nlmsg_parse(nlh, ct) };
            if (*(*container).h).cb != 0 {
                ret = (unsafe { ((*(*container).h).cb.unwrap())(type_, ct, (*container).data) }) as i32;
            } else if (*(*container).h).cb2 != 0 {
                ret = (unsafe { ((*(*container).h).cb2.unwrap())(nlh, type_, ct, (*container).data) }) as i32;
            }
        }
        2 => {
            exp = (unsafe { nfexp_new() } as *mut nf_expect);
            if exp.is_null() {
                return NFNL_CB_FAILURE as i32;
            }
            unsafe { nfexp_nlmsg_parse(nlh, exp) };
            if (*(*container).h).expect_cb != 0 {
                ret = (unsafe { ((*(*container).h).expect_cb.unwrap())(type_, exp, (*container).data) }) as i32;
            } else if (*(*container).h).expect_cb2 != 0 {
                ret = (unsafe { ((*(*container).h).expect_cb2.unwrap())(nlh, type_, exp, (*container).data) }) as i32;
            }
        }
        _ => {
            errno = 95;
            ret = NFNL_CB_FAILURE as i32;
        }
    }
    if ret == NFCT_CB_STOLEN {
        return NFNL_CB_CONTINUE as i32;
    }
    if !ct.is_null() {
        unsafe { nfct_destroy(ct) };
    }
    if !exp.is_null() {
        unsafe { nfexp_destroy(exp) };
    }
    return ret;
}

