/**
 * nfct_attr_is_set - check if a certain attribute is set
 * \param ct pointer to a valid conntrack object
 * \param type attribute type
 *
 * On error, -1 is returned and errno is set appropiately, otherwise
 * the value of the attribute is returned.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfct_attr_is_set(mut ct: *const nf_conntrack, mut type_: nf_conntrack_attr) -> i32 {
    assert!(!ct.is_null());
    if unsafe { unlikely(((type_ >= ATTR_MAX) as i32)) } != 0 {
        (*unsafe { __errno_location() }) = 22;
        return -1;
    }
    return (unsafe { test_bit(type_, (*ct).head.set) }) as i32;
}

/**
 * nfct_attr_is_set_array - check if an array of attribute types is set
 * \param ct pointer to a valid conntrack object
 * \param array attribute type array
 * \param size size of the array
 *
 * On error, -1 is returned and errno is set appropiately, otherwise
 * the value of the attribute is returned.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfct_attr_is_set_array(mut ct: *const nf_conntrack, mut type_array: *const core::ffi::c_void, mut size: i32) -> i32 {
    let mut i: i32 = 0;
    assert!(!ct.is_null());
    {
        i = 0;
        while i < size {
            if unsafe { unlikely((((*type_array.offset(i as isize)) >= ATTR_MAX) as i32)) } != 0 {
                (*unsafe { __errno_location() }) = 22;
                return -1;
            }
            if !(unsafe { test_bit((*type_array.offset(i as isize)), (*ct).head.set) } != 0) {
                return 0;
            }
            i += 1;
        }
    }
    return 1;
}

