#[unsafe(no_mangle)]
pub unsafe extern "C" fn __build_conntrack(mut req: *mut nfnlhdr, mut size: usize, mut type_: u16, mut flags: u16, mut ct: *const nf_conntrack) -> i32 {
    let mut l3num: u8 = (*ct).head.orig.l3protonum as u8;
    let mut nlh: *mut nlmsghdr = core::ptr::null_mut();
    let mut nfh: *mut nfgenmsg = core::ptr::null_mut();
    let mut buf: *mut core::ffi::c_char = core::ptr::null_mut();
    if !(unsafe { test_bit(ATTR_ORIG_L3PROTO, (*ct).head.set) } != 0) {
        errno = 22;
        return -1;
    }
    buf = (&raw mut (*req).nlh as *mut core::ffi::c_char);
    nlh = (unsafe { mnl_nlmsg_put_header(buf) } as *mut nlmsghdr);
    (*nlh).nlmsg_type = (256 | (type_ as i32)) as u16;
    (*nlh).nlmsg_flags = flags;
    (*nlh).nlmsg_seq = 0u32;
    nfh = (unsafe { mnl_nlmsg_put_extra_header(nlh, core::mem::size_of::<nfgenmsg>()) } as *mut nfgenmsg);
    (*nfh).nfgen_family = l3num;
    (*nfh).version = 0;
    (*nfh).res_id = 0;
    return (unsafe { nfct_nlmsg_build(nlh, ct) }) as i32;
}

