#[unsafe(no_mangle)]
pub unsafe extern "C" fn __copy_fast(mut ct1: *mut nf_conntrack, mut ct2: *const nf_conntrack) {
    unsafe { memcpy((ct1 as *mut core::ffi::c_void), (ct2 as *const core::ffi::c_void), core::mem::size_of::<nf_conntrack>()) };
    /* malloc'd attributes: don't free, do copy */
    (*ct1).secctx = core::ptr::null_mut();
    (*ct1).helper_info = core::ptr::null_mut();
    (*ct1).connlabels = core::ptr::null_mut();
    (*ct1).connlabels_mask = core::ptr::null_mut();
    unsafe { copy_attr_secctx(ct1, ct2) };
    unsafe { copy_attr_help_info(ct1, ct2) };
    unsafe { copy_attr_connlabels(ct1, ct2) };
    unsafe { copy_attr_connlabels_mask(ct1, ct2) };
}

