unsafe extern "C" fn filter_attr_l4proto(mut filter: *mut nfct_filter, mut value: *const core::ffi::c_void) {
    let mut protonum: i32 = 0;
    if (*filter).l4proto_len >= __FILTER_L4PROTO_MAX {
        return;
    }
    protonum = *(value as *mut i32);
    if protonum >= 256 {
        return;
    }
    unsafe { set_bit(protonum, (*filter).l4proto_map) };
    (*filter).l4proto_len += 1;
}

