unsafe extern "C" fn label_is_sane(mut label: *const core::ffi::c_char) -> bool {
    while (*label) != 0 {
        'c0: {
            if (((*label) as i32) >= 97) && (((*label) as i32) <= 122) {
                break 'c0;
            }
            if (((*label) as i32) >= 65) && (((*label) as i32) <= 90) {
                break 'c0;
            }
            if (((*label) as i32) >= 48) && (((*label) as i32) <= 57) {
                break 'c0;
            }
            if (((*label) as i32) == 32) || (((*label) as i32) == 45) {
                break 'c0;
            }
            return false;
        }
        label = label.offset(1);
    }
    return true;
}

