unsafe extern "C" fn __snprintf_l3protocol(mut buf: *mut core::ffi::c_char, mut len: u32, mut ct: *const nf_conntrack) -> i32 {
    let mut num: u8 = (*ct).head.orig.l3protonum as u8;
    if !(unsafe { test_bit(ATTR_ORIG_L3PROTO, (*ct).head.set) } != 0) {
        return -1;
    }
    return unsafe { snprintf(buf, len as usize, c"%-8s %u ".as_ptr(), unsafe { __l3proto2str((num as i32)) }, (num as i32)) };
}

