unsafe extern "C" fn __snprintf_address_ipv4(mut buf: *mut core::ffi::c_char, mut len: u32, mut tuple: *const __nfct_tuple, mut src_tag: *const core::ffi::c_char, mut dst_tag: *const core::ffi::c_char) -> i32 {
    let mut ret: i32 = 0;
    let mut size: i32 = 0;
    let mut offset: i32 = 0;
    let mut src: in_addr = in_addr { s_addr: (*tuple).src.v4 as u32 };
    let mut dst: in_addr = in_addr { s_addr: (*tuple).dst.v4 as u32 };
    ret = unsafe { snprintf(buf, len as usize, c"%s=%s ".as_ptr(), src_tag, unsafe { inet_ntoa(src) }) };
    unsafe { BUFFER_SIZE(ret, size, len, offset) };
    ret = unsafe { snprintf(buf.offset(offset as isize), len as usize, c"%s=%s ".as_ptr(), dst_tag, unsafe { inet_ntoa(dst) }) };
    unsafe { BUFFER_SIZE(ret, size, len, offset) };
    return size;
}

unsafe extern "C" fn __snprintf_address_ipv6(mut buf: *mut core::ffi::c_char, mut len: u32, mut tuple: *const __nfct_tuple, mut src_tag: *const core::ffi::c_char, mut dst_tag: *const core::ffi::c_char) -> i32 {
    let mut ret: i32 = 0;
    let mut size: i32 = 0;
    let mut offset: i32 = 0;
    let mut src: in6_addr = unsafe { core::mem::zeroed() };
    let mut dst: in6_addr = unsafe { core::mem::zeroed() };
    let mut tmp: [core::ffi::c_char; 46] = [0; 46];
    unsafe { memcpy((&raw mut src as *mut core::ffi::c_void), (((&raw const (*tuple).src.v6).cast_mut()) as *const core::ffi::c_void), core::mem::size_of::<in6_addr>()) };
    unsafe { memcpy((&raw mut dst as *mut core::ffi::c_void), (((&raw const (*tuple).dst.v6).cast_mut()) as *const core::ffi::c_void), core::mem::size_of::<in6_addr>()) };
    if unsafe { inet_ntop(10, (&raw mut src as *const core::ffi::c_void), (tmp.as_mut_ptr() as *mut core::ffi::c_char), (core::mem::size_of::<[core::ffi::c_char; 46]>()) as u32) }.is_null() {
        return -1;
    }
    ret = unsafe { snprintf(buf, len as usize, c"%s=%s ".as_ptr(), src_tag, tmp.as_mut_ptr()) };
    unsafe { BUFFER_SIZE(ret, size, len, offset) };
    if unsafe { inet_ntop(10, (&raw mut dst as *const core::ffi::c_void), (tmp.as_mut_ptr() as *mut core::ffi::c_char), (core::mem::size_of::<[core::ffi::c_char; 46]>()) as u32) }.is_null() {
        return -1;
    }
    ret = unsafe { snprintf(buf.offset(offset as isize), len as usize, c"%s=%s ".as_ptr(), dst_tag, tmp.as_mut_ptr()) };
    unsafe { BUFFER_SIZE(ret, size, len, offset) };
    return size;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn __snprintf_address(mut buf: *mut core::ffi::c_char, mut len: u32, mut tuple: *const __nfct_tuple, mut src_tag: *const core::ffi::c_char, mut dst_tag: *const core::ffi::c_char) -> i32 {
    let mut size: i32 = 0;
    match (*tuple).l3protonum {
        2 => {
            size = unsafe { __snprintf_address_ipv4(buf, len, tuple, src_tag, dst_tag) };
        }
        10 => {
            size = unsafe { __snprintf_address_ipv6(buf, len, tuple, src_tag, dst_tag) };
        }
        _ => {}
    }
    return size;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn __snprintf_proto(mut buf: *mut core::ffi::c_char, mut len: u32, mut tuple: *const __nfct_tuple) -> i32 {
    let mut size: i32 = 0;
    match (*tuple).protonum {
        6 | 17 | 136 | 132 | 33 => {
            return unsafe { snprintf(buf, len as usize, c"sport=%u dport=%u ".as_ptr(), (unsafe { ntohs((*tuple).l4src.tcp.port as u16) } as i32), (unsafe { ntohs((*tuple).l4dst.tcp.port as u16) } as i32)) };
        }
        47 => {
            return unsafe { snprintf(buf, len as usize, c"srckey=0x%x dstkey=0x%x ".as_ptr(), (unsafe { ntohs((*tuple).l4src.all as u16) } as i32), (unsafe { ntohs((*tuple).l4dst.all as u16) } as i32)) };
        }
        1 | 58 => {
            /* The ID only makes sense some ICMP messages but we want to
    		 * display the same output that /proc/net/ip_conntrack does */
            return unsafe { snprintf(buf, len as usize, c"type=%d code=%d id=%d ".as_ptr(), (*tuple).l4dst.icmp.type_, (*tuple).l4dst.icmp.code, (unsafe { ntohs((*tuple).l4src.icmp.id as u16) } as i32)) };
        }
        _ => {}
    }
    return size;
}

