unsafe extern "C" fn __snprintf_status_assured(mut buf: *mut core::ffi::c_char, mut len: u32, mut ct: *const nf_conntrack) -> i32 {
    let mut size: i32 = 0;
    if ((*ct).status & IPS_HW_OFFLOAD) != 0 {
        size = unsafe { snprintf(buf, len as usize, c"[HW_OFFLOAD] ".as_ptr()) };
    } else if ((*ct).status & IPS_OFFLOAD) != 0 {
        size = unsafe { snprintf(buf, len as usize, c"[OFFLOAD] ".as_ptr()) };
    } else if ((*ct).status & IPS_ASSURED) != 0 {
        size = unsafe { snprintf(buf, len as usize, c"[ASSURED] ".as_ptr()) };
    }
    return size;
}

