unsafe extern "C" fn __snprintf_timestamp_start(mut buf: *mut core::ffi::c_char, mut len: u32, mut ct: *const nf_conntrack) -> i32 {
    let mut start: i64 = (((*ct).timestamp.start / NSEC_PER_SEC) as i64) as i64;
    let mut tmp: *mut core::ffi::c_char = unsafe { ctime((&raw mut start as *const i64)) };
    /* overwrite \n in the ctime() output. */
    (*tmp.offset(((unsafe { strlen((tmp as *const core::ffi::c_char)) }) - (1 as usize)) as isize)) = (0 as core::ffi::c_char);
    return unsafe { snprintf(buf, len as usize, c"[start=%s] ".as_ptr(), tmp) };
}

unsafe extern "C" fn __snprintf_timestamp_stop(mut buf: *mut core::ffi::c_char, mut len: u32, mut ct: *const nf_conntrack) -> i32 {
    let mut stop: i64 = (((*ct).timestamp.stop / NSEC_PER_SEC) as i64) as i64;
    let mut tmp: *mut core::ffi::c_char = unsafe { ctime((&raw mut stop as *const i64)) };
    /* overwrite \n in the ctime() output. */
    (*tmp.offset(((unsafe { strlen((tmp as *const core::ffi::c_char)) }) - (1 as usize)) as isize)) = (0 as core::ffi::c_char);
    return unsafe { snprintf(buf, len as usize, c"[stop=%s] ".as_ptr(), tmp) };
}

unsafe extern "C" fn __snprintf_timestamp_delta(mut buf: *mut core::ffi::c_char, mut len: u32, mut ct: *const nf_conntrack) -> i32 {
    let mut delta_time: i64 = 0;
    let mut stop: i64 = 0;
    if (*ct).timestamp.stop == 0 {
        unsafe { time((&raw mut stop as *mut i64)) };
    } else {
        stop = (((*ct).timestamp.stop / NSEC_PER_SEC) as i64) as i64;
    }
    delta_time = (stop - (((*ct).timestamp.start / NSEC_PER_SEC) as i64)) as i64;
    return unsafe { snprintf(buf, len as usize, c"delta-time=%llu ".as_ptr(), (delta_time as u64)) };
}

