#[repr(C)]
#[derive(Copy, Clone, PartialEq, Eq)]
pub struct stack {
    pub num_elems: i32,
    pub max_elems: i32,
    pub elem_size: usize,
    pub data: *mut core::ffi::c_char,
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn stack_create(mut elem_size: usize, mut max_elems: i32) -> *mut stack {
    let mut s: *mut stack = core::ptr::null_mut();
    s = (unsafe { calloc(1usize, core::mem::size_of::<stack>()) } as *mut stack);
    if s.is_null() {
        return core::ptr::null_mut();
    }
    (*s).data = (unsafe { calloc(max_elems as usize, elem_size) } as *mut core::ffi::c_char);
    if (*s).data.is_null() {
        unsafe { free((s as *mut core::ffi::c_void)) };
        return core::ptr::null_mut();
    }
    (*s).elem_size = elem_size;
    (*s).max_elems = max_elems;
    return s;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn stack_destroy(mut s: *mut stack) {
    unsafe { free(((*s).data as *mut core::ffi::c_void)) };
    unsafe { free((s as *mut core::ffi::c_void)) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn stack_push(mut s: *mut stack, mut data: *mut core::ffi::c_void) -> i32 {
    if (*s).num_elems >= (*s).max_elems {
        (*unsafe { __errno_location() }) = 28;
        return -1;
    }
    unsafe { memcpy(((*s).data.offset(((*s).elem_size * ((*s).num_elems as usize)) as isize) as *mut core::ffi::c_void), (data as *const core::ffi::c_void), (*s).elem_size) };
    (*s).num_elems += 1;
    return 0;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn stack_pop(mut s: *mut stack, mut data: *mut core::ffi::c_void) -> i32 {
    if (*s).num_elems <= 0 {
        (*unsafe { __errno_location() }) = 22;
        return -1;
    }
    (*s).num_elems -= 1;
    unsafe { memcpy(data, ((*s).data.offset(((*s).elem_size * ((*s).num_elems as usize)) as isize) as *const core::ffi::c_void), (*s).elem_size) };
    return 0;
}

