pub unsafe extern "C" fn nfexp_build_expect(mut ssh: *mut nfnl_subsys_handle, mut req: *mut core::ffi::c_void, mut size: usize, mut type_: u16, mut flags: u16, mut exp: *const nf_expect) -> i32 {
    assert!(!ssh.is_null());
    assert!(!req.is_null());
    assert!(!exp.is_null());
    unsafe { memset(req, 0, size) };
    return (unsafe { __build_expect(req, size, (type_ as i32), (flags as i32), exp) }) as i32;
}

unsafe extern "C" fn nfexp_fill_hdr(mut req: *mut nfnlhdr, mut type_: u16, mut flags: u16, mut l3num: u8, mut version: u8) {
    let mut buf: *mut core::ffi::c_char = (&raw mut (*req).nlh as *mut core::ffi::c_char);
    let mut nlh: *mut nlmsghdr = core::ptr::null_mut();
    let mut nfh: *mut nfgenmsg = core::ptr::null_mut();
    nlh = (unsafe { mnl_nlmsg_put_header(buf) } as *mut nlmsghdr);
    (*nlh).nlmsg_type = (512 | (type_ as i32)) as u16;
    (*nlh).nlmsg_flags = (1 | (flags as i32)) as u16;
    (*nlh).nlmsg_seq = 0u32;
    nfh = (unsafe { mnl_nlmsg_put_extra_header(nlh, core::mem::size_of::<nfgenmsg>()) } as *mut nfgenmsg);
    (*nfh).nfgen_family = l3num;
    (*nfh).version = version;
    (*nfh).res_id = 0;
}

unsafe extern "C" fn __build_query_exp(mut qt: nf_conntrack_query, mut data: *const core::ffi::c_void, mut buffer: *mut core::ffi::c_void, mut size: u32) -> i32 {
    let mut req: *mut nfnlhdr = (buffer as *mut nfnlhdr);
    let mut family: *const u8 = (data as *const u8);
    assert!(!data.is_null());
    assert!(!req.is_null());
    unsafe { memset(buffer, 0, size as usize) };
    match qt {
        _ => {
            (*unsafe { __errno_location() }) = 95;
            return -1;
        }
    }
    return 1;
}

/**
 * nfexp_build_query - build a query in netlink message format for ctnetlink
 * \param ssh nfnetlink subsystem handler
 * \param qt query type
 * \param data data required to build the query
 * \param req buffer to build the netlink message
 * \param size size of the buffer passed
 *
 * This is a low level function, use it if you want to require to work
 * with netlink details via libnfnetlink, otherwise we suggest you to
 * use nfexp_query.
 * 
 * The pointer to data can be a conntrack object or the protocol family
 * depending on the request.
 * 
 * For query types:
 * 	NFEXP_Q_CREATE
 * 	NFEXP_Q_DESTROY
 * 
 * Pass a valid pointer to an expectation object.
 * 
 * For query types:
 * 	NFEXP_Q_FLUSH
 * 	NFEXP_Q_DUMP
 * 
 * Pass a valid pointer to the protocol family (uint8_t)
 * 
 * On success, 0 is returned. On error, -1 is returned and errno is set
 * appropiately.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfexp_build_query(mut ssh: *mut nfnl_subsys_handle, mut qt: nf_conntrack_query, mut data: *const core::ffi::c_void, mut buffer: *mut core::ffi::c_void, mut size: u32) -> i32 {
    return unsafe { __build_query_exp(qt, data, buffer, size) };
}

unsafe extern "C" fn __parse_expect_message_type(mut nlh: *const nlmsghdr) -> i32 {
    let mut type_: u16 = (unsafe { NFNL_MSG_TYPE(((*nlh).nlmsg_type as i32)) }) as u16;
    let mut flags: u16 = (*nlh).nlmsg_flags;
    let mut ret: i32 = NFCT_T_UNKNOWN as i32;
    if type_ == IPCTNL_MSG_EXP_NEW {
        if ((flags as i32) & 1536) != 0 {
            ret = NFCT_T_NEW as i32;
        } else {
            ret = NFCT_T_UPDATE as i32;
        }
    } else if type_ == IPCTNL_MSG_EXP_DELETE {
        ret = NFCT_T_DESTROY as i32;
    }
    return ret;
}

/**
 * nfexp_parse_expect - translate a netlink message to a conntrack object
 * \param type do the translation iif the message type is of a certain type
 * \param nlh pointer to the netlink message
 * \param exp pointer to the conntrack object
 *
 * This is a low level function, use it in case that you require to work
 * with netlink details via libnfnetlink. Otherwise, we suggest you to
 * use the high level API.
 * 
 * The message types are:
 * 
 * NFEXP_T_NEW: parse messages with new conntracks
 * NFEXP_T_UPDATE: parse messages with conntrack updates
 * NFEXP_T_DESTROY: parse messages with conntrack destroy 
 * NFEXP_T_ALL: all message types
 * 
 * The message type is a flag, therefore the can be combined, ie.
 * NFEXP_T_NEW | NFEXP_T_DESTROY to parse only new and destroy messages
 * 
 * On error, NFEXP_T_ERROR is returned and errno is set appropiately. If 
 * the message received is not of the requested type then 0 is returned, 
 * otherwise this function returns the message type parsed.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfexp_parse_expect(mut type_: nf_conntrack_msg_type, mut nlh: *const nlmsghdr, mut exp: *mut nf_expect) -> i32 {
    let mut flags: u32 = 0;
    assert!(!nlh.is_null());
    assert!(!exp.is_null());
    flags = (unsafe { __parse_expect_message_type(nlh) }) as u32;
    if !((flags & type_) != 0) {
        return 0;
    }
    unsafe { nfexp_nlmsg_parse(nlh, exp) };
    return flags as i32;
}

