#[unsafe(no_mangle)]
pub unsafe extern "C" fn __build_expect(mut req: *mut nfnlhdr, mut size: usize, mut type_: u16, mut flags: u16, mut exp: *const nf_expect) -> i32 {
    let mut nlh: *mut nlmsghdr = core::ptr::null_mut();
    let mut nfh: *mut nfgenmsg = core::ptr::null_mut();
    let mut l3num: u8 = 0;
    let mut buf: *mut core::ffi::c_char = core::ptr::null_mut();
    if unsafe { test_bit(ATTR_ORIG_L3PROTO, (*exp).master.set) } != 0 {
        l3num = (*exp).master.orig.l3protonum as u8;
    } else if unsafe { test_bit(ATTR_ORIG_L3PROTO, (*exp).expected.set) } != 0 {
        l3num = (*exp).expected.orig.l3protonum as u8;
    } else {
        return -1;
    }
    buf = (&raw mut (*req).nlh as *mut core::ffi::c_char);
    nlh = (unsafe { mnl_nlmsg_put_header(buf) } as *mut nlmsghdr);
    (*nlh).nlmsg_type = (512 | (type_ as i32)) as u16;
    (*nlh).nlmsg_flags = flags;
    (*nlh).nlmsg_seq = 0u32;
    nfh = (unsafe { mnl_nlmsg_put_extra_header(nlh, core::mem::size_of::<nfgenmsg>()) } as *mut nfgenmsg);
    (*nfh).nfgen_family = l3num;
    (*nfh).version = 0;
    (*nfh).res_id = 0;
    return (unsafe { nfexp_nlmsg_build(nlh, exp) }) as i32;
}

// ######## /home/matt/.c2r/tree/libnetfilter_conntrack/src/expect/build_mnl.c

#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfexp_nlmsg_build(mut nlh: *mut nlmsghdr, mut exp: *const nf_expect) -> i32 {
    if unsafe { test_bit(ATTR_EXP_EXPECTED, (*exp).set) } != 0 {
        unsafe { nfct_build_tuple(nlh, ((&raw const (*exp).expected.orig).cast_mut()), CTA_EXPECT_TUPLE) };
    }
    if unsafe { test_bit(ATTR_EXP_MASTER, (*exp).set) } != 0 {
        unsafe { nfct_build_tuple(nlh, ((&raw const (*exp).master.orig).cast_mut()), CTA_EXPECT_MASTER) };
    }
    if unsafe { test_bit(ATTR_EXP_MASK, (*exp).set) } != 0 {
        unsafe { nfct_build_tuple(nlh, ((&raw const (*exp).mask.orig).cast_mut()), CTA_EXPECT_MASK) };
    }
    if unsafe { test_bit(ATTR_EXP_TIMEOUT, (*exp).set) } != 0 {
        unsafe { mnl_attr_put_u32(nlh, CTA_EXPECT_TIMEOUT, unsafe { htonl((*exp).timeout as u32) }) };
    }
    if unsafe { test_bit(ATTR_EXP_FLAGS, (*exp).set) } != 0 {
        unsafe { mnl_attr_put_u32(nlh, CTA_EXPECT_FLAGS, unsafe { htonl((*exp).flags as u32) }) };
    }
    if unsafe { test_bit(ATTR_EXP_ZONE, (*exp).set) } != 0 {
        unsafe { mnl_attr_put_u16(nlh, CTA_EXPECT_ZONE, (unsafe { htons((*exp).zone as u16) } as i32)) };
    }
    if unsafe { test_bit(ATTR_EXP_HELPER_NAME, (*exp).set) } != 0 {
        unsafe { mnl_attr_put_strz(nlh, CTA_EXPECT_HELP_NAME, (*exp).helper_name) };
    }
    return 0;
}

// ######## /home/matt/.c2r/tree/libnetfilter_conntrack/src/expect/compare.c

unsafe extern "C" fn exp_cmp(mut attr: i32, mut exp1: *const nf_expect, mut exp2: *const nf_expect, mut flags: u32, mut cmp: Option<unsafe extern "C" fn(*const nf_expect, *const nf_expect, u32) -> i32>) -> i32 {
    let mut a: i32 = (unsafe { test_bit(attr, (*exp1).set) }) as i32;
    let mut b: i32 = (unsafe { test_bit(attr, (*exp2).set) }) as i32;
    if (a != 0) && (b != 0) {
        return unsafe { (cmp.unwrap())(exp1, exp2, flags) };
    } else if !(a != 0) && !(b != 0) {
        return 1;
    } else if ((flags & NFCT_CMP_MASK) != 0) && (unsafe { test_bit(attr, (*exp1).set) } != 0) {
        return 0;
    } else if (flags & NFCT_CMP_STRICT) != 0 {
        return 0;
    }
    return 1;
}

unsafe extern "C" fn cmp_exp_master(mut exp1: *const nf_expect, mut exp2: *const nf_expect, mut flags: u32) -> i32 {
    return (unsafe { __cmp_orig((((&raw const (*exp1).master).cast_mut()) as *mut core::ffi::c_void), (((&raw const (*exp2).master).cast_mut()) as *mut core::ffi::c_void), flags) }) as i32;
}

unsafe extern "C" fn cmp_exp_expected(mut exp1: *const nf_expect, mut exp2: *const nf_expect, mut flags: u32) -> i32 {
    return (unsafe { __cmp_orig((((&raw const (*exp1).expected).cast_mut()) as *mut core::ffi::c_void), (((&raw const (*exp2).expected).cast_mut()) as *mut core::ffi::c_void), flags) }) as i32;
}

