        unsafe { nfct_parse_tuple(tb[CTA_EXPECT_TUPLE as usize], &raw mut (*exp).expected.orig, __DIR_ORIG, (*exp).expected.set) };
        unsafe { set_bit(ATTR_EXP_EXPECTED, (*exp).set) };
