        (*exp).master.orig.l3protonum = (*nfg).nfgen_family;
        unsafe { set_bit(ATTR_ORIG_L3PROTO, (*exp).master.set) };
        unsafe { nfct_parse_tuple(tb[CTA_EXPECT_MASK as usize], &raw mut (*exp).mask.orig, __DIR_ORIG, (*exp).mask.set) };
        unsafe { set_bit(ATTR_EXP_MASK, (*exp).set) };
