#[unsafe(no_mangle)]
pub unsafe extern "C" fn __snprintf_expect(mut buf: *mut core::ffi::c_char, mut len: u32, mut exp: *const nf_expect, mut type_: u32, mut msg_output: u32, mut flags: u32) -> i32 {
    let mut size: i32 = 0;
    match msg_output {
        _ => {
            errno = 2;
            return -1;
        }
    }
    if size < 0 {
        return size;
    }
    /* NULL terminated string */
    (*buf.offset((if (((size + 1) as u32) > len) { len - (1 as u32) } else { size as u32 }) as isize)) = (0 as core::ffi::c_char);
    return size;
}

