    ret = (unsafe { __snprintf_proto_xml(buf.offset(offset as isize), len, ((&raw const (*exp).master.orig).cast_mut()), __ADDR_DST) }) as i32;
    unsafe { BUFFER_SIZE(ret, size, len, offset) };
    ret = unsafe { snprintf(buf.offset(offset as isize), len, c"</master>".as_ptr()) };
    unsafe { BUFFER_SIZE(ret, size, len, offset) };
    ret = unsafe { snprintf(buf.offset(offset as isize), len, c"</layer4>".as_ptr()) };
