#[unsafe(no_mangle)]
pub unsafe extern "C" fn __snprintf_expect_xml(mut buf: *mut core::ffi::c_char, mut len: u32, mut exp: *const nf_expect, mut msg_type: u32, mut flags: u32) -> i32 {
    let mut ret: i32 = 0;
    let mut size: i32 = 0;
    let mut offset: i32 = 0;
    match msg_type {
        _ => {
            ret = unsafe { snprintf(buf, len as usize, c"<flow>".as_ptr()) };
        }
    }
    unsafe { BUFFER_SIZE(ret, size, len, offset) };
    ret = unsafe { snprintf_expect_layer3_xml(buf.offset(offset as isize), len as usize, exp) };
    unsafe { BUFFER_SIZE(ret, size, len, offset) };
    ret = unsafe { snprintf_expect_layer4_xml(buf.offset(offset as isize), len as usize, exp) };
    unsafe { BUFFER_SIZE(ret, size, len, offset) };
    ret = unsafe { snprintf_expect_meta_xml(buf.offset(offset as isize), len as usize, exp, flags) };
    unsafe { BUFFER_SIZE(ret, size, len, offset) };
    ret = unsafe { snprintf(buf.offset(offset as isize), len as usize, c"</flow>".as_ptr()) };
    unsafe { BUFFER_SIZE(ret, size, len, offset) };
    return size;
}

// ######## /home/matt/.c2r/tree/libnetfilter_conntrack/src/main.c

#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfct_open_nfnl(mut nfnlh: *mut nfnl_handle, mut subsys_id: u8, mut subscriptions: u32) -> *mut nfct_handle {
    let mut cth: *mut nfct_handle = core::ptr::null_mut();
    cth = (unsafe { malloc(core::mem::size_of::<nfct_handle>()) } as *mut nfct_handle);
    if cth.is_null() {
        return core::ptr::null_mut();
    }
    unsafe { memset((cth as *mut core::ffi::c_void), 0, core::mem::size_of::<nfct_handle>()) };
    (*cth).nfnlh = nfnlh;
    'g_out_free: {
        if ((subsys_id as i32) == 0) || ((subsys_id as i32) == 1) {
            (*cth).nfnlssh_ct = unsafe { nfnl_subsys_open((*cth).nfnlh, 1, IPCTNL_MSG_MAX, subscriptions) };
            if !((*cth).nfnlssh_ct != 0) {
                break 'g_out_free;
            }
        }
        if ((subsys_id as i32) == 0) || ((subsys_id as i32) == 2) {
            (*cth).nfnlssh_exp = unsafe { nfnl_subsys_open((*cth).nfnlh, 2, IPCTNL_MSG_EXP_MAX, subscriptions) };
            if !((*cth).nfnlssh_exp != 0) {
                break 'g_out_free;
            }
        }
        return cth;
    }
    if (*cth).nfnlssh_exp != 0 {
        unsafe { nfnl_subsys_close((*cth).nfnlssh_exp) };
        (*cth).nfnlssh_exp = core::ptr::null_mut();
    }
    if (*cth).nfnlssh_ct != 0 {
        unsafe { nfnl_subsys_close((*cth).nfnlssh_ct) };
        (*cth).nfnlssh_ct = core::ptr::null_mut();
    }
    unsafe { free((cth as *mut core::ffi::c_void)) };
    return core::ptr::null_mut();
}

/**
 * \defgroup LibrarySetup Library setup
 * @{
 */
/**
 * nfct_open - open a ctnetlink handler
 * \param subsys_id can be NFNL_SUBSYS_CTNETLINK or NFNL_SUBSYS_CTNETLINK_EXP
 * \param subscriptions ctnetlink groups to subscribe to events
 *
 * This function returns a handler to send commands to and receive replies from
 * kernel-space. You can pass the following subsystem IDs:
 *
 * - NFNL_SUBSYS_CTNETLINK: if you are only interested in conntrack operations
 * (excluding expectations).
 * - NFNL_SUBSYS_CTNETLINK_EXP: if you are only interested in expectation
 * operations (exclude conntracks).
 * - NFNL_SUBSYS_NONE: if you are interested in both conntrack and expectation
 * operations.
 *
 * On error, NULL is returned and errno is explicitly set.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfct_open(mut subsys_id: u8, mut subscriptions: u32) -> *mut nfct_handle {
    let mut nfnlh: *mut nfnl_handle = (unsafe { nfnl_open() } as *mut nfnl_handle);
    let mut nfcth: *mut nfct_handle = core::ptr::null_mut();
    if nfnlh.is_null() {
        return core::ptr::null_mut();
    }
    nfcth = unsafe { nfct_open_nfnl(nfnlh, subsys_id, subscriptions) };
    if nfcth.is_null() {
        unsafe { nfnl_close(nfnlh) };
    }
    return nfcth;
}

/**
 * nfct_close - close a ctnetlink handler
 * \param cth handler obtained via nfct_open()
 *
 * This function returns -1 on error and errno is explicitly set.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfct_close(mut cth: *mut nfct_handle) -> i32 {
    let mut err: i32 = 0;
    if (*cth).nfnlssh_exp != 0 {
        unsafe { nfnl_subsys_close((*cth).nfnlssh_exp) };
        (*cth).nfnlssh_exp = core::ptr::null_mut();
    }
    if (*cth).nfnlssh_ct != 0 {
        unsafe { nfnl_subsys_close((*cth).nfnlssh_ct) };
        (*cth).nfnlssh_ct = core::ptr::null_mut();
    }
    /* required by the new API */
    (*cth).cb = core::ptr::null_mut();
    (*cth).cb2 = core::ptr::null_mut();
    (*cth).expect_cb = core::ptr::null_mut();
    (*cth).expect_cb2 = core::ptr::null_mut();
    unsafe { free(((*cth).nfnl_cb_ct.data as *mut core::ffi::c_void)) };
    unsafe { free(((*cth).nfnl_cb_exp.data as *mut core::ffi::c_void)) };
    (*cth).nfnl_cb_ct.call = core::ptr::null_mut();
    (*cth).nfnl_cb_ct.data = core::ptr::null_mut();
    (*cth).nfnl_cb_ct.attr_count = 0;
    (*cth).nfnl_cb_exp.call = core::ptr::null_mut();
    (*cth).nfnl_cb_exp.data = core::ptr::null_mut();
    (*cth).nfnl_cb_exp.attr_count = 0;
    err = (unsafe { nfnl_close((*cth).nfnlh) }) as i32;
    unsafe { free((cth as *mut core::ffi::c_void)) };
    return err;
}

/**
 * nfct_fd - get the Netlink file descriptor of one existing ctnetlink handler
 * \param cth handler obtained via nfct_open()
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfct_fd(mut cth: *mut nfct_handle) -> i32 {
    return (unsafe { nfnl_fd((*cth).nfnlh) }) as i32;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfct_nfnlh(mut cth: *mut nfct_handle) -> *const nfnl_handle {
    return ((*cth).nfnlh as *const nfnl_handle);
}

