// ######## /home/matt/.c2r/tree/libnetfilter_conntrack/tests/ct_events_reliable.c

static mut events: i32 = 0;

static mut new: i32 = 0;

static mut update: i32 = 0;

static mut destroy: i32 = 0;

unsafe extern "C" fn event_cb(mut type_: nf_conntrack_msg_type, mut ct: *mut nf_conntrack, mut data: *mut core::ffi::c_void) -> i32 {
    if type_ == NFCT_T_NEW {
        new += 1;
    } else if type_ == NFCT_T_UPDATE {
        update += 1;
    } else if type_ == NFCT_T_DESTROY {
        destroy += 1;
    }
    if (({ events += 1; events }) % 10000) == 0 {
        unsafe { printf(c"%d events received (%d new, %d update, %d destroy)\n".as_ptr(), events, new, update, destroy) };
    }
    return NFCT_CB_CONTINUE as i32;
}

unsafe extern "C" fn sighandler(mut foo: i32) {
    unsafe { printf(c"%d events received (%d new, %d update, %d destroy)\n".as_ptr(), events, new, update, destroy) };
    unsafe { exit(0) };
}

unsafe extern "C" fn c_main() -> i32 {
    let mut ret: i32 = 0;
    let mut h: *mut nfct_handle = core::ptr::null_mut();
    let mut on: i32 = 1;
    unsafe { signal(2, Some(sighandler)) };
    h = (unsafe { nfct_open(CONNTRACK, NFCT_ALL_CT_GROUPS) } as *mut nfct_handle);
    if h.is_null() {
        unsafe { perror(c"nfct_open".as_ptr()) };
        return 0;
    }
    unsafe { setsockopt((unsafe { nfct_fd(h) }) as i32, 270, NETLINK_BROADCAST_SEND_ERROR as i32, (&raw mut on as *const core::ffi::c_void), (core::mem::size_of::<i32>()) as u32) };
    unsafe { setsockopt((unsafe { nfct_fd(h) }) as i32, 270, 5, (&raw mut on as *const core::ffi::c_void), (core::mem::size_of::<i32>()) as u32) };
    unsafe { nfct_callback_register(h, NFCT_T_ALL, Some(event_cb), core::ptr::null_mut()) };
    unsafe { printf(c"TEST: waiting for events...\n".as_ptr()) };
    ret = (unsafe { nfct_catch(h) }) as i32;
    unsafe { printf(c"TEST: conntrack events ".as_ptr()) };
    if ret == -1 {
        unsafe { printf(c"(%d)(%s)\n".as_ptr(), ret, unsafe { strerror(*unsafe { __errno_location() }) }) };
    } else {
        unsafe { printf(c"(OK)\n".as_ptr()) };
    }
    unsafe { nfct_close(h) };
    if (ret == -1) { unsafe { exit(1) }; } else { unsafe { exit(0) }; }
    unsafe { core::mem::zeroed() }
}

