#[unsafe(no_mangle)]
pub unsafe extern "C" fn author_new(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> *mut nf_conntrack {
    let mut ct: *mut nf_conntrack = core::ptr::null_mut();
    assert!((((*nlh).nlmsg_type as i32) & 255) == IPCTNL_MSG_CT_NEW);
    assert!(((*nlh).nlmsg_flags as i32) == 1536);
    ct = (unsafe { nfct_new() } as *mut nf_conntrack);
    assert!(!ct.is_null());
    assert!((unsafe { nfct_nlmsg_parse(nlh, ct) }) == 0);
    unsafe { assert_proto((ct as *const nf_conntrack), 2u8, *(data as *mut u8)) };
    unsafe { assert_inaddr((ct as *const nf_conntrack), (VETH_PARENT_ADDR as *const core::ffi::c_char), (VETH_CHILD_ADDR as *const core::ffi::c_char)) };
    assert!(((unsafe { nfct_get_attr_u32(ct, ATTR_STATUS) }) & IPS_SEEN_REPLY) == 0);
    timeout.tv_sec = ((unsafe { nfct_get_attr_u32(ct, ATTR_TIMEOUT) }) + 1) as i64;
    return ct;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn author_update(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> *mut nf_conntrack {
    let mut ct: *mut nf_conntrack = core::ptr::null_mut();
    assert!((((*nlh).nlmsg_type as i32) & 255) == IPCTNL_MSG_CT_NEW);
    assert!(((*nlh).nlmsg_flags as i32) == 0);
    ct = (unsafe { nfct_new() } as *mut nf_conntrack);
    assert!(!ct.is_null());
    assert!((unsafe { nfct_nlmsg_parse(nlh, ct) }) == 0);
    unsafe { assert_proto((ct as *const nf_conntrack), 2u8, *(data as *mut u8)) };
    unsafe { assert_inaddr((ct as *const nf_conntrack), (VETH_PARENT_ADDR as *const core::ffi::c_char), (VETH_CHILD_ADDR as *const core::ffi::c_char)) };
    assert!(((unsafe { nfct_get_attr_u32(ct, ATTR_STATUS) }) & IPS_SEEN_REPLY) != 0);
    timeout.tv_sec = ((unsafe { nfct_get_attr_u32(ct, ATTR_TIMEOUT) }) + 1) as i64;
    return ct;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn author_destroy(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> *mut nf_conntrack {
    let mut ct: *mut nf_conntrack = core::ptr::null_mut();
    assert!((((*nlh).nlmsg_type as i32) & 255) == IPCTNL_MSG_CT_DELETE);
    assert!(((*nlh).nlmsg_flags as i32) == 0);
    ct = (unsafe { nfct_new() } as *mut nf_conntrack);
    assert!(!ct.is_null());
    assert!((unsafe { nfct_nlmsg_parse(nlh, ct) }) == 0);
    unsafe { assert_proto((ct as *const nf_conntrack), 2u8, *(data as *mut u8)) };
    unsafe { assert_inaddr((ct as *const nf_conntrack), (VETH_PARENT_ADDR as *const core::ffi::c_char), (VETH_CHILD_ADDR as *const core::ffi::c_char)) };
    assert!(((unsafe { nfct_get_attr_u32(ct, ATTR_STATUS) }) & IPS_SEEN_REPLY) != 0);
    return ct;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn assert_proto(mut ct: *const nf_conntrack, mut l3proto: u8, mut l4proto: u8) {
    assert!((unsafe { nfct_get_attr_u8(ct, ATTR_ORIG_L3PROTO) }) == l3proto);
    assert!((unsafe { nfct_get_attr_u8(ct, ATTR_REPL_L3PROTO) }) == l3proto);
    assert!((unsafe { nfct_get_attr_u8(ct, ATTR_ORIG_L4PROTO) }) == l4proto);
    assert!((unsafe { nfct_get_attr_u8(ct, ATTR_REPL_L4PROTO) }) == l4proto);
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn assert_inaddr(mut ct: *const nf_conntrack, mut src: *const core::ffi::c_char, mut dst: *const core::ffi::c_char) {
    let mut addr: in_addr = unsafe { core::mem::zeroed() };
    assert!((unsafe { inet_aton(src, &raw mut addr) }) != 0);
    assert!((unsafe { nfct_get_attr_u32(ct, ATTR_ORIG_IPV4_SRC) }) == addr.s_addr);
    assert!((unsafe { nfct_get_attr_u32(ct, ATTR_REPL_IPV4_DST) }) == addr.s_addr);
    assert!((unsafe { inet_aton(dst, &raw mut addr) }) != 0);
    assert!((unsafe { nfct_get_attr_u32(ct, ATTR_ORIG_IPV4_DST) }) == addr.s_addr);
    assert!((unsafe { nfct_get_attr_u32(ct, ATTR_REPL_IPV4_SRC) }) == addr.s_addr);
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn assert_port(mut ct: *const nf_conntrack, mut src: u16, mut dst: u16) {
    if src != 0 {
        assert!((unsafe { nfct_get_attr_u16(ct, ATTR_ORIG_PORT_SRC) }) == unsafe { htons(src) });
        assert!((unsafe { nfct_get_attr_u16(ct, ATTR_REPL_PORT_DST) }) == unsafe { htons(src) });
    }
    if dst != 0 {
        assert!((unsafe { nfct_get_attr_u16(ct, ATTR_ORIG_PORT_DST) }) == unsafe { htons(dst) });
        assert!((unsafe { nfct_get_attr_u16(ct, ATTR_REPL_PORT_SRC) }) == unsafe { htons(dst) });
    }
}

