pub unsafe extern "C" fn add_child(mut pid: i32) {
    /* XXX: check excess MAX_CHILD */
    children[({ let __old = nchild; nchild += 1; __old }) as usize] = pid;
}

unsafe extern "C" fn get_unaligned_int(mut s: *const core::ffi::c_void) -> i32 {
    let mut x: i32 = 0;
    unsafe { memcpy((&raw mut x as *mut core::ffi::c_void), s, core::mem::size_of::<i32>()) };
    return x;
}

unsafe extern "C" fn put_unaligned_int(mut d: *mut core::ffi::c_void, mut x: i32) {
    unsafe { memcpy(d, (&raw mut x as *const core::ffi::c_void), core::mem::size_of::<i32>()) };
}

unsafe extern "C" fn setns(mut fd: i32, mut nstype: i32) -> i32 {
    return (unsafe { syscall(308i64, fd, nstype) }) as i32;
}

unsafe extern "C" fn netns_setup(mut name: *const core::ffi::c_char) -> i32 {
    /* Setup the proper environment for apps that are not netns
    	 * aware, and execute a program in that environment.
    	 */
    let mut net_path: [core::ffi::c_char; 4096] = [0; 4096];
    let mut netns: i32 = 0;
    unsafe { snprintf((net_path.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 4096]>(), c"%s/%s".as_ptr(), NETNS_RUN_DIR.as_ptr(), name) };
    netns = unsafe { open((net_path.as_mut_ptr() as *const core::ffi::c_char), 524288) };
    if netns < 0 {
        unsafe { fprintf(stderr, c"Cannot open network namespace \"%s\": %s\n".as_ptr(), name, unsafe { strerror(*unsafe { __errno_location() }) }) };
        return -1;
    }
    if (unsafe { setns(netns, 1073741824) }) < 0 {
        unsafe { fprintf(stderr, c"setting the network namespace \"%s\" failed: %s\n".as_ptr(), name, unsafe { strerror(*unsafe { __errno_location() }) }) };
        return -1;
    }
    if (unsafe { unshare(131072) }) < 0 {
        unsafe { fprintf(stderr, c"unshare failed: %s\n".as_ptr(), unsafe { strerror(*unsafe { __errno_location() }) }) };
        return -1;
    }
    /* Don't let any mounts propagate back to the parent */
    if unsafe { mount(c"".as_ptr(), c"/".as_ptr(), c"none".as_ptr(), 540672u64, core::ptr::null()) } != 0 {
        unsafe { fprintf(stderr, c"\"mount --make-rslave /\" failed: %s\n".as_ptr(), unsafe { strerror(*unsafe { __errno_location() }) }) };
        return -1;
    }
    /* Mount a version of /sys that describes the network namespace */
    if (unsafe { umount2(c"/sys".as_ptr(), 2) }) < 0 {
        unsafe { fprintf(stderr, c"umount of /sys failed: %s\n".as_ptr(), unsafe { strerror(*unsafe { __errno_location() }) }) };
        return -1;
    }
    if (unsafe { mount(name, c"/sys".as_ptr(), c"sysfs".as_ptr(), 0u64, core::ptr::null()) }) < 0 {
        unsafe { fprintf(stderr, c"mount of /sys failed: %s\n".as_ptr(), unsafe { strerror(*unsafe { __errno_location() }) }) };
        return -1;
    }
    return 0;
}

unsafe extern "C" fn child(mut nsname: *const core::ffi::c_char) {
    let mut cmd: i32 = 0;
    let mut params: [i32; 3] = [0; 3];
    /* XXX: magic number, see enum CALL_ */
    let mut sockfd: i32 = 0;
    if (unsafe { netns_setup(nsname) }) == -1 {
        {
            {
                unsafe { fprintf(stderr, c"child exiting - %s:%d %s() %s: %s\n".as_ptr(), c"".as_ptr(), 0, c"".as_ptr(), c"netns_setup".as_ptr(), unsafe { strerror(*unsafe { __errno_location() }) }) };
            }
            unsafe { _exit(1) };
        }
    }
    /* sync with parent */
    if (unsafe { tx_cmd(fdpair[1], 0) }) == -1 {
        {
            {
                unsafe { fprintf(stderr, c"child exiting - %s:%d %s() %s: %s\n".as_ptr(), c"".as_ptr(), 0, c"".as_ptr(), c"tx_cmd".as_ptr(), unsafe { strerror(*unsafe { __errno_location() }) }) };
            }
            unsafe { _exit(1) };
        }
    }
    /* waiting cmd */
    loop {
        cmd = unsafe { rx_cmd(fdpair[1]) };
        match cmd {
            CMD_DONE => {
                unsafe { close(fdpair[1]) };
                {
                    unsafe { _exit(0) };
                }
            }
            CMD_SOCKET => {
                if (unsafe { rx(fdpair[1], (params.as_mut_ptr() as *mut i32), 3u8, core::ptr::null_mut()) }) == ((-1) as isize) {
                    {
                        {
                            unsafe { fprintf(stderr, c"child exiting - %s:%d %s() %s: %s\n".as_ptr(), c"".as_ptr(), 0, c"".as_ptr(), c"rx".as_ptr(), unsafe { strerror(*unsafe { __errno_location() }) }) };
                        }
                        unsafe { _exit(1) };
                    }
                }
                sockfd = unsafe { socket(params[0], params[1], params[2]) };
                if (unsafe { tx_fd(fdpair[1], sockfd, -(*unsafe { __errno_location() })) }) == -1 {
                    {
                        {
                            unsafe { fprintf(stderr, c"child exiting - %s:%d %s() %s: %s\n".as_ptr(), c"".as_ptr(), 0, c"".as_ptr(), c"tx_fd".as_ptr(), unsafe { strerror(*unsafe { __errno_location() }) }) };
                        }
                        unsafe { _exit(1) };
                    }
                }
            }
            _ => {
                {
                    {
                        unsafe { fprintf(stderr, c"child exiting - %s:%d %s() %s: %s\n".as_ptr(), c"".as_ptr(), 0, c"".as_ptr(), c"receive unknown cmd".as_ptr(), unsafe { strerror(*unsafe { __errno_location() }) }) };
                    }
                    unsafe { _exit(1) };
                }
            }
        }
    }
}

/*
 * kill all the other registered child by SIGKILL
 *
 * SIGCHLD will not be raised if child has killed in SIGABRT handler
 */
unsafe extern "C" fn sigchld_handler(mut signum: i32) {
    let mut pid: i32 = 0;
    let mut status: i32 = 0;
    let mut i: i32 = 0;
    let mut fail: i32 = 0;
    while ({ let __v = unsafe { waitpid(-1, &raw mut status, 1) }; pid = __v; __v }) > 0 {
        if (status & 127) == 0 {
            fail |= ((status & 65280) >> (8 as u32));
        } else if ((((((status & 127) + 1) as i8) as i32) >> (1 as u32)) > 0) || ((status & __WCOREFLAG) != 0) {
            fail |= status;
        }
        if pid == child_pid {
            child_pid = 0;
        }
        {
            i = 0;
            while i < nchild {
                if children[i as usize] == pid {
                    children[i as usize] = 0;
                } else {
                    unsafe { kill(children[i as usize], 9) };
                }
                i += 1;
            }
        }
    }
    if (pid == -1) && ((*unsafe { __errno_location() }) != ECHILD) {
        fail |= (*unsafe { __errno_location() });
    }
}

unsafe extern "C" fn sigabrt_handler(mut signum: i32) {
    unsafe { fini_nssocket() };
}

