/*
 * this file contains a test to check the set/get/copy/cmp APIs.
 */
unsafe extern "C" fn eval_status(mut status: i32) -> i32 {
    if (status & 127) == 0 {
        let mut rc: i32 = (status & 65280) >> (8 as u32);
        if rc == 0 {
            unsafe { printf(c"OK\n".as_ptr()) };
        } else {
            unsafe { printf(c"FAIL\n".as_ptr()) };
        }
        return rc;
    }
    match status & 127 {
        11 => {
            unsafe { printf(c"received SIGSEV\n".as_ptr()) };
            return 1;
        }
        6 => {
            unsafe { printf(c"received SIGABRT\n".as_ptr()) };
            return 2;
        }
        _ => {
            unsafe { printf(c"exited with signal: %d\n".as_ptr(), (status & 127)) };
            return 1;
        }
    }
    unsafe { core::mem::zeroed() }
}

unsafe extern "C" fn test_nfct_bitmask() {
    let mut a: *mut nfct_bitmask = core::ptr::null_mut();
    let mut b: *mut nfct_bitmask = core::ptr::null_mut();
    let mut maxb: u16 = 0;
    let mut i: u16 = 0;
    let mut ct1: *mut nf_conntrack = core::ptr::null_mut();
    let mut ct2: *mut nf_conntrack = core::ptr::null_mut();
    unsafe { printf(c"== test nfct_bitmask_* API ==\n".as_ptr()) };
    maxb = ((unsafe { rand() }) & 65535) as u16;
    a = (unsafe { nfct_bitmask_new((maxb as i32)) } as *mut nfct_bitmask);
    assert!(!(unsafe { nfct_bitmask_test_bit(a, ((maxb as i32) + 32)) } != 0));
    unsafe { nfct_bitmask_set_bit(a, ((maxb as i32) + 32)) };
    assert!(!(unsafe { nfct_bitmask_test_bit(a, ((maxb as i32) + 32)) } != 0));
    {
        i = 0u16;
        while i <= maxb {
            assert!(!(unsafe { nfct_bitmask_test_bit(a, (i as i32)) } != 0));
            i += 1;
        }
    }
    {
        i = 0u16;
        while i <= maxb {
            'c1: {
                if ((unsafe { rand() }) & 1) != 0 {
                    assert!(!(unsafe { nfct_bitmask_test_bit(a, (i as i32)) } != 0));
                    break 'c1;
                }
                unsafe { nfct_bitmask_set_bit(a, (i as i32)) };
                assert!(unsafe { nfct_bitmask_test_bit(a, (i as i32)) } != 0);
            }
            i += 1;
        }
    }
    b = (unsafe { nfct_bitmask_clone(a) } as *mut nfct_bitmask);
    assert!(!b.is_null());
    {
        i = 0u16;
        while i <= maxb {
            if unsafe { nfct_bitmask_test_bit(a, (i as i32)) } != 0 {
                assert!(unsafe { nfct_bitmask_test_bit(b, (i as i32)) } != 0);
            } else {
                assert!(!(unsafe { nfct_bitmask_test_bit(b, (i as i32)) } != 0));
            }
            i += 1;
        }
    }
    unsafe { nfct_bitmask_destroy(a) };
    {
        i = 0u16;
        while i <= maxb {
            'c3: {
                if ((unsafe { rand() }) & 1) != 0 {
                    break 'c3;
                }
                unsafe { nfct_bitmask_unset_bit(b, (i as i32)) };
                assert!(!(unsafe { nfct_bitmask_test_bit(b, (i as i32)) } != 0));
            }
            i += 1;
        }
    }
    /* nfct_bitmask_clear() */
    {
        i = 0u16;
        while i < maxb {
            unsafe { nfct_bitmask_set_bit(b, (i as i32)) };
            assert!(unsafe { nfct_bitmask_test_bit(b, (i as i32)) } != 0);
            unsafe { nfct_bitmask_clear(b) };
            assert!(!(unsafe { nfct_bitmask_test_bit(b, (i as i32)) } != 0));
            i += 1;
        }
    }
    {
        i = 0u16;
        while i < maxb {
            unsafe { nfct_bitmask_set_bit(b, (i as i32)) };
            i += 1;
        }
    }
    unsafe { nfct_bitmask_clear(b) };
    {
        i = 0u16;
        while i < maxb {
            assert!(!(unsafe { nfct_bitmask_test_bit(b, (i as i32)) } != 0));
            i += 1;
        }
    }
    /* nfct_bitmask_equal() */
    {
        i = 0u16;
        while (i as i32) < (((maxb as i32) / 32) * 32) {
            a = (unsafe { nfct_bitmask_new((i as i32)) } as *mut nfct_bitmask);
            assert!(!(unsafe { nfct_bitmask_equal(a, b) } != 0));
            unsafe { nfct_bitmask_destroy(a) };
            i += ((32) as u16);
        }
    }
    a = (unsafe { nfct_bitmask_clone(b) } as *mut nfct_bitmask);
    assert!(unsafe { nfct_bitmask_equal(a, b) } != 0);
    {
        i = 0u16;
        while i < maxb {
            if unsafe { nfct_bitmask_test_bit(a, (i as i32)) } != 0 {
                unsafe { nfct_bitmask_unset_bit(a, (i as i32)) };
                assert!(!(unsafe { nfct_bitmask_equal(a, b) } != 0));
                unsafe { nfct_bitmask_set_bit(a, (i as i32)) };
            } else {
                unsafe { nfct_bitmask_set_bit(a, (i as i32)) };
                assert!(!(unsafe { nfct_bitmask_equal(a, b) } != 0));
                unsafe { nfct_bitmask_unset_bit(a, (i as i32)) };
            }
            assert!(unsafe { nfct_bitmask_equal(a, b) } != 0);
            i += 1;
        }
    }
    unsafe { nfct_bitmask_destroy(a) };
    unsafe { nfct_bitmask_destroy(b) };
    ct1 = (unsafe { nfct_new() } as *mut nf_conntrack);
    ct2 = (unsafe { nfct_new() } as *mut nf_conntrack);
    maxb = ((unsafe { rand() }) & 255) as u16;
    maxb += ((128) as u16);
    maxb /= ((2) as u16);
    a = (unsafe { nfct_bitmask_new(((maxb as i32) * 2)) } as *mut nfct_bitmask);
    b = (unsafe { nfct_bitmask_new((maxb as i32)) } as *mut nfct_bitmask);
    unsafe { nfct_set_attr(ct1, ATTR_CONNLABELS, a) };
    unsafe { nfct_set_attr(ct2, ATTR_CONNLABELS, b) };
    assert!((unsafe { nfct_cmp(ct1, ct2, NFCT_CMP_ALL) }) == 1);
    unsafe { nfct_bitmask_set_bit(a, (maxb as i32)) };
    unsafe { nfct_bitmask_set_bit(b, (maxb as i32)) };
    assert!((unsafe { nfct_cmp(ct1, ct2, NFCT_CMP_ALL) }) == 1);
    unsafe { nfct_bitmask_set_bit(a, ((maxb as i32) * 2)) };
    assert!((unsafe { nfct_cmp(ct1, ct2, NFCT_CMP_ALL) }) == 0);
    unsafe { nfct_destroy(ct1) };
    unsafe { nfct_destroy(ct2) };
    unsafe { printf(c"OK\n".as_ptr()) };
}

