// ######## /home/matt/.c2r/tree/libnetfilter_conntrack/utils/ctexp_events.c

static mut n: i32 = 0;

unsafe extern "C" fn ct_event_cb(mut type_: nf_conntrack_msg_type, mut ct: *mut nf_conntrack, mut data: *mut core::ffi::c_void) -> i32 {
    let mut buf: [core::ffi::c_char; 1024] = [0; 1024];
    unsafe { nfct_snprintf(buf.as_mut_ptr(), core::mem::size_of::<[core::ffi::c_char; 1024]>(), ct, type_, NFCT_O_PLAIN, NFCT_OF_TIME) };
    unsafe { printf(c"[CT] %s\n".as_ptr(), buf.as_mut_ptr()) };
    if ({ n += 1; n }) == 20 {
        return NFCT_CB_STOP as i32;
    }
    return NFCT_CB_CONTINUE as i32;
}

unsafe extern "C" fn exp_event_cb(mut type_: nf_conntrack_msg_type, mut exp: *mut nf_expect, mut data: *mut core::ffi::c_void) -> i32 {
    let mut buf: [core::ffi::c_char; 1024] = [0; 1024];
    unsafe { nfexp_snprintf(buf.as_mut_ptr(), 1024, exp, type_, NFCT_O_DEFAULT, 0) };
    unsafe { printf(c"[EXP] %s\n".as_ptr(), buf.as_mut_ptr()) };
    if ({ n += 1; n }) == 20 {
        return NFCT_CB_STOP as i32;
    }
    return NFCT_CB_CONTINUE as i32;
}

unsafe extern "C" fn c_main() -> i32 {
    let mut ret: i32 = 0;
    let mut h: *mut nfct_handle = core::ptr::null_mut();
    h = (unsafe { nfct_open(0, 63) } as *mut nfct_handle);
    if h.is_null() {
        unsafe { perror(c"nfct_open".as_ptr()) };
        return -1;
    }
    unsafe { nfexp_callback_register(h, NFCT_T_ALL, Some(exp_event_cb), core::ptr::null_mut()) };
    unsafe { nfct_callback_register(h, NFCT_T_ALL, Some(ct_event_cb), core::ptr::null_mut()) };
    unsafe { printf(c"TEST: waiting for 20 expectation events...\n".as_ptr()) };
    /* we may use nfexp_catch() instead, it would also work. */
    ret = (unsafe { nfct_catch(h) }) as i32;
    unsafe { printf(c"TEST: expectation events ".as_ptr()) };
    if ret == -1 {
        unsafe { printf(c"(%d)(%s)\n".as_ptr(), ret, unsafe { strerror(*unsafe { __errno_location() }) }) };
    } else {
        unsafe { printf(c"(OK)\n".as_ptr()) };
    }
    unsafe { nfct_close(h) };
    if (ret == -1) { unsafe { exit(1) }; } else { unsafe { exit(0) }; }
    unsafe { core::mem::zeroed() }
}

