    data = (((*pktb).network_header + dataoff) as *mut u8);
    /* move post-replacement */
    unsafe { memmove((data.offset(match_offset as isize).offset(rep_len as isize) as *mut core::ffi::c_void), (data.offset(match_offset as isize).offset(match_len as isize) as *const core::ffi::c_void), ((unsafe { pktb_tail(pktb) }) - ((((*pktb).network_header + dataoff) + match_offset) + match_len)) as usize) };
