/**
 * nfq_tcp_snprintf - print tcp header into one buffer in a human
 * readable way
 * \param buf: pointer to buffer that is used to print the object
 * \param size: size of the buffer (or remaining room in it).
 * \param tcph: pointer to a valid tcp header.
 * \returns Same as \b snprintf
 * \sa __snprintf__(3)
 *
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfq_tcp_snprintf(mut buf: *mut core::ffi::c_char, mut size: usize, mut tcph: *const tcphdr) -> i32 {
    let mut ret: i32 = 0;
    let mut len: i32 = 0;
    ret = unsafe { snprintf(buf, size, c"SPT=%u DPT=%u SEQ=%u ACK=%u WINDOW=%u RES=0x%02x ".as_ptr(), (unsafe { ntohs((*tcph).anon0.anon1.source) } as i32), (unsafe { ntohs((*tcph).anon0.anon1.dest) } as i32), unsafe { ntohl((*tcph).anon0.anon1.seq) }, unsafe { ntohl((*tcph).anon0.anon1.ack_seq) }, (unsafe { ntohs((*tcph).anon0.anon1.window) } as i32), ((((unsafe { ntohl((*(tcph as *mut tcp_word_hdr)).words[3] & unsafe { htonl(251658240u32) }) }) >> (22 as u32)) as u8) as i32)) };
    len += ret;
    if (*tcph).anon0.anon1.urg != 0 {
        ret = unsafe { snprintf(buf.offset(len as isize), size - (len as usize), c"URG ".as_ptr()) };
        len += ret;
    }
    if (*tcph).anon0.anon1.ack != 0 {
        ret = unsafe { snprintf(buf.offset(len as isize), size - (len as usize), c"ACK ".as_ptr()) };
        len += ret;
    }
    if (*tcph).anon0.anon1.psh != 0 {
        ret = unsafe { snprintf(buf.offset(len as isize), size - (len as usize), c"PSH ".as_ptr()) };
        len += ret;
    }
    if (*tcph).anon0.anon1.rst != 0 {
        ret = unsafe { snprintf(buf.offset(len as isize), size - (len as usize), c"RST ".as_ptr()) };
        len += ret;
    }
    if (*tcph).anon0.anon1.syn != 0 {
        ret = unsafe { snprintf(buf.offset(len as isize), size - (len as usize), c"SYN ".as_ptr()) };
        len += ret;
    }
    if (*tcph).anon0.anon1.fin != 0 {
        ret = unsafe { snprintf(buf.offset(len as isize), size - (len as usize), c"FIN ".as_ptr()) };
        len += ret;
    }
    /* XXX: Not TCP options implemented yet, sorry. */
    return ret;
}

