pub unsafe extern "C" fn nfq_udp_get_payload(mut udph: *mut udphdr, mut pktb: *mut pkt_buff) -> *mut core::ffi::c_void {
    let mut len: u16 = unsafe { ntohs((*udph).anon0.anon1.len) };
    /* the UDP packet is too short. */
    if (len as usize) < core::mem::size_of::<udphdr>() {
        return core::ptr::null_mut();
    }
    /* malformed UDP packet. */
    if ((*pktb).transport_header + len) > unsafe { pktb_tail(pktb) } {
        return core::ptr::null_mut();
    }
    return (((*pktb).transport_header + core::mem::size_of::<udphdr>()) as *mut core::ffi::c_void);
}

/**
 * nfq_udp_get_payload_len - get the udp packet payload.
 * \param udph: Pointer to UDP header
 * \param pktb: Pointer to userspace network packet buffer
 * \returns Length of UDP payload (user data)
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfq_udp_get_payload_len(mut udph: *mut udphdr, mut pktb: *mut pkt_buff) -> u32 {
    return (((unsafe { pktb_tail(pktb) }) - (*pktb).transport_header) - core::mem::size_of::<udphdr>()) as u32;
}

