/**
 * nfq_get_timestamp - get the packet timestamp
 * \param nfad Netlink packet data handle passed to callback function
 * \param tv structure to fill with timestamp info
 *
 * Retrieves the received timestamp when the given queued packet.
 *
 * \return 0 on success, non-zero on failure.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfq_get_timestamp(mut nfad: *mut nfq_data, mut tv: *mut timeval) -> i32 {
    let mut qpt: *mut nfqnl_msg_packet_timestamp = core::ptr::null_mut();
    // C (statement): qpt = nfnl_get_pointer_to_data ( nfad -> data , NFQA_TIMESTAMP , struct nfqnl_msg_packet_timestamp ) ;
    todo!();
    if qpt.is_null() {
        return -1;
    }
    (*tv).tv_sec = (unsafe { __be64_to_cpu((*qpt).sec) }) as i64;
    (*tv).tv_usec = (unsafe { __be64_to_cpu((*qpt).usec) }) as i64;
    return 0;
}

