/**
 * \defgroup nlmsg Netlink message helper functions
 *
 * \manonly
.SH SYNOPSIS
.nf
\fB
#include <linux/netfilter/nfnetlink_queue.h>
#include <libnetfilter_queue/libnetfilter_queue.h>
\endmanonly
 *
 * @{
 */
unsafe extern "C" fn nfq_pkt_parse_attr_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut tb: *mut *const nlattr = (data as *mut *const nlattr);
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    /* skip unsupported attribute in user-space */
    if (unsafe { mnl_attr_type_valid(attr, NFQA_MAX) }) < 0 {
        return MNL_CB_OK as i32;
    }
    match type_ {
        NFQA_MARK | NFQA_IFINDEX_INDEV | NFQA_IFINDEX_OUTDEV | NFQA_IFINDEX_PHYSINDEV | NFQA_IFINDEX_PHYSOUTDEV | NFQA_CAP_LEN | NFQA_SKB_INFO | NFQA_UID | NFQA_GID | NFQA_CT_INFO => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U32) }) < 0 {
                return MNL_CB_ERROR as i32;
            }
        }
        NFQA_TIMESTAMP => {
            if (unsafe { mnl_attr_validate2(attr, MNL_TYPE_UNSPEC, core::mem::size_of::<nfqnl_msg_packet_timestamp>()) }) < 0 {
                return MNL_CB_ERROR as i32;
            }
        }
        NFQA_HWADDR => {
            if (unsafe { mnl_attr_validate2(attr, MNL_TYPE_UNSPEC, core::mem::size_of::<nfqnl_msg_packet_hw>()) }) < 0 {
                return MNL_CB_ERROR as i32;
            }
        }
        NFQA_PACKET_HDR => {
            if (unsafe { mnl_attr_validate2(attr, MNL_TYPE_UNSPEC, core::mem::size_of::<nfqnl_msg_packet_hdr>()) }) < 0 {
                return MNL_CB_ERROR as i32;
            }
        }
        NFQA_PAYLOAD | NFQA_CT | NFQA_EXP | NFQA_SECCTX => {
        }
        _ => {}
    }
    (*tb.offset(type_ as isize)) = attr;
    return MNL_CB_OK as i32;
}

/**
 * nfq_nlmsg_parse - set packet attributes from netlink message
 * \param nlh Pointer to netlink message
 * \param attr Pointer to array of attributes to set
 * \returns MNL_CB_OK on success or MNL_CB_ERROR if any error occurs
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfq_nlmsg_parse(mut nlh: *const nlmsghdr, mut attr: *mut *mut nlattr) -> i32 {
    return (unsafe { mnl_attr_parse(nlh, core::mem::size_of::<nfgenmsg>(), Some(nfq_pkt_parse_attr_cb), attr) }) as i32;
}

/**
 * nfq_nlmsg_put - Convert memory buffer into a Netlink buffer
 * \param *buf Pointer to memory buffer
 * \param type Either NFQNL_MSG_CONFIG or NFQNL_MSG_VERDICT
 * \param queue_num Queue number
 * \returns Pointer to netlink message
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfq_nlmsg_put(mut buf: *mut core::ffi::c_char, mut type_: i32, mut queue_num: u32) -> *mut nlmsghdr {
    return unsafe { nfq_nlmsg_put2(buf, type_, queue_num, 0u16) };
}

/**
 * nfq_nlmsg_put2 - Set up a netlink header with user-specified flags
 *                  in a memory buffer
 * \param *buf Pointer to memory buffer
 * \param type One of NFQNL_MSG_CONFIG, NFQNL_MSG_VERDICT
 *             or NFQNL_MSG_VERDICT_BATCH
 * \param queue_num Queue number
 * \param flags additional NLM_F_xxx flags to put in message header. These are
 *              defined in /usr/include/linux/netlink.h. nfq_nlmsg_put2() always
 *              sets NLM_F_REQUEST
 * \returns Pointer to netlink header
 *
 * For most applications, the only sensible flag will be NLM_F_ACK.
 * Use it to get an explicit acknowledgment from the kernel, e.g.
 * attempt to configure NFQA_CFG_F_SECCTX on a kernel not supporting
 * CONFIG_NETWORK_SECMARK.
 * \n
 * The kernel always sends a message in response to a failed command.
 * NLM_F_ACK instructs the kernel to also send a message in response
 * to a successful command.
 * \n
 * This code snippet demonstrates reading these responses:
 * \verbatim
	char buf[MNL_SOCKET_BUFFER_SIZE];

	nlh = nfq_nlmsg_put2(buf, NFQNL_MSG_CONFIG, queue_num,
			     NLM_F_ACK);
	mnl_attr_put_u32(nlh, NFQA_CFG_FLAGS, NFQA_CFG_F_SECCTX);
	mnl_attr_put_u32(nlh, NFQA_CFG_MASK, NFQA_CFG_F_SECCTX);

	if (mnl_socket_sendto(nl, nlh, nlh->nlmsg_len) < 0) {
		perror("mnl_socket_send");
		exit(EXIT_FAILURE);
	}

	ret = mnl_socket_recvfrom(nl, buf, sizeof buf);
	if (ret == -1) {
		perror("mnl_socket_recvfrom");
		exit(EXIT_FAILURE);
	}

	ret = mnl_cb_run(buf, ret, 0, portid, NULL, NULL);
	if (ret == -1)
		fprintf(stderr, "This kernel version does not allow to "
				"retrieve security context.\n");
\endverbatim
 *
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nfq_nlmsg_put2(mut buf: *mut core::ffi::c_char, mut type_: i32, mut queue_num: u32, mut flags: u16) -> *mut nlmsghdr {
    let mut nlh: *mut nlmsghdr = (unsafe { mnl_nlmsg_put_header(buf) } as *mut nlmsghdr);
    (*nlh).nlmsg_type = (768 | type_) as u16;
    (*nlh).nlmsg_flags = (1 | (flags as i32)) as u16;
    let mut nfg: *mut nfgenmsg = (unsafe { mnl_nlmsg_put_extra_header(nlh, core::mem::size_of::<nfgenmsg>()) } as *mut nfgenmsg);
    (*nfg).nfgen_family = 0u8;
    (*nfg).version = 0u8;
    (*nfg).res_id = unsafe { htons(queue_num as u16) };
    return nlh;
}

