/* returns packet id */
unsafe extern "C" fn print_pkt(mut tb: *mut nfq_data) -> u32 {
    let mut id: i32 = 0;
    let mut ph: *mut nfqnl_msg_packet_hdr = core::ptr::null_mut();
    let mut hwph: *mut nfqnl_msg_packet_hw = core::ptr::null_mut();
    let mut mark: u32 = 0;
    let mut ifi: u32 = 0;
    let mut uid: u32 = 0;
    let mut gid: u32 = 0;
    let mut ret: i32 = 0;
    let mut data: *mut u8 = core::ptr::null_mut();
    let mut secdata: *mut u8 = core::ptr::null_mut();
    ph = (unsafe { nfq_get_msg_packet_hdr(tb) } as *mut nfqnl_msg_packet_hdr);
    if !ph.is_null() {
        id = (unsafe { ntohl((*ph).packet_id) }) as i32;
        unsafe { printf(c"hw_protocol=0x%04x hook=%u id=%u ".as_ptr(), (unsafe { ntohs((*ph).hw_protocol) } as i32), ((*ph).hook as i32), id) };
    }
    hwph = (unsafe { nfq_get_packet_hw(tb) } as *mut nfqnl_msg_packet_hw);
    if !hwph.is_null() {
        let mut i: i32 = 0;
        let mut hlen: i32 = (unsafe { ntohs((*hwph).hw_addrlen) }) as i32;
        unsafe { printf(c"hw_src_addr=".as_ptr()) };
        {
            i = 0;
            while i < (hlen - 1) {
                unsafe { printf(c"%02x:".as_ptr(), ((*hwph).hw_addr[i as usize] as i32)) };
                i += 1;
            }
        }
        unsafe { printf(c"%02x ".as_ptr(), ((*hwph).hw_addr[(hlen - 1) as usize] as i32)) };
    }
    mark = (unsafe { nfq_get_nfmark(tb) }) as u32;
    if mark != 0 {
        unsafe { printf(c"mark=%u ".as_ptr(), mark) };
    }
    ifi = (unsafe { nfq_get_indev(tb) }) as u32;
    if ifi != 0 {
        unsafe { printf(c"indev=%u ".as_ptr(), ifi) };
    }
    ifi = (unsafe { nfq_get_outdev(tb) }) as u32;
    if ifi != 0 {
        unsafe { printf(c"outdev=%u ".as_ptr(), ifi) };
    }
    ifi = (unsafe { nfq_get_physindev(tb) }) as u32;
    if ifi != 0 {
        unsafe { printf(c"physindev=%u ".as_ptr(), ifi) };
    }
    ifi = (unsafe { nfq_get_physoutdev(tb) }) as u32;
    if ifi != 0 {
        unsafe { printf(c"physoutdev=%u ".as_ptr(), ifi) };
    }
    if unsafe { nfq_get_uid(tb, &raw mut uid) } != 0 {
        unsafe { printf(c"uid=%u ".as_ptr(), uid) };
    }
    if unsafe { nfq_get_gid(tb, &raw mut gid) } != 0 {
        unsafe { printf(c"gid=%u ".as_ptr(), gid) };
    }
    ret = (unsafe { nfq_get_secctx(tb, &raw mut secdata) }) as i32;
    if ret > 0 {
        unsafe { printf(c"secctx=\"%.*s\" ".as_ptr(), ret, secdata) };
    }
    ret = (unsafe { nfq_get_payload(tb, &raw mut data) }) as i32;
    if ret >= 0 {
        unsafe { printf(c"payload_len=%d ".as_ptr(), ret) };
    }
    unsafe { fputc(10, stdout) };
    return id as u32;
}

unsafe extern "C" fn cb(mut qh: *mut nfq_q_handle, mut nfmsg: *mut nfgenmsg, mut nfa: *mut nfq_data, mut data: *mut core::ffi::c_void) -> i32 {
    let mut id: u32 = unsafe { print_pkt(nfa) };
    unsafe { printf(c"entering callback\n".as_ptr()) };
    return (unsafe { nfq_set_verdict(qh, id, NF_ACCEPT, 0, core::ptr::null_mut()) }) as i32;
}

unsafe extern "C" fn c_main(mut argc: i32, mut argv: *mut *mut core::ffi::c_char) -> i32 {
    let mut h: *mut nfq_handle = core::ptr::null_mut();
    let mut qh: *mut nfq_q_handle = core::ptr::null_mut();
    let mut fd: i32 = 0;
    let mut rv: i32 = 0;
    let mut queue: u32 = 0u32;
    let mut buf: [core::ffi::c_char; 4096] = [0; 4096];
    if argc == 2 {
        queue = (unsafe { atoi(((*argv.offset(1)) as *const core::ffi::c_char)) }) as u32;
        if queue > (65535 as u32) {
            unsafe { fprintf(stderr, c"Usage: %s [<0-65535>]\n".as_ptr(), (*argv.offset(0))) };
            unsafe { exit(1) };
        }
    }
    unsafe { printf(c"opening library handle\n".as_ptr()) };
    h = (unsafe { nfq_open() } as *mut nfq_handle);
    if h.is_null() {
        unsafe { fprintf(stderr, c"error during nfq_open()\n".as_ptr()) };
        unsafe { exit(1) };
    }
    unsafe { printf(c"unbinding existing nf_queue handler for AF_INET (if any)\n".as_ptr()) };
    if (unsafe { nfq_unbind_pf(h, AF_INET) }) < 0 {
        unsafe { fprintf(stderr, c"error during nfq_unbind_pf()\n".as_ptr()) };
        unsafe { exit(1) };
    }
    unsafe { printf(c"binding nfnetlink_queue as nf_queue handler for AF_INET\n".as_ptr()) };
    if (unsafe { nfq_bind_pf(h, AF_INET) }) < 0 {
        unsafe { fprintf(stderr, c"error during nfq_bind_pf()\n".as_ptr()) };
        unsafe { exit(1) };
    }
    unsafe { printf(c"binding this socket to queue '%d'\n".as_ptr(), queue) };
    qh = (unsafe { nfq_create_queue(h, queue, Some((cb as *const ())), core::ptr::null_mut()) } as *mut nfq_q_handle);
    if qh.is_null() {
        unsafe { fprintf(stderr, c"error during nfq_create_queue()\n".as_ptr()) };
        unsafe { exit(1) };
    }
    unsafe { printf(c"setting copy_packet mode\n".as_ptr()) };
    if (unsafe { nfq_set_mode(qh, NFQNL_COPY_PACKET, 65535) }) < 0 {
        unsafe { fprintf(stderr, c"can't set packet_copy mode\n".as_ptr()) };
        unsafe { exit(1) };
    }
    unsafe { printf(c"setting flags to request UID and GID\n".as_ptr()) };
    if unsafe { nfq_set_queue_flags(qh, NFQA_CFG_F_UID_GID, NFQA_CFG_F_UID_GID) } != 0 {
        unsafe { fprintf(stderr, c"This kernel version does not allow to retrieve process UID/GID.\n".as_ptr()) };
    }
    unsafe { printf(c"setting flags to request security context\n".as_ptr()) };
    if unsafe { nfq_set_queue_flags(qh, NFQA_CFG_F_SECCTX, NFQA_CFG_F_SECCTX) } != 0 {
        unsafe { fprintf(stderr, c"This kernel version does not allow to retrieve security context.\n".as_ptr()) };
    }
    unsafe { printf(c"Waiting for packets...\n".as_ptr()) };
    fd = (unsafe { nfq_fd(h) }) as i32;
    loop {
        if ({ let __v = (unsafe { recv(fd, (buf.as_mut_ptr() as *mut core::ffi::c_void), core::mem::size_of::<[core::ffi::c_char; 4096]>(), 0) }) as i32; rv = __v; __v }) >= 0 {
            unsafe { printf(c"pkt received\n".as_ptr()) };
            unsafe { nfq_handle_packet(h, buf.as_mut_ptr(), rv) };
            continue;
        }
        /* if your application is too slow to digest the packets that
        		 * are sent from kernel-space, the socket buffer that we use
        		 * to enqueue packets may fill up returning ENOBUFS. Depending
        		 * on your application, this error may be ignored. Please, see
        		 * the doxygen documentation of this library on how to improve
        		 * this situation.
        		 */
        if (rv < 0) && ((*unsafe { __errno_location() }) == ENOBUFS) {
            unsafe { printf(c"losing packets!\n".as_ptr()) };
            continue;
        }
        unsafe { perror(c"recv failed".as_ptr()) };
        break;
    }
    unsafe { printf(c"unbinding from queue 0\n".as_ptr()) };
    unsafe { nfq_destroy_queue(qh) };
    /* normally, applications SHOULD NOT issue this command, since
    	 * it detaches other programs/sockets from AF_INET, too ! */
    unsafe { printf(c"closing library handle\n".as_ptr()) };
    unsafe { nfq_close(h) };
    unsafe { exit(0) };
    unsafe { core::mem::zeroed() }
}

