#[unsafe(no_mangle)]
pub unsafe extern "C" fn nftnl_parse_perror(mut msg: *const core::ffi::c_char, mut err: *mut nftnl_parse_err) -> i32 {
    match (*err).error {
        NFTNL_PARSE_EBADINPUT => {
            return unsafe { fprintf(stderr, c"%s: Bad input format in line %d column %d\n".as_ptr(), msg, (*err).line, (*err).column) };
        }
        NFTNL_PARSE_EMISSINGNODE => {
            return unsafe { fprintf(stderr, c"%s: Node \"%s\" not found\n".as_ptr(), msg, (*err).node_name) };
        }
        NFTNL_PARSE_EBADTYPE => {
            return unsafe { fprintf(stderr, c"%s: Invalid type in node \"%s\"\n".as_ptr(), msg, (*err).node_name) };
        }
        NFTNL_PARSE_EOPNOTSUPP => {
            return unsafe { fprintf(stderr, c"%s: Operation not supported\n".as_ptr(), msg) };
        }
        _ => {
            return unsafe { fprintf(stderr, c"%s: Undefined error\n".as_ptr(), msg) };
        }
    }
    unsafe { core::mem::zeroed() }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn nftnl_batch_is_supported() -> i32 {
    let mut nl: *mut mnl_socket = core::ptr::null_mut();
    let mut b: *mut mnl_nlmsg_batch = core::ptr::null_mut();
    let mut __buf_storage: Vec<core::ffi::c_char> = vec![unsafe { core::mem::zeroed() }; (MNL_SOCKET_BUFFER_SIZE) as usize];
    let buf: *mut core::ffi::c_char = __buf_storage.as_mut_ptr();
    let mut seq: u32 = (unsafe { time(core::ptr::null_mut()) }) as u32;
    let mut req_seq: u32 = 0;
    let mut ret: i32 = 0;
    nl = (unsafe { mnl_socket_open(NETLINK_NETFILTER) } as *mut mnl_socket);
    if nl.is_null() {
        return -1;
    }
    if (unsafe { mnl_socket_bind(nl, 0, MNL_SOCKET_AUTOPID) }) < 0 {
        return -1;
    }
    b = (unsafe { mnl_nlmsg_batch_start(buf, core::mem::size_of::<*mut core::ffi::c_char>()) } as *mut mnl_nlmsg_batch);
    unsafe { nftnl_batch_begin((unsafe { mnl_nlmsg_batch_current(b) } as *mut core::ffi::c_char), { let __old = seq; seq += 1; __old }) };
    unsafe { mnl_nlmsg_batch_next(b) };
    req_seq = seq;
    unsafe { nftnl_nlmsg_build_hdr((unsafe { mnl_nlmsg_batch_current(b) } as *mut core::ffi::c_char), 9u16, 2u16, 4u16, { let __old = seq; seq += 1; __old }) };
    unsafe { mnl_nlmsg_batch_next(b) };
    unsafe { nftnl_batch_end((unsafe { mnl_nlmsg_batch_current(b) } as *mut core::ffi::c_char), { let __old = seq; seq += 1; __old }) };
    unsafe { mnl_nlmsg_batch_next(b) };
    ret = (unsafe { mnl_socket_sendto(nl, unsafe { mnl_nlmsg_batch_head(b) }, unsafe { mnl_nlmsg_batch_size(b) }) }) as i32;
    'g_err: {
        if ret < 0 {
            break 'g_err;
        }
        unsafe { mnl_nlmsg_batch_stop(b) };
        ret = (unsafe { mnl_socket_recvfrom(nl, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
        while ret > 0 {
            ret = (unsafe { mnl_cb_run(buf, ret, req_seq, unsafe { mnl_socket_get_portid(nl) }, core::ptr::null_mut(), core::ptr::null_mut()) }) as i32;
            if ret <= 0 {
                break;
            }
            ret = (unsafe { mnl_socket_recvfrom(nl, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
        }
        unsafe { mnl_socket_close(nl) };
        /* We're sending an incomplete message to see if the kernel supports
    	 * set messages in batches. EINVAL means that we sent an incomplete
    	 * message with missing attributes. The kernel just ignores messages
    	 * that we cannot include in the batch.
    	 */
        return (if ((ret == -1) && ((*unsafe { __errno_location() }) == EINVAL)) { 1 } else { 0 });
    }
    unsafe { mnl_nlmsg_batch_stop(b) };
    return -1;
}

