#[unsafe(no_mangle)]
pub unsafe extern "C" fn nftnl_expr_alloc(mut name: *const core::ffi::c_char) -> *mut nftnl_expr {
    let mut expr: *mut nftnl_expr = core::ptr::null_mut();
    let mut ops: *mut expr_ops = core::ptr::null_mut();
    ops = (unsafe { nftnl_expr_ops_lookup(name) } as *mut expr_ops);
    if ops.is_null() {
        return core::ptr::null_mut();
    }
    expr = (unsafe { calloc(1usize, (core::mem::size_of::<nftnl_expr>() + (*ops).alloc_len) as usize) } as *mut nftnl_expr);
    if expr.is_null() {
        return core::ptr::null_mut();
    }
    /* Manually set expression name attribute */
    (*expr).flags |= 1;
    (*expr).ops = ops;
    if (*ops).init != 0 {
        unsafe { ((*ops).init.unwrap())(expr) };
    }
    return expr;
}

