unsafe extern "C" fn nftnl_expr_hash_snprintf(mut buf: *mut core::ffi::c_char, mut remain: usize, mut flags: u32, mut e: *const nftnl_expr) -> i32 {
    let mut hash: *mut nftnl_expr_hash = (unsafe { nftnl_expr_data(e) } as *mut nftnl_expr_hash);
    let mut offset: i32 = 0;
    let mut ret: i32 = 0;
    match (*hash).type_ {
        NFT_HASH_SYM => {
            ret = unsafe { snprintf(buf, remain, c"reg %u = symhash() %% mod %u ".as_ptr(), (*hash).dreg, (*hash).modulus) };
            unsafe { SNPRINTF_BUFFER_SIZE(ret, remain, offset) };
        }
        _ => {
            ret = unsafe { snprintf(buf, remain, c"reg %u = jhash(reg %u, %u, 0x%x) %% mod %u ".as_ptr(), (*hash).dreg, (*hash).sreg, (*hash).len, (*hash).seed, (*hash).modulus) };
            unsafe { SNPRINTF_BUFFER_SIZE(ret, remain, offset) };
        }
    }
    if (*hash).offset != 0 {
        ret = unsafe { snprintf(buf.offset(offset as isize), remain, c"offset %u ".as_ptr(), (*hash).offset) };
        unsafe { SNPRINTF_BUFFER_SIZE(ret, remain, offset) };
    }
    return offset;
}

