unsafe extern "C" fn nftnl_expr_immediate_build(mut nlh: *mut nlmsghdr, mut e: *const nftnl_expr) {
    let mut imm: *mut nftnl_expr_immediate = (unsafe { nftnl_expr_data(e) } as *mut nftnl_expr_immediate);
    if ((*e).flags & 2) != 0 {
        unsafe { mnl_attr_put_u32(nlh, NFTA_IMMEDIATE_DREG, unsafe { htonl((*imm).dreg as u32) }) };
    }
    /* Sane configurations allows you to set ONLY one of these two below */
    if ((*e).flags & 4) != 0 {
        let mut nest: *mut nlattr = core::ptr::null_mut();
        nest = (unsafe { mnl_attr_nest_start(nlh, NFTA_IMMEDIATE_DATA) } as *mut nlattr);
        unsafe { mnl_attr_put(nlh, NFTA_DATA_VALUE, (*imm).data.len, (*imm).data.val) };
        unsafe { mnl_attr_nest_end(nlh, nest) };
    } else if ((*e).flags & 8) != 0 {
        let mut nest1: *mut nlattr = core::ptr::null_mut();
        let mut nest2: *mut nlattr = core::ptr::null_mut();
        nest1 = (unsafe { mnl_attr_nest_start(nlh, NFTA_IMMEDIATE_DATA) } as *mut nlattr);
        nest2 = (unsafe { mnl_attr_nest_start(nlh, NFTA_DATA_VERDICT) } as *mut nlattr);
        unsafe { mnl_attr_put_u32(nlh, NFTA_VERDICT_CODE, unsafe { htonl((*imm).data.verdict as u32) }) };
        if ((*e).flags & 16) != 0 {
            unsafe { mnl_attr_put_strz(nlh, NFTA_VERDICT_CHAIN, (*imm).data.chain) };
        }
        if ((*e).flags & 32) != 0 {
            unsafe { mnl_attr_put_u32(nlh, NFTA_VERDICT_CHAIN_ID, unsafe { htonl((*imm).data.chain_id as u32) }) };
        }
        unsafe { mnl_attr_nest_end(nlh, nest1) };
        unsafe { mnl_attr_nest_end(nlh, nest2) };
    }
}

