unsafe extern "C" fn nftnl_expr_immediate_snprintf(mut buf: *mut core::ffi::c_char, mut remain: usize, mut flags: u32, mut e: *const nftnl_expr) -> i32 {
    let mut imm: *mut nftnl_expr_immediate = (unsafe { nftnl_expr_data(e) } as *mut nftnl_expr_immediate);
    let mut offset: i32 = 0;
    let mut ret: i32 = 0;
    ret = unsafe { snprintf(buf, remain, c"reg %u ".as_ptr(), (*imm).dreg) };
    unsafe { SNPRINTF_BUFFER_SIZE(ret, remain, offset) };
    if ((*e).flags & 4) != 0 {
        ret = (unsafe { nftnl_data_reg_snprintf(buf.offset(offset as isize), remain, &raw mut (*imm).data, flags, DATA_VALUE) }) as i32;
        unsafe { SNPRINTF_BUFFER_SIZE(ret, remain, offset) };
    } else if ((*e).flags & 8) != 0 {
        ret = (unsafe { nftnl_data_reg_snprintf(buf.offset(offset as isize), remain, &raw mut (*imm).data, flags, DATA_VERDICT) }) as i32;
        unsafe { SNPRINTF_BUFFER_SIZE(ret, remain, offset) };
    } else if ((*e).flags & 16) != 0 {
        ret = (unsafe { nftnl_data_reg_snprintf(buf.offset(offset as isize), remain, &raw mut (*imm).data, flags, DATA_CHAIN) }) as i32;
        unsafe { SNPRINTF_BUFFER_SIZE(ret, remain, offset) };
    }
    ret = unsafe { snprintf(buf.offset(offset as isize), remain, c" ".as_ptr()) };
    unsafe { SNPRINTF_BUFFER_SIZE(ret, remain, offset) };
    return offset;
}

