unsafe extern "C" fn get_time(mut seconds: u64, mut val: *mut u64) -> *const core::ffi::c_char {
    static mut units: [Anonf2fecea2; 5] = [Anonf2fecea2 { size: 0u32, name: c"second".as_ptr() }, Anonf2fecea2 { size: 60u32, name: c"minute".as_ptr() }, Anonf2fecea2 { size: 60u32, name: c"hour".as_ptr() }, Anonf2fecea2 { size: 24u32, name: c"day".as_ptr() }, Anonf2fecea2 { size: 7u32, name: c"week".as_ptr() }];
    let mut i: i32 = 0;
    {
        i = 1;
        'b0: while i < unsafe { array_size(units.as_mut_ptr()) } {
            if (seconds % ((units[i as usize].size) as u64)) != 0 {
                break 'b0;
            }
            seconds /= ((units[i as usize].size) as u64);
            i += 1;
        }
    }
    if !val.is_null() {
        (*val) = seconds;
    }
    return units[(i - 1) as usize].name;
}

