unsafe extern "C" fn nftnl_obj_parse_attr_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut tb: *mut *const nlattr = (data as *mut *const nlattr);
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    if (unsafe { mnl_attr_type_valid(attr, NFTA_OBJ_MAX) }) < 0 {
        return MNL_CB_OK as i32;
    }
    match type_ {
        NFTA_OBJ_TABLE | NFTA_OBJ_NAME => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_STRING) }) < 0 {
                unsafe { __abi_breakage((c"".as_ptr() as *const core::ffi::c_char), 0 as i32, (unsafe { strerror(*unsafe { __errno_location() }) } as *const core::ffi::c_char)) };
            }
        }
        NFTA_OBJ_HANDLE => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U64) }) < 0 {
                unsafe { __abi_breakage((c"".as_ptr() as *const core::ffi::c_char), 0 as i32, (unsafe { strerror(*unsafe { __errno_location() }) } as *const core::ffi::c_char)) };
            }
        }
        NFTA_OBJ_DATA => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_NESTED) }) < 0 {
                unsafe { __abi_breakage((c"".as_ptr() as *const core::ffi::c_char), 0 as i32, (unsafe { strerror(*unsafe { __errno_location() }) } as *const core::ffi::c_char)) };
            }
        }
        NFTA_OBJ_USE => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U32) }) < 0 {
                unsafe { __abi_breakage((c"".as_ptr() as *const core::ffi::c_char), 0 as i32, (unsafe { strerror(*unsafe { __errno_location() }) } as *const core::ffi::c_char)) };
            }
        }
        NFTA_OBJ_USERDATA => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_BINARY) }) < 0 {
                unsafe { __abi_breakage((c"".as_ptr() as *const core::ffi::c_char), 0 as i32, (unsafe { strerror(*unsafe { __errno_location() }) } as *const core::ffi::c_char)) };
            }
        }
        _ => {}
    }
    (*tb.offset(type_ as isize)) = attr;
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn nftnl_obj_snprintf_dflt(mut buf: *mut core::ffi::c_char, mut remain: usize, mut obj: *const nftnl_obj, mut type_: u32, mut flags: u32) -> i32 {
    let mut name: *const core::ffi::c_char = (if !(*obj).ops.is_null() { (*(*obj).ops).name } else { c"(unknown)".as_ptr() });
    let mut ret: i32 = 0;
    let mut offset: i32 = 0;
    ret = unsafe { snprintf(buf, remain, c"table %s name %s use %u [ %s ".as_ptr(), (*obj).table, (*obj).name, (*obj).use_, name) };
    if ret < 0 {
        ret = 0;
    }
    offset += ret;
    if (ret as usize) > remain {
        ret = remain as i32;
    }
    remain -= ((ret) as usize);
    if !(*obj).ops.is_null() {
        ret = unsafe { ((*(*obj).ops).output.unwrap())(buf.offset(offset as isize), remain, flags, obj) };
        if ret < 0 {
            ret = 0;
        }
        offset += ret;
        if (ret as usize) > remain {
            ret = remain as i32;
        }
        remain -= ((ret) as usize);
    }
    ret = unsafe { snprintf(buf.offset(offset as isize), remain, c"]".as_ptr()) };
    if ret < 0 {
        ret = 0;
    }
    offset += ret;
    if (ret as usize) > remain {
        ret = remain as i32;
    }
    remain -= ((ret) as usize);
    return offset;
}

unsafe extern "C" fn nftnl_obj_cmd_snprintf(mut buf: *mut core::ffi::c_char, mut remain: usize, mut obj: *const nftnl_obj, mut cmd: u32, mut type_: u32, mut flags: u32) -> i32 {
    let mut ret: i32 = 0;
    let mut offset: i32 = 0;
    if type_ != (NFTNL_OUTPUT_DEFAULT as u32) {
        return -1;
    }
    ret = unsafe { nftnl_obj_snprintf_dflt(buf.offset(offset as isize), remain, obj, type_, flags) };
    if ret < 0 {
        ret = 0;
    }
    offset += ret;
    if (ret as usize) > remain {
        ret = remain as i32;
    }
    remain -= ((ret) as usize);
    return offset;
}

unsafe extern "C" fn nftnl_obj_do_snprintf(mut buf: *mut core::ffi::c_char, mut size: usize, mut obj: *const core::ffi::c_void, mut cmd: u32, mut type_: u32, mut flags: u32) -> i32 {
    return unsafe { nftnl_obj_snprintf(buf, size, (obj as *const nftnl_obj), type_, flags) };
}

