unsafe extern "C" fn nftnl_ruleset_cb(mut ctx: *const nftnl_parse_ctx) -> i32 {
    let mut r: *mut nftnl_ruleset = ((*ctx).data as *mut nftnl_ruleset);
    if (*ctx).cmd != NFTNL_CMD_ADD {
        return -1;
    }
    match (*ctx).type_ {
        NFTNL_RULESET_TABLE => {
            if (*r).table_list.is_null() {
                (*r).table_list = unsafe { nftnl_table_list_alloc() };
                if (*r).table_list.is_null() {
                    return -1;
                }
                unsafe { nftnl_ruleset_set(r, 0u16, ((*r).table_list as *mut core::ffi::c_void)) };
            }
            unsafe { nftnl_table_list_add_tail((*ctx).anon2.table, (*r).table_list) };
        }
        NFTNL_RULESET_CHAIN => {
            if (*r).chain_list.is_null() {
                (*r).chain_list = unsafe { nftnl_chain_list_alloc() };
                if (*r).chain_list.is_null() {
                    return -1;
                }
                unsafe { nftnl_ruleset_set(r, 1u16, ((*r).chain_list as *mut core::ffi::c_void)) };
            }
            unsafe { nftnl_chain_list_add_tail((*ctx).anon2.chain, (*r).chain_list) };
        }
        NFTNL_RULESET_SET => {
            if (*r).set_list.is_null() {
                (*r).set_list = unsafe { nftnl_set_list_alloc() };
                if (*r).set_list.is_null() {
                    return -1;
                }
                unsafe { nftnl_ruleset_set(r, 2u16, ((*r).set_list as *mut core::ffi::c_void)) };
            }
            unsafe { nftnl_set_list_add_tail((*ctx).anon2.set, (*r).set_list) };
        }
        NFTNL_RULESET_RULE => {
            if (*r).rule_list.is_null() {
                (*r).rule_list = unsafe { nftnl_rule_list_alloc() };
                if (*r).rule_list.is_null() {
                    return -1;
                }
                unsafe { nftnl_ruleset_set(r, 3u16, ((*r).rule_list as *mut core::ffi::c_void)) };
            }
            unsafe { nftnl_rule_list_add_tail((*ctx).anon2.rule, (*r).rule_list) };
        }
        NFTNL_RULESET_RULESET => {
        }
        _ => {
            return -1;
        }
    }
    return 0;
}

