unsafe extern "C" fn nftnl_set_parse_attr_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut tb: *mut *const nlattr = (data as *mut *const nlattr);
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    if (unsafe { mnl_attr_type_valid(attr, NFTA_SET_MAX) }) < 0 {
        return MNL_CB_OK as i32;
    }
    match type_ {
        NFTA_SET_TABLE | NFTA_SET_NAME | NFTA_SET_TYPE => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_STRING) }) < 0 {
                unsafe { abi_breakage() };
            }
        }
        NFTA_SET_HANDLE => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U64) }) < 0 {
                unsafe { abi_breakage() };
            }
        }
        NFTA_SET_FLAGS | NFTA_SET_KEY_TYPE | NFTA_SET_KEY_LEN | NFTA_SET_DATA_TYPE | NFTA_SET_DATA_LEN | NFTA_SET_ID | NFTA_SET_POLICY | NFTA_SET_GC_INTERVAL | NFTA_SET_COUNT => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U32) }) < 0 {
                unsafe { abi_breakage() };
            }
        }
        NFTA_SET_USERDATA => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_BINARY) }) < 0 {
                unsafe { abi_breakage() };
            }
        }
        NFTA_SET_TIMEOUT => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U64) }) < 0 {
                unsafe { abi_breakage() };
            }
        }
        NFTA_SET_DESC | NFTA_SET_EXPR | NFTA_SET_EXPRESSIONS => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_NESTED) }) < 0 {
                unsafe { abi_breakage() };
            }
        }
        _ => {}
    }
    (*tb.offset(type_ as isize)) = attr;
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn nftnl_set_desc_concat_field_parse_attr_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    let mut s: *mut nftnl_set = (data as *mut nftnl_set);
    if type_ != NFTA_SET_FIELD_LEN {
        return MNL_CB_OK as i32;
    }
    if unsafe { mnl_attr_validate(attr, MNL_TYPE_U32) } != 0 {
        return MNL_CB_ERROR as i32;
    }
    // C (statement): s -> desc . field_len [ s -> desc . field_count ] = ntohl ( mnl_attr_get_u32 ( attr ) ) ;
    todo!();
    (*s).desc.field_count += 1;
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn nftnl_set_desc_concat_parse_attr_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    let mut s: *mut nftnl_set = (data as *mut nftnl_set);
    if type_ != NFTA_LIST_ELEM {
        return MNL_CB_OK as i32;
    }
    return (unsafe { mnl_attr_parse_nested(attr, Some(nftnl_set_desc_concat_field_parse_attr_cb), s) }) as i32;
}

unsafe extern "C" fn nftnl_set_desc_parse_attr_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    let mut err: i32 = 0;
    let mut s: *mut nftnl_set = (data as *mut nftnl_set);
    if (unsafe { mnl_attr_type_valid(attr, NFTA_SET_DESC_MAX) }) < 0 {
        return MNL_CB_OK as i32;
    }
    'b0: {
        match type_ {
            NFTA_SET_DESC_SIZE => {
                if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U32) }) < 0 {
                    unsafe { abi_breakage() };
                    break 'b0;
                }
                (*s).desc.size = unsafe { ntohl((unsafe { mnl_attr_get_u32(attr) }) as u32) };
                (*s).flags |= 1024;
            }
            NFTA_SET_DESC_CONCAT => {
                err = (unsafe { mnl_attr_parse_nested(attr, Some(nftnl_set_desc_concat_parse_attr_cb), s) }) as i32;
                if err != MNL_CB_OK {
                    unsafe { abi_breakage() };
                }
                (*s).flags |= 65536;
            }
            _ => {
            }
        }
    }
    return MNL_CB_OK as i32;
}

