pub unsafe extern "C" fn nftnl_flag2cmd(mut flags: u32) -> nftnl_cmd_type {
    if (flags & (NFTNL_OF_EVENT_NEW as u32)) != 0 {
        return 1;
    } else if (flags & (NFTNL_OF_EVENT_DEL as u32)) != 0 {
        return 3;
    }
    return 0;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn nftnl_fprintf(mut fp: *mut core::ffi::c_void, mut obj: *const core::ffi::c_void, mut cmd: u32, mut type_: u32, mut flags: u32, mut snprintf_cb: Option<unsafe extern "C" fn(*mut core::ffi::c_char, usize, *const core::ffi::c_void, u32, u32, u32) -> i32>) -> i32 {
    let mut _buf: [core::ffi::c_char; 4096] = [0; 4096];
    let mut buf: *mut core::ffi::c_char = (_buf.as_mut_ptr() as *mut core::ffi::c_char);
    let mut bufsiz: usize = core::mem::size_of::<[core::ffi::c_char; 4096]>();
    let mut ret: i32 = 0;
    ret = unsafe { (snprintf_cb.unwrap())(buf, bufsiz, obj, cmd, type_, flags) };
    'g_out: {
        if ret <= 0 {
            break 'g_out;
        }
        if ret >= 4096 {
            bufsiz = (ret + 1) as usize;
            buf = (unsafe { malloc(bufsiz) } as *mut core::ffi::c_char);
            if buf.is_null() {
                return -1;
            }
            ret = unsafe { (snprintf_cb.unwrap())(buf, bufsiz, obj, cmd, type_, flags) };
            if ret <= 0 {
                break 'g_out;
            }
        }
        ret = unsafe { fprintf(fp, c"%s".as_ptr(), buf) };
    }
    if buf != (_buf.as_mut_ptr() as *mut core::ffi::c_char) {
        unsafe { xfree(buf) };
    }
    return ret;
}

