unsafe extern "C" fn cmp_devices(mut adevs: *mut *const core::ffi::c_char, mut bdevs: *mut *const core::ffi::c_char) {
    let mut i: i32 = 0;
    if adevs.is_null() && bdevs.is_null() {
        return;
    }
    if ((!adevs.is_null() as i32) ^ (!bdevs.is_null() as i32)) != 0 {
        unsafe { print_err(c"Chain devices mismatches".as_ptr()) };
    }
    {
        i = 0;
        'b0: while !(*adevs.offset(i as isize)).is_null() && !(*bdevs.offset(i as isize)).is_null() {
            if unsafe { strcmp(((*adevs.offset(i as isize)) as *const core::ffi::c_char), ((*bdevs.offset(i as isize)) as *const core::ffi::c_char)) } != 0 {
                break 'b0;
            }
            i += 1;
        }
    }
    if !(*adevs.offset(i as isize)).is_null() || !(*bdevs.offset(i as isize)).is_null() {
        unsafe { print_err(c"Chain devices mismatches".as_ptr()) };
    }
}

unsafe extern "C" fn cmp_nftnl_chain(mut a: *mut nftnl_chain, mut b: *mut nftnl_chain) {
    if (unsafe { strcmp(unsafe { nftnl_chain_get_str((a as *const nftnl_chain), 0u16) }, unsafe { nftnl_chain_get_str((b as *const nftnl_chain), 0u16) }) }) != 0 {
        unsafe { print_err(c"Chain name mismatches".as_ptr()) };
    }
    if (unsafe { strcmp(unsafe { nftnl_chain_get_str((a as *const nftnl_chain), 2u16) }, unsafe { nftnl_chain_get_str((b as *const nftnl_chain), 2u16) }) }) != 0 {
        unsafe { print_err(c"Chain table mismatches".as_ptr()) };
    }
    if (unsafe { nftnl_chain_get_u32((a as *const nftnl_chain), 1u16) }) != unsafe { nftnl_chain_get_u32((b as *const nftnl_chain), 1u16) } {
        unsafe { print_err(c"Chain family mismatches".as_ptr()) };
    }
    if (unsafe { nftnl_chain_get_u32((a as *const nftnl_chain), 5u16) }) != unsafe { nftnl_chain_get_u32((b as *const nftnl_chain), 5u16) } {
        unsafe { print_err(c"Chain policy mismatches".as_ptr()) };
    }
    if (unsafe { nftnl_chain_get_u32((a as *const nftnl_chain), 3u16) }) != unsafe { nftnl_chain_get_u32((b as *const nftnl_chain), 3u16) } {
        unsafe { print_err(c"Chain hooknum mismatches".as_ptr()) };
    }
    if (unsafe { nftnl_chain_get_s32((a as *const nftnl_chain), 4u16) }) != unsafe { nftnl_chain_get_s32((b as *const nftnl_chain), 4u16) } {
        unsafe { print_err(c"Chain Prio mismatches".as_ptr()) };
    }
    if (unsafe { nftnl_chain_get_u32((a as *const nftnl_chain), 6u16) }) != unsafe { nftnl_chain_get_u32((b as *const nftnl_chain), 6u16) } {
        unsafe { print_err(c"Chain use mismatches".as_ptr()) };
    }
    if (unsafe { nftnl_chain_get_u64((a as *const nftnl_chain), 8u16) }) != unsafe { nftnl_chain_get_u64((b as *const nftnl_chain), 8u16) } {
        unsafe { print_err(c"Chain packets mismatches".as_ptr()) };
    }
    if (unsafe { nftnl_chain_get_u64((a as *const nftnl_chain), 7u16) }) != unsafe { nftnl_chain_get_u64((b as *const nftnl_chain), 7u16) } {
        unsafe { print_err(c"Chain bytes mismatches".as_ptr()) };
    }
    if (unsafe { nftnl_chain_get_u64((a as *const nftnl_chain), 9u16) }) != unsafe { nftnl_chain_get_u64((b as *const nftnl_chain), 9u16) } {
        unsafe { print_err(c"Chain handle mismatches".as_ptr()) };
    }
    if (unsafe { strcmp(unsafe { nftnl_chain_get_str((a as *const nftnl_chain), 10u16) }, unsafe { nftnl_chain_get_str((b as *const nftnl_chain), 10u16) }) }) != 0 {
        unsafe { print_err(c"Chain type mismatches".as_ptr()) };
    }
    if unsafe { nftnl_chain_is_set((a as *const nftnl_chain), 11u16) } && ((unsafe { strcmp(unsafe { nftnl_chain_get_str((a as *const nftnl_chain), 11u16) }, unsafe { nftnl_chain_get_str((b as *const nftnl_chain), 11u16) }) }) != 0) {
        unsafe { print_err(c"Chain device mismatches".as_ptr()) };
    }
    unsafe { cmp_devices(unsafe { nftnl_chain_get_array((a as *const nftnl_chain), 12u16) }, unsafe { nftnl_chain_get_array((b as *const nftnl_chain), 12u16) }) };
}

unsafe extern "C" fn c_main(mut argc: i32, mut argv: *mut *mut core::ffi::c_char) -> i32 {
    let mut devs: [*const core::ffi::c_char; 4] = [c"eth0".as_ptr(), c"eth1".as_ptr(), c"eth2".as_ptr(), core::ptr::null()];
    let mut a: *mut nftnl_chain = core::ptr::null_mut();
    let mut b: *mut nftnl_chain = core::ptr::null_mut();
    let mut buf: [core::ffi::c_char; 4096] = [0; 4096];
    let mut nlh: *mut nlmsghdr = core::ptr::null_mut();
    a = unsafe { nftnl_chain_alloc() };
    b = unsafe { nftnl_chain_alloc() };
    if a.is_null() || b.is_null() {
        unsafe { print_err(c"OOM".as_ptr()) };
    }
    unsafe { nftnl_chain_set_str(a, 0u16, c"test".as_ptr()) };
    unsafe { nftnl_chain_set_u32(a, 1u16, 2u32) };
    unsafe { nftnl_chain_set_str(a, 2u16, c"Table".as_ptr()) };
    unsafe { nftnl_chain_set_u32(a, 5u16, 305419896u32) };
    unsafe { nftnl_chain_set_u32(a, 3u16, 878082066u32) };
    unsafe { nftnl_chain_set_s32(a, 4u16, 1450709556) };
    unsafe { nftnl_chain_set_u32(a, 6u16, 2014458966u32) };
    unsafe { nftnl_chain_set_u64(a, 8u16, 1311768465173141112u64) };
    unsafe { nftnl_chain_set_u64(a, 7u16, 8652035380118434902u64) };
    unsafe { nftnl_chain_set_u64(a, 9u16, 6230750100465390132u64) };
    unsafe { nftnl_chain_set_str(a, 10u16, c"Prueba".as_ptr()) };
    unsafe { nftnl_chain_set_str(a, 11u16, c"eth0".as_ptr()) };
    /* cmd extracted from include/linux/netfilter/nf_tables.h */
    nlh = unsafe { nftnl_nlmsg_build_hdr((buf.as_mut_ptr() as *mut core::ffi::c_char), 3u16, 2u16, 0u16, 1234u32) };
    unsafe { nftnl_chain_nlmsg_build_payload(nlh, (a as *const nftnl_chain)) };
    if (unsafe { nftnl_chain_nlmsg_parse((nlh as *const nlmsghdr), b) }) < 0 {
        unsafe { print_err(c"parsing problems".as_ptr()) };
    }
    unsafe { cmp_nftnl_chain(a, b) };
    /* repeat test with multiple devices */
    unsafe { nftnl_chain_unset(a, 11u16) };
    unsafe { nftnl_chain_set_array(a, 12u16, (devs.as_mut_ptr() as *mut *const core::ffi::c_char)) };
    nlh = unsafe { nftnl_nlmsg_build_hdr((buf.as_mut_ptr() as *mut core::ffi::c_char), 3u16, 2u16, 0u16, 1234u32) };
    unsafe { nftnl_chain_nlmsg_build_payload(nlh, (a as *const nftnl_chain)) };
    if (unsafe { nftnl_chain_nlmsg_parse((nlh as *const nlmsghdr), b) }) < 0 {
        unsafe { print_err(c"parsing problems".as_ptr()) };
    }
    unsafe { cmp_nftnl_chain(a, b) };
    unsafe { nftnl_chain_free((a as *const nftnl_chain)) };
    unsafe { nftnl_chain_free((b as *const nftnl_chain)) };
    if !(test_ok != 0) {
        unsafe { exit(1) };
    }
    unsafe { printf(c"%s: \x1b[32mOK\x1b[0m\n".as_ptr(), (*argv.offset(0))) };
    return 0;
}

