unsafe extern "C" fn nft_cache_init(mut ctx: *mut netlink_ctx, mut flags: u32, mut filter: *const nft_cache_filter) -> i32 {
    // TODO initializer: { . family = NFPROTO_UNSPEC , }
    let mut handle: handle = unsafe { core::mem::zeroed() };
    let mut ret: i32 = 0;
    if flags == (NFT_CACHE_EMPTY as u32) {
        return 0;
    }
    /* assume NFT_CACHE_TABLE is always set. */
    ret = unsafe { cache_init_tables(ctx, &raw mut handle, (((&raw const (*(*ctx).nft).cache).cast_mut()) as *mut nft_cache), filter) };
    if ret < 0 {
        return ret;
    }
    ret = unsafe { cache_init_objects(ctx, flags, filter) };
    if ret < 0 {
        return ret;
    }
    return 0;
}

unsafe extern "C" fn nft_cache_is_complete(mut cache: *mut nft_cache, mut flags: u32) -> bool {
    return ((((*cache).flags & flags) == flags) as i32) != 0;
}

unsafe extern "C" fn nft_cache_needs_refresh(mut cache: *mut nft_cache, mut flags: u32) -> bool {
    return (((((*cache).flags & (NFT_CACHE_REFRESH as u32)) != 0) || ((flags & (NFT_CACHE_REFRESH as u32)) != 0)) as i32) != 0;
}

unsafe extern "C" fn nft_cache_is_updated(mut cache: *mut nft_cache, mut genid: u16) -> bool {
    return (((genid != 0) && ((genid as u32) == (*cache).genid)) as i32) != 0;
}

