pub const CMDLINE_HISTFILE: &core::ffi::CStr = c".nft.history";

pub const CMDLINE_PROMPT: &core::ffi::CStr = c"nft> ";

pub const CMDLINE_QUIT: &core::ffi::CStr = c"quit";

static mut cli_quit: bool = false;

static mut cli_rc: i32 = 0;

static mut histfile: [core::ffi::c_char; 4096] = [0; 4096];

#[unsafe(no_mangle)]
pub unsafe extern "C" fn cli_init(mut nft: *mut nft_ctx) -> i32 {
    let mut line: *mut core::ffi::c_char = core::ptr::null_mut();
    unsafe { init_histfile() };
    unsafe { linenoiseHistoryLoad(histfile.as_mut_ptr()) };
    unsafe { linenoiseSetMultiLine(1) };
    while !cli_quit {
        line = (unsafe { linenoise(CMDLINE_PROMPT.as_ptr()) } as *mut core::ffi::c_char);
        if line.is_null() {
            unsafe { cli_exit(0) };
            break;
        }
        if (unsafe { strcmp((line as *const core::ffi::c_char), CMDLINE_QUIT.as_ptr()) }) == 0 {
            unsafe { cli_exit(0) };
        } else if ((*line.offset(0)) as i32) != 0 {
            unsafe { linenoiseHistoryAdd(line) };
            unsafe { nft_run_cmd_from_buffer(nft, (line as *const core::ffi::c_char)) };
        }
        unsafe { linenoiseFree(line) };
    }
    return cli_rc;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn cli_exit(mut rc: i32) {
    unsafe { linenoiseHistorySave(histfile.as_mut_ptr()) };
    unsafe { __cli_exit(rc) };
}

unsafe extern "C" fn __cli_exit(mut rc: i32) {
    cli_quit = true;
    cli_rc = rc;
}

unsafe extern "C" fn init_histfile() {
    let mut home: *const core::ffi::c_char = core::ptr::null();
    home = (unsafe { getenv(c"HOME".as_ptr()) } as *const core::ffi::c_char);
    if home.is_null() {
        home = c"".as_ptr();
    }
    unsafe { snprintf((histfile.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 4096]>(), c"%s/%s".as_ptr(), home, CMDLINE_HISTFILE.as_ptr()) };
}

