#[unsafe(no_mangle)]
pub unsafe extern "C" fn ct_expr_alloc(mut loc: *const location, mut key: nft_ct_keys, mut direction: i8) -> *mut expr {
    let mut tmpl: *const ct_template = (((&raw const ct_templates[key as usize]).cast_mut()) as *const ct_template);
    let mut expr: *mut expr = core::ptr::null_mut();
    expr = unsafe { expr_alloc(loc, 12, (*tmpl).dtype, (*tmpl).byteorder, (*tmpl).len) };
    (*expr).anon9.ct.key = key;
    (*expr).anon9.ct.direction = direction;
    match key {
        NFT_CT_SRC | NFT_CT_SRC_IP | NFT_CT_SRC_IP6 | NFT_CT_DST | NFT_CT_DST_IP | NFT_CT_DST_IP6 => {
            (*expr).anon9.ct.base = PROTO_BASE_NETWORK_HDR;
        }
        NFT_CT_PROTO_SRC | NFT_CT_PROTO_DST => {
            (*expr).anon9.ct.base = PROTO_BASE_TRANSPORT_HDR;
        }
        NFT_CT_PROTOCOL => {
            (*expr).flags = 4u32;
            (*expr).anon9.ct.base = PROTO_BASE_NETWORK_HDR;
        }
        NFT_CT_L3PROTOCOL => {
            (*expr).flags = 4u32;
            (*expr).anon9.ct.base = PROTO_BASE_LL_HDR;
        }
        _ => {
        }
    }
    return expr;
}

