unsafe extern "C" fn ct_label_type_print(mut expr: *const expr, mut octx: *mut output_ctx) {
    let mut bit: u64 = unsafe { mpz_scan1((*expr).anon9.anon3.value, 0u64) };
    let mut labelstr: *const core::ffi::c_char = unsafe { ct_label2str((*octx).tbl.ct_label, bit) };
    if !labelstr.is_null() {
        unsafe { nft_print(octx, c"\"%s\"".as_ptr(), labelstr) };
        return;
    }
    /* can happen when connlabel.conf is altered after rules were added */
    unsafe { nft_print(octx, c"%lu".as_ptr(), bit) };
}

unsafe extern "C" fn ct_label_type_parse(mut ctx: *mut parse_ctx, mut sym: *const expr, mut res: *mut *mut expr) -> *mut error_record {
    let mut s: *const symbolic_constant = core::ptr::null();
    let mut dtype: *const datatype = core::ptr::null();
    let mut __data_storage: Vec<u8> = vec![unsafe { core::mem::zeroed() }; (CT_LABEL_BIT_SIZE / BITS_PER_BYTE) as usize];
    let data: *mut u8 = __data_storage.as_mut_ptr();
    let mut bit: u64 = 0;
    let mut value: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    {
        s = ((*(*(*ctx).tbl).ct_label).symbols as *const symbolic_constant);
        'b0: while !(*s).identifier.is_null() {
            if !(unsafe { strcmp((*sym).anon9.anon0.anon1.identifier, (*s).identifier) } != 0) {
                break 'b0;
            }
            s = s.offset(1);
        }
    }
    dtype = (*sym).dtype;
    if (*s).identifier.is_null() {
        let mut ptr: *mut core::ffi::c_char = core::ptr::null_mut();
        (*unsafe { __errno_location() }) = 0;
        bit = unsafe { strtoull((*sym).anon9.anon0.anon1.identifier, (&raw mut ptr as *mut *mut core::ffi::c_char), 0) };
        if (*ptr) != 0 {
            // C (return): return error ( & sym -> location , "%s: could not parse %s \"%s\"" , CONNLABEL_CONF , dtype -> desc , sym -> identifier ) ;
            todo!();
        }
        if (*unsafe { __errno_location() }) != 0 {
            // C (return): return error ( & sym -> location , "%s: could not parse %s \"%s\": %s" , CONNLABEL_CONF , dtype -> desc , sym -> identifier , strerror ( errno ) ) ;
            todo!();
        }
    } else {
        bit = (*s).value;
    }
    if bit >= (CT_LABEL_BIT_SIZE as u64) {
        return unsafe { erec_create(2, (((&raw const (*sym).location).cast_mut()) as *const location), c"%s: bit %lu out of range (%u max)".as_ptr(), (*sym).anon9.anon0.anon1.identifier, bit, CT_LABEL_BIT_SIZE) };
    }
    unsafe { mpz_init2(value, (*dtype).size as u64) };
    unsafe { mpz_setbit(value, bit) };
    {
        assert!(core::mem::size_of::<*mut u8>() > (0 as usize));
        unsafe { __mpz_export_data((data as *mut core::ffi::c_void), value, 1, (core::mem::size_of::<*mut u8>()) as u32) };
    }
    (*res) = unsafe { constant_expr_alloc((((&raw const (*sym).location).cast_mut()) as *const location), dtype, (*dtype).byteorder(), 128u32, (data as *const core::ffi::c_void)) };
    unsafe { mpz_clear(value) };
    return core::ptr::null_mut();
}

