unsafe extern "C" fn ct_print(mut key: nft_ct_keys, mut dir: i8, mut nfproto: u8, mut octx: *mut output_ctx) {
    let mut dirstr: *const core::ffi::c_char = unsafe { ct_dir2str(dir as i32) };
    let mut desc: *const proto_desc = core::ptr::null();
    unsafe { nft_print(octx, c"ct ".as_ptr()) };
    'g_done: {
        if (dir as i32) < 0 {
            break 'g_done;
        }
        if !dirstr.is_null() {
            unsafe { nft_print(octx, c"%s ".as_ptr(), dirstr) };
        }
        match key {
            NFT_CT_SRC | NFT_CT_DST => {
                desc = (unsafe { proto_find_upper(((&raw const proto_inet).cast_mut()), (nfproto as i32)) } as *const proto_desc);
                if !desc.is_null() {
                    unsafe { nft_print(octx, c"%s ".as_ptr(), (*desc).name) };
                }
            }
            _ => {
            }
        }
    }
    unsafe { nft_print(octx, c"%s".as_ptr(), ct_templates[key as usize].token) };
}

