unsafe extern "C" fn ct_expr_pctx_update(mut ctx: *mut proto_ctx, mut loc: *const location, mut left: *const expr, mut right: *const expr) {
    let mut base: *const proto_desc = core::ptr::null();
    let mut desc: *const proto_desc = core::ptr::null();
    let mut nhproto: u32 = 0;
    nhproto = unsafe { mpz_get_uint32((*right).anon9.anon3.value) };
    // C (statement): base = ctx -> protocol [ left -> ct . base ] . desc ;
    todo!();
    if base.is_null() {
        return;
    }
    desc = (unsafe { proto_find_upper(base, nhproto) } as *const proto_desc);
    if desc.is_null() {
        return;
    }
    unsafe { proto_ctx_update(ctx, ((*left).anon9.ct.base + 1), loc, desc) };
}

