unsafe extern "C" fn verdict_type_print(mut expr: *const expr, mut octx: *mut output_ctx) {
    match (*expr).anon9.anon2.verdict {
        NFT_CONTINUE => {
            unsafe { nft_print(octx, c"continue".as_ptr()) };
        }
        NFT_BREAK => {
            unsafe { nft_print(octx, c"break".as_ptr()) };
        }
        NFT_JUMP => {
            if (*(*expr).anon9.anon2.chain).etype() == EXPR_VALUE {
                unsafe { verdict_jump_chain_print(c"jump".as_ptr(), ((*expr).anon9.anon2.chain as *const expr), octx) };
            } else {
                unsafe { nft_print(octx, c"jump ".as_ptr()) };
                unsafe { expr_print(((*expr).anon9.anon2.chain as *const expr), octx) };
            }
        }
        NFT_GOTO => {
            if (*(*expr).anon9.anon2.chain).etype() == EXPR_VALUE {
                unsafe { verdict_jump_chain_print(c"goto".as_ptr(), ((*expr).anon9.anon2.chain as *const expr), octx) };
            } else {
                unsafe { nft_print(octx, c"goto ".as_ptr()) };
                unsafe { expr_print(((*expr).anon9.anon2.chain as *const expr), octx) };
            }
        }
        NFT_RETURN => {
            unsafe { nft_print(octx, c"return".as_ptr()) };
        }
        _ => {
            match (*expr).anon9.anon2.verdict & NF_VERDICT_MASK {
                1 => {
                    unsafe { nft_print(octx, c"accept".as_ptr()) };
                }
                0 => {
                    unsafe { nft_print(octx, c"drop".as_ptr()) };
                }
                3 => {
                    unsafe { nft_print(octx, c"queue".as_ptr()) };
                }
                2 => {
                    unsafe { nft_print(octx, c"stolen".as_ptr()) };
                }
                _ => {
                    unsafe { nft_print(octx, c"unknown verdict value %u".as_ptr(), (*expr).anon9.anon2.verdict) };
                }
            }
        }
    }
}

