unsafe extern "C" fn cgroupv2_get_path(mut path: *const core::ffi::c_char, mut id: u64) -> *mut core::ffi::c_char {
    let mut dent_name: [core::ffi::c_char; 4097] = [0; 4097];
    let mut cgroup_path: *mut core::ffi::c_char = core::ptr::null_mut();
    let mut dent: *mut dirent = core::ptr::null_mut();
    let mut st: stat = unsafe { core::mem::zeroed() };
    let mut d: *mut __dirstream = core::ptr::null_mut();
    d = unsafe { opendir(path) };
    if d.is_null() {
        return core::ptr::null_mut();
    }
    while !{ let __v = unsafe { readdir(d) }; dent = __v; __v }.is_null() {
        if !(unsafe { strcmp(((*dent).d_name.as_mut_ptr() as *const core::ffi::c_char), c".".as_ptr()) } != 0) || !(unsafe { strcmp(((*dent).d_name.as_mut_ptr() as *const core::ffi::c_char), c"..".as_ptr()) } != 0) {
            continue;
        }
        unsafe { snprintf((dent_name.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 4097]>(), c"%s/%s".as_ptr(), path, (*dent).d_name.as_mut_ptr()) };
        dent_name[(core::mem::size_of::<[core::ffi::c_char; 4097]>() - (1 as usize)) as usize] = (0 as core::ffi::c_char);
        if (*dent).d_ino == id {
            cgroup_path = (unsafe { xstrdup(dent_name.as_mut_ptr()) } as *mut core::ffi::c_char);
            break;
        }
        if ((unsafe { stat((dent_name.as_mut_ptr() as *const core::ffi::c_char), &raw mut st) }) >= 0) && ((st.st_mode & (__S_IFMT as u32)) == (__S_IFDIR as u32)) {
            cgroup_path = unsafe { cgroupv2_get_path((dent_name.as_mut_ptr() as *const core::ffi::c_char), id) };
            if !cgroup_path.is_null() {
                break;
            }
        }
    }
    unsafe { closedir(d) };
    return cgroup_path;
}

unsafe extern "C" fn cgroupv2_type_print(mut expr: *const expr, mut octx: *mut output_ctx) {
    let mut id: u64 = unsafe { mpz_get_uint64((*expr).anon9.anon3.value) };
    let mut cgroup_path: *mut core::ffi::c_char = core::ptr::null_mut();
    cgroup_path = unsafe { cgroupv2_get_path(SYSFS_CGROUPSV2_PATH.as_ptr(), id) };
    if !cgroup_path.is_null() {
        unsafe { nft_print(octx, c"\"%s\"".as_ptr(), ((&raw const (*cgroup_path.offset(((unsafe { strlen(SYSFS_CGROUPSV2_PATH.as_ptr()) }) + (1 as usize)) as isize))).cast_mut())) };
    } else {
        unsafe { nft_print(octx, c"%lu".as_ptr(), id) };
    }
    unsafe { free((cgroup_path as *mut core::ffi::c_void)) };
}

