    let mut ino: u64 = 0;
    unsafe { snprintf((cgroupv2_path.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 4097]>(), c"%s/%s".as_ptr(), SYSFS_CGROUPSV2_PATH.as_ptr(), (*sym).anon9.anon0.anon1.identifier) };
