#[unsafe(no_mangle)]
pub unsafe extern "C" fn print_location(mut f: *mut _IO_FILE, mut indesc: *const input_descriptor, mut loc: *const location) {
    let mut tmp: *const input_descriptor = core::ptr::null();
    let mut iloc: *const location = core::ptr::null();
    if !(*indesc).location.indesc.is_null() {
        let mut prefix: *const core::ffi::c_char = c"In file included from".as_ptr();
        iloc = (((&raw const (*indesc).location).cast_mut()) as *const location);
        {
            tmp = (*iloc).indesc;
            while !tmp.is_null() && ((*tmp).type_ != INDESC_INTERNAL) {
                unsafe { fprintf(f, c"%s %s:%u:%u-%u:\n".as_ptr(), prefix, (*tmp).name, (*iloc).anon1.anon0.first_line, (*iloc).anon1.anon0.first_column, (*iloc).anon1.anon0.last_column) };
                prefix = c"                 from".as_ptr();
                iloc = (((&raw const (*tmp).location).cast_mut()) as *const location);
                tmp = (*iloc).indesc;
            }
        }
    }
    if ((*indesc).type_ != INDESC_BUFFER) && !(*indesc).name.is_null() {
        unsafe { fprintf(f, c"%s:%u:%u-%u: ".as_ptr(), (*indesc).name, (*loc).anon1.anon0.first_line, (*loc).anon1.anon0.first_column, (*loc).anon1.anon0.last_column) };
    }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn line_location(mut indesc: *const input_descriptor, mut loc: *const location, mut buf: *mut core::ffi::c_char, mut bufsiz: usize) -> *const core::ffi::c_char {
    let mut line: *const core::ffi::c_char = core::ptr::null();
    let mut f: *mut _IO_FILE = core::ptr::null_mut();
    f = unsafe { fopen((*indesc).name, c"r".as_ptr()) };
    if f.is_null() {
        return core::ptr::null();
    }
    if !(unsafe { fseek(f, (*loc).anon1.anon0.line_offset as i64, 0) } != 0) && ((unsafe { fread((buf as *mut core::ffi::c_void), 1usize, bufsiz - (1 as usize), f) }) > (0 as usize)) {
        (*unsafe { strchrnul((buf as *const core::ffi::c_char), 10) }) = (0 as core::ffi::c_char);
        line = (buf as *const core::ffi::c_char);
    }
    unsafe { fclose(f) };
    return line;
}

