        payload_byte_size += 1;
        if (payload_byte_offset & (1 as u32)) != 0 {
            /* prefer 16bit aligned fetch */
            payload_byte_offset -= 1;
            assert!((*payload).anon9.payload.offset >= BITS_PER_BYTE);
        } else {
            shift_imm += ((BITS_PER_BYTE) as u8);
        }
