#[unsafe(no_mangle)]
pub unsafe extern "C" fn expr_free(mut expr: *mut expr) {
    if expr.is_null() {
        return;
    }
    unsafe { assert_refcount_safe((*expr).refcnt) };
    if ({ (*expr).refcnt -= 1; (*expr).refcnt }) > (0 as u32) {
        return;
    }
    unsafe { datatype_free((*expr).dtype) };
    /* EXPR_INVALID expressions lack ->ops structure.
    	 * This happens for set, list and concat types.
    	 */
    if (*expr).etype() != EXPR_INVALID {
        unsafe { expr_destroy(expr) };
    }
    unsafe { free((expr as *mut core::ffi::c_void)) };
}

