/*
 * Convert an expression of basetype TYPE_BITMASK into a series of inclusive
 * OR binop expressions of the individual flag values.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bitmask_expr_to_binops(mut expr: *mut expr) -> *mut expr {
    let mut expr: *mut expr = core::ptr::null_mut();
    let mut flag: *mut expr = core::ptr::null_mut();
    let mut n: u64 = 0;
    assert!((*expr).etype() == EXPR_VALUE);
    assert!((*(*(*expr).dtype).basetype).type_ == (TYPE_BITMASK as u32));
    n = unsafe { mpz_popcount((*expr).anon9.anon3.value) };
    if (n == (0 as u64)) || (n == (1 as u64)) {
        return expr;
    }
    binop = core::ptr::null_mut();
    n = 0u64;
    while ({ let __v = unsafe { mpz_scan1((*expr).anon9.anon3.value, n) }; n = __v; __v }) != ULONG_MAX {
        flag = unsafe { flag_expr_alloc((&raw mut (*expr).location as *const location), (*expr).dtype, (*expr).byteorder(), (*expr).len, n) };
        if !binop.is_null() {
            binop = unsafe { binop_expr_alloc((&raw mut (*expr).location as *const location), 8, binop, flag) };
        } else {
            binop = flag;
        }
        n += 1;
    }
    unsafe { expr_free(expr) };
    return binop;
}

