unsafe extern "C" fn calculate_delim(mut expr: *const expr, mut count: *mut i32, mut octx: *mut output_ctx) -> *const core::ffi::c_char {
    let mut newline: *const core::ffi::c_char = c",\n\t\t\t     ".as_ptr();
    let mut singleline: *const core::ffi::c_char = c", ".as_ptr();
    if (*octx).force_newline {
        return newline;
    }
    // C (if condition): if ( set_is_anonymous ( expr_set ( expr ) -> set_flags ) )
    todo!();
    if !!(*expr).dtype.is_null() {
        return newline;
    }
    match (*(*expr).dtype).type_ {
        TYPE_NFPROTO | TYPE_INTEGER | TYPE_ARPOP | TYPE_INET_PROTOCOL | TYPE_INET_SERVICE | TYPE_TCP_FLAG | TYPE_DCCP_PKTTYPE | TYPE_MARK | TYPE_IFINDEX | TYPE_CLASSID | TYPE_UID | TYPE_GID | TYPE_CT_DIR => {
            if (*count) < 5 {
                return singleline;
            }
            (*count) = 0;
        }
        TYPE_IPADDR | TYPE_CT_STATE | TYPE_CT_STATUS | TYPE_PKTTYPE => {
            if (*count) < 2 {
                return singleline;
            }
            (*count) = 0;
        }
        _ => {
        }
    }
    return newline;
}

