unsafe extern "C" fn obj_print_json(mut octx: *mut output_ctx, mut obj: *const obj, mut delete: bool) -> *mut json_t {
    let mut rate_unit: *const core::ffi::c_char = core::ptr::null();
    let mut burst_unit: *const core::ffi::c_char = core::ptr::null();
    let mut type_: *const core::ffi::c_char = (unsafe { obj_type_name((*obj).type_) } as *const core::ffi::c_char);
    let mut root: *mut json_t = core::ptr::null_mut();
    let mut tmp: *mut json_t = core::ptr::null_mut();
    let mut flags: *mut json_t = core::ptr::null_mut();
    let mut rate: u64 = 0;
    let mut burst: u64 = 0;
    root = unsafe { __nft_json_pack(0 as u32, c"{s:s, s:s, s:s, s:I}".as_ptr(), c"family".as_ptr(), unsafe { family2str((*obj).handle.family) }, c"name".as_ptr(), (*obj).handle.obj.name, c"table".as_ptr(), (*obj).handle.table.name, c"handle".as_ptr(), (*obj).handle.handle.id) };
    'g_out: {
        if delete {
            break 'g_out;
        }
        if (*obj).comment != 0 {
            tmp = unsafe { __nft_json_pack(0 as u32, c"{s:s}".as_ptr(), c"comment".as_ptr(), (*obj).comment) };
            unsafe { json_object_update(root, tmp) };
            unsafe { json_decref(tmp) };
        }
        match (*obj).type_ {
            1 => {
                tmp = unsafe { __nft_json_pack(0 as u32, c"{s:I, s:I}".as_ptr(), c"packets".as_ptr(), (*obj).counter.packets, c"bytes".as_ptr(), (*obj).counter.bytes) };
                unsafe { json_object_update(root, tmp) };
                unsafe { json_decref(tmp) };
            }
            2 => {
                tmp = unsafe { __nft_json_pack(0 as u32, c"{s:I, s:I, s:b}".as_ptr(), c"bytes".as_ptr(), (*obj).quota.bytes, c"used".as_ptr(), (*obj).quota.used, c"inv".as_ptr(), ((*obj).quota.flags & NFT_QUOTA_F_INV)) };
                unsafe { json_object_update(root, tmp) };
                unsafe { json_decref(tmp) };
            }
            8 => {
                tmp = unsafe { __nft_json_pack(0 as u32, c"{s:s}".as_ptr(), c"context".as_ptr(), (*obj).secmark.ctx) };
                unsafe { json_object_update(root, tmp) };
                unsafe { json_decref(tmp) };
            }
            3 => {
                tmp = unsafe { __nft_json_pack(0 as u32, c"{s:s, s:o, s:s}".as_ptr(), c"type".as_ptr(), (*obj).ct_helper.name, c"protocol".as_ptr(), unsafe { proto_name_json((*obj).ct_helper.l4proto as u8) }, c"l3proto".as_ptr(), unsafe { family2str((*obj).ct_helper.l3proto) }) };
                unsafe { json_object_update(root, tmp) };
                unsafe { json_decref(tmp) };
            }
            7 => {
                tmp = unsafe { timeout_policy_json((*obj).ct_timeout.l4proto as u8, ((*obj).ct_timeout.timeout as *const u32)) };
                tmp = unsafe { __nft_json_pack(0 as u32, c"{s:o, s:s, s:o}".as_ptr(), c"protocol".as_ptr(), unsafe { proto_name_json((*obj).ct_timeout.l4proto as u8) }, c"l3proto".as_ptr(), unsafe { family2str((*obj).ct_timeout.l3proto) }, c"policy".as_ptr(), tmp) };
                unsafe { json_object_update(root, tmp) };
                unsafe { json_decref(tmp) };
            }
            9 => {
                tmp = unsafe { __nft_json_pack(0 as u32, c"{s:o, s:I, s:I, s:I, s:s}".as_ptr(), c"protocol".as_ptr(), unsafe { proto_name_json((*obj).ct_expect.l4proto as u8) }, c"dport".as_ptr(), (*obj).ct_expect.dport, c"timeout".as_ptr(), (*obj).ct_expect.timeout, c"size".as_ptr(), (*obj).ct_expect.size, c"l3proto".as_ptr(), unsafe { family2str((*obj).ct_expect.l3proto) }) };
                unsafe { json_object_update(root, tmp) };
                unsafe { json_decref(tmp) };
            }
            4 => {
                rate = (*obj).limit.rate as u64;
                burst = (*obj).limit.burst as u64;
                if (*obj).limit.type_ == NFT_LIMIT_PKT_BYTES {
                    rate_unit = unsafe { get_rate((*obj).limit.rate as u64, &raw mut rate) };
                    burst_unit = unsafe { get_rate((*obj).limit.burst as u64, &raw mut burst) };
                }
                tmp = unsafe { __nft_json_pack(0 as u32, c"{s:I, s:s}".as_ptr(), c"rate".as_ptr(), rate, c"per".as_ptr(), unsafe { get_unit((*obj).limit.unit as u64) }) };
                if ((*obj).limit.flags & NFT_LIMIT_F_INV) != 0 {
                    unsafe { json_object_set_new(tmp, c"inv".as_ptr(), unsafe { json_true() }) };
                }
                if !rate_unit.is_null() {
                    unsafe { json_object_set_new(tmp, c"rate_unit".as_ptr(), unsafe { json_string(rate_unit) }) };
                }
                if burst != 0 {
                    unsafe { json_object_set_new(tmp, c"burst".as_ptr(), unsafe { json_integer(burst as i64) }) };
                    if !burst_unit.is_null() {
                        unsafe { json_object_set_new(tmp, c"burst_unit".as_ptr(), unsafe { json_string(burst_unit) }) };
                    }
                }
                unsafe { json_object_update(root, tmp) };
                unsafe { json_decref(tmp) };
            }
            10 => {
                tmp = unsafe { __nft_json_pack(0 as u32, c"{s:i, s:i}".as_ptr(), c"mss".as_ptr(), (*obj).synproxy.mss, c"wscale".as_ptr(), (*obj).synproxy.wscale) };
                flags = unsafe { json_array() };
                if ((*obj).synproxy.flags & NF_SYNPROXY_OPT_TIMESTAMP) != 0 {
                    unsafe { json_array_append_new(flags, unsafe { json_string(c"timestamp".as_ptr()) }) };
                }
                if ((*obj).synproxy.flags & NF_SYNPROXY_OPT_SACK_PERM) != 0 {
                    unsafe { json_array_append_new(flags, unsafe { json_string(c"sack-perm".as_ptr()) }) };
                }
                unsafe { json_add_array_new(tmp, c"flags".as_ptr(), flags) };
                unsafe { json_object_update(root, tmp) };
                unsafe { json_decref(tmp) };
            }
            6 => {
                tmp = unsafe { tunnel_obj_print_json(octx, obj) };
                unsafe { json_object_update(root, tmp) };
                unsafe { json_decref(tmp) };
            }
            5 => {
                tmp = unsafe { json_pack(c"{s:i}".as_ptr(), c"val".as_ptr(), (*obj).connlimit.count) };
                if ((*obj).connlimit.flags & NFT_CONNLIMIT_F_INV) != 0 {
                    unsafe { json_object_set_new(root, c"inv".as_ptr(), unsafe { json_true() }) };
                }
                unsafe { json_object_update(root, tmp) };
                unsafe { json_decref(tmp) };
            }
            _ => {}
        }
    }
    return unsafe { __nft_json_pack(0 as u32, c"{s:o}".as_ptr(), type_, root) };
}

