#[unsafe(no_mangle)]
pub unsafe extern "C" fn meta_expr_alloc(mut loc: *const location, mut key: nft_meta_keys) -> *mut expr {
    let mut tmpl: *const meta_template = (((&raw const meta_templates[key as usize]).cast_mut()) as *const meta_template);
    let mut expr: *mut expr = core::ptr::null_mut();
    expr = unsafe { expr_alloc(loc, 9, (*tmpl).dtype, (*tmpl).byteorder, (*tmpl).len) };
    (*expr).anon9.meta.key = key;
    match key {
        8 => {
            (*expr).flags |= ((EXPR_F_PROTOCOL) as u32);
        }
        NFT_META_NFPROTO => {
            (*expr).flags |= ((EXPR_F_PROTOCOL) as u32);
            (*expr).anon9.meta.base = PROTO_BASE_LL_HDR;
        }
        NFT_META_L4PROTO => {
            (*expr).flags |= ((EXPR_F_PROTOCOL) as u32);
            (*expr).anon9.meta.base = PROTO_BASE_NETWORK_HDR;
        }
        NFT_META_PROTOCOL => {
            (*expr).flags |= ((EXPR_F_PROTOCOL) as u32);
            (*expr).anon9.meta.base = PROTO_BASE_LL_HDR;
        }
        _ => {
        }
    }
    return expr;
}

