pub struct mpn_base_info {
    /* bb is the largest power of the base which fits in one limb, and
     exp is the corresponding exponent. */
    pub exp: u32,
    pub bb: u64,
}

pub const mp_bits_per_limb: i32 = 64;

static mut gmp_allocate_func: Option<unsafe extern "C" fn(usize) -> *mut core::ffi::c_void> = Some(gmp_default_alloc);

static mut gmp_reallocate_func: Option<unsafe extern "C" fn(*mut core::ffi::c_void, usize, usize) -> *mut core::ffi::c_void> = Some(gmp_default_realloc);

static mut gmp_free_func: Option<unsafe extern "C" fn(*mut core::ffi::c_void, usize)> = Some(gmp_default_free);

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mp_set_memory_functions(mut alloc_func: Option<unsafe extern "C" fn(usize) -> *mut core::ffi::c_void>, mut realloc_func: Option<unsafe extern "C" fn(*mut core::ffi::c_void, usize, usize) -> *mut core::ffi::c_void>, mut free_func: Option<unsafe extern "C" fn(*mut core::ffi::c_void, usize)>) {
    if alloc_func.is_none() {
        alloc_func = Some(gmp_default_alloc);
    }
    if realloc_func.is_none() {
        realloc_func = Some(gmp_default_realloc);
    }
    if free_func.is_none() {
        free_func = Some(gmp_default_free);
    }
    gmp_allocate_func = alloc_func;
    gmp_reallocate_func = realloc_func;
    gmp_free_func = free_func;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mp_get_memory_functions(mut alloc_func: *mut Option<unsafe extern "C" fn(usize) -> *mut core::ffi::c_void>, mut realloc_func: *mut Option<unsafe extern "C" fn(*mut core::ffi::c_void, usize, usize) -> *mut core::ffi::c_void>, mut free_func: *mut Option<unsafe extern "C" fn(*mut core::ffi::c_void, usize)>) {
    if !alloc_func.is_null() {
        (*alloc_func) = gmp_allocate_func;
    }
    if !realloc_func.is_null() {
        (*realloc_func) = gmp_reallocate_func;
    }
    if !free_func.is_null() {
        (*free_func) = gmp_free_func;
    }
}

/* MPN interface */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpn_copyi(mut d: *mut u64, mut s: *const u64, mut n: i64) {
    let mut i: i64 = 0;
    {
        i = 0i64;
        while i < n {
            (*d.offset(i as isize)) = *s.offset(i as isize);
            i += 1;
        }
    }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpn_copyd(mut d: *mut u64, mut s: *const u64, mut n: i64) {
    while ({ n -= 1; n }) >= (0 as i64) {
        (*d.offset(n as isize)) = *s.offset(n as isize);
    }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpn_zero(mut rp: *mut u64, mut n: i64) {
    while ({ n -= 1; n }) >= (0 as i64) {
        (*rp.offset(n as isize)) = 0u64;
    }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpn_cmp(mut ap: *const u64, mut bp: *const u64, mut n: i64) -> i32 {
    while ({ n -= 1; n }) >= (0 as i64) {
        if (*ap.offset(n as isize)) != (*bp.offset(n as isize)) {
            return (if ((*ap.offset(n as isize)) > (*bp.offset(n as isize))) { 1 } else { -1 });
        }
    }
    return 0;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpn_zero_p(mut rp: *const u64, mut n: i64) -> i32 {
    return ((unsafe { mpn_normalized_size(rp, n) }) == (0 as i64)) as i32;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpn_add_1(mut rp: *mut u64, mut ap: *const u64, mut n: i64, mut b: u64) -> u64 {
    let mut i: i64 = 0;
    assert!(n > (0 as i64));
    i = 0i64;
    loop {
        let mut r: u64 = (*ap.offset(i as isize)) + b;
        /* Carry out */
        b = ((r < b) as i32) as u64;
        (*rp.offset(i as isize)) = r;
        if !(({ i += 1; i }) < n) { break; }
    }
    return b;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpn_add_n(mut rp: *mut u64, mut ap: *const u64, mut bp: *const u64, mut n: i64) -> u64 {
    let mut i: i64 = 0;
    let mut cy: u64 = 0;
    {
        i = 0i64; cy = 0u64;
        while i < n {
            let mut a: u64 = 0;
            let mut b: u64 = 0;
            let mut r: u64 = 0;
            a = *ap.offset(i as isize);
            b = *bp.offset(i as isize);
            r = a + cy;
            cy = ((r < cy) as i32) as u64;
            r += b;
            cy += ((((r < b) as i32)) as u64);
            (*rp.offset(i as isize)) = r;
            i += 1;
        }
    }
    return cy;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpn_add(mut rp: *mut u64, mut ap: *const u64, mut an: i64, mut bp: *const u64, mut bn: i64) -> u64 {
    let mut cy: u64 = 0;
    assert!(an >= bn);
    cy = unsafe { mpn_add_n(rp, ap, bp, bn) };
    if an > bn {
        cy = unsafe { mpn_add_1(rp.offset(bn as isize), ap.offset(bn as isize), an - bn, cy) };
    }
    return cy;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpn_sub_1(mut rp: *mut u64, mut ap: *const u64, mut n: i64, mut b: u64) -> u64 {
    let mut i: i64 = 0;
    assert!(n > (0 as i64));
    i = 0i64;
    loop {
        let mut a: u64 = *ap.offset(i as isize);
        /* Carry out */
        let mut cy: u64 = ((a < b) as i32) as u64;
        (*rp.offset(i as isize)) = a - b;
        b = cy;
        if !(({ i += 1; i }) < n) { break; }
    }
    return b;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpn_sub_n(mut rp: *mut u64, mut ap: *const u64, mut bp: *const u64, mut n: i64) -> u64 {
    let mut i: i64 = 0;
    let mut cy: u64 = 0;
    {
        i = 0i64; cy = 0u64;
        while i < n {
            let mut a: u64 = 0;
            let mut b: u64 = 0;
            a = *ap.offset(i as isize);
            b = *bp.offset(i as isize);
            b += cy;
            cy = ((b < cy) as i32) as u64;
            cy += ((((a < b) as i32)) as u64);
            (*rp.offset(i as isize)) = a - b;
            i += 1;
        }
    }
    return cy;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpn_sub(mut rp: *mut u64, mut ap: *const u64, mut an: i64, mut bp: *const u64, mut bn: i64) -> u64 {
    let mut cy: u64 = 0;
    assert!(an >= bn);
    cy = unsafe { mpn_sub_n(rp, ap, bp, bn) };
    if an > bn {
        cy = unsafe { mpn_sub_1(rp.offset(bn as isize), ap.offset(bn as isize), an - bn, cy) };
    }
    return cy;
}

