#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpz_congruent_p(mut a: [__mpz_struct; 1], mut b: [__mpz_struct; 1], mut m: [__mpz_struct; 1]) -> i32 {
    let mut t: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut res: i32 = 0;
    /* a == b (mod 0) iff a == b */
    if (unsafe { mpz_sgn(m) }) == 0 {
        return ((unsafe { mpz_cmp(a, b) }) == 0) as i32;
    }
    unsafe { mpz_init(t) };
    unsafe { mpz_sub(t, a, b) };
    res = unsafe { mpz_divisible_p(t, m) };
    unsafe { mpz_clear(t) };
    return res;
}

