#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpz_gcd_ui(mut g: [__mpz_struct; 1], mut u: [__mpz_struct; 1], mut v: u64) -> u64 {
    let mut un: i64 = 0;
    if v == (0 as u64) {
        if !g.is_null() {
            unsafe { mpz_abs(g, u) };
        }
    } else {
        un = (if (u[0]._mp_size >= 0) { (u[0]._mp_size) as i64 } else { (-u[0]._mp_size) as i64 });
        if un != (0 as i64) {
            v = unsafe { mpn_gcd_11(unsafe { mpn_div_qr_1(core::ptr::null_mut(), (u[0]._mp_d as *const u64), un, v) }, v) };
        }
        if !g.is_null() {
            unsafe { mpz_set_ui(g, v) };
        }
    }
    return v;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpz_gcd(mut g: [__mpz_struct; 1], mut u: [__mpz_struct; 1], mut v: [__mpz_struct; 1]) {
    let mut tu: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut tv: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut uz: u64 = 0;
    let mut vz: u64 = 0;
    let mut gz: u64 = 0;
    if u[0]._mp_size == 0 {
        unsafe { mpz_abs(g, v) };
        return;
    }
    if v[0]._mp_size == 0 {
        unsafe { mpz_abs(g, u) };
        return;
    }
    unsafe { mpz_init(tu) };
    unsafe { mpz_init(tv) };
    unsafe { mpz_abs(tu, u) };
    uz = unsafe { mpz_make_odd(tu) };
    unsafe { mpz_abs(tv, v) };
    vz = unsafe { mpz_make_odd(tv) };
    gz = (if (uz < vz) { uz } else { vz });
    if tu[0]._mp_size < tv[0]._mp_size {
        unsafe { mpz_swap(tu, tv) };
    }
    unsafe { mpz_tdiv_r(tu, tu, tv) };
    if tu[0]._mp_size == 0 {
        unsafe { mpz_swap(g, tv) };
    } else {
        loop {
            let mut c: i32 = 0;
            unsafe { mpz_make_odd(tu) };
            c = unsafe { mpz_cmp(tu, tv) };
            if c == 0 {
                unsafe { mpz_swap(g, tu) };
                break;
            }
            if c < 0 {
                unsafe { mpz_swap(tu, tv) };
            }
            if tv[0]._mp_size == 1 {
                let mut vl: u64 = *tv[0]._mp_d.offset(0);
                let mut ul: u64 = unsafe { mpz_tdiv_ui(tu, vl) };
                unsafe { mpz_set_ui(g, unsafe { mpn_gcd_11(ul, vl) }) };
                break;
            }
            unsafe { mpz_sub(tu, tu, tv) };
        }
    }
    unsafe { mpz_clear(tu) };
    unsafe { mpz_clear(tv) };
    unsafe { mpz_mul_2exp(g, g, gz) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpz_gcdext(mut g: [__mpz_struct; 1], mut s: [__mpz_struct; 1], mut t: [__mpz_struct; 1], mut u: [__mpz_struct; 1], mut v: [__mpz_struct; 1]) {
    let mut tu: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut tv: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut s0: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut s1: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut t0: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut t1: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut uz: u64 = 0;
    let mut vz: u64 = 0;
    let mut gz: u64 = 0;
    let mut power: u64 = 0;
    if u[0]._mp_size == 0 {
        /* g = 0 u + sgn(v) v */
        let mut sign: i64 = (unsafe { mpz_sgn(v) }) as i64;
        unsafe { mpz_abs(g, v) };
        if !s.is_null() {
            unsafe { mpz_set_ui(s, 0u64) };
        }
        if !t.is_null() {
            unsafe { mpz_set_si(t, sign) };
        }
        return;
    }
    if v[0]._mp_size == 0 {
        /* g = sgn(u) u + 0 v */
        let mut sign: i64 = (unsafe { mpz_sgn(u) }) as i64;
        unsafe { mpz_abs(g, u) };
        if !s.is_null() {
            unsafe { mpz_set_si(s, sign) };
        }
        if !t.is_null() {
            unsafe { mpz_set_ui(t, 0u64) };
        }
        return;
    }
    unsafe { mpz_init(tu) };
    unsafe { mpz_init(tv) };
    unsafe { mpz_init(s0) };
    unsafe { mpz_init(s1) };
    unsafe { mpz_init(t0) };
    unsafe { mpz_init(t1) };
    unsafe { mpz_abs(tu, u) };
    uz = unsafe { mpz_make_odd(tu) };
    unsafe { mpz_abs(tv, v) };
    vz = unsafe { mpz_make_odd(tv) };
    gz = (if (uz < vz) { uz } else { vz });
    uz -= gz;
    vz -= gz;
    /* Cofactors corresponding to odd gcd. gz handled later. */
    if tu[0]._mp_size < tv[0]._mp_size {
        unsafe { mpz_swap(tu, tv) };
        {
            let mut __mpz_srcptr_swap__tmp: *const __mpz_struct = (u.as_mut_ptr() as *const __mpz_struct);
            u = v;
            v = __mpz_srcptr_swap__tmp;
        }
        {
            let mut __mpz_ptr_swap__tmp: *mut __mpz_struct = (s.as_mut_ptr() as *mut __mpz_struct);
            s = t;
            t = __mpz_ptr_swap__tmp;
        }
        {
            let mut __mp_bitcnt_t_swap__tmp: u64 = uz;
            uz = vz;
            vz = __mp_bitcnt_t_swap__tmp;
        }
    }
    /* Maintain
       *
       * u = t0 tu + t1 tv
       * v = s0 tu + s1 tv
       *
       * where u and v denote the inputs with common factors of two
       * eliminated, and det (s0, t0; s1, t1) = 2^p. Then
       *
       * 2^p tu =  s1 u - t1 v
       * 2^p tv = -s0 u + t0 v
       */
    /* After initial division, tu = q tv + tu', we have
       *
       * u = 2^uz (tu' + q tv)
       * v = 2^vz tv
       *
       * or
       *
       * t0 = 2^uz, t1 = 2^uz q
       * s0 = 0,    s1 = 2^vz
       */
    unsafe { mpz_setbit(t0, uz) };
    unsafe { mpz_tdiv_qr(t1, tu, tu, tv) };
    unsafe { mpz_mul_2exp(t1, t1, uz) };
    unsafe { mpz_setbit(s1, vz) };
    power = uz + vz;
    if tu[0]._mp_size > 0 {
        let mut shift: u64 = 0;
        shift = unsafe { mpz_make_odd(tu) };
        unsafe { mpz_mul_2exp(t0, t0, shift) };
        unsafe { mpz_mul_2exp(s0, s0, shift) };
        power += shift;
        loop {
            let mut c: i32 = 0;
            c = unsafe { mpz_cmp(tu, tv) };
            if c == 0 {
                break;
            }
            if c < 0 {
                /* tv = tv' + tu
            	       *
            	       * u = t0 tu + t1 (tv' + tu) = (t0 + t1) tu + t1 tv'
            	       * v = s0 tu + s1 (tv' + tu) = (s0 + s1) tu + s1 tv' */
                unsafe { mpz_sub(tv, tv, tu) };
                unsafe { mpz_add(t0, t0, t1) };
                unsafe { mpz_add(s0, s0, s1) };
                shift = unsafe { mpz_make_odd(tv) };
                unsafe { mpz_mul_2exp(t1, t1, shift) };
                unsafe { mpz_mul_2exp(s1, s1, shift) };
            } else {
                unsafe { mpz_sub(tu, tu, tv) };
                unsafe { mpz_add(t1, t0, t1) };
                unsafe { mpz_add(s1, s0, s1) };
                shift = unsafe { mpz_make_odd(tu) };
                unsafe { mpz_mul_2exp(t0, t0, shift) };
                unsafe { mpz_mul_2exp(s0, s0, shift) };
            }
            power += shift;
        }
    }
    /* Now tv = odd part of gcd, and -s0 and t0 are corresponding
         cofactors. */
    unsafe { mpz_mul_2exp(tv, tv, gz) };
    unsafe { mpz_neg(s0, s0) };
    /* 2^p g = s0 u + t0 v. Eliminate one factor of two at a time. To
         adjust cofactors, we need u / g and v / g */
    unsafe { mpz_divexact(s1, v, tv) };
    unsafe { mpz_abs(s1, s1) };
    unsafe { mpz_divexact(t1, u, tv) };
    unsafe { mpz_abs(t1, t1) };
    while ({ let __old = power; power -= 1; __old }) > (0 as u64) {
        /* s0 u + t0 v = (s0 - v/g) u - (t0 + u/g) v */
        if ((((s0[0]._mp_size != 0) as i32) & ((*s0[0]._mp_d.offset(0)) as i32)) != 0) || ((((t0[0]._mp_size != 0) as i32) & ((*t0[0]._mp_d.offset(0)) as i32)) != 0) {
            unsafe { mpz_sub(s0, s0, s1) };
            unsafe { mpz_add(t0, t0, t1) };
        }
        unsafe { mpz_divexact_ui(s0, s0, 2u64) };
        unsafe { mpz_divexact_ui(t0, t0, 2u64) };
    }
    /* Arrange so that |s| < |u| / 2g */
    unsafe { mpz_add(s1, s0, s1) };
    if (unsafe { mpz_cmpabs(s0, s1) }) > 0 {
        unsafe { mpz_swap(s0, s1) };
        unsafe { mpz_sub(t0, t0, t1) };
    }
    if u[0]._mp_size < 0 {
        unsafe { mpz_neg(s0, s0) };
    }
    if v[0]._mp_size < 0 {
        unsafe { mpz_neg(t0, t0) };
    }
    unsafe { mpz_swap(g, tv) };
    if !s.is_null() {
        unsafe { mpz_swap(s, s0) };
    }
    if !t.is_null() {
        unsafe { mpz_swap(t, t0) };
    }
    unsafe { mpz_clear(tu) };
    unsafe { mpz_clear(tv) };
    unsafe { mpz_clear(s0) };
    unsafe { mpz_clear(s1) };
    unsafe { mpz_clear(t0) };
    unsafe { mpz_clear(t1) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpz_lcm_ui(mut r: [__mpz_struct; 1], mut u: [__mpz_struct; 1], mut v: u64) {
    if (v == (0 as u64)) || (u[0]._mp_size == 0) {
        r[0]._mp_size = 0;
        return;
    }
    v /= unsafe { mpz_gcd_ui(core::ptr::null_mut(), u, v) };
    unsafe { mpz_mul_ui(r, u, v) };
    unsafe { mpz_abs(r, r) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpz_lcm(mut r: [__mpz_struct; 1], mut u: [__mpz_struct; 1], mut v: [__mpz_struct; 1]) {
    let mut g: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    if (u[0]._mp_size == 0) || (v[0]._mp_size == 0) {
        r[0]._mp_size = 0;
        return;
    }
    unsafe { mpz_init(g) };
    unsafe { mpz_gcd(g, u, v) };
    unsafe { mpz_divexact(g, u, g) };
    unsafe { mpz_mul(r, g, v) };
    unsafe { mpz_clear(g) };
    unsafe { mpz_abs(r, r) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpz_invert(mut r: [__mpz_struct; 1], mut u: [__mpz_struct; 1], mut m: [__mpz_struct; 1]) -> i32 {
    let mut g: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut tr: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut invertible: i32 = 0;
    if (u[0]._mp_size == 0) || ((unsafe { mpz_cmpabs_ui(m, 1u64) }) <= 0) {
        return 0;
    }
    unsafe { mpz_init(g) };
    unsafe { mpz_init(tr) };
    unsafe { mpz_gcdext(g, tr, core::ptr::null_mut(), u, m) };
    invertible = ((unsafe { mpz_cmp_ui(g, 1u64) }) == 0) as i32;
    if invertible != 0 {
        if tr[0]._mp_size < 0 {
            if m[0]._mp_size >= 0 {
                unsafe { mpz_add(tr, tr, m) };
            } else {
                unsafe { mpz_sub(tr, tr, m) };
            }
        }
        unsafe { mpz_swap(r, tr) };
    }
    unsafe { mpz_clear(g) };
    unsafe { mpz_clear(tr) };
    return invertible;
}

/* Compute s = floor(sqrt(u)) and r = u - s^2. Allows r == NULL */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpz_sqrtrem(mut s: [__mpz_struct; 1], mut r: [__mpz_struct; 1], mut u: [__mpz_struct; 1]) {
    unsafe { mpz_rootrem(s, r, u, 2u64) };
}

