#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpz_probab_prime_p(mut n: [__mpz_struct; 1], mut reps: i32) -> i32 {
    let mut nm1: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut q: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut y: [__mpz_struct; 1] = unsafe { core::mem::zeroed() };
    let mut k: u64 = 0;
    let mut is_prime: i32 = 0;
    let mut j: i32 = 0;
    /* Note that we use the absolute value of n only, for compatibility
         with the real GMP. */
    if !((((n[0]._mp_size != 0) as i32) & ((*n[0]._mp_d.offset(0)) as i32)) != 0) {
        return (if ((unsafe { mpz_cmpabs_ui(n, 2u64) }) == 0) { 2 } else { 0 });
    }
    /* Above test excludes n == 0 */
    assert!(n[0]._mp_size != 0);
    if (unsafe { mpz_cmpabs_ui(n, 64u64) }) < 0 {
        return ((GMP_PRIME_MASK >> (((*n[0]._mp_d.offset(0)) >> (1 as u32)) as u32)) & (2 as u64)) as i32;
    }
    if (unsafe { mpz_gcd_ui(core::ptr::null_mut(), n, 3234846615u64) }) != (1 as u64) {
        return 0;
    }
    /* All prime factors are >= 31. */
    if (unsafe { mpz_cmpabs_ui(n, 961u64) }) < 0 {
        return 2;
    }
    /* Use Miller-Rabin, with a deterministic sequence of bases, a[j] =
         j^2 + j + 41 using Euler's polynomial. We potentially stop early,
         if a[j] >= n - 1. Since n >= 31*31, this can happen only if reps >
         30 (a[30] == 971 > 31*31 == 961). */
    unsafe { mpz_init(nm1) };
    unsafe { mpz_init(q) };
    unsafe { mpz_init(y) };
    /* Find q and k, where q is odd and n = 1 + 2**k * q.  */
    nm1[0]._mp_size = (unsafe { mpz_abs_sub_ui(nm1, n, 1u64) }) as i32;
    k = unsafe { mpz_scan1(nm1, 0u64) };
    unsafe { mpz_tdiv_q_2exp(q, nm1, k) };
    {
        j = 0; is_prime = 1;
        'b0: while (is_prime & ((j < reps) as i32)) != 0 {
            unsafe { mpz_set_ui(y, (((j as u64) * (j as u64)) + (j as u64)) + (41 as u64)) };
            if (unsafe { mpz_cmp(y, nm1) }) >= 0 {
                /* Don't try any further bases. This "early" break does not affect
            	     the result for any reasonable reps value (<=5000 was tested) */
                assert!(j >= 30);
                break 'b0;
            }
            is_prime = unsafe { gmp_millerrabin(n, nm1, y, q, k) };
            j += 1;
        }
    }
    unsafe { mpz_clear(nm1) };
    unsafe { mpz_clear(q) };
    unsafe { mpz_clear(y) };
    return is_prime;
}

/* Logical operations and bit manipulation. */
/* Numbers are treated as if represented in two's complement (and
   infinitely sign extended). For a negative values we get the two's
   complement from -x = ~x + 1, where ~ is bitwise complement.
   Negation transforms

     xxxx10...0

   into

     yyyy10...0

   where yyyy is the bitwise complement of xxxx. So least significant
   bits, up to and including the first one bit, are unchanged, and
   the more significant bits are all complemented.

   To change a bit from zero to one in a negative number, subtract the
   corresponding power of two from the absolute value. This can never
   underflow. To change a bit from one to zero, add the corresponding
   power of two, and this might overflow. E.g., if x = -001111, the
   two's complement is 110001. Clearing the least significant bit, we
   get two's complement 110000, and -010000. */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn mpz_tstbit(mut d: [__mpz_struct; 1], mut bit_index: u64) -> i32 {
    let mut limb_index: i64 = 0;
    let mut shift: u32 = 0;
    let mut ds: i64 = 0;
    let mut dn: i64 = 0;
    let mut w: u64 = 0;
    let mut bit: i32 = 0;
    ds = (d[0]._mp_size) as i64;
    dn = (if (ds >= (0 as i64)) { ds } else { -ds });
    limb_index = ((bit_index as usize) / GMP_LIMB_BITS) as i64;
    if limb_index >= dn {
        return (ds < (0 as i64)) as i32;
    }
    shift = ((bit_index as usize) % GMP_LIMB_BITS) as u32;
    w = *d[0]._mp_d.offset(limb_index as isize);
    bit = ((w >> (shift as u32)) & (1 as u64)) as i32;
    if ds < (0 as i64) {
        /* d < 0. Check if any of the bits below is set: If so, our bit
    	 must be complemented. */
        if (shift > (0 as u32)) && ((w << ((GMP_LIMB_BITS - (shift as usize)) as u32)) > (0 as u64)) {
            return bit ^ 1;
        }
        while ({ limb_index -= 1; limb_index }) >= (0 as i64) {
            if (*d[0]._mp_d.offset(limb_index as isize)) > (0 as u64) {
                return bit ^ 1;
            }
        }
    }
    return bit;
}

#[unsafe(no_mangle)]
