    static mut cb_ctl_array: [mnl_cb_t; 16] = [unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, mnl_batch_extack_cb, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];
    // TODO initializer: { . err_list = err_list , . nl_ctx = ctx , }
    let mut cb_data: netlink_cb_data = unsafe { core::mem::zeroed() };
