    unsafe { nftnl_flowtable_nlmsg_build_payload(nlh, (n as *const nftnl_flowtable)) };
    unsafe { nftnl_flowtable_free((n as *const nftnl_flowtable)) };
    nln_list = unsafe { nftnl_flowtable_list_alloc() };
