#[unsafe(no_mangle)]
pub unsafe extern "C" fn mnl_nft_flowtable_add(mut ctx: *mut netlink_ctx, mut cmd: *mut cmd, mut flags: u32) -> i32 {
    let mut flo: *mut nftnl_flowtable = core::ptr::null_mut();
    let mut nlh: *mut nlmsghdr = core::ptr::null_mut();
    let mut nest: *mut nlattr = core::ptr::null_mut();
    let mut priority: i32 = 0;
    flo = unsafe { nftnl_flowtable_alloc() };
    if flo.is_null() {
        unsafe { memory_allocation_error() };
    }
    unsafe { nftnl_flowtable_set_u32(flo, 1u16, (*cmd).handle.family as u32) };
    unsafe { nftnl_flowtable_set_u32(flo, 8u16, (*(*cmd).flowtable).flags as u32) };
    unsafe { netlink_dump_flowtable(flo, ctx) };
    nlh = unsafe { nftnl_nlmsg_build_hdr((unsafe { nftnl_batch_buffer(((*ctx).batch as *mut nftnl_batch)) } as *mut core::ffi::c_char), 22u16, (*cmd).handle.family as u16, ((NLM_F_CREATE as u32) | flags) as u16, (*ctx).seqnum as u32) };
    unsafe { cmd_add_loc(cmd, (nlh as *const nlmsghdr), (&raw mut (*cmd).handle.table.location as *const location)) };
    unsafe { mnl_attr_put_strz(nlh, NFTA_FLOWTABLE_TABLE, (*cmd).handle.table.name) };
    unsafe { cmd_add_loc(cmd, (nlh as *const nlmsghdr), (&raw mut (*cmd).handle.flowtable.location as *const location)) };
    unsafe { mnl_attr_put_strz(nlh, NFTA_FLOWTABLE_NAME, (*cmd).handle.flowtable.name) };
    unsafe { nftnl_flowtable_nlmsg_build_payload(nlh, (flo as *const nftnl_flowtable)) };
    nest = (unsafe { mnl_attr_nest_start(nlh, NFTA_FLOWTABLE_HOOK) } as *mut nlattr);
    if ((*cmd).flowtable != 0) && ((*(*cmd).flowtable).priority.expr != 0) {
        unsafe { mnl_attr_put_u32(nlh, NFTA_FLOWTABLE_HOOK_NUM, unsafe { htonl((*(*cmd).flowtable).hook.num as u32) }) };
        unsafe { mpz_export_data(&raw mut priority, (*(*(*cmd).flowtable).priority.expr).value, BYTEORDER_HOST_ENDIAN, core::mem::size_of::<i32>()) };
        unsafe { mnl_attr_put_u32(nlh, NFTA_FLOWTABLE_HOOK_PRIORITY, unsafe { htonl(priority as u32) }) };
    }
    if (*(*cmd).flowtable).dev_expr != 0 {
        unsafe { mnl_nft_ft_devs_build(nlh, cmd) };
    }
    unsafe { mnl_attr_nest_end(nlh, nest) };
    unsafe { nftnl_flowtable_free((flo as *const nftnl_flowtable)) };
    unsafe { mnl_nft_batch_continue(((*ctx).batch as *mut nftnl_batch)) };
    return 0;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mnl_nft_flowtable_del(mut ctx: *mut netlink_ctx, mut cmd: *mut cmd) -> i32 {
    let mut msg_type: nf_tables_msg_types = 24;
    let mut flo: *mut nftnl_flowtable = core::ptr::null_mut();
    let mut nlh: *mut nlmsghdr = core::ptr::null_mut();
    let mut nest: *mut nlattr = core::ptr::null_mut();
    flo = unsafe { nftnl_flowtable_alloc() };
    if flo.is_null() {
        unsafe { memory_allocation_error() };
    }
    unsafe { nftnl_flowtable_set_u32(flo, 1u16, (*cmd).handle.family as u32) };
    if (*cmd).op == CMD_DESTROY {
        msg_type = 32;
    }
    nlh = unsafe { nftnl_nlmsg_build_hdr((unsafe { nftnl_batch_buffer(((*ctx).batch as *mut nftnl_batch)) } as *mut core::ffi::c_char), msg_type as u16, (*cmd).handle.family as u16, 0u16, (*ctx).seqnum as u32) };
    unsafe { cmd_add_loc(cmd, (nlh as *const nlmsghdr), (&raw mut (*cmd).handle.table.location as *const location)) };
    unsafe { mnl_attr_put_strz(nlh, NFTA_FLOWTABLE_TABLE, (*cmd).handle.table.name) };
    if (*cmd).handle.flowtable.name != 0 {
        unsafe { cmd_add_loc(cmd, (nlh as *const nlmsghdr), (&raw mut (*cmd).handle.flowtable.location as *const location)) };
        unsafe { mnl_attr_put_strz(nlh, NFTA_FLOWTABLE_NAME, (*cmd).handle.flowtable.name) };
    } else if (*cmd).handle.handle.id != 0 {
        unsafe { cmd_add_loc(cmd, (nlh as *const nlmsghdr), (&raw mut (*cmd).handle.handle.location as *const location)) };
        unsafe { mnl_attr_put_u64(nlh, NFTA_FLOWTABLE_HANDLE, unsafe { __bswap_64((*cmd).handle.handle.id as u64) }) };
    }
    unsafe { nftnl_flowtable_nlmsg_build_payload(nlh, (flo as *const nftnl_flowtable)) };
    if (((*cmd).op == CMD_DELETE) && ((*cmd).flowtable != 0)) && ((*(*cmd).flowtable).dev_expr != 0) {
        nest = (unsafe { mnl_attr_nest_start(nlh, NFTA_FLOWTABLE_HOOK) } as *mut nlattr);
        unsafe { mnl_nft_ft_devs_build(nlh, cmd) };
        unsafe { mnl_attr_nest_end(nlh, nest) };
    }
    unsafe { nftnl_flowtable_free((flo as *const nftnl_flowtable)) };
    unsafe { mnl_nft_batch_continue(((*ctx).batch as *mut nftnl_batch)) };
    return 0;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mnl_nft_dump_nf_hooks(mut ctx: *mut netlink_ctx, mut family: i32, mut devname: *const core::ffi::c_char) -> i32 {
    let mut hook_list: list_head = list_head { next: &raw mut hook_list, prev: &raw mut hook_list };
    let mut ret: i32 = -1;
    let mut tmp: i32 = 0;
    (*unsafe { __errno_location() }) = 0;
    match family {
        NFPROTO_UNSPEC => {
            ret = unsafe { mnl_nft_dump_nf_hooks(ctx, 3, core::ptr::null()) };
            tmp = unsafe { mnl_nft_dump_nf_hooks(ctx, 1, core::ptr::null()) };
            if tmp == 0 {
                ret = 0;
            }
            tmp = unsafe { mnl_nft_dump_nf_hooks(ctx, 7, core::ptr::null()) };
            if tmp == 0 {
                ret = 0;
            }
            tmp = unsafe { mnl_nft_dump_nf_hooks(ctx, 5, devname) };
            if tmp == 0 {
                ret = 0;
            }
            return ret;
        }
        NFPROTO_INET => {
            ret = 0;
            if !devname.is_null() {
                ret = unsafe { __mnl_nft_dump_nf_hooks(ctx, family as u8, 5u8, 0u8, devname, &raw mut hook_list) };
            }
            tmp = unsafe { mnl_nft_dump_nf_hooks(ctx, 2, core::ptr::null()) };
            if tmp == 0 {
                ret = 0;
            }
            tmp = unsafe { mnl_nft_dump_nf_hooks(ctx, 10, core::ptr::null()) };
            if tmp == 0 {
                ret = 0;
            }
        }
        NFPROTO_IPV4 | NFPROTO_IPV6 | NFPROTO_BRIDGE => {
            unsafe { warn_if_device(((*ctx).nft as *mut nft_ctx), devname) };
            ret = unsafe { mnl_nft_dump_nf(ctx, family, devname, &raw mut hook_list) };
        }
        NFPROTO_ARP => {
            unsafe { warn_if_device(((*ctx).nft as *mut nft_ctx), devname) };
            ret = unsafe { mnl_nft_dump_nf_arp(ctx, family, devname, &raw mut hook_list) };
        }
        NFPROTO_NETDEV => {
            if !devname.is_null() {
                ret = unsafe { mnl_nft_dump_nf_netdev(ctx, family, devname, &raw mut hook_list) };
            } else {
                let mut iface: *const iface = core::ptr::null();
                iface = unsafe { iface_cache_get_next_entry(core::ptr::null()) };
                ret = 0;
                while !iface.is_null() {
                    tmp = unsafe { mnl_nft_dump_nf_netdev(ctx, family, ((*iface).name.as_ptr() as *const core::ffi::c_char), &raw mut hook_list) };
                    if tmp == 0 {
                        ret = 0;
                    }
                    iface = unsafe { iface_cache_get_next_entry(iface) };
                }
            }
        }
        _ => {}
    }
    unsafe { print_hooks(ctx, family, &raw mut hook_list) };
    unsafe { release_hook_list(&raw mut hook_list) };
    return ret;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn mnl_nft_event_listener(mut nf_sock: *mut mnl_socket, mut debug_mask: u32, mut octx: *mut output_ctx, mut cb: Option<unsafe extern "C" fn(*const nlmsghdr, *mut core::ffi::c_void) -> i32>, mut cb_data: *mut core::ffi::c_void) -> i32 {
    /* Set netlink socket buffer size to 16 Mbytes to reduce chances of
    	 * message loss due to ENOBUFS.
    	 */
    let mut bufsiz: u32 = 16777216u32;
    let mut fd: i32 = (unsafe { mnl_socket_get_fd(nf_sock) }) as i32;
    let mut __buf_storage: Vec<core::ffi::c_char> = vec![unsafe { core::mem::zeroed() }; ((u16::MAX as i32) + unsafe { getpagesize() }) as usize];
    let buf: *mut core::ffi::c_char = __buf_storage.as_mut_ptr();
    let mut sigfd: i32 = unsafe { get_signalfd() };
    let mut pfd: [pollfd; 2] = [pollfd { fd: fd, events: 1i16, ..unsafe { core::mem::zeroed() } }, pollfd { fd: sigfd, events: 1i16, ..unsafe { core::mem::zeroed() } }];
    let mut ret: i32 = 0;
    ret = unsafe { mnl_set_rcvbuffer((nf_sock as *const mnl_socket), bufsiz) };
    if ret < 0 {
        unsafe { nft_print(octx, c"# Cannot set up netlink receive socket buffer size to %u bytes, falling back to %u bytes\n".as_ptr(), NFTABLES_NLEVENT_BUFSIZ, bufsiz) };
    }
    loop {
        ret = unsafe { poll((pfd.as_mut_ptr() as *mut pollfd), ((core::mem::size_of::<[pollfd; 2]>() / core::mem::size_of::<pollfd>()) + (core::mem::size_of::<[core::ffi::c_char; 1]>() - (1 as usize))) as u64, -1) };
        if ret < 0 {
            return -1;
        }
        if (sigfd >= 0) && ((((pfd[1].revents) as i32) & POLLIN) != 0) {
            unsafe { check_signalfd(sigfd) };
        }
        if (((pfd[0].revents) as i32) & POLLIN) != 0 {
            ret = (unsafe { mnl_socket_recvfrom(nf_sock, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
            if ret < 0 {
                if (*unsafe { __errno_location() }) == ENOBUFS {
                    unsafe { nft_print(octx, c"# ERROR: We lost some netlink events!\n".as_ptr()) };
                    continue;
                }
                unsafe { nft_print(octx, c"# ERROR: %s\n".as_ptr(), unsafe { strerror(*unsafe { __errno_location() }) }) };
                break;
            }
        }
        if (debug_mask & (NFT_DEBUG_MNL as u32)) != 0 {
            unsafe { mnl_nlmsg_fprintf((*octx).anon2.output_fp, buf, core::mem::size_of::<*mut core::ffi::c_char>(), core::mem::size_of::<nfgenmsg>()) };
        }
        ret = (unsafe { mnl_cb_run(buf, ret, 0, 0, cb, cb_data) }) as i32;
        if ret <= 0 {
            break;
        }
    }
    return ret;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn nft_mnl_talk(mut ctx: *mut netlink_ctx, mut data: *const core::ffi::c_void, mut len: u32, mut cb: Option<unsafe extern "C" fn(*const nlmsghdr, *mut core::ffi::c_void) -> i32>, mut cb_data: *mut core::ffi::c_void) -> i32 {
    let mut portid: u32 = (unsafe { mnl_socket_get_portid((*(*ctx).nft).nf_sock) }) as u32;
    if ((*(*ctx).nft).debug_mask & NFT_DEBUG_MNL) != 0 {
        unsafe { mnl_nlmsg_fprintf((*(*ctx).nft).output.output_fp, data, len, core::mem::size_of::<nfgenmsg>()) };
    }
    if (unsafe { mnl_socket_sendto((*(*ctx).nft).nf_sock, data, len) }) < 0 {
        return -1;
    }
    return unsafe { nft_mnl_recv(ctx, portid, cb, cb_data) };
}

unsafe extern "C" fn get_signalfd() -> i32 {
    return -1;
}

unsafe extern "C" fn check_signalfd(mut fd: i32) {
}

unsafe extern "C" fn nft_mnl_recv(mut ctx: *mut netlink_ctx, mut portid: u32, mut cb: Option<unsafe extern "C" fn(*const nlmsghdr, *mut core::ffi::c_void) -> i32>, mut cb_data: *mut core::ffi::c_void) -> i32 {
    let mut __buf_storage: Vec<core::ffi::c_char> = vec![unsafe { core::mem::zeroed() }; ((u16::MAX as i32) + unsafe { getpagesize() }) as usize];
    let buf: *mut core::ffi::c_char = __buf_storage.as_mut_ptr();
    let mut eintr: bool = false;
    let mut ret: i32 = 0;
    ret = (unsafe { mnl_socket_recvfrom((*(*ctx).nft).nf_sock, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
    while ret > 0 {
        ret = (unsafe { mnl_cb_run(buf, ret, (*ctx).seqnum, portid, cb, cb_data) }) as i32;
        if ret == 0 {
            break;
        }
        if ret < 0 {
            if (*unsafe { __errno_location() }) == EAGAIN {
                ret = 0;
                break;
            }
            if (*unsafe { __errno_location() }) != EINTR {
                break;
            }
            /* process all pending messages before reporting EINTR */
            eintr = true;
        }
        ret = (unsafe { mnl_socket_recvfrom((*(*ctx).nft).nf_sock, buf, core::mem::size_of::<*mut core::ffi::c_char>()) }) as i32;
    }
    if eintr {
        ret = -1;
        (*unsafe { __errno_location() }) = 4;
    }
    return ret;
}

unsafe extern "C" fn genid_cb(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut nfh: *mut nfgenmsg = (unsafe { mnl_nlmsg_get_payload(nlh) } as *mut nfgenmsg);
    nft_genid = (unsafe { ntohs((*nfh).res_id) }) as u32;
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn nft_genid_u16(mut genid: u32) -> u16 {
    return (genid & (65535 as u32)) as u16;
}

unsafe extern "C" fn check_genid(mut nlh: *const nlmsghdr) -> i32 {
    let mut nfh: *mut nfgenmsg = (unsafe { mnl_nlmsg_get_payload(nlh) } as *mut nfgenmsg);
    if (unsafe { nft_genid_u16(nft_genid) }) != unsafe { ntohs((*nfh).res_id) } {
        (*unsafe { __errno_location() }) = 4;
        return -1;
    }
    return 0;
}

unsafe extern "C" fn mnl_nft_batch_continue(mut batch: *mut nftnl_batch) {
    if (unsafe { nftnl_batch_update(batch) }) < 0 {
        unsafe { memory_allocation_error() };
    }
}

unsafe extern "C" fn mnl_err_list_node_add(mut err_list: *mut list_head, mut error: i32, mut seqnum: i32, mut offset: u32, mut errmsg: *const core::ffi::c_char) {
    let mut err: *mut mnl_err = (unsafe { xmalloc(core::mem::size_of::<mnl_err>()) } as *mut mnl_err);
    (*err).seqnum = seqnum as u32;
    (*err).offset = offset;
    (*err).err = error;
    unsafe { list_add_tail(&raw mut (*err).head, err_list) };
}

unsafe extern "C" fn mnl_set_sndbuffer(mut ctx: *mut netlink_ctx) {
    let mut nl: *mut mnl_socket = ((*(*ctx).nft).nf_sock as *mut mnl_socket);
    let mut batch: *mut nftnl_batch = ((*ctx).batch as *mut nftnl_batch);
    let mut len: u32 = (core::mem::size_of::<i32>()) as u32;
    let mut sndnlbuffsiz: i32 = 0;
    let mut newbuffsiz: i32 = 0;
    unsafe { getsockopt((unsafe { mnl_socket_get_fd(nl) }) as i32, 1, 7, (&raw mut sndnlbuffsiz as *mut core::ffi::c_void), &raw mut len) };
    newbuffsiz = (unsafe { nftnl_batch_iovec_len(batch) }) * BATCH_PAGE_SIZE;
    if newbuffsiz <= sndnlbuffsiz {
        return;
    }
    /* Rise sender buffer length to avoid hitting -EMSGSIZE */
    unsafe { setsockopt((unsafe { mnl_socket_get_fd(nl) }) as i32, 1, 7, (&raw mut newbuffsiz as *const core::ffi::c_void), (core::mem::size_of::<u32>()) as u32) };
    /* unpriviledged containers check for CAP_NET_ADMIN on the init_user_ns. */
    if (unsafe { setsockopt((unsafe { mnl_socket_get_fd(nl) }) as i32, 1, 32, (&raw mut newbuffsiz as *const core::ffi::c_void), (core::mem::size_of::<u32>()) as u32) }) < 0 {
        if (*unsafe { __errno_location() }) == EPERM {
            (*ctx).maybe_emsgsize = newbuffsiz;
        }
    }
}

unsafe extern "C" fn mnl_set_rcvbuffer(mut nl: *const mnl_socket, mut bufsiz: u32) -> i32 {
    let mut len: u32 = (core::mem::size_of::<u32>()) as u32;
    let mut ret: i32 = 0;
    if !(nlsndbufsiz != 0) {
        unsafe { getsockopt((unsafe { mnl_socket_get_fd(nl) }) as i32, 1, 8, (&raw mut nlsndbufsiz as *mut core::ffi::c_void), &raw mut len) };
    }
    if nlsndbufsiz >= bufsiz {
        return 0;
    }
    ret = unsafe { setsockopt((unsafe { mnl_socket_get_fd(nl) }) as i32, 1, 33, (&raw mut bufsiz as *const core::ffi::c_void), (core::mem::size_of::<u32>()) as u32) };
    if ret < 0 {
        /* If this doesn't work, try to reach the system wide maximum
    		 * (or whatever the user requested).
    		 */
        ret = unsafe { setsockopt((unsafe { mnl_socket_get_fd(nl) }) as i32, 1, 8, (&raw mut bufsiz as *const core::ffi::c_void), (core::mem::size_of::<u32>()) as u32) };
    }
    return ret;
}

unsafe extern "C" fn mnl_nft_batch_to_msg(mut ctx: *mut netlink_ctx, mut msg: *mut msghdr, mut snl: *const sockaddr_nl, mut iov: *mut iovec, mut iov_len: u32) {
    (*msg).msg_name = ((snl as *mut sockaddr_nl) as *mut core::ffi::c_void);
    (*msg).msg_namelen = (core::mem::size_of::<sockaddr_nl>()) as u32;
    (*msg).msg_iov = iov;
    (*msg).msg_iovlen = iov_len as usize;
    unsafe { nftnl_batch_iovec(((*ctx).batch as *mut nftnl_batch), iov, iov_len) };
}

unsafe extern "C" fn mnl_nft_socket_sendmsg(mut ctx: *mut netlink_ctx, mut msg: *const msghdr) -> isize {
    let mut iov_len: u32 = (*msg).msg_iovlen as u32;
    let mut iov: *mut iovec = (*msg).msg_iov;
    let mut i: u32 = 0;
    if ((*(*ctx).nft).debug_mask & NFT_DEBUG_MNL) != 0 {
        {
            i = 0u32;
            while i < iov_len {
                unsafe { mnl_nlmsg_fprintf((*(*ctx).nft).output.output_fp, (*iov.offset(i as isize)).iov_base, (*iov.offset(i as isize)).iov_len, core::mem::size_of::<nfgenmsg>()) };
                i += 1;
            }
        }
    }
    return unsafe { sendmsg((unsafe { mnl_socket_get_fd((*(*ctx).nft).nf_sock) }) as i32, msg, 0) };
}

unsafe extern "C" fn err_attr_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut tb: *mut *const nlattr = (data as *mut *const nlattr);
    let mut type_: u16 = 0;
    if (unsafe { mnl_attr_type_valid(attr, NLMSGERR_ATTR_MAX) }) < 0 {
        return MNL_CB_ERROR as i32;
    }
    type_ = (unsafe { mnl_attr_get_type(attr) }) as u16;
    match (type_ as i32) {
        _ => {}
    }
    (*tb.offset(type_ as isize)) = attr;
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn mnl_batch_extack_cb(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut cb_data: *mut netlink_cb_data = (data as *mut netlink_cb_data);
    // TODO initializer: { }
    let mut tb: *mut *mut nlattr = unsafe { core::mem::zeroed() };
    let mut err: *const nlmsgerr = (unsafe { mnl_nlmsg_get_payload(nlh) } as *const nlmsgerr);
    let mut hlen: u32 = (core::mem::size_of::<nlmsgerr>()) as u32;
    let mut msg: *const core::ffi::c_char = core::ptr::null();
    let mut off: u32 = 0u32;
    let mut errval: i32 = 0;
    if (*nlh).nlmsg_len < unsafe { mnl_nlmsg_size(core::mem::size_of::<nlmsgerr>()) } {
        return MNL_CB_ERROR as i32;
    }
    if (*err).error < 0 {
        errval = -(*err).error;
    } else {
        errval = (*err).error;
    }
    if errval == 0 {
        return MNL_CB_STOP as i32;
    }
    if !((((*nlh).nlmsg_flags as i32) & 256) != 0) {
        hlen += ((unsafe { mnl_nlmsg_get_payload_len(((&raw const (*err).msg).cast_mut())) }) as u32);
    }
    if (unsafe { mnl_attr_parse(nlh, hlen, Some(err_attr_cb), tb) }) != MNL_CB_OK {
        return MNL_CB_ERROR as i32;
    }
    if !(*tb.offset(NLMSGERR_ATTR_OFFS as isize)).is_null() {
        off = (unsafe { mnl_attr_get_u32((*tb.offset(NLMSGERR_ATTR_OFFS as isize))) }) as u32;
    }
    unsafe { mnl_err_list_node_add(((*cb_data).err_list as *mut list_head), errval, (*nlh).nlmsg_seq as i32, off, msg) };
    return MNL_CB_ERROR as i32;
}

unsafe extern "C" fn mnl_nft_expr_build_cb(mut nle: *mut nftnl_expr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut ctx: *mut mnl_nft_rule_build_ctx = (data as *mut mnl_nft_rule_build_ctx);
    let mut nlh: *mut nlmsghdr = (*ctx).nlh;
    let mut cmd: *mut cmd = (*ctx).cmd;
    let mut eloc: *mut nft_expr_loc = core::ptr::null_mut();
    let mut nest: *mut nlattr = core::ptr::null_mut();
    eloc = (unsafe { nft_expr_loc_find(nle, (*ctx).lctx) } as *mut nft_expr_loc);
    if !eloc.is_null() {
        unsafe { cmd_add_loc(cmd, (nlh as *const nlmsghdr), ((*eloc).loc as *const location)) };
    }
    nest = (unsafe { mnl_attr_nest_start(nlh, NFTA_LIST_ELEM) } as *mut nlattr);
    unsafe { nftnl_expr_build_payload(nlh, nle) };
    unsafe { mnl_attr_nest_end(nlh, nest) };
    unsafe { nftnl_rule_del_expr(nle) };
    unsafe { nftnl_expr_free((nle as *const nftnl_expr)) };
    return 0;
}

unsafe extern "C" fn mnl_nft_rule_build_ctx_init(mut rule_ctx: *mut mnl_nft_rule_build_ctx, mut nlh: *mut nlmsghdr, mut cmd: *mut cmd, mut lctx: *mut netlink_linearize_ctx) {
    unsafe { memset((rule_ctx as *mut core::ffi::c_void), 0, core::mem::size_of::<mnl_nft_rule_build_ctx>()) };
    (*rule_ctx).nlh = nlh;
    (*rule_ctx).cmd = cmd;
    (*rule_ctx).lctx = lctx;
}

unsafe extern "C" fn rule_cb(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut args: *mut rule_cb_args = (data as *mut rule_cb_args);
    let mut nlr_list: *mut nftnl_rule_list = (*args).list;
    let mut r: *mut nftnl_rule = core::ptr::null_mut();
    if (unsafe { check_genid(nlh) }) < 0 {
        return MNL_CB_ERROR as i32;
    }
    r = unsafe { nftnl_rule_alloc() };
    if r.is_null() {
        unsafe { memory_allocation_error() };
    }
    'g_err_free: {
        if (unsafe { nftnl_rule_nlmsg_parse(nlh, r) }) < 0 {
            break 'g_err_free;
        }
        unsafe { netlink_dump_rule(r, (*args).ctx) };
        unsafe { nftnl_rule_list_add_tail(r, nlr_list) };
        return MNL_CB_OK as i32;
    }
    unsafe { nftnl_rule_free((r as *const nftnl_rule)) };
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn nft_dev_add(mut dev_array: *mut nft_dev, mut expr: *const expr, mut i: i32) {
    let mut ifname_len: u32 = 0;
    let mut ifname: [core::ffi::c_char; 16] = [0; 16];
    if (*expr).etype != EXPR_VALUE {
        unsafe { BUG(c"Must be a value, not %s".as_ptr(), unsafe { expr_name(expr) }) };
    }
    ifname_len = ((((*expr).len + BITS_PER_BYTE) - 1) / BITS_PER_BYTE) as u32;
    unsafe { memset((ifname.as_mut_ptr() as *mut core::ffi::c_void), 0, core::mem::size_of::<[core::ffi::c_char; 16]>()) };
    if (ifname_len as usize) > core::mem::size_of::<[core::ffi::c_char; 16]>() {
        unsafe { BUG(c"Interface length %u exceeds limit".as_ptr(), ifname_len) };
    }
    unsafe { mpz_export_data(ifname.as_mut_ptr(), (*expr).value, BYTEORDER_HOST_ENDIAN, ifname_len) };
    if (unsafe { strnlen((ifname.as_mut_ptr() as *const core::ffi::c_char), 16usize) }) >= (IFNAMSIZ as usize) {
        unsafe { BUG(c"Interface length %zu exceeds limit, no NUL byte".as_ptr(), unsafe { strnlen((ifname.as_mut_ptr() as *const core::ffi::c_char), 16usize) }) };
    }
    (*dev_array.offset(i as isize)).ifname = (unsafe { xstrdup(ifname.as_mut_ptr()) } as *const core::ffi::c_char);
    (*dev_array.offset(i as isize)).location = (((&raw const (*expr).location).cast_mut()) as *const location);
}

unsafe extern "C" fn nft_dev_array(mut dev_expr: *const expr, mut num_devs: *mut i32) -> *mut nft_dev {
    let mut dev_array: *mut nft_dev = core::ptr::null_mut();
    let mut i: i32 = 0;
    let mut len: i32 = 1;
    let mut expr: *mut expr = core::ptr::null_mut();
    match (*dev_expr).etype {
        _ => {
            assert!(false);
        }
    }
    (*dev_array.offset(i as isize)).ifname = core::ptr::null();
    (*num_devs) = i;
    return dev_array;
}

unsafe extern "C" fn nft_dev_array_free(mut dev_array: *const nft_dev) {
    let mut i: i32 = 0;
    while !(*dev_array.offset(i as isize)).ifname.is_null() {
        unsafe { free(((*dev_array.offset(({ let __old = i; i += 1; __old }) as isize)).ifname as *mut core::ffi::c_void)) };
    }
    unsafe { free((dev_array as *mut core::ffi::c_void)) };
}

unsafe extern "C" fn is_wildcard_str(mut str: *const core::ffi::c_char) -> bool {
    let mut len: usize = unsafe { strlen(str) };
    if (len < (1 as usize)) || (((*str.offset((len - (1 as usize)) as isize)) as i32) != 42) {
        return false;
    }
    if (len < (2 as usize)) || (((*str.offset((len - (2 as usize)) as isize)) as i32) != 92) {
        return true;
    }
    /* XXX: ignore backslash escaping for now */
    return false;
}

unsafe extern "C" fn mnl_nft_attr_put_ifname(mut nlh: *mut nlmsghdr, mut ifname: *const core::ffi::c_char) {
    let mut attr: u16 = 1u16;
    let mut pfx: [core::ffi::c_char; 16] = [0; 16];
    if unsafe { is_wildcard_str(ifname) } {
        unsafe { snprintf((pfx.as_mut_ptr() as *mut core::ffi::c_char), 16usize, c"%s".as_ptr(), ifname) };
        pfx[((unsafe { strlen((pfx.as_mut_ptr() as *const core::ffi::c_char)) }) - (1 as usize)) as usize] = (0 as core::ffi::c_char);
        attr = 2u16;
        ifname = (pfx.as_mut_ptr() as *const core::ffi::c_char);
    }
    unsafe { mnl_attr_put_strz(nlh, (attr as i32), ifname) };
}

unsafe extern "C" fn mnl_nft_chain_devs_build(mut nlh: *mut nlmsghdr, mut cmd: *mut cmd) {
    let mut dev_expr: *const expr = ((*(*cmd).chain).dev_expr as *const expr);
    let mut dev_array: *const nft_dev = core::ptr::null();
    let mut nest_dev: *mut nlattr = core::ptr::null_mut();
    let mut i: i32 = 0;
    let mut num_devs: i32 = 0;
    dev_array = (unsafe { nft_dev_array(dev_expr, &raw mut num_devs) } as *const nft_dev);
    if (num_devs == 1) && !unsafe { is_wildcard_str((*dev_array.offset(0)).ifname) } {
        unsafe { cmd_add_loc(cmd, (nlh as *const nlmsghdr), (*dev_array.offset(0)).location) };
        unsafe { mnl_attr_put_strz(nlh, NFTA_HOOK_DEV, (*dev_array.offset(0)).ifname) };
    } else {
        nest_dev = (unsafe { mnl_attr_nest_start(nlh, NFTA_HOOK_DEVS) } as *mut nlattr);
        {
            i = 0;
            while i < num_devs {
                unsafe { cmd_add_loc(cmd, (nlh as *const nlmsghdr), (*dev_array.offset(i as isize)).location) };
                unsafe { mnl_nft_attr_put_ifname(nlh, (*dev_array.offset(i as isize)).ifname) };
                i += 1;
            }
        }
        unsafe { mnl_attr_nest_end(nlh, nest_dev) };
    }
    unsafe { nft_dev_array_free(dev_array) };
}

