unsafe extern "C" fn mnl_nft_attr_nest_overflow(mut nlh: *mut nlmsghdr, mut from: *const nlattr, mut to: *const nlattr, mut nest_len: u32) -> bool {
    let mut len: i32 = ((to as *mut core::ffi::c_void).offset(nest_len as isize).offset_from((from as *mut core::ffi::c_void))) as i32;
    /* The attribute length field is 16 bits long, thus the maximum payload
    	 * that an attribute can convey is UINT16_MAX. In case of overflow,
    	 * discard the last attribute that did not fit into the nest.
    	 */
    if len > (u16::MAX as i32) {
        (*nlh).nlmsg_len -= nest_len;
        return true;
    }
    return false;
}

unsafe extern "C" fn netlink_dump_setelem(mut nlse: *const nftnl_set_elem, mut ctx: *mut netlink_ctx) {
    let mut fp: *mut _IO_FILE = ((*(*ctx).nft).output.output_fp as *mut _IO_FILE);
    let mut buf: [core::ffi::c_char; 4096] = [0; 4096];
    if !(((*(*ctx).nft).debug_mask & NFT_DEBUG_NETLINK) != 0) || fp.is_null() {
        return;
    }
    unsafe { nftnl_set_elem_snprintf((buf.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 4096]>(), nlse, 0u32, 0u32) };
    unsafe { fprintf(fp, c"\t%s".as_ptr(), buf.as_mut_ptr()) };
}

