unsafe extern "C" fn mnl_nft_setelem_batch(mut nls: *const nftnl_set, mut cmd: *mut cmd, mut batch: *mut nftnl_batch, mut msg_type: nf_tables_msg_types, mut flags: u32, mut seqnum: *mut u32, mut set: *const set, mut init: *const expr, mut ctx: *mut netlink_ctx) -> i32 {
    let mut nlse: *mut nftnl_set_elem = core::ptr::null_mut();
    let mut nlse_high: *mut nftnl_set_elem = core::ptr::null_mut();
    let mut nest1: *mut nlattr = core::ptr::null_mut();
    let mut nest2: *mut nlattr = core::ptr::null_mut();
    let mut nest3: *mut nlattr = core::ptr::null_mut();
    let mut expr: *mut expr = core::ptr::null_mut();
    let mut next: *mut expr = core::ptr::null_mut();
    let mut nest_len: u32 = 0u32;
    let mut nlh: *mut nlmsghdr = core::ptr::null_mut();
    let mut i: i32 = 0;
    if msg_type == NFT_MSG_NEWSETELEM {
        flags |= ((NLM_F_CREATE) as u32);
    }
    if !init.is_null() {
        // C (statement): expr = list_first_entry ( & expr_set ( init ) -> expressions , struct expr , list ) ;
        todo!();
    }
    'g_next: loop {
        nlh = unsafe { nftnl_nlmsg_build_hdr((unsafe { nftnl_batch_buffer(batch) } as *mut core::ffi::c_char), msg_type as u16, (unsafe { nftnl_set_get_u32(nls, 7u16) }) as u16, flags as u16, *seqnum) };
        if unsafe { nftnl_set_is_set(nls, 0u16) } {
            unsafe { mnl_attr_put_strz(nlh, NFTA_SET_ELEM_LIST_TABLE, unsafe { nftnl_set_get_str(nls, 0u16) }) };
        }
        if unsafe { nftnl_set_is_set(nls, 1u16) } {
            unsafe { mnl_attr_put_strz(nlh, NFTA_SET_ELEM_LIST_SET, unsafe { nftnl_set_get_str(nls, 1u16) }) };
        }
        if unsafe { nftnl_set_is_set(nls, 8u16) } {
            unsafe { mnl_attr_put_u32(nlh, NFTA_SET_ELEM_LIST_SET_ID, unsafe { htonl(unsafe { nftnl_set_get_u32(nls, 8u16) }) }) };
        }
        if init.is_null() || (unsafe { list_empty((((&raw const (*unsafe { expr_set(init) }).expressions).cast_mut()) as *const list_head)) } != 0) {
            return 0;
        }
        assert!(!expr.is_null());
        nest1 = (unsafe { mnl_attr_nest_start(nlh, NFTA_SET_ELEM_LIST_ELEMENTS) } as *mut nlattr);
        while { let _ = 0; ((&raw mut (*expr).list != ((&raw const (*unsafe { expr_set(init) }).expressions).cast_mut())) as i32) } != 0 {
            if unsafe { set_is_non_concat_range(set) } != 0 {
                if (unsafe { set_is_anonymous((*set).flags) } != 0) && !(unsafe { list_is_last((&raw mut (*expr).list as *const list_head), (((&raw const (*unsafe { expr_set(init) }).expressions).cast_mut()) as *const list_head)) } != 0) {
                    // C (statement): next = list_next_entry ( expr , list ) ;
                    todo!();
                } else {
                    next = core::ptr::null_mut();
                }
                nlse = unsafe { alloc_nftnl_setelem_interval(set, init, expr, next, &raw mut nlse_high) };
            } else {
                nlse = (unsafe { alloc_nftnl_setelem(init, expr) } as *mut nftnl_set_elem);
            }
            unsafe { cmd_add_loc(cmd, (nlh as *const nlmsghdr), (&raw mut (*expr).location as *const location)) };
            nest2 = (unsafe { mnl_attr_nest_start(nlh, { i += 1; i }) } as *mut nlattr);
            unsafe { nftnl_set_elem_nlmsg_build_payload(nlh, nlse) };
            unsafe { mnl_attr_nest_end(nlh, nest2) };
            unsafe { netlink_dump_setelem((nlse as *const nftnl_set_elem), ctx) };
            unsafe { nftnl_set_elem_free(nlse) };
            nest_len = (*nest2).nla_len as u32;
            if !nlse_high.is_null() {
                nest3 = (unsafe { mnl_attr_nest_start(nlh, { i += 1; i }) } as *mut nlattr);
                unsafe { nftnl_set_elem_nlmsg_build_payload(nlh, nlse_high) };
                unsafe { mnl_attr_nest_end(nlh, nest3) };
                unsafe { netlink_dump_setelem((nlse_high as *const nftnl_set_elem), ctx) };
                unsafe { nftnl_set_elem_free(nlse_high) };
                nlse_high = core::ptr::null_mut();
                nest_len += (((*nest3).nla_len) as u32);
            }
            if unsafe { mnl_nft_attr_nest_overflow(nlh, (nest1 as *const nlattr), (nest2 as *const nlattr), nest_len) } {
                unsafe { mnl_attr_nest_end(nlh, nest1) };
                unsafe { mnl_nft_batch_continue(batch) };
                unsafe { mnl_seqnum_inc(seqnum) };
                continue 'g_next;
            }
            // C (for step): expr = list_entry ( expr -> list . next , typeof ( * expr ) , list )
            todo!();
        }
        unsafe { mnl_attr_nest_end(nlh, nest1) };
        unsafe { mnl_nft_batch_continue(batch) };
        unsafe { netlink_dump_setelem_done(ctx) };
        return 0;
        break;
    }
    unsafe { core::mem::zeroed() }
}

