unsafe extern "C" fn basehook_alloc() -> *mut basehook {
    return (unsafe { xzalloc(core::mem::size_of::<basehook>()) } as *mut basehook);
}

unsafe extern "C" fn basehook_free(mut b: *mut basehook) {
    unsafe { list_del(&raw mut (*b).list) };
    unsafe { free(((*b).module_name as *mut core::ffi::c_void)) };
    unsafe { free(((*b).hookfn as *mut core::ffi::c_void)) };
    unsafe { free(((*b).chain as *mut core::ffi::c_void)) };
    unsafe { free(((*b).table as *mut core::ffi::c_void)) };
    unsafe { free(((*b).devname as *mut core::ffi::c_void)) };
    unsafe { free((b as *mut core::ffi::c_void)) };
}

unsafe extern "C" fn basehook_eq(mut prev: *const basehook, mut hook: *const basehook) -> bool {
    if (*prev).num != (*hook).num {
        return false;
    }
    if !(*prev).devname.is_null() && !(*hook).devname.is_null() {
        return (((unsafe { strcmp((*prev).devname, (*hook).devname) }) == 0) as i32) != 0;
    }
    if (*prev).devname.is_null() && (*hook).devname.is_null() {
        return true;
    }
    return false;
}

unsafe extern "C" fn basehook_list_add_tail(mut b: *mut basehook, mut head: *mut list_head) {
    let mut hook: *mut basehook = core::ptr::null_mut();
    {
        // C (statement): hook = list_entry ( ( head ) -> next , typeof ( * hook ) , list ) ;
        todo!();
        while { let _ = 0; ((&raw mut (*hook).list != head) as i32) } != 0 {
            'c0: {
                if (*hook).family != (*b).family {
                    break 'c0;
                }
                if !unsafe { basehook_eq((hook as *const basehook), (b as *const basehook)) } {
                    break 'c0;
                }
                if (*hook).prio <= (*b).prio {
                    break 'c0;
                }
                unsafe { list_add(&raw mut (*b).list, &raw mut (*hook).list) };
                return;
            }
            // C (for step): hook = list_entry ( hook -> list . next , typeof ( * hook ) , list )
            todo!();
        }
    }
    unsafe { list_add_tail(&raw mut (*b).list, head) };
}

unsafe extern "C" fn dump_nf_attr_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    let mut tb: *mut *const nlattr = (data as *mut *const nlattr);
    if (unsafe { mnl_attr_type_valid(attr, NFNLA_HOOK_MAX) }) < 0 {
        return MNL_CB_OK as i32;
    }
    match type_ {
        NFNLA_HOOK_HOOKNUM | NFNLA_HOOK_PRIORITY => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U32) }) < 0 {
                return MNL_CB_ERROR as i32;
            }
        }
        NFNLA_HOOK_DEV => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_STRING) }) < 0 {
                return MNL_CB_ERROR as i32;
            }
        }
        NFNLA_HOOK_MODULE_NAME | NFNLA_HOOK_FUNCTION_NAME => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_NUL_STRING) }) < 0 {
                return MNL_CB_ERROR as i32;
            }
        }
        NFNLA_HOOK_CHAIN_INFO => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_NESTED) }) < 0 {
                return MNL_CB_ERROR as i32;
            }
        }
        _ => {
            return MNL_CB_OK as i32;
        }
    }
    (*tb.offset(type_ as isize)) = attr;
    return MNL_CB_OK as i32;
}

