unsafe extern "C" fn dump_nf_attr_bpf_cb(mut attr: *const nlattr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut type_: i32 = (unsafe { mnl_attr_get_type(attr) }) as i32;
    let mut tb: *mut *const nlattr = (data as *mut *const nlattr);
    if (unsafe { mnl_attr_type_valid(attr, NFNLA_HOOK_BPF_MAX) }) < 0 {
        return MNL_CB_OK as i32;
    }
    match type_ {
        NFNLA_HOOK_BPF_ID => {
            if (unsafe { mnl_attr_validate(attr, MNL_TYPE_U32) }) < 0 {
                return MNL_CB_ERROR as i32;
            }
        }
        _ => {
            return MNL_CB_OK as i32;
        }
    }
    (*tb.offset(type_ as isize)) = attr;
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn dump_nf_hooks(mut nlh: *const nlmsghdr, mut _data: *mut core::ffi::c_void) -> i32 {
    let mut nfg: *const nfgenmsg = (unsafe { mnl_nlmsg_get_payload(nlh) } as *const nfgenmsg);
    let mut tb: [*mut nlattr; 7] = [unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];
    let mut data: *mut dump_nf_hook_data = (_data as *mut dump_nf_hook_data);
    let mut hook: *mut basehook = core::ptr::null_mut();
    /* NB: Don't check the nft generation ID, this is not
    	 * an nftables subsystem.
    	 */
    if (unsafe { mnl_attr_parse(nlh, core::mem::size_of::<nfgenmsg>(), Some(dump_nf_attr_cb), tb.as_mut_ptr()) }) < 0 {
        return -1;
    }
    if tb[NFNLA_HOOK_PRIORITY as usize].is_null() {
        unsafe { netlink_abi_error() };
    }
    hook = unsafe { basehook_alloc() };
    (*hook).prio = (unsafe { ntohl((unsafe { mnl_attr_get_u32(tb[NFNLA_HOOK_PRIORITY as usize]) }) as u32) }) as i32;
    (*hook).devname = (if !(*data).devname.is_null() { (unsafe { xstrdup((*data).devname) } as *const core::ffi::c_char) } else { core::ptr::null() });
    if !tb[NFNLA_HOOK_FUNCTION_NAME as usize].is_null() {
        (*hook).hookfn = (unsafe { xstrdup(unsafe { mnl_attr_get_str(tb[NFNLA_HOOK_FUNCTION_NAME as usize]) }) } as *const core::ffi::c_char);
    }
    if !tb[NFNLA_HOOK_MODULE_NAME as usize].is_null() {
        (*hook).module_name = (unsafe { xstrdup(unsafe { mnl_attr_get_str(tb[NFNLA_HOOK_MODULE_NAME as usize]) }) } as *const core::ffi::c_char);
    }
    if !tb[NFNLA_HOOK_CHAIN_INFO as usize].is_null() {
        let mut nested: [*mut nlattr; 3] = [unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];
        let mut type_: u32 = 0;
        if (unsafe { mnl_attr_parse_nested(tb[NFNLA_HOOK_CHAIN_INFO as usize], Some(dump_nf_chain_info_cb), nested.as_mut_ptr()) }) < 0 {
            unsafe { basehook_free(hook) };
            return -1;
        }
        type_ = unsafe { ntohl((unsafe { mnl_attr_get_u32(nested[NFNLA_HOOK_INFO_TYPE as usize]) }) as u32) };
        if (type_ == (NFNL_HOOK_TYPE_NFTABLES as u32)) || (type_ == (NFNL_HOOK_TYPE_NFT_FLOWTABLE as u32)) {
            let mut info: [*mut nlattr; 4] = [unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];
            let mut tablename: *const core::ffi::c_char = core::ptr::null();
            let mut chainname: *const core::ffi::c_char = core::ptr::null();
            if (unsafe { mnl_attr_parse_nested(nested[NFNLA_HOOK_INFO_DESC as usize], Some(dump_nf_attr_chain_cb), info.as_mut_ptr()) }) < 0 {
                unsafe { basehook_free(hook) };
                return -1;
            }
            tablename = (unsafe { mnl_attr_get_str(info[NFNLA_CHAIN_TABLE as usize]) } as *const core::ffi::c_char);
            chainname = (unsafe { mnl_attr_get_str(info[NFNLA_CHAIN_NAME as usize]) } as *const core::ffi::c_char);
            if !tablename.is_null() && !chainname.is_null() {
                (*hook).table = (unsafe { xstrdup(tablename) } as *const core::ffi::c_char);
                (*hook).chain = (unsafe { xstrdup(chainname) } as *const core::ffi::c_char);
            }
            (*hook).chain_family = (unsafe { mnl_attr_get_u8(info[NFNLA_CHAIN_FAMILY as usize]) }) as i32;
            if type_ == (NFNL_HOOK_TYPE_NFT_FLOWTABLE as u32) {
                (*hook).objtype = c"flowtable".as_ptr();
            } else {
                (*hook).objtype = c"chain".as_ptr();
            }
        } else if type_ == (NFNL_HOOK_TYPE_BPF as u32) {
            let mut info: [*mut nlattr; 2] = [unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];
            if (unsafe { mnl_attr_parse_nested(nested[NFNLA_HOOK_INFO_DESC as usize], Some(dump_nf_attr_bpf_cb), info.as_mut_ptr()) }) < 0 {
                unsafe { basehook_free(hook) };
                return -1;
            }
            if !info[NFNLA_HOOK_BPF_ID as usize].is_null() {
                let mut tmpbuf: [core::ffi::c_char; 16] = [0; 16];
                unsafe { snprintf((tmpbuf.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 16]>(), c"id %u".as_ptr(), unsafe { ntohl((unsafe { mnl_attr_get_u32(info[NFNLA_HOOK_BPF_ID as usize]) }) as u32) }) };
                (*hook).chain = (unsafe { xstrdup(tmpbuf.as_mut_ptr()) } as *const core::ffi::c_char);
            }
        }
    }
    if !tb[NFNLA_HOOK_HOOKNUM as usize].is_null() {
        (*hook).num = unsafe { ntohl((unsafe { mnl_attr_get_u32(tb[NFNLA_HOOK_HOOKNUM as usize]) }) as u32) };
    }
    (*hook).family = (*nfg).nfgen_family as i32;
    unsafe { basehook_list_add_tail(hook, (*data).hook_list) };
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn nf_hook_dump_request(mut buf: *mut core::ffi::c_char, mut family: u8, mut seq: u32) -> *mut nlmsghdr {
    let mut nlh: *mut nlmsghdr = (unsafe { mnl_nlmsg_put_header(buf) } as *mut nlmsghdr);
    let mut nfg: *mut nfgenmsg = core::ptr::null_mut();
    (*nlh).nlmsg_flags = 769u16;
    (*nlh).nlmsg_type = 3072u16;
    (*nlh).nlmsg_seq = seq;
    nfg = (unsafe { mnl_nlmsg_put_extra_header(nlh, core::mem::size_of::<nfgenmsg>()) } as *mut nfgenmsg);
    (*nfg).nfgen_family = family;
    (*nfg).version = 0u8;
    return nlh;
}

unsafe extern "C" fn __mnl_nft_dump_nf_hooks(mut ctx: *mut netlink_ctx, mut query_family: u8, mut family: u8, mut hooknum: u8, mut devname: *const core::ffi::c_char, mut hook_list: *mut list_head) -> i32 {
    let mut __buf_storage: Vec<core::ffi::c_char> = vec![unsafe { core::mem::zeroed() }; (MNL_SOCKET_BUFFER_SIZE) as usize];
    let buf: *mut core::ffi::c_char = __buf_storage.as_mut_ptr();
    let mut data: dump_nf_hook_data = dump_nf_hook_data { hook_list: hook_list, devname: devname, family: query_family as i32 };
    let mut nlh: *mut nlmsghdr = core::ptr::null_mut();
    nlh = unsafe { nf_hook_dump_request((buf as *mut core::ffi::c_char), family, (*ctx).seqnum as u32) };
    if !devname.is_null() {
        unsafe { mnl_attr_put_strz(nlh, NFNLA_HOOK_DEV, devname) };
    }
    unsafe { mnl_attr_put_u32(nlh, NFNLA_HOOK_HOOKNUM, unsafe { htonl(hooknum as u32) }) };
    return unsafe { nft_mnl_talk(ctx, (nlh as *const core::ffi::c_void), (*nlh).nlmsg_len, Some(dump_nf_hooks), (&raw mut data as *mut core::ffi::c_void)) };
}

unsafe extern "C" fn print_hooks(mut ctx: *mut netlink_ctx, mut family: i32, mut hook_list: *mut list_head) {
    let mut hook: *mut basehook = core::ptr::null_mut();
    let mut tmp: *mut basehook = core::ptr::null_mut();
    let mut prev: *mut basehook = core::ptr::null_mut();
    let mut same: bool = false;
    let mut family_in_use: bool = false;
    let mut prio: i32 = 0;
    let mut fp: *mut _IO_FILE = core::ptr::null_mut();
    fp = ((*(*ctx).nft).output.output_fp as *mut _IO_FILE);
    {
        // C (statement): hook = list_entry ( ( hook_list ) -> next , typeof ( * hook ) , list ) , tmp = list_entry ( hook -> list . next , typeof ( * hook ) , list ) ;
        todo!();
        'b0: while &raw mut (*hook).list != hook_list {
            if (*hook).family == family {
                family_in_use = true;
                break 'b0;
            }
            // C (for step): hook = tmp , tmp = list_entry ( tmp -> list . next , typeof ( * tmp ) , list )
            todo!();
        }
    }
    if !family_in_use {
        return;
    }
    unsafe { fprintf(fp, c"family %s {\n".as_ptr(), unsafe { family2str(family) }) };
    {
        // C (statement): hook = list_entry ( ( hook_list ) -> next , typeof ( * hook ) , list ) , tmp = list_entry ( hook -> list . next , typeof ( * hook ) , list ) ;
        todo!();
        while &raw mut (*hook).list != hook_list {
            'c1: {
                if (*hook).family != family {
                    break 'c1;
                }
                if !prev.is_null() {
                    if unsafe { basehook_eq((prev as *const basehook), (hook as *const basehook)) } {
                        unsafe { fprintf(fp, c"\n".as_ptr()) };
                        same = true;
                    } else {
                        same = false;
                        unsafe { fprintf(fp, c"\n\t}\n".as_ptr()) };
                    }
                } else {
                    same = false;
                }
                prev = hook;
                if !same {
                    if !(*hook).devname.is_null() {
                        unsafe { fprintf(fp, c"\thook %s device %s {\n".as_ptr(), unsafe { hooknum2str(family, (*hook).num) }, (*hook).devname) };
                    } else {
                        unsafe { fprintf(fp, c"\thook %s {\n".as_ptr(), unsafe { hooknum2str(family, (*hook).num) }) };
                    }
                }
                prio = (*hook).prio;
                if prio < 0 {
                    unsafe { fprintf(fp, c"\t\t%011d".as_ptr(), prio) };
                } else if prio == 0 {
                    unsafe { fprintf(fp, c"\t\t %010u".as_ptr(), prio) };
                } else {
                    unsafe { fprintf(fp, c"\t\t+%010u".as_ptr(), prio) };
                }
                if !(*hook).table.is_null() && !(*hook).chain.is_null() {
                    unsafe { fprintf(fp, c" %s %s %s %s".as_ptr(), (*hook).objtype, unsafe { family2str((*hook).chain_family) }, (*hook).table, (*hook).chain) };
                } else if !(*hook).hookfn.is_null() && !(*hook).chain.is_null() {
                    unsafe { fprintf(fp, c" %s %s".as_ptr(), (*hook).hookfn, (*hook).chain) };
                } else if !(*hook).hookfn.is_null() {
                    unsafe { fprintf(fp, c" %s".as_ptr(), (*hook).hookfn) };
                }
                if !(*hook).module_name.is_null() {
                    unsafe { fprintf(fp, c" [%s]".as_ptr(), (*hook).module_name) };
                }
            }
            // C (for step): hook = tmp , tmp = list_entry ( tmp -> list . next , typeof ( * tmp ) , list )
            todo!();
        }
    }
    unsafe { fprintf(fp, c"\n\t}\n".as_ptr()) };
    unsafe { fprintf(fp, c"}\n".as_ptr()) };
}

unsafe extern "C" fn mnl_nft_dump_nf(mut ctx: *mut netlink_ctx, mut family: i32, mut devname: *const core::ffi::c_char, mut hook_list: *mut list_head) -> i32 {
    let mut i: i32 = 0;
    let mut err: i32 = 0;
    {
        i = 0;
        while i <= NF_INET_POST_ROUTING {
            let mut tmp: i32 = 0;
            tmp = unsafe { __mnl_nft_dump_nf_hooks(ctx, family as u8, family as u8, i as u8, devname, hook_list) };
            if tmp == 0 {
                err = 0;
            }
            i += 1;
        }
    }
    return err;
}

unsafe extern "C" fn mnl_nft_dump_nf_arp(mut ctx: *mut netlink_ctx, mut family: i32, mut devname: *const core::ffi::c_char, mut hook_list: *mut list_head) -> i32 {
    let mut err1: i32 = 0;
    let mut err2: i32 = 0;
    err1 = unsafe { __mnl_nft_dump_nf_hooks(ctx, family as u8, family as u8, 0u8, devname, hook_list) };
    err2 = unsafe { __mnl_nft_dump_nf_hooks(ctx, family as u8, family as u8, 1u8, devname, hook_list) };
    return (if (err1 != 0) { err2 } else { err1 });
}

unsafe extern "C" fn mnl_nft_dump_nf_netdev(mut ctx: *mut netlink_ctx, mut family: i32, mut devname: *const core::ffi::c_char, mut hook_list: *mut list_head) -> i32 {
    let mut err1: i32 = 0;
    let mut err2: i32 = 0;
    err1 = unsafe { __mnl_nft_dump_nf_hooks(ctx, family as u8, 5u8, 0u8, devname, hook_list) };
    err2 = unsafe { __mnl_nft_dump_nf_hooks(ctx, family as u8, 5u8, 1u8, devname, hook_list) };
    return (if (err1 != 0) { err2 } else { err1 });
}

unsafe extern "C" fn release_hook_list(mut hook_list: *mut list_head) {
    let mut hook: *mut basehook = core::ptr::null_mut();
    let mut next: *mut basehook = core::ptr::null_mut();
    {
        // C (statement): hook = list_entry ( ( hook_list ) -> next , typeof ( * hook ) , list ) , next = list_entry ( hook -> list . next , typeof ( * hook ) , list ) ;
        todo!();
        while &raw mut (*hook).list != hook_list {
            unsafe { basehook_free(hook) };
            // C (for step): hook = next , next = list_entry ( next -> list . next , typeof ( * next ) , list )
            todo!();
        }
    }
}

unsafe extern "C" fn warn_if_device(mut nft: *mut nft_ctx, mut devname: *const core::ffi::c_char) {
    if !devname.is_null() {
        unsafe { nft_print(&raw mut (*nft).output, c"# device keyword (%s) unexpected for this family\n".as_ptr(), devname) };
    }
}

