/* returns true if the event should be ignored (i.e. null element) */
unsafe extern "C" fn netlink_event_ignore_range_event(mut nlse: *mut nftnl_set_elem) -> bool {
    let mut flags: u32 = 0u32;
    if unsafe { nftnl_set_elem_is_set((nlse as *const nftnl_set_elem), 0u16) } {
        flags = unsafe { nftnl_set_elem_get_u32(nlse, 0u16) };
    }
    if !((flags & (NFT_SET_ELEM_INTERVAL_END as u32)) != 0) {
        return false;
    }
    if (unsafe { nftnl_set_elem_get_u32(nlse, 1u16) }) != (0 as u32) {
        return false;
    }
    return true;
}

unsafe extern "C" fn set_elem_is_open_interval(mut elem: *mut expr) -> bool {
    match (*elem).etype() {
        EXPR_SET_ELEM => {
            return ((*(*elem).anon9.anon10.key).flags & (EXPR_F_INTERVAL_OPEN as u32)) != 0;
        }
        EXPR_MAPPING => {
            return unsafe { set_elem_is_open_interval((*elem).anon9.anon12.left) };
        }
        _ => {
            return false;
        }
    }
    unsafe { core::mem::zeroed() }
}

/* returns true if the we cached the range element */
unsafe extern "C" fn netlink_event_range_cache(mut cached_set: *mut set, mut dummyset: *mut set) -> bool {
    let mut elem: *mut expr = core::ptr::null_mut();
    /* not an interval ? */
    if !(((*cached_set).flags & NFT_SET_INTERVAL) != 0) {
        return false;
    }
    'g_out_decompose: {
        /* if cache exists, dummyset must contain the other end of the range */
        if (*cached_set).rg_cache != 0 {
            unsafe { set_expr_add(((*dummyset).init as *mut expr), ((*cached_set).rg_cache as *mut expr)) };
            (*cached_set).rg_cache = core::ptr::null_mut();
            break 'g_out_decompose;
        }
        /* don't cache half-open range elements */
        // C (statement): elem = list_entry ( expr_set ( dummyset -> init ) -> expressions . prev , struct expr , list ) ;
        todo!();
        if !unsafe { set_elem_is_open_interval(elem) } && ((*dummyset).desc.field_count <= 1) {
            (*cached_set).rg_cache = unsafe { expr_clone((elem as *const expr)) };
            return true;
        }
    }
    if (((*dummyset).flags & NFT_SET_INTERVAL) != 0) && ((*dummyset).desc.field_count > 1) {
        unsafe { concat_range_aggregate(((*dummyset).init as *mut expr)) };
    } else {
        unsafe { interval_map_decompose(((*dummyset).init as *mut expr)) };
    }
    return false;
}

unsafe extern "C" fn netlink_events_setelem_cb(mut nlh: *const nlmsghdr, mut type_: i32, mut monh: *mut netlink_mon_handler) -> i32 {
    let mut nlsei: *mut nftnl_set_elems_iter = core::ptr::null_mut();
    let mut nlse: *mut nftnl_set_elem = core::ptr::null_mut();
    let mut nls: *mut nftnl_set = core::ptr::null_mut();
    let mut set: *mut set = core::ptr::null_mut();
    let mut set: *mut set = core::ptr::null_mut();
    let mut setname: *const core::ffi::c_char = core::ptr::null();
    let mut table: *const core::ffi::c_char = core::ptr::null();
    let mut cmd: *const core::ffi::c_char = core::ptr::null();
    let mut family: u32 = 0;
    nls = unsafe { netlink_setelem_alloc(nlh) };
    table = unsafe { nftnl_set_get_str((nls as *const nftnl_set), 0u16) };
    setname = unsafe { nftnl_set_get_str((nls as *const nftnl_set), 1u16) };
    family = unsafe { nftnl_set_get_u32((nls as *const nftnl_set), 7u16) };
    cmd = unsafe { netlink_msg2cmd(type_ as u32, (*nlh).nlmsg_flags) };
    set = (unsafe { set_lookup_global(family, table, setname, ((&raw const (*(*(*monh).ctx).nft).cache).cast_mut())) } as *mut set);
    'g_out: {
        if set.is_null() {
            unsafe { fprintf(stderr, c"W: Received event for an unknown set.\n".as_ptr()) };
            break 'g_out;
        }
        if unsafe { set_is_anonymous((*set).flags) } != 0 {
            break 'g_out;
        }
        /* we want to 'delinearize' the set_elem, but don't
    	 * modify the original cached set. This path is only
    	 * used by named sets, so use a dummy set.
    	 */
        dummyset = (unsafe { set_alloc((*monh).loc) } as *mut set);
        unsafe { handle_merge(&raw mut (*dummyset).handle, &raw mut (*set).handle) };
        (*dummyset).key = unsafe { expr_clone(((*set).key as *const expr)) };
        if (*set).data != 0 {
            (*dummyset).data = unsafe { expr_clone(((*set).data as *const expr)) };
        }
        (*dummyset).flags = (*set).flags;
        (*dummyset).init = unsafe { set_expr_alloc(((*monh).loc as *const location), (set as *const set)) };
        (*dummyset).desc.field_count = (*set).desc.field_count;
        nlsei = unsafe { nftnl_set_elems_iter_create((nls as *const nftnl_set)) };
        if nlsei.is_null() {
            unsafe { memory_allocation_error() };
        }
        nlse = unsafe { nftnl_set_elems_iter_next(nlsei) };
        while !nlse.is_null() {
            if unsafe { netlink_event_ignore_range_event(nlse) } {
                unsafe { set_free(dummyset) };
                unsafe { nftnl_set_elems_iter_destroy(nlsei) };
                break 'g_out;
            }
            if (unsafe { netlink_delinearize_setelem((*monh).ctx, nlse, dummyset) }) < 0 {
                unsafe { set_free(dummyset) };
                unsafe { nftnl_set_elems_iter_destroy(nlsei) };
                break 'g_out;
            }
            nlse = unsafe { nftnl_set_elems_iter_next(nlsei) };
        }
        unsafe { nftnl_set_elems_iter_destroy(nlsei) };
        if unsafe { netlink_event_range_cache(set, dummyset) } {
            unsafe { set_free(dummyset) };
            break 'g_out;
        }
        match (*monh).format {
            NFTNL_OUTPUT_DEFAULT => {
                unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"%s element %s %s %s ".as_ptr(), cmd, unsafe { family2str(family) }, table, setname) };
                unsafe { expr_print(((*dummyset).init as *const expr), (((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx)) };
                unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"\n".as_ptr()) };
            }
            NFTNL_OUTPUT_JSON => {
                unsafe { monitor_print_element_json(monh, cmd, dummyset) };
                if !unsafe { nft_output_echo((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *const output_ctx)) } {
                    unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"\n".as_ptr()) };
                }
            }
            _ => {}
        }
        unsafe { set_free(dummyset) };
    }
    unsafe { nftnl_set_free((nls as *const nftnl_set)) };
    return MNL_CB_OK as i32;
}

