unsafe extern "C" fn netlink_events_flowtable_cb(mut nlh: *const nlmsghdr, mut type_: i32, mut monh: *mut netlink_mon_handler) -> i32 {
    let mut family: *const core::ffi::c_char = core::ptr::null();
    let mut cmd: *const core::ffi::c_char = core::ptr::null();
    let mut nlf: *mut nftnl_flowtable = core::ptr::null_mut();
    let mut ft: *mut flowtable = core::ptr::null_mut();
    nlf = unsafe { netlink_flowtable_alloc(nlh) };
    ft = (unsafe { netlink_delinearize_flowtable((*monh).ctx, nlf) } as *mut flowtable);
    if ft.is_null() {
        unsafe { nftnl_flowtable_free((nlf as *const nftnl_flowtable)) };
        return MNL_CB_ERROR as i32;
    }
    family = (unsafe { family2str((*ft).handle.family) } as *const core::ffi::c_char);
    cmd = unsafe { netlink_msg2cmd(type_ as u32, (*nlh).nlmsg_flags) };
    match (*monh).format {
        NFTNL_OUTPUT_DEFAULT => {
            unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"%s ".as_ptr(), cmd) };
            'b1: {
                {
                    let __sw = (type_) as i64;
                    let mut __ft = false;
                    if __ft || __sw == (NFT_MSG_DELFLOWTABLE as i64) {
                        __ft = true;
                        if !((*ft).dev_array_len != 0) {
                            unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"flowtable %s %s %s".as_ptr(), family, (*ft).handle.table.name, (*ft).handle.flowtable.name) };
                            break 'b1;
                        }
                    }
                    if __ft || __sw == (NFT_MSG_NEWFLOWTABLE as i64) {
                        __ft = true;
                        unsafe { flowtable_print_plain(ft, ((&raw const (*(*(*monh).ctx).nft).output).cast_mut())) };
                        break 'b1;
                    }
                    let _ = __ft;
                }
            }
            unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"\n".as_ptr()) };
        }
        NFTNL_OUTPUT_JSON => {
            unsafe { monitor_print_flowtable_json(monh, cmd, ft) };
            if !unsafe { nft_output_echo((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *const output_ctx)) } {
                unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"\n".as_ptr()) };
            }
        }
        _ => {}
    }
    unsafe { flowtable_free(ft) };
    unsafe { nftnl_flowtable_free((nlf as *const nftnl_flowtable)) };
    return MNL_CB_OK as i32;
}

unsafe extern "C" fn rule_map_decompose_cb(mut s: *mut set, mut data: *mut core::ffi::c_void) {
    if !(unsafe { set_is_anonymous((*s).flags) } != 0) {
        return;
    }
    if unsafe { set_is_non_concat_range(s) } != 0 {
        unsafe { interval_map_decompose(((*s).init as *mut expr)) };
    } else if unsafe { set_is_interval((*s).flags) } != 0 {
        unsafe { concat_range_aggregate(((*s).init as *mut expr)) };
    }
}

unsafe extern "C" fn netlink_events_rule_cb(mut nlh: *const nlmsghdr, mut type_: i32, mut monh: *mut netlink_mon_handler) -> i32 {
    let mut family: *const core::ffi::c_char = core::ptr::null();
    let mut cmd: *const core::ffi::c_char = core::ptr::null();
    let mut nlr: *mut nftnl_rule = core::ptr::null_mut();
    let mut r: *mut rule = core::ptr::null_mut();
    nlr = unsafe { netlink_rule_alloc(nlh) };
    r = (unsafe { netlink_delinearize_rule((*monh).ctx, nlr) } as *mut rule);
    'g_out_free_nlr: {
        if r.is_null() {
            unsafe { fprintf(stderr, c"W: Received event for an unknown table.\n".as_ptr()) };
            break 'g_out_free_nlr;
        }
        unsafe { nlr_for_each_set(nlr, Some(rule_map_decompose_cb), core::ptr::null_mut(), (((&raw const (*(*(*monh).ctx).nft).cache).cast_mut()) as *mut nft_cache)) };
        cmd = unsafe { netlink_msg2cmd(type_ as u32, (*nlh).nlmsg_flags) };
        match (*monh).format {
            NFTNL_OUTPUT_DEFAULT => {
                family = (unsafe { family2str((*r).handle.family) } as *const core::ffi::c_char);
                unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"%s rule %s %s %s ".as_ptr(), cmd, family, (*r).handle.table.name, (*r).handle.chain.name) };
                if (*r).handle.position.id != 0 {
                    unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"handle %lu ".as_ptr(), (*r).handle.position.id) };
                }
                match type_ {
                    NFT_MSG_NEWRULE => {
                        unsafe { rule_print(r, ((&raw const (*(*(*monh).ctx).nft).output).cast_mut())) };
                    }
                    NFT_MSG_DELRULE => {
                        unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"handle %lu".as_ptr(), (*r).handle.handle.id) };
                    }
                    _ => {}
                }
                unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"\n".as_ptr()) };
            }
            NFTNL_OUTPUT_JSON => {
                unsafe { monitor_print_rule_json(monh, cmd, r) };
                if !unsafe { nft_output_echo((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *const output_ctx)) } {
                    unsafe { nft_print((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *mut output_ctx), c"\n".as_ptr()) };
                }
            }
            _ => {}
        }
        unsafe { rule_free(r) };
    }
    unsafe { nftnl_rule_free(nlr) };
    return MNL_CB_OK as i32;
}

