unsafe extern "C" fn netlink_events_cache_addset(mut monh: *mut netlink_mon_handler, mut nlh: *const nlmsghdr) {
    let mut set_tmpctx: netlink_ctx = unsafe { core::mem::zeroed() };
    let mut nls: *mut nftnl_set = core::ptr::null_mut();
    let mut t: *mut table = core::ptr::null_mut();
    let mut s: *mut set = core::ptr::null_mut();
    let mut msgs: list_head = list_head { next: &raw mut msgs, prev: &raw mut msgs };
    unsafe { memset((&raw mut set_tmpctx as *mut core::ffi::c_void), 0, core::mem::size_of::<netlink_ctx>()) };
    unsafe { init_list_head((&raw mut set_tmpctx.list as *mut list_head)) };
    unsafe { init_list_head(&raw mut msgs) };
    set_tmpctx.nft = (*(*monh).ctx).nft;
    set_tmpctx.msgs = &raw mut msgs;
    nls = unsafe { netlink_set_alloc(nlh) };
    s = (unsafe { netlink_delinearize_set(&raw mut set_tmpctx, nls) } as *mut set);
    'g_out: {
        if s.is_null() {
            break 'g_out;
        }
        (*s).init = unsafe { set_expr_alloc(((*monh).loc as *const location), (s as *const set)) };
        t = unsafe { table_cache_find((((&raw const (*(*(*monh).ctx).nft).cache.table_cache).cast_mut()) as *const cache), ((*s).handle.table.name as *const core::ffi::c_char), (*s).handle.family as u32) };
        if t.is_null() {
            unsafe { fprintf(stderr, c"W: Unable to cache set: table not found.\n".as_ptr()) };
            unsafe { set_free(s) };
            break 'g_out;
        }
        if unsafe { nft_output_echo((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *const output_ctx)) } && !(unsafe { set_is_anonymous((*s).flags) } != 0) {
            unsafe { set_free(s) };
            break 'g_out;
        }
        unsafe { set_cache_add(s, t) };
    }
    unsafe { nftnl_set_free((nls as *const nftnl_set)) };
}

unsafe extern "C" fn netlink_events_cache_addsetelem(mut monh: *mut netlink_mon_handler, mut nlh: *const nlmsghdr) {
    let mut nlsei: *mut nftnl_set_elems_iter = core::ptr::null_mut();
    let mut nlse: *mut nftnl_set_elem = core::ptr::null_mut();
    let mut nls: *mut nftnl_set = core::ptr::null_mut();
    let mut set: *mut set = core::ptr::null_mut();
    let mut table: *const core::ffi::c_char = core::ptr::null();
    let mut setname: *const core::ffi::c_char = core::ptr::null();
    let mut family: u32 = 0;
    nls = unsafe { netlink_setelem_alloc(nlh) };
    family = unsafe { nftnl_set_get_u32((nls as *const nftnl_set), 7u16) };
    table = unsafe { nftnl_set_get_str((nls as *const nftnl_set), 0u16) };
    setname = unsafe { nftnl_set_get_str((nls as *const nftnl_set), 1u16) };
    set = (unsafe { set_lookup_global(family, table, setname, ((&raw const (*(*(*monh).ctx).nft).cache).cast_mut())) } as *mut set);
    'g_out: {
        if set.is_null() {
            unsafe { fprintf(stderr, c"W: Unable to cache set_elem. Set not found.\n".as_ptr()) };
            break 'g_out;
        }
        if unsafe { nft_output_echo((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *const output_ctx)) } && !(unsafe { set_is_anonymous((*set).flags) } != 0) {
            break 'g_out;
        }
        nlsei = unsafe { nftnl_set_elems_iter_create((nls as *const nftnl_set)) };
        if nlsei.is_null() {
            unsafe { memory_allocation_error() };
        }
        nlse = unsafe { nftnl_set_elems_iter_next(nlsei) };
        while !nlse.is_null() {
            if (unsafe { netlink_delinearize_setelem((*monh).ctx, nlse, set) }) < 0 {
                unsafe { fprintf(stderr, c"W: Unable to cache set_elem. Delinearize failed.\n".as_ptr()) };
                unsafe { nftnl_set_elems_iter_destroy(nlsei) };
                break 'g_out;
            }
            nlse = unsafe { nftnl_set_elems_iter_next(nlsei) };
        }
        unsafe { nftnl_set_elems_iter_destroy(nlsei) };
    }
    unsafe { nftnl_set_free((nls as *const nftnl_set)) };
}

unsafe extern "C" fn netlink_events_cache_delset_cb(mut s: *mut set, mut data: *mut core::ffi::c_void) {
    unsafe { set_cache_del(s) };
    unsafe { set_free(s) };
}

unsafe extern "C" fn netlink_events_cache_delsets(mut monh: *mut netlink_mon_handler, mut nlh: *const nlmsghdr) {
    let mut nlr: *mut nftnl_rule = unsafe { netlink_rule_alloc(nlh) };
    unsafe { nlr_for_each_set(nlr, Some(netlink_events_cache_delset_cb), core::ptr::null_mut(), (((&raw const (*(*(*monh).ctx).nft).cache).cast_mut()) as *mut nft_cache)) };
    unsafe { nftnl_rule_free(nlr) };
}

unsafe extern "C" fn netlink_events_cache_addobj(mut monh: *mut netlink_mon_handler, mut nlh: *const nlmsghdr) {
    let mut obj_tmpctx: netlink_ctx = unsafe { core::mem::zeroed() };
    let mut nlo: *mut nftnl_obj = core::ptr::null_mut();
    let mut t: *mut table = core::ptr::null_mut();
    let mut obj: *mut obj = core::ptr::null_mut();
    let mut msgs: list_head = list_head { next: &raw mut msgs, prev: &raw mut msgs };
    unsafe { memset((&raw mut obj_tmpctx as *mut core::ffi::c_void), 0, core::mem::size_of::<netlink_ctx>()) };
    unsafe { init_list_head((&raw mut obj_tmpctx.list as *mut list_head)) };
    unsafe { init_list_head(&raw mut msgs) };
    obj_tmpctx.msgs = &raw mut msgs;
    nlo = unsafe { netlink_obj_alloc(nlh) };
    obj = (unsafe { netlink_delinearize_obj(&raw mut obj_tmpctx, nlo) } as *mut obj);
    'g_out: {
        if obj.is_null() {
            break 'g_out;
        }
        t = unsafe { table_cache_find((((&raw const (*(*(*monh).ctx).nft).cache.table_cache).cast_mut()) as *const cache), ((*obj).handle.table.name as *const core::ffi::c_char), (*obj).handle.family as u32) };
        if t.is_null() {
            unsafe { fprintf(stderr, c"W: Unable to cache object: table not found.\n".as_ptr()) };
            unsafe { obj_free(obj) };
            break 'g_out;
        }
        unsafe { obj_cache_add(obj, t) };
    }
    unsafe { nftnl_obj_free((nlo as *const nftnl_obj)) };
}

unsafe extern "C" fn netlink_events_cache_delobj(mut monh: *mut netlink_mon_handler, mut nlh: *const nlmsghdr) {
    let mut nlo: *mut nftnl_obj = core::ptr::null_mut();
    let mut name: *const core::ffi::c_char = core::ptr::null();
    let mut obj: *mut obj = core::ptr::null_mut();
    let mut h: handle = unsafe { core::mem::zeroed() };
    let mut t: *mut table = core::ptr::null_mut();
    let mut type_: u32 = 0;
    nlo = unsafe { netlink_obj_alloc(nlh) };
    h.family = unsafe { nftnl_obj_get_u32((nlo as *const nftnl_obj), 3u16) };
    h.table.name = unsafe { nftnl_obj_get_str((nlo as *const nftnl_obj), 0u16) };
    name = unsafe { nftnl_obj_get_str((nlo as *const nftnl_obj), 1u16) };
    type_ = unsafe { nftnl_obj_get_u32((nlo as *const nftnl_obj), 2u16) };
    h.handle.id = unsafe { nftnl_obj_get_u64((nlo as *const nftnl_obj), 5u16) };
    t = unsafe { table_cache_find((((&raw const (*(*(*monh).ctx).nft).cache.table_cache).cast_mut()) as *const cache), (h.table.name as *const core::ffi::c_char), h.family as u32) };
    'g_out: {
        if t.is_null() {
            unsafe { fprintf(stderr, c"W: Unable to cache object: table not found.\n".as_ptr()) };
            break 'g_out;
        }
        obj = unsafe { obj_cache_find((t as *const table), name, type_) };
        if obj.is_null() {
            unsafe { fprintf(stderr, c"W: Unable to find object in cache\n".as_ptr()) };
            break 'g_out;
        }
        unsafe { obj_cache_del(obj) };
        unsafe { obj_free(obj) };
    }
    unsafe { nftnl_obj_free((nlo as *const nftnl_obj)) };
}

unsafe extern "C" fn netlink_events_cache_update(mut monh: *mut netlink_mon_handler, mut nlh: *const nlmsghdr, mut type_: i32) {
    if (unsafe { nft_output_echo((((&raw const (*(*(*monh).ctx).nft).output).cast_mut()) as *const output_ctx)) } && (type_ != NFT_MSG_NEWSET)) && (type_ != NFT_MSG_NEWSETELEM) {
        return;
    }
    match type_ {
        NFT_MSG_NEWTABLE => {
            unsafe { netlink_events_cache_addtable(monh, nlh) };
        }
        NFT_MSG_DELTABLE => {
            unsafe { netlink_events_cache_deltable(monh, nlh) };
        }
        NFT_MSG_NEWSET => {
            unsafe { netlink_events_cache_addset(monh, nlh) };
        }
        NFT_MSG_NEWSETELEM => {
            unsafe { netlink_events_cache_addsetelem(monh, nlh) };
        }
        NFT_MSG_DELRULE => {
            /* there are no notification for anon-set deletion */
            unsafe { netlink_events_cache_delsets(monh, nlh) };
        }
        NFT_MSG_NEWOBJ => {
            unsafe { netlink_events_cache_addobj(monh, nlh) };
        }
        NFT_MSG_DELOBJ => {
            unsafe { netlink_events_cache_delobj(monh, nlh) };
        }
        _ => {}
    }
}

unsafe extern "C" fn nftnl_msgtype2str(mut type_: u16) -> *const core::ffi::c_char {
    if ((type_ as i32) >= NFT_MSG_MAX) || nftnl_msg_types[type_ as usize].is_null() {
        return c"unknown".as_ptr();
    }
    return nftnl_msg_types[type_ as usize];
}

unsafe extern "C" fn netlink_events_debug(mut type_: u16, mut debug_mask: u32) {
    if !((debug_mask & (NFT_DEBUG_NETLINK as u32)) != 0) {
        return;
    }
    unsafe { printf(c"netlink event: %s\n".as_ptr(), unsafe { nftnl_msgtype2str(type_) }) };
}

