unsafe extern "C" fn netlink_events_cb(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut ret: i32 = MNL_CB_OK as i32;
    let mut type_: u16 = (((*nlh).nlmsg_type as i32) & 255) as u16;
    let mut monh: *mut netlink_mon_handler = (data as *mut netlink_mon_handler);
    unsafe { netlink_events_debug(type_, (*(*(*monh).ctx).nft).debug_mask as u32) };
    unsafe { netlink_events_cache_update(monh, nlh, type_ as i32) };
    if !(((*monh).monitor_flags & (1 << (type_ as u32))) != 0) {
        return ret;
    }
    match (type_ as i32) {
        NFT_MSG_NEWTABLE | NFT_MSG_DELTABLE => {
            ret = unsafe { netlink_events_table_cb(nlh, type_ as i32, monh) };
        }
        NFT_MSG_NEWCHAIN | NFT_MSG_DELCHAIN => {
            ret = unsafe { netlink_events_chain_cb(nlh, type_ as i32, monh) };
        }
        NFT_MSG_NEWSET | NFT_MSG_DELSET => {
            /* nft {add|delete} set */
            ret = unsafe { netlink_events_set_cb(nlh, type_ as i32, monh) };
        }
        NFT_MSG_NEWSETELEM | NFT_MSG_DELSETELEM => {
            /* nft {add|delete} element */
            ret = unsafe { netlink_events_setelem_cb(nlh, type_ as i32, monh) };
        }
        NFT_MSG_NEWRULE | NFT_MSG_DELRULE => {
            ret = unsafe { netlink_events_rule_cb(nlh, type_ as i32, monh) };
        }
        NFT_MSG_TRACE => {
            ret = (unsafe { netlink_events_trace_cb(nlh, (type_ as i32), monh) }) as i32;
        }
        NFT_MSG_NEWOBJ | NFT_MSG_DELOBJ => {
            ret = unsafe { netlink_events_obj_cb(nlh, type_ as i32, monh) };
        }
        NFT_MSG_NEWFLOWTABLE | NFT_MSG_DELFLOWTABLE => {
            ret = unsafe { netlink_events_flowtable_cb(nlh, type_ as i32, monh) };
        }
        NFT_MSG_NEWGEN => {
            ret = unsafe { netlink_events_newgen_cb(nlh, type_ as i32, monh) };
        }
        _ => {}
    }
    return ret;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn netlink_echo_callback(mut nlh: *const nlmsghdr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut nl_cb_data: *mut netlink_cb_data = (data as *mut netlink_cb_data);
    let mut ctx: *mut netlink_ctx = ((*nl_cb_data).nl_ctx as *mut netlink_ctx);
    let mut nft: *mut nft_ctx = ((*ctx).nft as *mut nft_ctx);
    // TODO initializer: { . format = NFTNL_OUTPUT_DEFAULT , . ctx = ctx , . loc = & netlink_location , . monitor_flags = 0xffffffff , }
    let mut echo_monh: netlink_mon_handler = unsafe { core::mem::zeroed() };
    if !unsafe { nft_output_echo((((&raw const (*(*echo_monh.ctx).nft).output).cast_mut()) as *const output_ctx)) } {
        return MNL_CB_OK as i32;
    }
    if unsafe { nft_output_json((&raw mut (*nft).output as *const output_ctx)) } {
        if !(*nft).json_root.is_null() {
            return unsafe { json_events_cb(nlh, &raw mut echo_monh) };
        }
        if !!(*nft).json_echo.is_null() {
            unsafe { json_alloc_echo(nft) };
        }
        echo_monh.format = NFTNL_OUTPUT_JSON;
    }
    return unsafe { netlink_events_cb(nlh, (&raw mut echo_monh as *mut core::ffi::c_void)) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn netlink_monitor(mut monhandler: *mut netlink_mon_handler, mut nf_sock: *mut mnl_socket) -> i32 {
    let mut group: i32 = 0;
    if ((*monhandler).monitor_flags & 131072) != 0 {
        group = 9;
        if (unsafe { mnl_socket_setsockopt(nf_sock, NETLINK_ADD_MEMBERSHIP, &raw mut group, core::mem::size_of::<i32>()) }) < 0 {
            return -1;
        }
    }
    if ((*monhandler).monitor_flags & -131073i32) != 0 {
        group = 7;
        if (unsafe { mnl_socket_setsockopt(nf_sock, NETLINK_ADD_MEMBERSHIP, &raw mut group, core::mem::size_of::<i32>()) }) < 0 {
            return -1;
        }
    }
    return unsafe { mnl_nft_event_listener(nf_sock, (*(*(*monhandler).ctx).nft).debug_mask as u32, (((&raw const (*(*(*monhandler).ctx).nft).output).cast_mut()) as *mut output_ctx), Some(netlink_events_cb), (monhandler as *mut core::ffi::c_void)) };
}

