pub unsafe extern "C" fn netlink_alloc_data(mut loc: *const location, mut nld: *const nft_data_delinearize, mut dreg: nft_registers) -> *mut expr {
    match dreg {
        NFT_REG_VERDICT => {
            return unsafe { netlink_alloc_verdict(loc, nld) };
        }
        _ => {
            return unsafe { netlink_alloc_value(loc, nld) };
        }
    }
    unsafe { core::mem::zeroed() }
}

