unsafe extern "C" fn chain_parse_udata_cb(mut attr: *const nftnl_udata, mut data: *mut core::ffi::c_void) -> i32 {
    let mut value: *mut u8 = (unsafe { nftnl_udata_get(attr) } as *mut u8);
    let mut type_: u8 = unsafe { nftnl_udata_type(attr) };
    let mut tb: *mut *const nftnl_udata = (data as *mut *const nftnl_udata);
    let mut len: u8 = unsafe { nftnl_udata_len(attr) };
    match (type_ as i32) {
        NFTNL_UDATA_CHAIN_COMMENT => {
            if ((*value.offset(((len as i32) - 1) as isize)) as i32) != 0 {
                return -1;
            }
        }
        _ => {
            return 0;
        }
    }
    (*tb.offset(type_ as isize)) = attr;
    return 0;
}

unsafe extern "C" fn qsort_device_cmp(mut a: *const core::ffi::c_void, mut b: *const core::ffi::c_void) -> i32 {
    let mut x: *mut *const core::ffi::c_char = (a as *mut *const core::ffi::c_char);
    let mut y: *mut *const core::ffi::c_char = (b as *mut *const core::ffi::c_char);
    return unsafe { strcmp(((*x) as *const core::ffi::c_char), ((*y) as *const core::ffi::c_char)) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn netlink_delinearize_chain(mut ctx: *mut netlink_ctx, mut nlc: *const nftnl_chain) -> *mut chain {
    let mut ud: [*const nftnl_udata; 1] = [unsafe { core::mem::zeroed() }];
    let mut priority: i32 = 0;
    let mut policy: i32 = 0;
    let mut len: i32 = 0;
    let mut i: i32 = 0;
    let mut dev_array: *mut *const core::ffi::c_char = core::ptr::null_mut();
    let mut chain: *mut chain = core::ptr::null_mut();
    let mut udata: *const core::ffi::c_char = core::ptr::null();
    let mut ulen: u32 = 0;
    chain = (unsafe { chain_alloc() } as *mut chain);
    (*chain).handle.family = unsafe { nftnl_chain_get_u32(nlc, 1u16) };
    (*chain).handle.table.name = unsafe { xstrdup(unsafe { nftnl_chain_get_str(nlc, 2u16) }) };
    (*chain).handle.chain.name = unsafe { xstrdup(unsafe { nftnl_chain_get_str(nlc, 0u16) }) };
    (*chain).handle.handle.id = unsafe { nftnl_chain_get_u64(nlc, 9u16) };
    if unsafe { nftnl_chain_is_set(nlc, 13u16) } {
        (*chain).flags = unsafe { nftnl_chain_get_u32(nlc, 13u16) };
    }
    if ((unsafe { nftnl_chain_is_set(nlc, 3u16) } && unsafe { nftnl_chain_is_set(nlc, 4u16) }) && unsafe { nftnl_chain_is_set(nlc, 10u16) }) && unsafe { nftnl_chain_is_set(nlc, 5u16) } {
        (*chain).hook.num = unsafe { nftnl_chain_get_u32(nlc, 3u16) };
        (*chain).hook.name = unsafe { hooknum2str((*chain).handle.family, (*chain).hook.num) };
        priority = unsafe { nftnl_chain_get_s32(nlc, 4u16) };
        (*chain).priority.expr = unsafe { constant_expr_alloc((((&raw const netlink_location).cast_mut()) as *const location), (((&raw const integer_type).cast_mut()) as *const datatype), 1, (core::mem::size_of::<i32>() * BITS_PER_BYTE) as u32, (&raw mut priority as *const core::ffi::c_void)) };
        (*chain).type_.str = unsafe { xstrdup(unsafe { nftnl_chain_get_str(nlc, 10u16) }) };
        policy = (unsafe { nftnl_chain_get_u32(nlc, 5u16) }) as i32;
        (*chain).policy = unsafe { constant_expr_alloc((((&raw const netlink_location).cast_mut()) as *const location), (((&raw const integer_type).cast_mut()) as *const datatype), 1, (core::mem::size_of::<i32>() * BITS_PER_BYTE) as u32, (&raw mut policy as *const core::ffi::c_void)) };
        unsafe { nftnl_chain_get_u32(nlc, 5u16) };
        if unsafe { nftnl_chain_is_set(nlc, 11u16) } {
            (*chain).dev_array = unsafe { xmalloc((core::mem::size_of::<*mut core::ffi::c_char>() * (2 as usize))) };
            (*chain).dev_array_len = 1;
            // C (statement): chain -> dev_array [ 0 ] = xstrdup ( nftnl_chain_get_str ( nlc , NFTNL_CHAIN_DEV ) ) ;
            todo!();
            // C (statement): chain -> dev_array [ 1 ] = NULL ;
            todo!();
        } else if unsafe { nftnl_chain_is_set(nlc, 12u16) } {
            dev_array = (unsafe { nftnl_chain_get(nlc, 12u16) } as *mut *const core::ffi::c_char);
            while !(*dev_array.offset(len as isize)).is_null() {
                len += 1;
            }
            (*chain).dev_array = unsafe { xmalloc((((len + 1) as usize) * core::mem::size_of::<*mut core::ffi::c_char>())) };
            {
                i = 0;
                while i < len {
                    // C (statement): chain -> dev_array [ i ] = xstrdup ( dev_array [ i ] ) ;
                    todo!();
                    i += 1;
                }
            }
            // C (statement): chain -> dev_array [ i ] = NULL ;
            todo!();
            (*chain).dev_array_len = len;
        }
        (*chain).flags |= CHAIN_F_BASECHAIN;
        if (*chain).dev_array_len != 0 {
            unsafe { qsort(((*chain).dev_array as *mut core::ffi::c_void), (*chain).dev_array_len as usize, core::mem::size_of::<*mut core::ffi::c_char>(), Some(qsort_device_cmp)) };
        }
    }
    if unsafe { nftnl_chain_is_set(nlc, 15u16) } {
        udata = (unsafe { nftnl_chain_get_data(nlc, 15u16, &raw mut ulen) } as *const core::ffi::c_char);
        if (unsafe { nftnl_udata_parse((udata as *const core::ffi::c_void), ulen, Some(chain_parse_udata_cb), (ud.as_mut_ptr() as *mut core::ffi::c_void)) }) < 0 {
            unsafe { netlink_io_error(ctx, core::ptr::null(), c"Cannot parse userdata".as_ptr()) };
            unsafe { chain_free(chain) };
            return core::ptr::null_mut();
        }
        if !ud[NFTNL_UDATA_CHAIN_COMMENT as usize].is_null() {
            (*chain).comment = unsafe { xstrdup(unsafe { nftnl_udata_get(ud[NFTNL_UDATA_CHAIN_COMMENT as usize]) }) };
        }
    }
    return chain;
}

unsafe extern "C" fn table_parse_udata_cb(mut attr: *const nftnl_udata, mut data: *mut core::ffi::c_void) -> i32 {
    let mut value: *mut u8 = (unsafe { nftnl_udata_get(attr) } as *mut u8);
    let mut tb: *mut *const nftnl_udata = (data as *mut *const nftnl_udata);
    let mut type_: u8 = unsafe { nftnl_udata_type(attr) };
    let mut len: u8 = unsafe { nftnl_udata_len(attr) };
    match (type_ as i32) {
        NFTNL_UDATA_TABLE_COMMENT => {
            if ((*value.offset(((len as i32) - 1) as isize)) as i32) != 0 {
                return -1;
            }
        }
        NFTNL_UDATA_TABLE_NFTVER => {
            if (len as usize) != core::mem::size_of::<[core::ffi::c_char; 4]>() {
                return -1;
            }
        }
        NFTNL_UDATA_TABLE_NFTBLD => {
            if (len as usize) != core::mem::size_of::<[core::ffi::c_char; 8]>() {
                return -1;
            }
        }
        _ => {
            return 0;
        }
    }
    (*tb.offset(type_ as isize)) = attr;
    return 0;
}

unsafe extern "C" fn version_cmp(mut ud: *mut *const nftnl_udata) -> i32 {
    let mut udbuf: *const core::ffi::c_char = core::ptr::null();
    let mut i: usize = 0;
    /* netlink attribute lengths checked by table_parse_udata_cb() */
    if !(*ud.offset(NFTNL_UDATA_TABLE_NFTVER as isize)).is_null() {
        udbuf = (unsafe { nftnl_udata_get((*ud.offset(NFTNL_UDATA_TABLE_NFTVER as isize))) } as *const core::ffi::c_char);
        {
            i = 0usize;
            while i < core::mem::size_of::<[core::ffi::c_char; 4]>() {
                if nftversion[i as usize] != (*udbuf.offset(i as isize)) {
                    return ((nftversion[i as usize]) as i32) - ((*udbuf.offset(i as isize)) as i32);
                }
                i += 1;
            }
        }
    }
    if !(*ud.offset(NFTNL_UDATA_TABLE_NFTBLD as isize)).is_null() {
        udbuf = (unsafe { nftnl_udata_get((*ud.offset(NFTNL_UDATA_TABLE_NFTBLD as isize))) } as *const core::ffi::c_char);
        {
            i = 0usize;
            while i < core::mem::size_of::<[core::ffi::c_char; 8]>() {
                if nftbuildstamp[i as usize] != (*udbuf.offset(i as isize)) {
                    return ((nftbuildstamp[i as usize]) as i32) - ((*udbuf.offset(i as isize)) as i32);
                }
                i += 1;
            }
        }
    }
    return 0;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn netlink_delinearize_table(mut ctx: *mut netlink_ctx, mut nlt: *const nftnl_table) -> *mut table {
    let mut ud: [*const nftnl_udata; 3] = [unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];
    let mut table: *mut table = core::ptr::null_mut();
    let mut udata: *const core::ffi::c_char = core::ptr::null();
    let mut ulen: u32 = 0;
    table = (unsafe { table_alloc() } as *mut table);
    (*table).handle.family = unsafe { nftnl_table_get_u32(nlt, 1u16) };
    (*table).handle.table.name = unsafe { xstrdup(unsafe { nftnl_table_get_str(nlt, 0u16) }) };
    (*table).flags = unsafe { nftnl_table_get_u32(nlt, 2u16) };
    (*table).handle.handle.id = unsafe { nftnl_table_get_u64(nlt, 4u16) };
    (*table).owner = unsafe { nftnl_table_get_u32(nlt, 6u16) };
    if unsafe { nftnl_table_is_set(nlt, 5u16) } {
        udata = (unsafe { nftnl_table_get_data(nlt, 5u16, &raw mut ulen) } as *const core::ffi::c_char);
        if (unsafe { nftnl_udata_parse((udata as *const core::ffi::c_void), ulen, Some(table_parse_udata_cb), (ud.as_mut_ptr() as *mut core::ffi::c_void)) }) < 0 {
            unsafe { netlink_io_error(ctx, core::ptr::null(), c"Cannot parse userdata".as_ptr()) };
            unsafe { table_free(table) };
            return core::ptr::null_mut();
        }
        if !ud[NFTNL_UDATA_TABLE_COMMENT as usize].is_null() {
            (*table).comment = unsafe { xstrdup(unsafe { nftnl_udata_get(ud[NFTNL_UDATA_TABLE_COMMENT as usize]) }) };
        }
        (*table).is_from_future = (((unsafe { version_cmp((ud.as_mut_ptr() as *mut *const nftnl_udata)) }) < 0) as i32);
    }
    return table;
}

unsafe extern "C" fn list_table_cb(mut nlt: *mut nftnl_table, mut arg: *mut core::ffi::c_void) -> i32 {
    let mut ctx: *mut netlink_ctx = (arg as *mut netlink_ctx);
    let mut table: *mut table = core::ptr::null_mut();
    table = unsafe { netlink_delinearize_table(ctx, (nlt as *const nftnl_table)) };
    if !table.is_null() {
        unsafe { list_add_tail((&raw mut (*table).list as *mut list_head), (&raw mut (*ctx).list as *mut list_head)) };
    }
    return 0;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn netlink_list_tables(mut ctx: *mut netlink_ctx, mut h: *const handle, mut filter: *const nft_cache_filter) -> i32 {
    let mut table_cache: *mut nftnl_table_list = core::ptr::null_mut();
    let mut family: u32 = (*h).family as u32;
    let mut table: *const core::ffi::c_char = core::ptr::null();
    if !filter.is_null() {
        family = (*filter).list.family;
        table = (*filter).list.table;
    }
    table_cache = unsafe { mnl_nft_table_dump(ctx, family as i32, table) };
    if table_cache.is_null() {
        if (*unsafe { __errno_location() }) == EINTR {
            return -1;
        }
        return -1;
    }
    (*ctx).data = h;
    unsafe { nftnl_table_list_foreach(table_cache, Some(list_table_cb), (ctx as *mut core::ffi::c_void)) };
    unsafe { nftnl_table_list_free(table_cache) };
    return 0;
}

