pub unsafe extern "C" fn dtype_map_to_kernel(mut dtype: *const datatype) -> nft_data_types {
    match (*dtype).type_ {
        TYPE_VERDICT => {
            return 4294967040u32;
        }
        _ => {
            return (*dtype).type_ as nft_data_types;
        }
    }
    unsafe { core::mem::zeroed() }
}

unsafe extern "C" fn dtype_map_from_kernel(mut type_: nft_data_types) -> *const datatype {
    /* The function always returns ownership of a reference. But for
    	 * &verdict_Type and datatype_lookup(), those are static instances,
    	 * we can omit the datatype_get() call.
    	 */
    match type_ {
        NFT_DATA_VERDICT => {
            return (((&raw const verdict_type).cast_mut()) as *const datatype);
        }
        _ => {
            if (type_ & ((-64i32) as u32)) != 0 {
                return unsafe { concat_type_alloc(type_ as u32) };
            }
            return unsafe { datatype_lookup(type_ as datatypes) };
        }
    }
    unsafe { core::mem::zeroed() }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn netlink_dump_set(mut nls: *const nftnl_set, mut ctx: *mut netlink_ctx) {
    let mut fp: *mut _IO_FILE = ((*(*ctx).nft).output.output_fp as *mut _IO_FILE);
    let mut family: u32 = 0;
    if !(((*(*ctx).nft).debug_mask & NFT_DEBUG_NETLINK) != 0) || fp.is_null() {
        return;
    }
    family = unsafe { nftnl_set_get_u32(nls, 7u16) };
    unsafe { fprintf(fp, c"family %d ".as_ptr(), family) };
    unsafe { nftnl_set_fprintf(fp, nls, 0u32, 0u32) };
    unsafe { fprintf(fp, c"\n".as_ptr()) };
}

unsafe extern "C" fn set_parse_udata_cb(mut attr: *const nftnl_udata, mut data: *mut core::ffi::c_void) -> i32 {
    let mut value: *mut u8 = (unsafe { nftnl_udata_get(attr) } as *mut u8);
    let mut tb: *mut *const nftnl_udata = (data as *mut *const nftnl_udata);
    let mut type_: u8 = unsafe { nftnl_udata_type(attr) };
    let mut len: u8 = unsafe { nftnl_udata_len(attr) };
    match (type_ as i32) {
        NFTNL_UDATA_SET_KEYBYTEORDER | NFTNL_UDATA_SET_DATABYTEORDER | NFTNL_UDATA_SET_MERGE_ELEMENTS | NFTNL_UDATA_SET_DATA_INTERVAL => {
            if (len as usize) != core::mem::size_of::<u32>() {
                return -1;
            }
        }
        NFTNL_UDATA_SET_KEY_TYPEOF | NFTNL_UDATA_SET_DATA_TYPEOF => {
            if (len as i32) < 3 {
                return -1;
            }
        }
        NFTNL_UDATA_SET_COMMENT => {
            if ((*value.offset(((len as i32) - 1) as isize)) as i32) != 0 {
                return -1;
            }
        }
        _ => {
            return 0;
        }
    }
    (*tb.offset(type_ as isize)) = attr;
    return 0;
}

unsafe extern "C" fn set_key_parse_udata(mut attr: *const nftnl_udata, mut data: *mut core::ffi::c_void) -> i32 {
    let mut tb: *mut *const nftnl_udata = (data as *mut *const nftnl_udata);
    let mut type_: u8 = unsafe { nftnl_udata_type(attr) };
    let mut len: u8 = unsafe { nftnl_udata_len(attr) };
    match (type_ as i32) {
        NFTNL_UDATA_SET_TYPEOF_EXPR => {
            if (len as usize) != core::mem::size_of::<u32>() {
                return -1;
            }
        }
        NFTNL_UDATA_SET_TYPEOF_DATA => {
        }
        _ => {
            return 0;
        }
    }
    (*tb.offset(type_ as isize)) = attr;
    return 0;
}

unsafe extern "C" fn set_make_key(mut attr: *const nftnl_udata) -> *mut expr {
    let mut ud: [*const nftnl_udata; 2] = [unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];
    let mut ops: *const expr_ops = core::ptr::null();
    let mut expr: *mut expr = core::ptr::null_mut();
    let mut etype: u32 = 0;
    let mut err: i32 = 0;
    if attr.is_null() {
        return core::ptr::null_mut();
    }
    err = unsafe { nftnl_udata_parse((unsafe { nftnl_udata_get(attr) } as *const core::ffi::c_void), (unsafe { nftnl_udata_len(attr) }) as u32, Some(set_key_parse_udata), (ud.as_mut_ptr() as *mut core::ffi::c_void)) };
    if err < 0 {
        return core::ptr::null_mut();
    }
    if ud[NFTNL_UDATA_SET_TYPEOF_EXPR as usize].is_null() || ud[NFTNL_UDATA_SET_TYPEOF_DATA as usize].is_null() {
        return core::ptr::null_mut();
    }
    etype = unsafe { nftnl_udata_get_u32(ud[NFTNL_UDATA_SET_TYPEOF_EXPR as usize]) };
    ops = unsafe { expr_ops_by_type_u32(etype) };
    if ops.is_null() || (*ops).parse_udata.is_none() {
        return core::ptr::null_mut();
    }
    expr = unsafe { ((*ops).parse_udata.unwrap())(ud[NFTNL_UDATA_SET_TYPEOF_DATA as usize]) };
    if expr.is_null() {
        return core::ptr::null_mut();
    }
    return expr;
}

unsafe extern "C" fn set_udata_key_valid(mut e: *const expr, mut len: u32) -> bool {
    if e.is_null() {
        return false;
    }
    return ((((((*e).len + BITS_PER_BYTE) - 1) / BITS_PER_BYTE) == (len / BITS_PER_BYTE)) as i32) != 0;
}

unsafe extern "C" fn set_elem_parse_expressions(mut e: *mut nftnl_expr, mut data: *mut core::ffi::c_void) -> i32 {
    let mut setelem_parse_ctx: *mut setelem_parse_ctx = (data as *mut setelem_parse_ctx);
    let mut cache: *mut nft_cache = (*setelem_parse_ctx).cache;
    let mut set: *mut set = (*setelem_parse_ctx).set;
    let mut stmt: *mut stmt = core::ptr::null_mut();
    stmt = (unsafe { netlink_parse_set_expr(set, cache, e) } as *mut stmt);
    if !stmt.is_null() {
        unsafe { list_add_tail(&raw mut (*stmt).list, &raw mut (*setelem_parse_ctx).stmt_list) };
    }
    return 0;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn netlink_delinearize_set(mut ctx: *mut netlink_ctx, mut nls: *const nftnl_set) -> *mut set {
    let mut ud: [*const nftnl_udata; 8] = [unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }, unsafe { core::mem::zeroed() }];
    let mut keybyteorder: byteorder = 0;
    let mut databyteorder: byteorder = 0;
    let mut set_parse_ctx: setelem_parse_ctx = unsafe { core::mem::zeroed() };
    let mut datatype: *const datatype = core::ptr::null();
    let mut datatype: *const datatype = core::ptr::null();
    let mut datatype: *const datatype = core::ptr::null();
    let mut datatype: *const datatype = core::ptr::null();
    let mut typeof_expr_data: *mut expr = core::ptr::null_mut();
    let mut typeof_expr_key: *mut expr = core::ptr::null_mut();
    let mut udata: *const core::ffi::c_char = core::ptr::null();
    let mut comment: *const core::ffi::c_char = core::ptr::null();
    let mut flags: u32 = 0;
    let mut key: u32 = 0;
    let mut objtype: u32 = 0u32;
    let mut data_interval: u32 = 0u32;
    let mut automerge: bool = false;
    let mut set: *mut set = core::ptr::null_mut();
    let mut ulen: u32 = 0;
    let mut klen: u32 = 0;
    if unsafe { nftnl_set_is_set(nls, 13u16) } {
        udata = (unsafe { nftnl_set_get_data(nls, 13u16, &raw mut ulen) } as *const core::ffi::c_char);
        if (unsafe { nftnl_udata_parse((udata as *const core::ffi::c_void), ulen, Some(set_parse_udata_cb), (ud.as_mut_ptr() as *mut core::ffi::c_void)) }) < 0 {
            unsafe { netlink_io_error(ctx, core::ptr::null(), c"Cannot parse userdata".as_ptr()) };
            return core::ptr::null_mut();
        }
        if !ud[NFTNL_UDATA_SET_KEYBYTEORDER as usize].is_null() {
            keybyteorder = (unsafe { nftnl_udata_get_u32(ud[NFTNL_UDATA_SET_KEYBYTEORDER as usize]) }) as byteorder;
        }
        if !ud[NFTNL_UDATA_SET_DATABYTEORDER as usize].is_null() {
            databyteorder = (unsafe { nftnl_udata_get_u32(ud[NFTNL_UDATA_SET_DATABYTEORDER as usize]) }) as byteorder;
        }
        if !ud[NFTNL_UDATA_SET_MERGE_ELEMENTS as usize].is_null() {
            automerge = unsafe { nftnl_udata_get_u32(ud[NFTNL_UDATA_SET_MERGE_ELEMENTS as usize]) } != 0;
        }
        if !ud[NFTNL_UDATA_SET_DATA_INTERVAL as usize].is_null() {
            data_interval = unsafe { nftnl_udata_get_u32(ud[NFTNL_UDATA_SET_DATA_INTERVAL as usize]) };
        }
        typeof_expr_key = unsafe { set_make_key(ud[NFTNL_UDATA_SET_KEY_TYPEOF as usize]) };
        if !ud[NFTNL_UDATA_SET_DATA_TYPEOF as usize].is_null() {
            typeof_expr_data = unsafe { set_make_key(ud[NFTNL_UDATA_SET_DATA_TYPEOF as usize]) };
        }
        if !ud[NFTNL_UDATA_SET_COMMENT as usize].is_null() {
            comment = (unsafe { nftnl_udata_get(ud[NFTNL_UDATA_SET_COMMENT as usize]) } as *const core::ffi::c_char);
        }
    }
    key = unsafe { nftnl_set_get_u32(nls, 3u16) };
    keytype = unsafe { dtype_map_from_kernel(key as nft_data_types) };
    if keytype.is_null() {
        unsafe { netlink_io_error(ctx, core::ptr::null(), c"Unknown data type in set key %u".as_ptr(), key) };
        return core::ptr::null_mut();
    }
    flags = unsafe { nftnl_set_get_u32(nls, 2u16) };
    'g_out: {
        if unsafe { set_is_datamap(flags) } != 0 {
            let mut data: u32 = 0;
            data = unsafe { nftnl_set_get_u32(nls, 5u16) };
            datatype = unsafe { dtype_map_from_kernel(data as nft_data_types) };
            if datatype.is_null() {
                unsafe { netlink_io_error(ctx, core::ptr::null(), c"Unknown data type in set key %u".as_ptr(), data) };
                set = core::ptr::null_mut();
                break 'g_out;
            }
        }
        if unsafe { set_is_objmap(flags) } != 0 {
            objtype = unsafe { nftnl_set_get_u32(nls, 14u16) };
            assert!(datatype.is_null());
            datatype = (((&raw const string_type).cast_mut()) as *const datatype);
        }
        set = (unsafe { set_alloc(((&raw const netlink_location).cast_mut())) } as *mut set);
        (*set).handle.family = unsafe { nftnl_set_get_u32(nls, 7u16) };
        (*set).handle.table.name = unsafe { xstrdup(unsafe { nftnl_set_get_str(nls, 0u16) }) };
        (*set).handle.set.name = unsafe { xstrdup(unsafe { nftnl_set_get_str(nls, 1u16) }) };
        (*set).automerge = automerge;
        if !comment.is_null() {
            (*set).comment = unsafe { xstrdup(comment) };
        }
        unsafe { init_list_head(&raw mut set_parse_ctx.stmt_list) };
        if unsafe { nftnl_set_is_set(nls, 17u16) } {
            let mut nle: *const nftnl_expr = core::ptr::null();
            let mut stmt: *mut stmt = core::ptr::null_mut();
            nle = (unsafe { nftnl_set_get(nls, 17u16) } as *const nftnl_expr);
            stmt = (unsafe { netlink_parse_set_expr(set, ((&raw const (*(*ctx).nft).cache).cast_mut()), nle) } as *mut stmt);
            unsafe { list_add_tail(&raw mut (*stmt).list, &raw mut set_parse_ctx.stmt_list) };
        } else if unsafe { nftnl_set_is_set(nls, 18u16) } {
            set_parse_ctx.cache = (((&raw const (*(*ctx).nft).cache).cast_mut()) as *mut nft_cache);
            set_parse_ctx.set = set;
            unsafe { nftnl_set_expr_foreach(nls, Some(set_elem_parse_expressions), (&raw mut set_parse_ctx as *mut core::ffi::c_void)) };
        }
        unsafe { list_splice_tail(&raw mut set_parse_ctx.stmt_list, (&raw mut (*set).stmt_list as *mut list_head)) };
        (*set).flags = unsafe { nftnl_set_get_u32(nls, 2u16) };
        if !datatype.is_null() {
            let mut dlen: u32 = 0;
            dtype2 = unsafe { set_datatype_alloc(datatype, databyteorder) };
            klen = ((unsafe { nftnl_set_get_u32(nls, 6u16) }) * BITS_PER_BYTE) as u32;
            dlen = (if (data_interval != 0) { klen / (2 as u32) } else { klen });
            if unsafe { set_udata_key_valid((typeof_expr_data as *const expr), dlen) } {
                (*typeof_expr_data).len = klen;
                (*set).data = typeof_expr_data;
                typeof_expr_data = core::ptr::null_mut();
            } else if ((*set).flags & NFT_SET_OBJECT) != 0 {
                (*set).data = unsafe { constant_expr_alloc((((&raw const netlink_location).cast_mut()) as *const location), dtype2, databyteorder, klen, core::ptr::null()) };
            } else {
                (*set).data = unsafe { constant_expr_alloc((((&raw const netlink_location).cast_mut()) as *const location), dtype2, databyteorder, klen, core::ptr::null()) };
                /* Can't use 'typeof' keyword, so discard key too */
                unsafe { expr_free(typeof_expr_key) };
                typeof_expr_key = core::ptr::null_mut();
            }
            if data_interval != 0 {
                (*(*set).data).flags |= EXPR_F_INTERVAL;
            }
        }
        dtype = unsafe { set_datatype_alloc(keytype, keybyteorder) };
        klen = ((unsafe { nftnl_set_get_u32(nls, 4u16) }) * BITS_PER_BYTE) as u32;
        if unsafe { set_udata_key_valid((typeof_expr_key as *const expr), klen) } {
            (*set).key = typeof_expr_key;
            typeof_expr_key = core::ptr::null_mut();
            (*set).key_typeof_valid = true;
        } else {
            (*set).key = unsafe { constant_expr_alloc((((&raw const netlink_location).cast_mut()) as *const location), dtype, keybyteorder, klen, core::ptr::null()) };
        }
        (*set).handle.handle.id = unsafe { nftnl_set_get_u64(nls, 15u16) };
        (*set).objtype = objtype;
        if unsafe { nftnl_set_is_set(nls, 11u16) } {
            (*set).timeout = unsafe { nftnl_set_get_u64(nls, 11u16) };
        }
        if unsafe { nftnl_set_is_set(nls, 12u16) } {
            (*set).gc_int = unsafe { nftnl_set_get_u32(nls, 12u16) };
        }
        if unsafe { nftnl_set_is_set(nls, 9u16) } {
            (*set).policy = unsafe { nftnl_set_get_u32(nls, 9u16) };
        }
        if unsafe { nftnl_set_is_set(nls, 10u16) } {
            (*set).desc.size = unsafe { nftnl_set_get_u32(nls, 10u16) };
        }
        if unsafe { nftnl_set_is_set(nls, 19u16) } {
            (*set).count = unsafe { nftnl_set_get_u32(nls, 19u16) };
        }
        if unsafe { nftnl_set_is_set(nls, 16u16) } {
            let mut len: u32 = 16u32;
            let mut data: *const u8 = core::ptr::null();
            data = (unsafe { nftnl_set_get_data(nls, 16u16, &raw mut len) } as *const u8);
            if !data.is_null() {
                unsafe { memcpy(((*set).desc.field_len as *mut core::ffi::c_void), (data as *const core::ffi::c_void), len as usize) };
                (*set).desc.field_count = len;
            }
        }
    }
    unsafe { expr_free(typeof_expr_data) };
    unsafe { expr_free(typeof_expr_key) };
    unsafe { datatype_free(datatype) };
    unsafe { datatype_free(keytype) };
    unsafe { datatype_free(dtype2) };
    unsafe { datatype_free(dtype) };
    return set;
}

