        i = 1u32;
        // C (for condition): for ( i = 1 ; i < array_size ( desc -> templates ) ; i ++ ) { tmpl = & desc -> templates [ i ] ; if ( tmpl -> len == 0 ) return ; if ( tmpl -> offset != expr -> payload . offset || tmpl -> len != expr -> len ) continue ; if ( desc -> protocol_key != i ) return ; expr -> payload . desc = desc ; expr -> payload . tmpl = tmpl ; dl -> pctx . th_dep . icmp . type = icmp_type ; return ; }
        todo!();
