unsafe extern "C" fn netlink_put_register(mut nle: *mut nftnl_expr, mut attr: u32, mut reg: u32) {
    /* Convert to 128 bit register numbers if possible for compatibility */
    if reg != (NFT_REG_VERDICT as u32) {
        reg -= ((NFT_REG_1) as u32);
        if (reg % (4 as u32)) == (0 as u32) {
            reg = (NFT_REG_1 as u32) + (reg / (4 as u32));
        } else {
            reg += ((NFT_REG32_00) as u32);
        }
    }
    unsafe { nftnl_expr_set_u32(nle, attr, reg) };
}

unsafe extern "C" fn __get_register(mut ctx: *mut netlink_linearize_ctx, mut size: u32) -> nft_registers {
    let mut reg: u32 = 0;
    let mut n: u32 = 0;
    n = (unsafe { netlink_register_space(size) }) as u32;
    if ((*ctx).reg_low + n) > 17 {
        unsafe { BUG(c"register reg_low %u invalid".as_ptr(), (*ctx).reg_low) };
    }
    reg = (*ctx).reg_low as u32;
    (*ctx).reg_low += n;
    return reg as nft_registers;
}

unsafe extern "C" fn __release_register(mut ctx: *mut netlink_linearize_ctx, mut size: u32) {
    let mut n: u32 = 0;
    n = (unsafe { netlink_register_space(size) }) as u32;
    if (*ctx).reg_low < ((NFT_REG_1 as u32) + n) {
        unsafe { BUG(c"register reg_low %u invalid".as_ptr(), (*ctx).reg_low) };
    }
    (*ctx).reg_low -= n;
}

unsafe extern "C" fn get_register(mut ctx: *mut netlink_linearize_ctx, mut expr: *const expr) -> nft_registers {
    if !expr.is_null() && ((*expr).etype() == EXPR_CONCAT) {
        return unsafe { __get_register(ctx, (*expr).len) };
    } else {
        return unsafe { __get_register(ctx, (NFT_REG_SIZE * BITS_PER_BYTE) as u32) };
    }
    unsafe { core::mem::zeroed() }
}

unsafe extern "C" fn release_register(mut ctx: *mut netlink_linearize_ctx, mut expr: *const expr) {
    if !expr.is_null() && ((*expr).etype() == EXPR_CONCAT) {
        unsafe { __release_register(ctx, (*expr).len) };
    } else {
        unsafe { __release_register(ctx, (NFT_REG_SIZE * BITS_PER_BYTE) as u32) };
    }
}

