#[unsafe(no_mangle)]
pub unsafe extern "C" fn netlink_gen_stmt_stateful(mut stmt: *const stmt) -> *mut nftnl_expr {
    match (*stmt).type_() {
        STMT_CONNLIMIT => {
            return unsafe { netlink_gen_connlimit_stmt(stmt) };
        }
        STMT_COUNTER => {
            return unsafe { netlink_gen_counter_stmt(stmt) };
        }
        STMT_LIMIT => {
            return unsafe { netlink_gen_limit_stmt(stmt) };
        }
        STMT_QUOTA => {
            return unsafe { netlink_gen_quota_stmt(stmt) };
        }
        STMT_LAST => {
            return unsafe { netlink_gen_last_stmt(stmt) };
        }
        _ => {
            unsafe { BUG(c"unknown stateful statement type %d".as_ptr(), (*stmt).type_()) };
        }
    }
    unsafe { core::mem::zeroed() }
}

