unsafe extern "C" fn netlink_gen_log_stmt(mut ctx: *mut netlink_linearize_ctx, mut stmt: *const stmt) {
    let mut nle: *mut nftnl_expr = core::ptr::null_mut();
    nle = (unsafe { alloc_nft_expr(c"log".as_ptr()) } as *mut nftnl_expr);
    if !(*stmt).anon4.log.prefix.is_null() {
        unsafe { nftnl_expr_set_str(nle, NFTNL_EXPR_LOG_PREFIX, (*stmt).anon4.log.prefix) };
    }
    if ((*stmt).anon4.log.flags & (STMT_LOG_GROUP as u32)) != 0 {
        unsafe { nftnl_expr_set_u16(nle, NFTNL_EXPR_LOG_GROUP, ((*stmt).anon4.log.group as i32)) };
        if ((*stmt).anon4.log.flags & (STMT_LOG_SNAPLEN as u32)) != 0 {
            unsafe { nftnl_expr_set_u32(nle, NFTNL_EXPR_LOG_SNAPLEN, (*stmt).anon4.log.snaplen) };
        }
        if ((*stmt).anon4.log.flags & (STMT_LOG_QTHRESHOLD as u32)) != 0 {
            unsafe { nftnl_expr_set_u16(nle, NFTNL_EXPR_LOG_QTHRESHOLD, ((*stmt).anon4.log.qthreshold as i32)) };
        }
    } else {
        if ((*stmt).anon4.log.flags & (STMT_LOG_LEVEL as u32)) != 0 {
            unsafe { nftnl_expr_set_u32(nle, NFTNL_EXPR_LOG_LEVEL, (*stmt).anon4.log.level) };
        }
        if (*stmt).anon4.log.logflags != 0 {
            unsafe { nftnl_expr_set_u32(nle, NFTNL_EXPR_LOG_FLAGS, (*stmt).anon4.log.logflags) };
        }
    }
    unsafe { nft_rule_add_expr(ctx, nle, (((&raw const (*stmt).location).cast_mut()) as *const location)) };
}

unsafe extern "C" fn netlink_gen_reject_stmt(mut ctx: *mut netlink_linearize_ctx, mut stmt: *const stmt) {
    let mut nle: *mut nftnl_expr = core::ptr::null_mut();
    nle = (unsafe { alloc_nft_expr(c"reject".as_ptr()) } as *mut nftnl_expr);
    unsafe { nftnl_expr_set_u32(nle, NFTNL_EXPR_REJECT_TYPE, (*stmt).anon4.reject.type_()) };
    if ((*stmt).anon4.reject.icmp_code as i32) != -1 {
        unsafe { nftnl_expr_set_u8(nle, NFTNL_EXPR_REJECT_CODE, ((*stmt).anon4.reject.icmp_code as i32)) };
    }
    unsafe { nft_rule_add_expr(ctx, nle, (((&raw const (*stmt).location).cast_mut()) as *const location)) };
}

unsafe extern "C" fn nat_addrlen(mut family: u8) -> u32 {
    match (family as i32) {
        NFPROTO_IPV4 => {
            return 32u32;
        }
        NFPROTO_IPV6 => {
            return 128u32;
        }
        _ => {}
    }
    unsafe { BUG(c"invalid nat family %u".as_ptr(), (family as i32)) };
    return 0u32;
}

unsafe extern "C" fn netlink_gen_nat_stmt(mut ctx: *mut netlink_linearize_ctx, mut stmt: *const stmt) {
    let mut nle: *mut nftnl_expr = core::ptr::null_mut();
    let mut amin_reg: nft_registers = unsafe { core::mem::zeroed() };
    let mut amax_reg: nft_registers = unsafe { core::mem::zeroed() };
    let mut pmin_reg: nft_registers = unsafe { core::mem::zeroed() };
    let mut pmax_reg: nft_registers = unsafe { core::mem::zeroed() };
    let mut family: u8 = 0u8;
    let mut registers: i32 = 0;
    let mut nftnl_flag_attr: i32 = 0;
    let mut nftnl_reg_pmin: i32 = 0;
    let mut nftnl_reg_pmax: i32 = 0;
    match (*stmt).anon4.nat.type_ {
        NFT_NAT_SNAT | NFT_NAT_DNAT => {
            nle = (unsafe { alloc_nft_expr(c"nat".as_ptr()) } as *mut nftnl_expr);
            unsafe { nftnl_expr_set_u32(nle, NFTNL_EXPR_NAT_TYPE, (*stmt).anon4.nat.type_) };
            family = (*stmt).anon4.nat.family;
            unsafe { nftnl_expr_set_u32(nle, NFTNL_EXPR_NAT_FAMILY, (family as i32)) };
            nftnl_flag_attr = NFTNL_EXPR_NAT_FLAGS as i32;
            nftnl_reg_pmin = NFTNL_EXPR_NAT_REG_PROTO_MIN as i32;
            nftnl_reg_pmax = NFTNL_EXPR_NAT_REG_PROTO_MAX as i32;
        }
        NFT_NAT_MASQ => {
            nle = (unsafe { alloc_nft_expr(c"masq".as_ptr()) } as *mut nftnl_expr);
            nftnl_flag_attr = NFTNL_EXPR_MASQ_FLAGS as i32;
            nftnl_reg_pmin = NFTNL_EXPR_MASQ_REG_PROTO_MIN as i32;
            nftnl_reg_pmax = NFTNL_EXPR_MASQ_REG_PROTO_MAX as i32;
        }
        NFT_NAT_REDIR => {
            nle = (unsafe { alloc_nft_expr(c"redir".as_ptr()) } as *mut nftnl_expr);
            nftnl_flag_attr = NFTNL_EXPR_REDIR_FLAGS as i32;
            nftnl_reg_pmin = NFTNL_EXPR_REDIR_REG_PROTO_MIN as i32;
            nftnl_reg_pmax = NFTNL_EXPR_REDIR_REG_PROTO_MAX as i32;
        }
        _ => {
            unsafe { BUG(c"unknown nat type %d".as_ptr(), (*stmt).anon4.nat.type_) };
        }
    }
    if (*stmt).anon4.nat.flags != (0 as u32) {
        unsafe { nftnl_expr_set_u32(nle, nftnl_flag_attr, (*stmt).anon4.nat.flags) };
    }
    if !(*stmt).anon4.nat.addr.is_null() {
        amin_reg = unsafe { get_register(ctx, ((*stmt).anon4.nat.addr as *const expr)) };
        if (*(*stmt).anon4.nat.addr).etype() == EXPR_RANGE {
            amax_reg = unsafe { get_register(ctx, core::ptr::null()) };
            registers += 1;
            unsafe { netlink_gen_expr(ctx, ((*(*stmt).anon4.nat.addr).anon9.anon12.left as *const expr), amin_reg) };
            unsafe { netlink_gen_expr(ctx, ((*(*stmt).anon4.nat.addr).anon9.anon12.right as *const expr), amax_reg) };
            unsafe { netlink_put_register(nle, NFTNL_EXPR_NAT_REG_ADDR_MIN as u32, amin_reg as u32) };
            unsafe { netlink_put_register(nle, NFTNL_EXPR_NAT_REG_ADDR_MAX as u32, amax_reg as u32) };
        } else {
            unsafe { netlink_gen_expr(ctx, ((*stmt).anon4.nat.addr as *const expr), amin_reg) };
            unsafe { netlink_put_register(nle, NFTNL_EXPR_NAT_REG_ADDR_MIN as u32, amin_reg as u32) };
            if ((*(*stmt).anon4.nat.addr).etype() == EXPR_MAP) && (((*(*(*(*(*stmt).anon4.nat.addr).anon9.anon13.mappings).anon9.anon9.set).data).flags & EXPR_F_INTERVAL) != 0) {
                amin_reg += unsafe { netlink_register_space(unsafe { nat_addrlen(family) }) };
                if ((*stmt).anon4.nat.type_flags & (STMT_NAT_F_CONCAT as u32)) != 0 {
                    unsafe { netlink_put_register(nle, nftnl_reg_pmin as u32, amin_reg as u32) };
                } else {
                    unsafe { netlink_put_register(nle, NFTNL_EXPR_NAT_REG_ADDR_MAX as u32, amin_reg as u32) };
                }
            }
        }
        if ((*stmt).anon4.nat.type_flags & (STMT_NAT_F_CONCAT as u32)) != 0 {
            /* nat_stmt evaluation step doesn't allow
    			 * STMT_NAT_F_CONCAT && stmt->nat.proto.
    			 */
            assert!((*stmt).anon4.nat.proto.is_null());
            pmin_reg = amin_reg;
            if ((*stmt).anon4.nat.type_flags & (STMT_NAT_F_INTERVAL as u32)) != 0 {
                pmin_reg += unsafe { netlink_register_space(unsafe { nat_addrlen(family) }) };
                unsafe { netlink_put_register(nle, NFTNL_EXPR_NAT_REG_ADDR_MAX as u32, pmin_reg as u32) };
            }
            /* if STMT_NAT_F_CONCAT is set, the mapped type is a
    			 * concatenation of 'addr . inet_service'.
    			 * The map lookup will then return the
    			 * concatenated value, so we need to skip
    			 * the address and use the register that
    			 * will hold the inet_service part.
    			 */
            pmin_reg += unsafe { netlink_register_space(unsafe { nat_addrlen(family) }) };
            if ((*stmt).anon4.nat.type_flags & (STMT_NAT_F_INTERVAL as u32)) != 0 {
                unsafe { netlink_put_register(nle, nftnl_reg_pmax as u32, pmin_reg as u32) };
            } else {
                unsafe { netlink_put_register(nle, nftnl_reg_pmin as u32, pmin_reg as u32) };
            }
        }
    }
    if !(*stmt).anon4.nat.proto.is_null() {
        pmin_reg = unsafe { get_register(ctx, core::ptr::null()) };
        registers += 1;
        if (*(*stmt).anon4.nat.proto).etype() == EXPR_RANGE {
            pmax_reg = unsafe { get_register(ctx, core::ptr::null()) };
            registers += 1;
            unsafe { netlink_gen_expr(ctx, ((*(*stmt).anon4.nat.proto).anon9.anon12.left as *const expr), pmin_reg) };
            unsafe { netlink_gen_expr(ctx, ((*(*stmt).anon4.nat.proto).anon9.anon12.right as *const expr), pmax_reg) };
            unsafe { netlink_put_register(nle, nftnl_reg_pmin as u32, pmin_reg as u32) };
            unsafe { netlink_put_register(nle, nftnl_reg_pmax as u32, pmax_reg as u32) };
        } else {
            unsafe { netlink_gen_expr(ctx, ((*stmt).anon4.nat.proto as *const expr), pmin_reg) };
            unsafe { netlink_put_register(nle, nftnl_reg_pmin as u32, pmin_reg as u32) };
        }
    }
    while registers > 0 {
        unsafe { release_register(ctx, core::ptr::null()) };
        registers -= 1;
    }
    if !(*stmt).anon4.nat.addr.is_null() {
        unsafe { release_register(ctx, ((*stmt).anon4.nat.addr as *const expr)) };
    }
    unsafe { nft_rule_add_expr(ctx, nle, (((&raw const (*stmt).location).cast_mut()) as *const location)) };
}

unsafe extern "C" fn netlink_gen_tproxy_stmt(mut ctx: *mut netlink_linearize_ctx, mut stmt: *const stmt) {
    let mut nle: *mut nftnl_expr = core::ptr::null_mut();
    let mut addr_reg: nft_registers = unsafe { core::mem::zeroed() };
    let mut port_reg: nft_registers = unsafe { core::mem::zeroed() };
    let mut registers: i32 = 0;
    let mut family: i32 = (*stmt).anon4.tproxy.family as i32;
    let mut nftnl_reg_port: i32 = 0;
    nle = (unsafe { alloc_nft_expr(c"tproxy".as_ptr()) } as *mut nftnl_expr);
    unsafe { nftnl_expr_set_u32(nle, NFTNL_EXPR_TPROXY_FAMILY, family) };
    nftnl_reg_port = NFTNL_EXPR_TPROXY_REG_PORT as i32;
    if !(*stmt).anon4.tproxy.addr.is_null() {
        addr_reg = unsafe { get_register(ctx, core::ptr::null()) };
        registers += 1;
        unsafe { netlink_gen_expr(ctx, ((*stmt).anon4.tproxy.addr as *const expr), addr_reg) };
        unsafe { netlink_put_register(nle, NFTNL_EXPR_TPROXY_REG_ADDR as u32, addr_reg as u32) };
    }
    if !(*stmt).anon4.tproxy.port.is_null() {
        port_reg = unsafe { get_register(ctx, core::ptr::null()) };
        registers += 1;
        unsafe { netlink_gen_expr(ctx, ((*stmt).anon4.tproxy.port as *const expr), port_reg) };
        unsafe { netlink_put_register(nle, nftnl_reg_port as u32, port_reg as u32) };
    }
    while registers > 0 {
        unsafe { release_register(ctx, core::ptr::null()) };
        registers -= 1;
    }
    unsafe { nft_rule_add_expr(ctx, nle, (((&raw const (*stmt).location).cast_mut()) as *const location)) };
}

