unsafe extern "C" fn netlink_gen_dup_stmt(mut ctx: *mut netlink_linearize_ctx, mut stmt: *const stmt) {
    let mut nle: *mut nftnl_expr = core::ptr::null_mut();
    let mut sreg1: nft_registers = unsafe { core::mem::zeroed() };
    let mut sreg2: nft_registers = unsafe { core::mem::zeroed() };
    nle = (unsafe { alloc_nft_expr(c"dup".as_ptr()) } as *mut nftnl_expr);
    if !(*stmt).anon4.dup.to.is_null() {
        if (*(*stmt).anon4.dup.to).dtype == (((&raw const ifindex_type).cast_mut()) as *const datatype) {
            sreg1 = unsafe { get_register(ctx, ((*stmt).anon4.dup.to as *const expr)) };
            unsafe { netlink_gen_expr(ctx, ((*stmt).anon4.dup.to as *const expr), sreg1) };
            unsafe { netlink_put_register(nle, NFTNL_EXPR_DUP_SREG_DEV as u32, sreg1 as u32) };
        } else {
            sreg1 = unsafe { get_register(ctx, ((*stmt).anon4.dup.to as *const expr)) };
            unsafe { netlink_gen_expr(ctx, ((*stmt).anon4.dup.to as *const expr), sreg1) };
            unsafe { netlink_put_register(nle, NFTNL_EXPR_DUP_SREG_ADDR as u32, sreg1 as u32) };
        }
    }
    if !(*stmt).anon4.dup.dev.is_null() {
        sreg2 = unsafe { get_register(ctx, ((*stmt).anon4.dup.dev as *const expr)) };
        unsafe { netlink_gen_expr(ctx, ((*stmt).anon4.dup.dev as *const expr), sreg2) };
        unsafe { netlink_put_register(nle, NFTNL_EXPR_DUP_SREG_DEV as u32, sreg2 as u32) };
        unsafe { release_register(ctx, ((*stmt).anon4.dup.dev as *const expr)) };
    }
    if !(*stmt).anon4.dup.to.is_null() {
        unsafe { release_register(ctx, ((*stmt).anon4.dup.to as *const expr)) };
    }
    unsafe { nft_rule_add_expr(ctx, nle, (((&raw const (*stmt).location).cast_mut()) as *const location)) };
}

unsafe extern "C" fn netlink_gen_fwd_stmt(mut ctx: *mut netlink_linearize_ctx, mut stmt: *const stmt) {
    let mut sreg1: nft_registers = unsafe { core::mem::zeroed() };
    let mut sreg2: nft_registers = unsafe { core::mem::zeroed() };
    let mut nle: *mut nftnl_expr = core::ptr::null_mut();
    nle = (unsafe { alloc_nft_expr(c"fwd".as_ptr()) } as *mut nftnl_expr);
    sreg1 = unsafe { get_register(ctx, ((*stmt).anon4.fwd.dev as *const expr)) };
    unsafe { netlink_gen_expr(ctx, ((*stmt).anon4.fwd.dev as *const expr), sreg1) };
    unsafe { netlink_put_register(nle, NFTNL_EXPR_FWD_SREG_DEV as u32, sreg1 as u32) };
    if !(*stmt).anon4.fwd.addr.is_null() {
        sreg2 = unsafe { get_register(ctx, ((*stmt).anon4.fwd.addr as *const expr)) };
        unsafe { netlink_gen_expr(ctx, ((*stmt).anon4.fwd.addr as *const expr), sreg2) };
        unsafe { netlink_put_register(nle, NFTNL_EXPR_FWD_SREG_ADDR as u32, sreg2 as u32) };
        unsafe { release_register(ctx, ((*stmt).anon4.fwd.addr as *const expr)) };
    }
    unsafe { release_register(ctx, ((*stmt).anon4.fwd.dev as *const expr)) };
    if (*stmt).anon4.fwd.family != 0 {
        unsafe { nftnl_expr_set_u32(nle, NFTNL_EXPR_FWD_NFPROTO, ((*stmt).anon4.fwd.family as i32)) };
    }
    unsafe { nft_rule_add_expr(ctx, nle, (((&raw const (*stmt).location).cast_mut()) as *const location)) };
}

