#[unsafe(no_mangle)]
pub unsafe extern "C" fn nft_getprotobynumber(mut proto: i32, mut out_name: *mut core::ffi::c_char, mut name_len: usize) -> bool {
    let mut result: *const protoent = core::ptr::null();
    result = (unsafe { getprotobynumber(proto) } as *const protoent);
    if result.is_null() {
        return false;
    }
    if (unsafe { strlen(((*result).p_name as *const core::ffi::c_char)) }) >= name_len {
        return false;
    }
    unsafe { strcpy(out_name, ((*result).p_name as *const core::ffi::c_char)) };
    return true;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn nft_getprotobyname(mut name: *const core::ffi::c_char) -> i32 {
    let mut result: *const protoent = core::ptr::null();
    result = (unsafe { getprotobyname(name) } as *const protoent);
    if result.is_null() {
        return -1;
    }
    if ((*result).p_proto < 0) || ((*result).p_proto > (u8::MAX as i32)) {
        return -1;
    }
    return ((*result).p_proto as u8) as i32;
}

