#[unsafe(no_mangle)]
pub unsafe extern "C" fn get_progname(mut portid: u32) -> *mut core::ffi::c_char {
    let mut fp: *mut _IO_FILE = unsafe { fopen(c"/proc/net/netlink".as_ptr(), c"r".as_ptr()) };
    let mut portid_check: u32 = 0;
    let mut inode: u64 = 0;
    let mut ret: i32 = 0;
    let mut prot: i32 = 0;
    if fp.is_null() {
        return core::ptr::null_mut();
    }
    loop {
        let mut line: [core::ffi::c_char; 256] = [0; 256];
        if unsafe { fgets((line.as_mut_ptr() as *mut core::ffi::c_char), (core::mem::size_of::<[core::ffi::c_char; 256]>()) as i32, fp) }.is_null() {
            break;
        }
        ret = unsafe { sscanf((line.as_mut_ptr() as *const core::ffi::c_char), c"%*x %d %u %*x %*d %*d %*x %*d %*u %lu\n".as_ptr(), &raw mut prot, &raw mut portid_check, &raw mut inode) };
        if ret == EOF {
            break;
        }
        if ((ret == 3) && (portid_check == portid)) && (prot == NETLINK_NETFILTER) {
            static mut last_portid: u32 = 0;
            static mut last_inode: u32 = 0;
            static mut last_program: *mut core::ffi::c_char = core::ptr::null_mut();
            let mut prog: *mut core::ffi::c_char = core::ptr::null_mut();
            unsafe { fclose(fp) };
            if (last_portid == portid) && ((last_inode as u64) == inode) {
                return last_program;
            }
            prog = unsafe { name_by_portid(portid, inode) };
            unsafe { free((last_program as *mut core::ffi::c_void)) };
            last_program = prog;
            last_portid = portid;
            last_inode = inode as u32;
            return prog;
        }
    }
    unsafe { fclose(fp) };
    return core::ptr::null_mut();
}

unsafe extern "C" fn pid2name(mut pid: i32) -> *mut core::ffi::c_char {
    let mut procname: [core::ffi::c_char; 256] = [0; 256];
    let mut prog: *mut core::ffi::c_char = core::ptr::null_mut();
    let mut fp: *mut _IO_FILE = core::ptr::null_mut();
    let mut ret: i32 = 0;
    ret = unsafe { snprintf((procname.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 256]>(), c"/proc/%lu/stat".as_ptr(), (pid as u64)) };
    if (ret < 0) || (ret > (core::mem::size_of::<[core::ffi::c_char; 256]>() as i32)) {
        return core::ptr::null_mut();
    }
    fp = unsafe { fopen((procname.as_mut_ptr() as *const core::ffi::c_char), c"r".as_ptr()) };
    if fp.is_null() {
        return core::ptr::null_mut();
    }
    ret = unsafe { fscanf(fp, c"%*u (%m[^)]".as_ptr(), &raw mut prog) };
    unsafe { fclose(fp) };
    if ret == 1 {
        return prog;
    }
    return core::ptr::null_mut();
}

unsafe extern "C" fn portid2name(mut pid: i32, mut portid: u32, mut inode: u64) -> *mut core::ffi::c_char {
    let mut ent: *const dirent = core::ptr::null();
    let mut procname: [core::ffi::c_char; 256] = [0; 256];
    let mut dir: *mut __dirstream = core::ptr::null_mut();
    let mut ret: i32 = 0;
    ret = unsafe { snprintf((procname.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 256]>(), c"/proc/%lu/fd/".as_ptr(), (pid as u64)) };
    if (ret < 0) || (ret >= (core::mem::size_of::<[core::ffi::c_char; 256]>() as i32)) {
        return core::ptr::null_mut();
    }
    dir = unsafe { opendir((procname.as_mut_ptr() as *const core::ffi::c_char)) };
    if dir.is_null() {
        return core::ptr::null_mut();
    }
    loop {
        let mut ino: u64 = 0;
        let mut tmp: [core::ffi::c_char; 128] = [0; 128];
        let mut rl: isize = 0;
        ent = (unsafe { readdir(dir) } as *const dirent);
        if ent.is_null() {
            break;
        }
        if ((*ent).d_type as i32) != DT_LNK {
            continue;
        }
        ret = unsafe { snprintf((procname.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 256]>(), c"/proc/%d/fd/%s".as_ptr(), pid, (*ent).d_name.as_ptr()) };
        if (ret < 0) || (ret >= (core::mem::size_of::<[core::ffi::c_char; 256]>() as i32)) {
            continue;
        }
        rl = unsafe { readlink((procname.as_mut_ptr() as *const core::ffi::c_char), (tmp.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 128]>()) };
        if (rl <= (0 as isize)) || (rl >= (core::mem::size_of::<[core::ffi::c_char; 128]>() as isize)) {
            continue;
        }
        tmp[rl as usize] = (0 as core::ffi::c_char);
        ret = unsafe { sscanf((tmp.as_mut_ptr() as *const core::ffi::c_char), c"socket:[%lu]".as_ptr(), &raw mut ino) };
        if (ret == 1) && (ino == inode) {
            unsafe { closedir(dir) };
            return unsafe { pid2name(pid) };
        }
    }
    unsafe { closedir(dir) };
    return core::ptr::null_mut();
}

unsafe extern "C" fn name_by_portid(mut portid: u32, mut inode: u64) -> *mut core::ffi::c_char {
    let mut ent: *const dirent = core::ptr::null();
    let mut prog: *mut core::ffi::c_char = core::ptr::null_mut();
    let mut dir: *mut __dirstream = core::ptr::null_mut();
    /* Many netlink users use their process ID to allocate the first port id. */
    prog = unsafe { portid2name(portid as i32, portid, inode) };
    if !prog.is_null() {
        return prog;
    }
    /* no luck, search harder. */
    dir = unsafe { opendir(c"/proc".as_ptr()) };
    if dir.is_null() {
        return core::ptr::null_mut();
    }
    loop {
        let mut pid: u64 = 0;
        let mut end: *mut core::ffi::c_char = core::ptr::null_mut();
        ent = (unsafe { readdir(dir) } as *const dirent);
        if ent.is_null() {
            break;
        }
        if ((*ent).d_type as i32) != DT_DIR {
            continue;
        }
        pid = unsafe { strtoul(((*ent).d_name.as_ptr() as *const core::ffi::c_char), (&raw mut end as *mut *mut core::ffi::c_char), 10) };
        if (pid <= (1 as u64)) || ((*end) != 0) {
            continue;
        }
        if pid == (portid as u64) {
            /* already tried */
            continue;
        }
        prog = unsafe { portid2name(pid as i32, portid, inode) };
        if !prog.is_null() {
            break;
        }
    }
    unsafe { closedir(dir) };
    return prog;
}

