#[unsafe(no_mangle)]
pub unsafe extern "C" fn parser_init(mut nft: *mut nft_ctx, mut state: *mut parser_state, mut msgs: *mut list_head, mut cmds: *mut list_head, mut top_scope: *mut scope) {
    unsafe { memset((state as *mut core::ffi::c_void), 0, core::mem::size_of::<parser_state>()) };
    (*state).msgs = msgs;
    (*state).cmds = cmds;
    (*state).scopes[0] = (unsafe { scope_init(top_scope, core::ptr::null_mut()) } as *mut scope);
    unsafe { init_list_head(&raw mut (*state).indesc_list) };
}

