/*-----------------------------------.
| Print this symbol's value on YYO.  |
`-----------------------------------*/
unsafe extern "C" fn yy_symbol_value_print(mut yyo: *mut _IO_FILE, mut yykind: yysymbol_kind_t, mut yyvaluep: *const YYSTYPE, mut yylocationp: *const location, mut nft: *mut nft_ctx, mut scanner: *mut core::ffi::c_void, mut state: *mut parser_state) {
    let mut yyoutput: *mut _IO_FILE = yyo;
    let _ = yyoutput;
    let _ = yylocationp;
    let _ = nft;
    let _ = scanner;
    let _ = state;
    if yyvaluep.is_null() {
        return;
    }
    let _ = yykind;
}

/*---------------------------.
| Print this symbol on YYO.  |
`---------------------------*/
unsafe extern "C" fn yy_symbol_print(mut yyo: *mut _IO_FILE, mut yykind: yysymbol_kind_t, mut yyvaluep: *const YYSTYPE, mut yylocationp: *const location, mut nft: *mut nft_ctx, mut scanner: *mut core::ffi::c_void, mut state: *mut parser_state) {
    unsafe { fprintf(yyo, c"%s %s (".as_ptr(), (if (yykind < YYNTOKENS) { c"token".as_ptr() } else { c"nterm".as_ptr() }), unsafe { yysymbol_name(yykind) }) };
    let _ = 0;
    unsafe { fprintf(yyo, c": ".as_ptr()) };
    unsafe { yy_symbol_value_print(yyo, yykind, yyvaluep, yylocationp, nft, scanner, state) };
    unsafe { fprintf(yyo, c")".as_ptr()) };
}

/*------------------------------------------------------------------.
| yy_stack_print -- Print the state stack from its BOTTOM up to its |
| TOP (included).                                                   |
`------------------------------------------------------------------*/
unsafe extern "C" fn yy_stack_print(mut yybottom: *mut i16, mut yytop: *mut i16) {
    unsafe { fprintf(stderr, c"Stack now".as_ptr()) };
    while yybottom <= yytop {
        let mut yybot: i32 = (*yybottom) as i32;
        unsafe { fprintf(stderr, c" %d".as_ptr(), yybot) };
        yybottom = yybottom.offset(1);
    }
    unsafe { fprintf(stderr, c"\n".as_ptr()) };
}

/*------------------------------------------------.
| Report that the YYRULE is going to be reduced.  |
`------------------------------------------------*/
unsafe extern "C" fn yy_reduce_print(mut yyssp: *mut i16, mut yyvsp: *mut YYSTYPE, mut yylsp: *mut location, mut yyrule: i32, mut nft: *mut nft_ctx, mut scanner: *mut core::ffi::c_void, mut state: *mut parser_state) {
    let mut yylno: i32 = (yyrline[yyrule as usize]) as i32;
    let mut yynrhs: i32 = (yyr2[yyrule as usize]) as i32;
    let mut yyi: i32 = 0;
    unsafe { fprintf(stderr, c"Reducing stack by rule %d (line %d):\n".as_ptr(), (yyrule - 1), yylno) };
    /* The symbols being reduced.  */
    {
        yyi = 0;
        while yyi < yynrhs {
            unsafe { fprintf(stderr, c"   $%d = ".as_ptr(), (yyi + 1)) };
            unsafe { yy_symbol_print(stderr, yystos[(*yyssp.offset(((yyi + 1) - yynrhs) as isize)) as usize] as yysymbol_kind_t, (&raw mut (*yyvsp.offset(((yyi + 1) - yynrhs) as isize)) as *const YYSTYPE), (&raw mut (*yylsp.offset(((yyi + 1) - yynrhs) as isize)) as *const location), nft, scanner, state) };
            unsafe { fprintf(stderr, c"\n".as_ptr()) };
            yyi += 1;
        }
    }
}

/* Given a state stack such that *YYBOTTOM is its bottom, such that
   *YYTOP is either its top or is YYTOP_EMPTY to indicate an empty
   stack, and such that *YYCAPACITY is the maximum number of elements it
   can hold without a reallocation, make sure there is enough room to
   store YYADD more elements.  If not, allocate a new stack using
   YYSTACK_ALLOC, copy the existing elements, and adjust *YYBOTTOM,
   *YYTOP, and *YYCAPACITY to reflect the new capacity and memory
   location.  If *YYBOTTOM != YYBOTTOM_NO_FREE, then free the old stack
   using YYSTACK_FREE.  Return 0 if successful or if no reallocation is
   required.  Return YYENOMEM if memory is exhausted.  */
unsafe extern "C" fn yy_lac_stack_realloc(mut yycapacity: *mut i64, mut yyadd: i64, mut yydebug_prefix: *const core::ffi::c_char, mut yydebug_suffix: *const core::ffi::c_char, mut yybottom: *mut *mut i16, mut yybottom_no_free: *mut i16, mut yytop: *mut *mut i16, mut yytop_empty: *mut i16) -> i32 {
    let mut yysize_old: i64 = (if ((*yytop) == yytop_empty) { 0i64 } else { (((*yytop).offset_from((*yybottom))) + (1 as isize)) as i64 });
    let mut yysize_new: i64 = yysize_old + yyadd;
    if (*yycapacity) < yysize_new {
        let mut yyalloc: i64 = (2 as i64) * yysize_new;
        let mut yybottom_new: *mut i16 = core::ptr::null_mut();
        /* Use YYMAXDEPTH for maximum stack size given that the stack
             should never need to grow larger than the main state stack
             needs to grow without LAC.  */
        if (YYMAXDEPTH as i64) < yysize_new {
            {
                if nft_debug != 0 {
                    unsafe { fprintf(stderr, c"%smax size exceeded%s".as_ptr(), yydebug_prefix, yydebug_suffix) };
                }
            }
            return -2;
        }
        if (YYMAXDEPTH as i64) < yyalloc {
            yyalloc = 10000i64;
        }
        yybottom_new = (unsafe { malloc(((yyalloc * (core::mem::size_of::<i16>() as i64)) as u64) as usize) } as *mut i16);
        if yybottom_new.is_null() {
            {
                if nft_debug != 0 {
                    unsafe { fprintf(stderr, c"%srealloc failed%s".as_ptr(), yydebug_prefix, yydebug_suffix) };
                }
            }
            return -2;
        }
        if (*yytop) != yytop_empty {
            unsafe { memcpy((yybottom_new as *mut core::ffi::c_void), ((*yybottom) as *const core::ffi::c_void), ((yysize_old as u64) as usize) * core::mem::size_of::<i16>()) };
            (*yytop) = yybottom_new.offset((yysize_old - (1 as i64)) as isize);
        }
        if (*yybottom) != yybottom_no_free {
            unsafe { free(((*yybottom) as *mut core::ffi::c_void)) };
        }
        (*yybottom) = yybottom_new;
        (*yycapacity) = yyalloc;
    }
    return 0;
}

/* Given the stack whose top is *YYSSP, return 0 iff YYTOKEN can
   eventually (after perhaps some reductions) be shifted, return 1 if
   not, or return YYENOMEM if memory is exhausted.  As preconditions and
   postconditions: *YYES_CAPACITY is the allocated size of the array to
   which *YYES points, and either *YYES = YYESA or *YYES points to an
   array allocated with YYSTACK_ALLOC.  yy_lac may overwrite the
   contents of either array, alter *YYES and *YYES_CAPACITY, and free
   any old *YYES other than YYESA.  */
unsafe extern "C" fn yy_lac(mut yyesa: *mut i16, mut yyes: *mut *mut i16, mut yyes_capacity: *mut i64, mut yyssp: *mut i16, mut yytoken: yysymbol_kind_t) -> i32 {
    let mut yyes_prev: *mut i16 = yyssp;
    let mut yyesp: *mut i16 = yyes_prev;
    /* Reduce until we encounter a shift and thereby accept the token.  */
    {
        if nft_debug != 0 {
            unsafe { fprintf(stderr, c"LAC: checking lookahead %s:".as_ptr(), unsafe { yysymbol_name(yytoken) }) };
        }
    }
    if yytoken == YYSYMBOL_YYUNDEF {
        {
            if nft_debug != 0 {
                unsafe { fprintf(stderr, c" Always Err\n".as_ptr()) };
            }
        }
        return 1;
    }
    loop {
        let mut yyrule: i32 = (yypact[*yyesp as usize]) as i32;
        if (((yyrule == YYPACT_NINF) || (({ yyrule += ((yytoken) as i32); yyrule }) < 0)) || (YYLAST < yyrule)) || (((yycheck[yyrule as usize]) as i32) != yytoken) {
            /* Use the default action.  */
            yyrule = (yydefact[*yyesp as usize]) as i32;
            if yyrule == 0 {
                {
                    if nft_debug != 0 {
                        unsafe { fprintf(stderr, c" Err\n".as_ptr()) };
                    }
                }
                return 1;
            }
        } else {
            /* Use the action from yytable.  */
            yyrule = (yytable[yyrule as usize]) as i32;
            if 0 < yyrule {
                {
                    if nft_debug != 0 {
                        unsafe { fprintf(stderr, c" S%d\n".as_ptr(), yyrule) };
                    }
                }
                return 0;
            }
            yyrule = -yyrule;
        }
        /* By now we know we have to simulate a reduce.  */
        {
            if nft_debug != 0 {
                unsafe { fprintf(stderr, c" R%d".as_ptr(), (yyrule - 1)) };
            }
        }
        {
            /* Pop the corresponding number of values from the stack.  */
            let mut yylen: i64 = (yyr2[yyrule as usize]) as i64;
            /* First pop from the LAC stack as many tokens as possible.  */
            if yyesp != yyes_prev {
                let mut yysize: i64 = ((yyesp.offset_from((*yyes))) + (1 as isize)) as i64;
                if yylen < yysize {
                    yyesp = yyesp.offset(-(yylen as isize));
                    yylen = 0i64;
                } else {
                    yyesp = yyes_prev;
                    yylen -= yysize;
                }
            }
            /* Only afterwards look at the main stack.  */
            if yylen != 0 {
                yyesp = { yyes_prev = yyes_prev.offset(-(yylen as isize)); yyes_prev };
            }
        }
        /* Push the resulting state of the reduction.  */
        {
            let mut yystate: i32 = 0;
            {
                let mut yylhs: i32 = ((yyr1[yyrule as usize]) as i32) - YYNTOKENS;
                let mut yyi: i32 = ((yypgoto[yylhs as usize]) as i32) + ((*yyesp) as i32);
                yystate = (if (((0 <= yyi) && (yyi <= YYLAST)) && (yycheck[yyi as usize] == (*yyesp))) { (yytable[yyi as usize]) as i32 } else { (yydefgoto[yylhs as usize]) as i32 });
            }
            if yyesp == yyes_prev {
                yyesp = (*yyes);
                (*yyesp) = yystate as i16;
            } else {
                if unsafe { yy_lac_stack_realloc(yyes_capacity, 1i64, c" (".as_ptr(), c")".as_ptr(), yyes, yyesa, &raw mut yyesp, yyes_prev) } != 0 {
                    {
                        if nft_debug != 0 {
                            unsafe { fprintf(stderr, c"\n".as_ptr()) };
                        }
                    }
                    return -2;
                }
                (*{ yyesp = yyesp.offset(1); yyesp }) = yystate as i16;
            }
            {
                if nft_debug != 0 {
                    unsafe { fprintf(stderr, c" G%d".as_ptr(), yystate) };
                }
            }
        }
    }
    unsafe { core::mem::zeroed() }
}

/* Put in YYARG at most YYARGN of the expected tokens given the
   current YYCTX, and return the number of tokens stored in YYARG.  If
   YYARG is null, return the number of expected tokens (guaranteed to
   be less than YYNTOKENS).  Return YYENOMEM on memory exhaustion.
   Return 0 if there are more than YYARGN expected tokens, yet fill
   YYARG up to YYARGN. */
unsafe extern "C" fn yypcontext_expected_tokens(mut yyctx: *const yypcontext_t, mut yyarg: *mut yysymbol_kind_t, mut yyargn: i32) -> i32 {
    /* Actual size of YYARG. */
    let mut yycount: i32 = 0;
    let mut yyx: i32 = 0;
    {
        yyx = 0;
        while yyx < YYNTOKENS {
            'c0: {
                let mut yysym: yysymbol_kind_t = yyx as yysymbol_kind_t;
                if (yysym != YYSYMBOL_YYerror) && (yysym != YYSYMBOL_YYUNDEF) {
                    match unsafe { yy_lac((*yyctx).yyesa, (*yyctx).yyes, (*yyctx).yyes_capacity, (*yyctx).yyssp, yysym) } {
                        YYENOMEM => {
                            return -2;
                        }
                        1 => {
                            break 'c0;
                        }
                        _ => {
                            if yyarg.is_null() {
                                yycount += 1;
                            } else if yycount == yyargn {
                                return 0;
                            } else {
                                (*yyarg.offset(({ let __old = yycount; yycount += 1; __old }) as isize)) = yysym;
                            }
                        }
                    }
                }
            }
            yyx += 1;
        }
    }
    if (!yyarg.is_null() && (yycount == 0)) && (0 < yyargn) {
        (*yyarg.offset(0)) = -2;
    }
    return yycount;
}

/* The kind of the lookahead of this context.  */
unsafe extern "C" fn yypcontext_token(mut yyctx: *const yypcontext_t) -> yysymbol_kind_t {
    return (*yyctx).yytoken;
}

/* The location of the lookahead of this context.  */
unsafe extern "C" fn yypcontext_location(mut yyctx: *const yypcontext_t) -> *mut location {
    return ((*yyctx).yylloc as *mut location);
}

/* User defined function to report a syntax error.  */
unsafe extern "C" fn yyreport_syntax_error(mut yyctx: *const yypcontext_t, mut nft: *mut nft_ctx, mut scanner: *mut core::ffi::c_void, mut state: *mut parser_state) -> i32 {
    let mut bad_token: *const core::ffi::c_char = unsafe { yysymbol_name(unsafe { yypcontext_token(yyctx) }) };
    let mut loc: *mut location = (unsafe { yypcontext_location(yyctx) } as *mut location);
    let mut exp_tokens: *mut yysymbol_kind_t = core::ptr::null_mut();
    let mut exp_tokens_cnt: i32 = 0;
    let mut errbufsz: usize = 0;
    let mut errfp: *mut _IO_FILE = core::ptr::null_mut();
    let mut msg: *mut core::ffi::c_char = core::ptr::null_mut();
    errfp = unsafe { open_memstream((&raw mut msg as *mut *mut core::ffi::c_char), &raw mut errbufsz) };
    if errfp.is_null() {
        unsafe { memory_allocation_error() };
    }
    exp_tokens_cnt = unsafe { yypcontext_expected_tokens(yyctx, core::ptr::null_mut(), 0) };
    exp_tokens = (unsafe { xmalloc_array(exp_tokens_cnt, core::mem::size_of::<yysymbol_kind_t>()) } as *mut yysymbol_kind_t);
    unsafe { yypcontext_expected_tokens(yyctx, exp_tokens, exp_tokens_cnt) };
    unsafe { fprintf(errfp, c"syntax error, unexpected %s\nexpected any of: ".as_ptr(), bad_token) };
    {
        let mut i: i32 = 0;
        while i < exp_tokens_cnt {
            let mut token_name: *const core::ffi::c_char = unsafe { yysymbol_name(*exp_tokens.offset(i as isize)) };
            let mut is_keyword: bool = true;
            /* tokens that name generic things shall be printed as <foo>; detect them */
            match *exp_tokens.offset(i as isize) {
                YYSYMBOL_NUM | YYSYMBOL_STRING | YYSYMBOL_QUOTED_STRING | YYSYMBOL_ASTERISK_STRING => {
                    is_keyword = false;
                }
                _ => {
                }
            }
            if i > 0 {
                unsafe { fputs(c", ".as_ptr(), errfp) };
            }
            if !is_keyword {
                unsafe { fputc(60, errfp) };
            }
            unsafe { fputs(token_name, errfp) };
            if !is_keyword {
                unsafe { fputc(62, errfp) };
            }
            i += 1;
        }
    }
    unsafe { free((exp_tokens as *mut core::ffi::c_void)) };
    unsafe { fclose(errfp) };
    /* no newline on the end of the error message; this is intended */
    unsafe { nft_error(loc, nft, scanner, state, (msg as *const core::ffi::c_char)) };
    unsafe { free((msg as *mut core::ffi::c_void)) };
    return 0;
}

