unsafe extern "C" fn seconds_from_unit(mut unit: *const core::ffi::c_char) -> u64 {
    if !(unsafe { strcmp(unit, c"week".as_ptr()) } != 0) {
        return 604800u64;
    }
    if !(unsafe { strcmp(unit, c"day".as_ptr()) } != 0) {
        return 86400u64;
    }
    if !(unsafe { strcmp(unit, c"hour".as_ptr()) } != 0) {
        return 3600u64;
    }
    if !(unsafe { strcmp(unit, c"minute".as_ptr()) } != 0) {
        return 60u64;
    }
    return 1u64;
}

