// json_echo_error is variadic and its body uses the `va_list` in a way a macro cannot carry; it is declared above
unsafe extern "C" fn handle_from_nlmsg(mut nlh: *const nlmsghdr) -> u64 {
    let mut nlf: *mut nftnl_flowtable = core::ptr::null_mut();
    let mut nlt: *mut nftnl_table = core::ptr::null_mut();
    let mut nlc: *mut nftnl_chain = core::ptr::null_mut();
    let mut nlr: *mut nftnl_rule = core::ptr::null_mut();
    let mut nls: *mut nftnl_set = core::ptr::null_mut();
    let mut nlo: *mut nftnl_obj = core::ptr::null_mut();
    let mut handle: u64 = 0u64;
    let mut flags: u32 = 0;
    match ((*nlh).nlmsg_type as i32) & 255 {
        NFT_MSG_NEWTABLE => {
            nlt = (unsafe { netlink_table_alloc(nlh) } as *mut nftnl_table);
            handle = (unsafe { nftnl_table_get_u64(nlt, NFTNL_TABLE_HANDLE) }) as u64;
            unsafe { nftnl_table_free(nlt) };
        }
        NFT_MSG_NEWCHAIN => {
            nlc = (unsafe { netlink_chain_alloc(nlh) } as *mut nftnl_chain);
            handle = (unsafe { nftnl_chain_get_u64(nlc, NFTNL_CHAIN_HANDLE) }) as u64;
            unsafe { nftnl_chain_free(nlc) };
        }
        NFT_MSG_NEWRULE => {
            nlr = (unsafe { netlink_rule_alloc(nlh) } as *mut nftnl_rule);
            handle = unsafe { nftnl_rule_get_u64((nlr as *const nftnl_rule), 3u16) };
            unsafe { nftnl_rule_free((nlr as *const nftnl_rule)) };
        }
        NFT_MSG_NEWSET => {
            nls = (unsafe { netlink_set_alloc(nlh) } as *mut nftnl_set);
            flags = (unsafe { nftnl_set_get_u32(nls, NFTNL_SET_FLAGS) }) as u32;
            if !(unsafe { set_is_anonymous(flags) } != 0) {
                handle = (unsafe { nftnl_set_get_u64(nls, NFTNL_SET_HANDLE) }) as u64;
            }
            unsafe { nftnl_set_free(nls) };
        }
        NFT_MSG_NEWOBJ => {
            nlo = (unsafe { netlink_obj_alloc(nlh) } as *mut nftnl_obj);
            handle = (unsafe { nftnl_obj_get_u64(nlo, NFTNL_OBJ_HANDLE) }) as u64;
            unsafe { nftnl_obj_free(nlo) };
        }
        NFT_MSG_NEWFLOWTABLE => {
            nlf = (unsafe { netlink_flowtable_alloc(nlh) } as *mut nftnl_flowtable);
            handle = (unsafe { nftnl_flowtable_get_u64(nlf, NFTNL_FLOWTABLE_HANDLE) }) as u64;
            unsafe { nftnl_flowtable_free(nlf) };
        }
        _ => {}
    }
    return handle;
}

