pub unsafe extern "C" fn payload_gen_dependency(mut ctx: *mut eval_ctx, mut expr: *const expr, mut res: *mut *mut stmt) -> i32 {
    let mut h: *const hook_proto_desc = core::ptr::null();
    let mut desc: *const proto_desc = core::ptr::null();
    let mut pctx: *mut proto_ctx = core::ptr::null_mut();
    let mut stmt: *mut stmt = core::ptr::null_mut();
    let mut type_: u16 = 0;
    pctx = (unsafe { eval_proto_ctx(ctx) } as *mut proto_ctx);
    // C (statement): h = & hook_proto_desc [ pctx -> family ] ;
    todo!();
    if (*expr).anon9.payload.base < (*h).base {
        if (*expr).anon9.payload.base < ((*h).base - 1) {
            return unsafe { expr_binary_error(((*ctx).msgs as *mut list_head), expr, core::ptr::null(), c"payload base is invalid for this family".as_ptr()) };
        }
        if (unsafe { proto_dev_type((*expr).anon9.payload.desc, &raw mut type_) }) < 0 {
            return unsafe { expr_binary_error(((*ctx).msgs as *mut list_head), expr, core::ptr::null(), c"protocol specification is invalid for this family".as_ptr()) };
        }
        stmt = unsafe { meta_stmt_meta_iiftype((((&raw const (*expr).location).cast_mut()) as *const location), type_) };
        if (unsafe { stmt_dependency_evaluate(ctx, stmt) }) < 0 {
            return -1;
        }
        (*res) = stmt;
        return 0;
    }
    // C (statement): desc = pctx -> protocol [ expr -> payload . base - 1 ] . desc ;
    todo!();
    /* Special case for mixed IPv4/IPv6 and bridge tables */
    if desc.is_null() {
        desc = unsafe { payload_gen_special_dependency(ctx, expr) };
    }
    if desc.is_null() {
        // C (return): return expr_error ( ctx -> msgs , expr , "ambiguous payload specification: " "no %s protocol specified" , proto_base_names [ expr -> payload . base - 1 ] ) ;
        todo!();
    }
    if ((*pctx).family == NFPROTO_BRIDGE) && (desc == ((&raw const proto_eth).cast_mut())) {
        /* prefer netdev proto, which adds dependencies based
    		 * on skb->protocol.
    		 *
    		 * This has the advantage that we will also match
    		 * vlan encapsulated traffic.
    		 *
    		 * eth_hdr(skb)->type would not match, as nft_payload
    		 * will pretend vlan tag was not offloaded, i.e.
    		 * type is ETH_P_8021Q in such a case, but skb->protocol
    		 * would still match the l3 header type.
    		 */
        if ((*expr).anon9.payload.desc == ((&raw const proto_ip).cast_mut())) || ((*expr).anon9.payload.desc == ((&raw const proto_ip6).cast_mut())) {
            desc = (((&raw const proto_netdev).cast_mut()) as *const proto_desc);
        }
    }
    return unsafe { payload_add_dependency(ctx, desc, (*expr).anon9.payload.desc, expr, res) };
}

