/**
 * payload_is_stacked - return whether a payload protocol match defines a stacked
 * 			protocol on the same layer
 *
 * @desc: current protocol description on this layer
 * @expr: payload match
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn payload_is_stacked(mut desc: *const proto_desc, mut expr: *const expr) -> bool {
    let mut next: *const proto_desc = core::ptr::null();
    if (((*(*expr).anon9.anon12.left).etype() != EXPR_PAYLOAD) || !(((*(*expr).anon9.anon12.left).flags & (EXPR_F_PROTOCOL as u32)) != 0)) || ((*expr).op() != OP_EQ) {
        return false;
    }
    next = (unsafe { proto_find_upper(desc, (unsafe { mpz_get_be16((*(*expr).anon9.anon12.right).anon9.anon3.value) } as i32)) } as *const proto_desc);
    return ((!next.is_null() && ((*next).base == (*desc).base)) as i32) != 0;
}

