#[unsafe(no_mangle)]
pub unsafe extern "C" fn payload_dependency_store(mut ctx: *mut payload_dep_ctx, mut stmt: *mut stmt, mut base: proto_bases) {
    let mut ignore_dep: bool = unsafe { payload_dependency_store_icmp_type(ctx, (stmt as *const stmt)) };
    if ignore_dep {
        return;
    }
    (*(*ctx).pdeps.offset((base + 1) as isize)) = stmt;
}

/**
 * payload_dependency_exists - there is a payload dependency in place
 * @ctx: payload dependency context
 * @base: payload protocol base
 *
 * Check if we have seen a protocol key payload expression for this base, we can
 * usually remove it if we can infer it from another payload expression in the
 * upper base.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn payload_dependency_exists(mut ctx: *const payload_dep_ctx, mut base: proto_bases) -> bool {
    if !(*(*ctx).pdeps.offset(base as isize)).is_null() {
        return true;
    }
    return (((base == PROTO_BASE_TRANSPORT_HDR) && !(*(*ctx).pdeps.offset(PROTO_BASE_INNER_HDR as isize)).is_null()) as i32) != 0;
}

/**
 * payload_dependency_get - return a payload dependency if available
 * @ctx: payload dependency context
 * @base: payload protocol base
 *
 * If we have seen a protocol key payload expression for this base, we return
 * it.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn payload_dependency_get(mut ctx: *mut payload_dep_ctx, mut base: proto_bases) -> *mut expr {
    if !(*(*ctx).pdeps.offset(base as isize)).is_null() {
        return (*(*(*ctx).pdeps.offset(base as isize))).anon4.expr;
    }
    if (base == PROTO_BASE_TRANSPORT_HDR) && !(*(*ctx).pdeps.offset(PROTO_BASE_INNER_HDR as isize)).is_null() {
        return (*(*(*ctx).pdeps.offset(PROTO_BASE_INNER_HDR as isize))).anon4.expr;
    }
    return core::ptr::null_mut();
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn payload_dependency_release(mut ctx: *mut payload_dep_ctx, mut base: proto_bases) {
    if !(*(*ctx).pdeps.offset(base as isize)).is_null() {
        unsafe { __payload_dependency_release(ctx, base) };
    } else if (base == PROTO_BASE_TRANSPORT_HDR) && !(*(*ctx).pdeps.offset(PROTO_BASE_INNER_HDR as isize)).is_null() {
        unsafe { __payload_dependency_release(ctx, PROTO_BASE_INNER_HDR) };
    }
}

/**
 * payload_dependency_kill - kill a redundant payload dependency
 *
 * @ctx: payload dependency context
 * @expr: higher layer payload expression
 *
 * Kill a redundant payload expression if a higher layer payload expression
 * implies its existence. Skip this if the dependency is a network payload and
 * we are in bridge, netdev and inet families.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn payload_dependency_kill(mut ctx: *mut payload_dep_ctx, mut expr: *mut expr, mut family: u32) {
    if (((*expr).anon9.payload.desc != ((&raw const proto_unknown).cast_mut())) && unsafe { payload_dependency_exists((ctx as *const payload_dep_ctx), (*expr).anon9.payload.base) }) && unsafe { payload_may_dependency_kill(ctx, family, expr) } {
        unsafe { payload_dependency_release(ctx, (*expr).anon9.payload.base) };
    }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn exthdr_dependency_kill(mut ctx: *mut payload_dep_ctx, mut expr: *mut expr, mut family: u32) {
    match (*expr).anon9.exthdr.op {
        NFT_EXTHDR_OP_TCPOPT => {
            if unsafe { payload_dependency_exists((ctx as *const payload_dep_ctx), PROTO_BASE_TRANSPORT_HDR) } {
                unsafe { payload_dependency_release(ctx, PROTO_BASE_TRANSPORT_HDR) };
            }
        }
        NFT_EXTHDR_OP_IPV6 => {
            if unsafe { payload_dependency_exists((ctx as *const payload_dep_ctx), PROTO_BASE_NETWORK_HDR) } {
                unsafe { payload_dependency_release(ctx, PROTO_BASE_NETWORK_HDR) };
            }
        }
        NFT_EXTHDR_OP_IPV4 => {
            if unsafe { payload_dependency_exists((ctx as *const payload_dep_ctx), PROTO_BASE_NETWORK_HDR) } {
                unsafe { payload_dependency_release(ctx, PROTO_BASE_NETWORK_HDR) };
            }
        }
        _ => {
        }
    }
}

/**
 * payload_can_merge - return whether two payload expressions can be merged
 *
 * @e1:		first payload expression
 * @e2:		second payload expression
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn payload_can_merge(mut e1: *const expr, mut e2: *const expr) -> bool {
    let mut total: u32 = 0;
    if (*e1).anon9.payload.inner_desc != (*e2).anon9.payload.inner_desc {
        return false;
    }
    if !unsafe { payload_is_adjacent(e1, e2) } {
        return false;
    }
    if (((((*e1).anon9.payload.offset % BITS_PER_BYTE) != 0) || (((*e1).len % BITS_PER_BYTE) != 0)) || (((*e2).anon9.payload.offset % BITS_PER_BYTE) != 0)) || (((*e2).len % BITS_PER_BYTE) != 0) {
        return false;
    }
    total = (*e1).len + (*e2).len;
    if (total < (*e1).len) || (total > (NFT_REG_SIZE * BITS_PER_BYTE)) {
        return false;
    }
    /* could return true after this, the expressions are mergeable.
    	 *
    	 * However, there are some caveats.
    	 *
    	 * Loading anything <= sizeof(u32) with base >= network header
    	 * is fast, because its handled directly from eval loop in the
    	 * kernel.
    	 *
    	 * We thus restrict merging a bit more.
    	 */
    /* can still be handled by fastpath after merge */
    if total <= (NFT_REG32_SIZE * BITS_PER_BYTE) {
        return true;
    }
    /* Linklayer base is not handled in fastpath, merge */
    if (*e1).anon9.payload.base == PROTO_BASE_LL_HDR {
        return true;
    }
    /* Also merge if at least one expression is already
    	 * above REG32 size, in this case merging is faster.
    	 */
    if ((*e1).len > (NFT_REG32_SIZE * BITS_PER_BYTE)) || ((*e2).len > (NFT_REG32_SIZE * BITS_PER_BYTE)) {
        return true;
    }
    return false;
}

/**
 * payload_expr_join - join two adjacent payload expressions
 *
 * @e1:		first payload expression
 * @e2:		second payload expression
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn payload_expr_join(mut e1: *const expr, mut e2: *const expr) -> *mut expr {
    let mut expr: *mut expr = core::ptr::null_mut();
    assert!(unsafe { payload_is_adjacent(e1, e2) });
    expr = unsafe { payload_expr_alloc((((&raw const internal_location).cast_mut()) as *const location), core::ptr::null(), 0u32) };
    (*expr).anon9.payload.base = (*e1).anon9.payload.base;
    (*expr).anon9.payload.offset = (*e1).anon9.payload.offset;
    (*expr).len = (*e1).len + (*e2).len;
    (*expr).anon9.payload.inner_desc = (*e1).anon9.payload.inner_desc;
    return expr;
}

