// ######## /home/matt/.c2r/tree/nftables/src/print.c

/// `nft_print` is variadic: its body is a macro, because Rust cannot define one as a function.
macro_rules! nft_print {
    ($octx:expr, $fmt:expr $(, $__va:expr)*) => {
        {
            '__va: {
                let mut octx: *mut output_ctx = $octx;
                let mut fmt: *const core::ffi::c_char = $fmt;
                let mut ret: i32 = 0;
                // va_start
                ret = unsafe { fprintf((*octx).anon2.output_fp, fmt $(, $__va)*) };
                // va_end
                unsafe { fflush((*octx).anon2.output_fp) };
                break '__va ret;
            }
        }
    }
}

