#[unsafe(no_mangle)]
pub unsafe extern "C" fn get_signalfd() -> i32 {
    let mut mask: __sigset_t = unsafe { core::mem::zeroed() };
    let mut fd: i32 = 0;
    unsafe { sigemptyset(&raw mut mask) };
    unsafe { sigaddset(&raw mut mask, 15) };
    unsafe { sigaddset(&raw mut mask, 2) };
    fd = unsafe { signalfd(-1, (&raw mut mask as *const __sigset_t), 0) };
    if fd < 0 {
        unsafe { perror(c"signalfd()".as_ptr()) };
        return fd;
    }
    if (unsafe { sigprocmask(0, (&raw mut mask as *const __sigset_t), core::ptr::null_mut()) }) < 0 {
        unsafe { perror(c"sigprocmask()".as_ptr()) };
        unsafe { close(fd) };
        return -1;
    }
    return fd;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn check_signalfd(mut fd: i32) {
    let mut info: signalfd_siginfo = unsafe { core::mem::zeroed() };
    if (unsafe { read(fd, (&raw mut info as *mut core::ffi::c_void), core::mem::size_of::<signalfd_siginfo>()) }) < ((core::mem::size_of::<signalfd_siginfo>() as i32) as isize) {
        return;
    }
    {
        let __sw = (info.ssi_signo) as i64;
        let mut __ft = false;
        if __ft || __sw == (15 as i64) {
            __ft = true;
            unsafe { exit(143) };
        }
        if __ft || __sw == (2 as i64) {
            __ft = true;
            unsafe { exit(130) };
        }
        let _ = __ft;
    }
}

