unsafe extern "C" fn std_prio_family_hook_compat(mut prio: i32, mut family: i32, mut hook: i32) -> bool {
    /* bridge family has different values */
    if family == NFPROTO_BRIDGE {
        match prio {
            NF_BR_PRI_NAT_DST_BRIDGED => {
                if hook == NF_BR_PRE_ROUTING {
                    return true;
                }
            }
            NF_BR_PRI_FILTER_BRIDGED => {
                return true;
            }
            NF_BR_PRI_NAT_DST_OTHER => {
                if hook == NF_BR_LOCAL_OUT {
                    return true;
                }
            }
            NF_BR_PRI_NAT_SRC => {
                if hook == NF_BR_POST_ROUTING {
                    return true;
                }
            }
            _ => {}
        }
        return false;
    }
    match prio {
        NF_IP_PRI_FILTER => {
            match family {
                NFPROTO_INET | NFPROTO_IPV4 | NFPROTO_IPV6 | NFPROTO_ARP | NFPROTO_NETDEV => {
                    return true;
                }
                _ => {}
            }
        }
        NF_IP_PRI_RAW | NF_IP_PRI_MANGLE | NF_IP_PRI_SECURITY => {
            match family {
                NFPROTO_INET | NFPROTO_IPV4 | NFPROTO_IPV6 => {
                    return true;
                }
                _ => {}
            }
        }
        NF_IP_PRI_NAT_DST => {
            match family {
                NFPROTO_INET | NFPROTO_IPV4 | NFPROTO_IPV6 => {
                    if (hook == NF_INET_PRE_ROUTING) || (hook == NF_INET_LOCAL_OUT) {
                        return true;
                    }
                }
                _ => {}
            }
        }
        NF_IP_PRI_NAT_SRC => {
            match family {
                NFPROTO_INET | NFPROTO_IPV4 | NFPROTO_IPV6 => {
                    if (hook == NF_INET_LOCAL_IN) || (hook == NF_INET_POST_ROUTING) {
                        return true;
                    }
                }
                _ => {}
            }
        }
        _ => {}
    }
    return false;
}

