    unsafe { scope_release((&raw mut (*table).scope as *const scope)) };
    unsafe { cache_free((&raw mut (*table).chain_cache as *mut cache)) };
    unsafe { cache_free((&raw mut (*table).set_cache as *mut cache)) };
    unsafe { cache_free((&raw mut (*table).obj_cache as *mut cache)) };
