#[unsafe(no_mangle)]
pub unsafe extern "C" fn cmd_free(mut cmd: *mut cmd) {
    if cmd.is_null() {
        return;
    }
    unsafe { handle_free((&raw mut (*cmd).handle as *mut handle)) };
    if !(*cmd).data.is_null() {
        match (*cmd).obj {
            _ => {
                unsafe { BUG(c"invalid command object type %u".as_ptr(), (*cmd).obj) };
            }
        }
    }
    unsafe { free(((*cmd).attr as *mut core::ffi::c_void)) };
    unsafe { free(((*cmd).arg as *mut core::ffi::c_void)) };
    unsafe { free((cmd as *mut core::ffi::c_void)) };
}

unsafe extern "C" fn __do_add_elements(mut ctx: *mut netlink_ctx, mut cmd: *mut cmd, mut set: *mut set, mut expr: *mut expr, mut flags: u32) -> i32 {
    // C (statement): ( assert ( ( expr ) -> etype == EXPR_SET ) , & ( expr ) -> expr_set ) -> set_flags |= set -> flags ;
    todo!();
    if (unsafe { mnl_nft_setelem_add(ctx, cmd, (set as *const set), (expr as *const expr), flags) }) < 0 {
        return -1;
    }
    return 0;
}

unsafe extern "C" fn do_add_elements(mut ctx: *mut netlink_ctx, mut cmd: *mut cmd, mut flags: u32) -> i32 {
    let mut init: *mut expr = ((*cmd).expr as *mut expr);
    let mut set: *mut set = ((*cmd).elem.set as *mut set);
    if (unsafe { set_is_non_concat_range(set) } != 0) && ((unsafe { set_to_intervals((set as *const set), init, true) }) < 0) {
        return -1;
    }
    return unsafe { __do_add_elements(ctx, cmd, set, init, flags) };
}

unsafe extern "C" fn do_add_setelems(mut ctx: *mut netlink_ctx, mut cmd: *mut cmd, mut flags: u32) -> i32 {
    let mut set: *mut set = ((*cmd).set as *mut set);
    if !((*set).init != 0) {
        return 0;
    }
    return unsafe { __do_add_elements(ctx, cmd, set, ((*set).init as *mut expr), flags) };
}

unsafe extern "C" fn do_add_set(mut ctx: *mut netlink_ctx, mut cmd: *mut cmd, mut flags: u32) -> i32 {
    let mut set: *mut set = ((*cmd).set as *mut set);
    if !(*set).init.is_null() {
        /* Update set->init->size (NFTNL_SET_DESC_SIZE) before adding
    		 * the set to the kernel. Calling this from do_add_setelems()
    		 * comes too late which might result in spurious ENFILE errors.
    		 */
        if (unsafe { set_is_non_concat_range(set) } != 0) && ((unsafe { set_to_intervals((set as *const set), ((*set).init as *mut expr), true) }) < 0) {
            return -1;
        }
    }
    if (unsafe { mnl_nft_set_add(ctx, cmd, flags) }) < 0 {
        return -1;
    }
    if unsafe { set_is_anonymous((*set).flags) } != 0 {
        return unsafe { __do_add_elements(ctx, cmd, set, ((*set).init as *mut expr), flags) };
    }
    return 0;
}

unsafe extern "C" fn do_command_add(mut ctx: *mut netlink_ctx, mut cmd: *mut cmd, mut excl: bool) -> i32 {
    let mut flags: u32 = (if excl { 512u32 } else { 0u32 });
    if unsafe { nft_output_echo((((&raw const (*(*ctx).nft).output).cast_mut()) as *const output_ctx)) } {
        flags |= ((NLM_F_ECHO) as u32);
    }
    match (*cmd).obj {
        _ => {
            unsafe { BUG(c"invalid command object type %u".as_ptr(), (*cmd).obj) };
        }
    }
    return 0;
}

