unsafe extern "C" fn do_delete_setelems(mut ctx: *mut netlink_ctx, mut cmd: *mut cmd) -> i32 {
    let mut set: *const set = ((*cmd).elem.set as *const set);
    let mut expr: *mut expr = ((*cmd).elem.expr as *mut expr);
    if (unsafe { set_is_non_concat_range(set) } != 0) && ((unsafe { set_to_intervals(set, expr, false) }) < 0) {
        return -1;
    }
    if (unsafe { mnl_nft_setelem_del(ctx, cmd, (&raw mut (*cmd).handle as *const handle), set, ((*cmd).elem.expr as *const expr)) }) < 0 {
        return -1;
    }
    return 0;
}

unsafe extern "C" fn do_command_delete(mut ctx: *mut netlink_ctx, mut cmd: *mut cmd) -> i32 {
    match (*cmd).obj {
        _ => {
            unsafe { BUG(c"invalid command object type %u".as_ptr(), (*cmd).obj) };
        }
    }
    unsafe { core::mem::zeroed() }
}

