#[unsafe(no_mangle)]
pub unsafe extern "C" fn obj_alloc(mut loc: *const location) -> *mut obj {
    let mut obj: *mut obj = core::ptr::null_mut();
    assert!(!loc.is_null());
    obj = (unsafe { xzalloc(core::mem::size_of::<obj>()) } as *mut obj);
    (*obj).location = (*loc);
    (*obj).refcnt = 1;
    return obj;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn obj_get(mut obj: *mut obj) -> *mut obj {
    unsafe { assert_refcount_safe((*obj).refcnt) };
    (*obj).refcnt += 1;
    return obj;
}

