#[unsafe(no_mangle)]
pub unsafe extern "C" fn cmd_alloc_obj_ct(mut op: cmd_ops, mut type_: i32, mut h: *const handle, mut loc: *const location, mut obj: *mut obj) -> *mut cmd {
    let mut cmd_obj: cmd_obj = unsafe { core::mem::zeroed() };
    if !obj.is_null() {
        (*obj).type_ = type_;
    }
    match type_ {
        3 => {
            cmd_obj = CMD_OBJ_CT_HELPER;
        }
        7 => {
            cmd_obj = CMD_OBJ_CT_TIMEOUT;
        }
        9 => {
            cmd_obj = CMD_OBJ_CT_EXPECT;
        }
        _ => {
            unsafe { BUG(c"missing type mapping".as_ptr()) };
        }
    }
    return unsafe { cmd_alloc(op, cmd_obj, h, loc, (obj as *mut core::ffi::c_void)) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn do_command(mut ctx: *mut netlink_ctx, mut cmd: *mut cmd) -> i32 {
    match (*cmd).op {
        _ => {
            unsafe { BUG(c"invalid command object type %u".as_ptr(), (*cmd).obj) };
        }
    }
    unsafe { core::mem::zeroed() }
}

unsafe extern "C" fn payload_match_stmt_cmp(mut p1: *const core::ffi::c_void, mut p2: *const core::ffi::c_void) -> i32 {
    let mut s1: *const stmt = (*(p1 as *mut *const stmt));
    let mut s2: *const stmt = (*(p2 as *mut *const stmt));
    let mut e1: *const expr = ((*s1).anon4.expr as *const expr);
    let mut e2: *const expr = ((*s2).anon4.expr as *const expr);
    let mut d: i32 = 0;
    d = ((*(*e1).anon9.anon12.left).anon9.payload.base - (*(*e2).anon9.anon12.left).anon9.payload.base) as i32;
    if d != 0 {
        return d;
    }
    return ((*(*e1).anon9.anon12.left).anon9.payload.offset - (*(*e2).anon9.anon12.left).anon9.payload.offset) as i32;
}

unsafe extern "C" fn relational_ops_match(mut e1: *const expr, mut e2: *const expr) -> bool {
    let mut op1: ops = unsafe { core::mem::zeroed() };
    let mut op2: ops = unsafe { core::mem::zeroed() };
    op1 = (if ((*e1).op() == OP_IMPLICIT) { 9 } else { (*e1).op() });
    op2 = (if ((*e2).op() == OP_IMPLICIT) { 9 } else { (*e2).op() });
    return ((op1 == op2) as i32) != 0;
}

unsafe extern "C" fn payload_do_merge(mut sa: *mut *mut stmt, mut n: u32) {
    let mut last: *mut expr = core::ptr::null_mut();
    let mut this: *mut expr = core::ptr::null_mut();
    let mut expr1: *mut expr = core::ptr::null_mut();
    let mut expr2: *mut expr = core::ptr::null_mut();
    let mut stmt: *mut stmt = core::ptr::null_mut();
    let mut i: u32 = 0;
    let mut j: u32 = 0;
    unsafe { qsort((sa as *mut core::ffi::c_void), n as usize, core::mem::size_of::<*mut stmt>(), Some(payload_match_stmt_cmp)) };
    last = (*(*sa.offset(0))).anon4.expr;
    {
        j = 0u32; i = 1u32;
        while i < n {
            'c0: {
                stmt = (*sa.offset(i as isize));
                this = (*stmt).anon4.expr;
                if !unsafe { payload_can_merge(((*last).anon9.anon12.left as *const expr), ((*this).anon9.anon12.left as *const expr)) } || !unsafe { relational_ops_match((last as *const expr), (this as *const expr)) } {
                    last = this;
                    j = i;
                    break 'c0;
                }
                expr1 = unsafe { payload_expr_join(((*last).anon9.anon12.left as *const expr), ((*this).anon9.anon12.left as *const expr)) };
                expr2 = unsafe { constant_expr_join(((*last).anon9.anon12.right as *const expr), ((*this).anon9.anon12.right as *const expr)) };
                /* We can merge last into this, but we can't replace
                		 * the statement associated with this if it does contain
                		 * a higher level protocol.
                		 *
                		 * ether type ip ip saddr X ether saddr Y
                		 * ... can be changed to
                		 * ether type ip ether saddr Y ip saddr X
                		 * ... but not
                		 * ip saddr X ether type ip ether saddr Y
                		 *
                		 * The latter form means we perform ip saddr test before
                		 * ensuring ip dependency, plus it makes decoding harder
                		 * since we don't know the type of the network header
                		 * right away.
                		 *
                		 * So, if we're about to replace a statement
                		 * containing a protocol identifier, just swap this and last
                		 * and replace the other one (i.e., replace 'load ether type ip'
                		 * with the combined 'load both ether type and saddr') and not
                		 * the other way around.
                		 */
                if ((*(*this).anon9.anon12.left).flags & (EXPR_F_PROTOCOL as u32)) != 0 {
                    let mut tmp: *mut expr = last;
                    last = this;
                    this = tmp;
                    (*expr1).flags |= ((EXPR_F_PROTOCOL) as u32);
                    stmt = (*sa.offset(j as isize));
                    assert!((*stmt).anon4.expr == this);
                    j = i;
                }
                unsafe { expr_free((*last).anon9.anon12.left) };
                (*last).anon9.anon12.left = expr1;
                unsafe { expr_free((*last).anon9.anon12.right) };
                (*last).anon9.anon12.right = expr2;
                unsafe { list_del(&raw mut (*stmt).list) };
                unsafe { stmt_free(stmt) };
            }
            i += 1;
        }
    }
}

/**
 * stmt_reduce - reduce statements in rule
 *
 * @rule:	nftables rule
 *
 * This function aims to:
 *
 * - remove redundant statement, e.g. remove 'meta protocol ip' if family is ip
 * - merge consecutive payload match statements
 *
 * Locate sequences of payload match statements referring to adjacent
 * header locations and merge those using only equality relations.
 *
 * As a side-effect, payload match statements are ordered in ascending
 * order according to the location of the payload.
 */
unsafe extern "C" fn stmt_reduce(mut rule: *const rule) {
    let mut stmt: *mut stmt = core::ptr::null_mut();
    let mut dstmt: *mut stmt = core::ptr::null_mut();
    let mut next: *mut stmt = core::ptr::null_mut();
    let mut stmt: *mut stmt = core::ptr::null_mut();
    let mut idx: u32 = 0u32;
    {
        // C (statement): stmt = list_entry ( ( & rule -> stmts ) -> next , typeof ( * stmt ) , list ) , next = list_entry ( stmt -> list . next , typeof ( * stmt ) , list ) ;
        todo!();
        while &raw mut (*stmt).list != ((&raw const (*rule).stmts).cast_mut()) {
            'c0: {
                /* delete this redundant statement */
                if !dstmt.is_null() {
                    unsafe { list_del(&raw mut (*dstmt).list) };
                    unsafe { stmt_free(dstmt) };
                    dstmt = core::ptr::null_mut();
                }
                /* Must not merge across other statements */
                if (*stmt).type_() != STMT_EXPRESSION {
                    if idx >= (2 as u32) {
                        unsafe { payload_do_merge(sa, idx) };
                    }
                    idx = 0u32;
                    break 'c0;
                }
                if (*(*stmt).anon4.expr).etype() != EXPR_RELATIONAL {
                    break 'c0;
                }
                if (*(*(*stmt).anon4.expr).anon9.anon12.right).etype() != EXPR_VALUE {
                    break 'c0;
                }
                if (*(*(*stmt).anon4.expr).anon9.anon12.left).etype() == EXPR_PAYLOAD {
                    match (*(*stmt).anon4.expr).op() {
                        OP_EQ | OP_IMPLICIT => {
                        }
                        _ => {
                            break 'c0;
                        }
                    }
                    (*sa.offset(({ let __old = idx; idx += 1; __old }) as isize)) = stmt;
                } else if (*(*(*stmt).anon4.expr).anon9.anon12.left).etype() == EXPR_META {
                    match (*(*stmt).anon4.expr).op() {
                        OP_EQ | OP_IMPLICIT => {
                            if ((*(*(*stmt).anon4.expr).anon9.anon12.left).anon9.meta.key == NFT_META_PROTOCOL) && !!(*(*(*stmt).anon4.expr).anon9.anon12.left).anon9.meta.inner_desc.is_null() {
                                let mut protocol: u16 = 0;
                                protocol = unsafe { mpz_get_uint16((*(*(*stmt).anon4.expr).anon9.anon12.right).anon9.anon3.value) };
                                if (((*rule).handle.family == NFPROTO_IPV4) && ((protocol as i32) == ETH_P_IP)) || (((*rule).handle.family == NFPROTO_IPV6) && ((protocol as i32) == ETH_P_IPV6)) {
                                    dstmt = stmt;
                                }
                            }
                        }
                        _ => {
                        }
                    }
                }
            }
            // C (for step): stmt = next , next = list_entry ( next -> list . next , typeof ( * next ) , list )
            todo!();
        }
    }
    if idx > (1 as u32) {
        unsafe { payload_do_merge(sa, idx) };
    }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn rule_postprocess(mut rule: *mut rule) -> *mut error_record {
    unsafe { stmt_reduce((rule as *const rule)) };
    return core::ptr::null_mut();
}

