/* %if-c-only */
unsafe extern "C" fn yy_fatal_error(mut msg: *const core::ffi::c_char, mut yyscanner: *mut core::ffi::c_void) {
    let mut yyg: *mut yyguts_t = (yyscanner as *mut yyguts_t);
    let _ = yyg;
    unsafe { fprintf(stderr, c"%s\n".as_ptr(), msg) };
    unsafe { exit(2) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn scanner_init(mut state: *mut parser_state) -> *mut core::ffi::c_void {
    let mut scanner: *mut core::ffi::c_void = core::ptr::null_mut();
    unsafe { nft_lex_init_extra((state as *mut core::ffi::c_void), &raw mut scanner) };
    unsafe { nft_set_out(core::ptr::null_mut(), scanner) };
    (*state).startcond_active = (unsafe { xzalloc_array(__SC_MAX, core::mem::size_of::<u32>()) } as *mut u32);
    return scanner;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn scanner_destroy(mut nft: *mut nft_ctx) {
    let mut state: *mut parser_state = (unsafe { nft_get_extra((*nft).scanner) } as *mut parser_state);
    unsafe { input_descriptor_list_destroy(state) };
    unsafe { free(((*state).startcond_active as *mut core::ffi::c_void)) };
    unsafe { nft_lex_destroy((*nft).scanner) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn scanner_read_file(mut nft: *mut nft_ctx, mut filename: *const core::ffi::c_char, mut loc: *const location) -> i32 {
    return unsafe { include_file(nft, (*nft).scanner, filename, loc, core::ptr::null(), 1) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn scanner_include_file(mut nft: *mut nft_ctx, mut scanner: *mut core::ffi::c_void, mut filename: *const core::ffi::c_char, mut loc: *const location) -> i32 {
    let mut state: *mut parser_state = (unsafe { nft_get_extra(scanner) } as *mut parser_state);
    let mut erec: *mut error_record = core::ptr::null_mut();
    let mut i: u32 = 0;
    let mut ret: i32 = -1;
    if unsafe { search_in_include_path(filename) } {
        {
            i = 0u32;
            while i < (*nft).num_include_paths {
                ret = unsafe { include_path_glob(nft, scanner, ((*(*nft).include_paths.offset(i as isize)) as *const core::ffi::c_char), filename, loc) };
                if ret <= 0 {
                    return ret;
                }
                i += 1;
            }
        }
        ret = unsafe { include_path_glob(nft, scanner, (DEFAULT_INCLUDE_PATH as *const core::ffi::c_char), filename, loc) };
        if ret <= 0 {
            return ret;
        }
    } else {
        /* an absolute path (starts with '/') */
        ret = unsafe { include_glob(nft, scanner, filename, loc) };
    }
    /* handle the case where no file was found */
    if ret == -1 {
        return -1;
    } else if (ret == 0) || (ret == 2) {
        return 0;
    }
    /* 1 means an error, because there are no more include directories to
    	 * search, and the pattern does not have wildcard characters.
    	 */
    erec = unsafe { erec_create(2, loc, c"File not found: %s".as_ptr(), filename) };
    unsafe { erec_queue(erec, (*state).msgs) };
    return -1;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn scanner_push_buffer(mut scanner: *mut core::ffi::c_void, mut indesc: *const input_descriptor, mut buffer: *const core::ffi::c_char) {
    let mut state: *mut parser_state = (unsafe { nft_get_extra(scanner) } as *mut parser_state);
    let mut new_indesc: *mut input_descriptor = core::ptr::null_mut();
    let mut b: *mut yy_buffer_state = core::ptr::null_mut();
    new_indesc = (unsafe { xzalloc(core::mem::size_of::<input_descriptor>()) } as *mut input_descriptor);
    unsafe { memcpy((new_indesc as *mut core::ffi::c_void), (indesc as *const core::ffi::c_void), core::mem::size_of::<input_descriptor>()) };
    (*new_indesc).data = buffer;
    (*new_indesc).name = (unsafe { xstrdup((*indesc).name) } as *const core::ffi::c_char);
    unsafe { scanner_push_indesc(state, new_indesc) };
    b = unsafe { nft__scan_string(buffer, scanner) };
    assert!(!b.is_null());
    unsafe { init_pos((*state).indesc) };
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn scanner_pop_start_cond(mut scanner: *mut core::ffi::c_void, mut t: startcond_type) {
    let mut state: *mut parser_state = (unsafe { nft_get_extra(scanner) } as *mut parser_state);
    (*(*state).startcond_active.offset(t as isize)) -= 1;
    if (*state).startcond_type != (t as u32) {
        (*state).flex_state_pop += 1;
        return;
    }
    while (*state).flex_state_pop != 0 {
        (*state).flex_state_pop -= 1;
        (*state).startcond_type = (unsafe { yy_top_state(scanner) }) as u32;
        unsafe { yy_pop_state(scanner) };
        t = (*state).startcond_type as startcond_type;
        if (*(*state).startcond_active.offset(t as isize)) != 0 {
            return;
        }
    }
    (*state).startcond_type = (unsafe { yy_top_state(scanner) }) as u32;
    unsafe { yy_pop_state(scanner) };
}

unsafe extern "C" fn scanner_pop_buffer(mut scanner: *mut core::ffi::c_void) {
    let mut state: *mut parser_state = (unsafe { nft_get_extra(scanner) } as *mut parser_state);
    unsafe { nft_pop_buffer_state(scanner) };
    unsafe { scanner_pop_indesc(state) };
}

unsafe extern "C" fn init_pos(mut indesc: *mut input_descriptor) {
    (*indesc).lineno = 1u32;
    (*indesc).column = 1u32;
    (*indesc).token_offset = 0i64;
    (*indesc).line_offset = 0i64;
}

unsafe extern "C" fn update_pos(mut state: *mut parser_state, mut loc: *mut location, mut len: i32) {
    (*loc).indesc = ((*state).indesc as *const input_descriptor);
    (*loc).anon1.anon0.first_line = (*(*state).indesc).lineno;
    (*loc).anon1.anon0.first_column = (*(*state).indesc).column;
    (*loc).anon1.anon0.last_column = ((*(*state).indesc).column + (len as u32)) - (1 as u32);
    (*(*state).indesc).column += ((len) as u32);
}

unsafe extern "C" fn update_offset(mut state: *mut parser_state, mut loc: *mut location, mut len: u32) {
    let mut line_offset: u32 = 0;
    (*(*state).indesc).token_offset += ((len) as i64);
    if (*(*state).indesc).line_offset > (u32::MAX as i64) {
        line_offset = 4294967295u32;
    } else {
        line_offset = (*(*state).indesc).line_offset as u32;
    }
    (*loc).anon1.anon0.line_offset = line_offset;
}

unsafe extern "C" fn reset_pos(mut state: *mut parser_state, mut loc: *mut location) {
    (*(*state).indesc).line_offset = (*(*state).indesc).token_offset;
    (*(*state).indesc).lineno += ((1) as u32);
    (*(*state).indesc).column = 1u32;
}

unsafe extern "C" fn scanner_push_start_cond(mut scanner: *mut core::ffi::c_void, mut type_: startcond_type) {
    let mut state: *mut parser_state = (unsafe { nft_get_extra(scanner) } as *mut parser_state);
    (*state).startcond_type = type_ as u32;
    (*(*state).startcond_active.offset(type_ as isize)) += 1;
    unsafe { yy_push_state(type_ as i32, scanner) };
}

/* avoid warnings with -Wmissing-prototypes */
/** Get the current column number.
 * @param yyscanner The scanner object.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nft_get_column(mut yyscanner: *mut core::ffi::c_void) -> i32 {
    let mut yyg: *mut yyguts_t = (yyscanner as *mut yyguts_t);
    if !(if !(*yyg).yy_buffer_stack.is_null() { !(*(*yyg).yy_buffer_stack.offset((*yyg).yy_buffer_stack_top as isize)).is_null() } else { !core::ptr::null_mut().is_null() }) {
        return 0;
    }
    return (*(*(*yyg).yy_buffer_stack.offset((*yyg).yy_buffer_stack_top as isize))).yy_bs_column;
}

/** Set the current column.
 * @param _column_no column number
 * @param yyscanner The scanner object.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nft_set_column(mut _column_no: i32, mut yyscanner: *mut core::ffi::c_void) {
    let mut yyg: *mut yyguts_t = (yyscanner as *mut yyguts_t);
    /* column is only valid if an input buffer exists. */
    if !(if !(*yyg).yy_buffer_stack.is_null() { !(*(*yyg).yy_buffer_stack.offset((*yyg).yy_buffer_stack_top as isize)).is_null() } else { !core::ptr::null_mut().is_null() }) {
        unsafe { yy_fatal_error(c"yyset_column called with no buffer".as_ptr(), yyscanner) };
    }
    (*(*(*yyg).yy_buffer_stack.offset((*yyg).yy_buffer_stack_top as isize))).yy_bs_column = _column_no;
}

/* %if-c-only */
/* %endif if-c-only */
/* %if-c-only */
unsafe extern "C" fn yy_init_globals(mut yyscanner: *mut core::ffi::c_void) -> i32 {
    let mut yyg: *mut yyguts_t = (yyscanner as *mut yyguts_t);
    /* Initialization is the same as for the non-reentrant scanner.
         * This function is called from yylex_destroy(), so don't allocate here.
         */
    (*yyg).yy_buffer_stack = core::ptr::null_mut();
    (*yyg).yy_buffer_stack_top = 0usize;
    (*yyg).yy_buffer_stack_max = 0usize;
    (*yyg).yy_c_buf_p = core::ptr::null_mut();
    (*yyg).yy_init = 0;
    (*yyg).yy_start = 0;
    (*yyg).yy_start_stack_ptr = 0;
    (*yyg).yy_start_stack_depth = 0;
    (*yyg).yy_start_stack = core::ptr::null_mut();
    /* Defined in main.c */
    (*yyg).yyin_r = core::ptr::null_mut();
    (*yyg).yyout_r = core::ptr::null_mut();
    /* For future reference: Set errno on error, since we are called by
         * yylex_init()
         */
    return 0;
}

/* %endif */
/* User-visible API */
/* yylex_init is special because it creates the scanner itself, so it is
 * the ONLY reentrant function that doesn't take the scanner as the last argument.
 * That's why we explicitly handle the declaration, instead of using our macros.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nft_lex_init(mut ptr_yy_globals: *mut *mut core::ffi::c_void) -> i32 {
    if ptr_yy_globals.is_null() {
        (*unsafe { __errno_location() }) = 22;
        return 1;
    }
    (*ptr_yy_globals) = (unsafe { nft_alloc(core::mem::size_of::<yyguts_t>(), core::ptr::null_mut()) } as *mut core::ffi::c_void);
    if (*ptr_yy_globals).is_null() {
        (*unsafe { __errno_location() }) = 12;
        return 1;
    }
    /* By setting to 0xAA, we expose bugs in yy_init_globals. Leave at 0x00 for releases. */
    unsafe { memset((*ptr_yy_globals), 0, core::mem::size_of::<yyguts_t>()) };
    return unsafe { yy_init_globals((*ptr_yy_globals)) };
}

/* yylex_init_extra has the same functionality as yylex_init, but follows the
 * convention of taking the scanner as the last argument. Note however, that
 * this is a *pointer* to a scanner, as it will be allocated by this call (and
 * is the reason, too, why this function also must handle its own declaration).
 * The user defined value in the first argument will be available to yyalloc in
 * the yyextra field.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nft_lex_init_extra(mut yy_user_defined: *mut core::ffi::c_void, mut ptr_yy_globals: *mut *mut core::ffi::c_void) -> i32 {
    let mut dummy_yyguts: yyguts_t = unsafe { core::mem::zeroed() };
    unsafe { nft_set_extra(yy_user_defined, (&raw mut dummy_yyguts as *mut core::ffi::c_void)) };
    if ptr_yy_globals.is_null() {
        (*unsafe { __errno_location() }) = 22;
        return 1;
    }
    (*ptr_yy_globals) = (unsafe { nft_alloc(core::mem::size_of::<yyguts_t>(), (&raw mut dummy_yyguts as *mut core::ffi::c_void)) } as *mut core::ffi::c_void);
    if (*ptr_yy_globals).is_null() {
        (*unsafe { __errno_location() }) = 12;
        return 1;
    }
    /* By setting to 0xAA, we expose bugs in
        yy_init_globals. Leave at 0x00 for releases. */
    unsafe { memset((*ptr_yy_globals), 0, core::mem::size_of::<yyguts_t>()) };
    unsafe { nft_set_extra(yy_user_defined, (*ptr_yy_globals)) };
    return unsafe { yy_init_globals((*ptr_yy_globals)) };
}

/* %endif */
/* %endif End reentrant structures and macros. */
/* Accessor methods to globals.
   These are made visible to non-reentrant scanners for convenience. */
/* %endif */
/* %if-c-only SNIP! this currently causes conflicts with the c++ scanner */
/* yylex_destroy is for both reentrant and non-reentrant scanners. */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nft_lex_destroy(mut yyscanner: *mut core::ffi::c_void) -> i32 {
    let mut yyg: *mut yyguts_t = (yyscanner as *mut yyguts_t);
    /* Pop the buffer stack, destroying each element. */
    while (if !(*yyg).yy_buffer_stack.is_null() { !(*(*yyg).yy_buffer_stack.offset((*yyg).yy_buffer_stack_top as isize)).is_null() } else { !core::ptr::null_mut().is_null() }) {
        unsafe { nft__delete_buffer((if !(*yyg).yy_buffer_stack.is_null() { (*(*yyg).yy_buffer_stack.offset((*yyg).yy_buffer_stack_top as isize)) } else { core::ptr::null_mut() }), yyscanner) };
        (*(*yyg).yy_buffer_stack.offset((*yyg).yy_buffer_stack_top as isize)) = core::ptr::null_mut();
        unsafe { nft_pop_buffer_state(yyscanner) };
    }
    /* Destroy the stack itself. */
    unsafe { nft_free(((*yyg).yy_buffer_stack as *mut core::ffi::c_void), yyscanner) };
    (*yyg).yy_buffer_stack = core::ptr::null_mut();
    /* Destroy the start condition stack. */
    unsafe { nft_free(((*yyg).yy_start_stack as *mut core::ffi::c_void), yyscanner) };
    (*yyg).yy_start_stack = core::ptr::null_mut();
    /* Reset the globals. This is important in a non-reentrant scanner so the next time
         * yylex() is called, initialization will occur. */
    unsafe { yy_init_globals(yyscanner) };
    /* %if-reentrant */
    /* Destroy the main struct (reentrant only). */
    unsafe { nft_free(yyscanner, yyscanner) };
    yyscanner = core::ptr::null_mut();
    /* %endif */
    return 0;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn nft_get_debug(mut yyscanner: *mut core::ffi::c_void) -> i32 {
    let mut yyg: *mut yyguts_t = (yyscanner as *mut yyguts_t);
    return (*yyg).yy_flex_debug_r;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn nft_set_debug(mut _bdebug: i32, mut yyscanner: *mut core::ffi::c_void) {
    let mut yyg: *mut yyguts_t = (yyscanner as *mut yyguts_t);
    (*yyg).yy_flex_debug_r = _bdebug;
}

/* Accessor  methods (get/set functions) to struct members. */
/* %if-c-only */
/* %if-reentrant */
/** Get the user-defined data for this scanner.
 * @param yyscanner The scanner object.
 */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn nft_get_extra(mut yyscanner: *mut core::ffi::c_void) -> *mut core::ffi::c_void {
    let mut yyg: *mut yyguts_t = (yyscanner as *mut yyguts_t);
    return (*yyg).yyextra_r;
}

/* %if-reentrant */
/** Set the user-defined data. This data is never touched by the scanner.
 * @param user_defined The data to be associated with this scanner.
 * @param yyscanner The scanner object.
 */
