unsafe extern "C" fn scanner_push_indesc(mut state: *mut parser_state, mut indesc: *mut input_descriptor) {
    if !!(*state).indesc.is_null() {
        unsafe { list_add_tail(&raw mut (*indesc).list, &raw mut (*state).indesc_list) };
    } else {
        unsafe { list_add(&raw mut (*indesc).list, &raw mut (*(*state).indesc).list) };
    }
    (*state).indesc = indesc;
}

unsafe extern "C" fn scanner_pop_indesc(mut state: *mut parser_state) {
    if !(unsafe { list_is_first((&raw mut (*(*state).indesc).list as *const list_head), (&raw mut (*state).indesc_list as *const list_head)) } != 0) {
        // C (statement): state -> indesc = list_entry ( state -> indesc -> list . prev , struct input_descriptor , list ) ;
        todo!();
    } else {
        (*state).indesc = core::ptr::null_mut();
    }
}

unsafe extern "C" fn scanner_push_file(mut nft: *mut nft_ctx, mut scanner: *mut core::ffi::c_void, mut f: *mut _IO_FILE, mut filename: *const core::ffi::c_char, mut loc: *const location, mut parent_indesc: *const input_descriptor) {
    let mut state: *mut parser_state = (unsafe { nft_get_extra(scanner) } as *mut parser_state);
    let mut indesc: *mut input_descriptor = core::ptr::null_mut();
    let mut b: *mut yy_buffer_state = core::ptr::null_mut();
    b = unsafe { nft__create_buffer(f, 16384, scanner) };
    unsafe { nft_push_buffer_state(b, scanner) };
    indesc = (unsafe { xzalloc(core::mem::size_of::<input_descriptor>()) } as *mut input_descriptor);
    if !loc.is_null() {
        (*indesc).location = *loc;
    }
    (*indesc).type_ = 3;
    (*indesc).name = (unsafe { xstrdup(filename) } as *const core::ffi::c_char);
    (*indesc).f = f;
    if parent_indesc.is_null() {
        (*indesc).depth = 1u32;
    } else {
        (*indesc).depth = (*parent_indesc).depth + (1 as u32);
    }
    unsafe { init_pos(indesc) };
    unsafe { scanner_push_indesc(state, indesc) };
}

unsafe extern "C" fn __is_useable(mut type_: u32, mut t: nft_include_type) -> bool {
    type_ &= ((S_IFMT) as u32);
    match type_ {
        32768 => {
            return true;
        }
        4096 => {
            return ((t == NFT_CMDLINE) as i32) != 0;
        }
        _ => {
        }
    }
    return false;
}

/* need to use stat() to, fopen() will block for named fifos */
unsafe extern "C" fn filename_is_useable(mut name: *const core::ffi::c_char) -> bool {
    let mut sb: stat = unsafe { core::mem::zeroed() };
    let mut err: i32 = 0;
    err = unsafe { stat(name, &raw mut sb) };
    if err != 0 {
        return false;
    }
    return unsafe { __is_useable(sb.st_mode, 0) };
}

unsafe extern "C" fn fp_is_useable(mut fp: *mut _IO_FILE, mut t: nft_include_type) -> bool {
    let mut fd: i32 = unsafe { fileno(fp) };
    let mut sb: stat = unsafe { core::mem::zeroed() };
    let mut err: i32 = 0;
    if fd < 0 {
        return false;
    }
    err = unsafe { fstat(fd, &raw mut sb) };
    if err < 0 {
        return false;
    }
    return unsafe { __is_useable(sb.st_mode, t) };
}

unsafe extern "C" fn include_file(mut nft: *mut nft_ctx, mut scanner: *mut core::ffi::c_void, mut filename: *const core::ffi::c_char, mut loc: *const location, mut parent_indesc: *const input_descriptor, mut includetype: nft_include_type) -> i32 {
    let mut state: *mut parser_state = (unsafe { nft_get_extra(scanner) } as *mut parser_state);
    let mut erec: *mut error_record = core::ptr::null_mut();
    let mut f: *mut _IO_FILE = core::ptr::null_mut();
    'g_err: {
        if !parent_indesc.is_null() && ((*parent_indesc).depth == (MAX_INCLUDE_DEPTH as u32)) {
            erec = unsafe { erec_create(2, loc, c"Include nested too deeply, max %u levels".as_ptr(), MAX_INCLUDE_DEPTH) };
            break 'g_err;
        }
        if (includetype == NFT_INCLUDE) && !unsafe { filename_is_useable(filename) } {
            erec = unsafe { erec_create(2, loc, c"Not a regular file: \"%s\"\n".as_ptr(), filename) };
            break 'g_err;
        }
        f = unsafe { fopen(filename, c"r".as_ptr()) };
        if f.is_null() {
            erec = unsafe { erec_create(2, loc, c"Could not open file \"%s\": %s\n".as_ptr(), filename, unsafe { strerror(*unsafe { __errno_location() }) }) };
            break 'g_err;
        }
        if !unsafe { fp_is_useable(f, includetype) } {
            unsafe { fclose(f) };
            erec = unsafe { erec_create(2, loc, c"Not a regular file: \"%s\"\n".as_ptr(), filename) };
            break 'g_err;
        }
        unsafe { scanner_push_file(nft, scanner, f, filename, loc, parent_indesc) };
        return 0;
    }
    unsafe { erec_queue(erec, (*state).msgs) };
    return -1;
}

unsafe extern "C" fn include_glob(mut nft: *mut nft_ctx, mut scanner: *mut core::ffi::c_void, mut pattern: *const core::ffi::c_char, mut loc: *const location) -> i32 {
    let mut state: *mut parser_state = (unsafe { nft_get_extra(scanner) } as *mut parser_state);
    let mut indesc: *mut input_descriptor = (*state).indesc;
    let mut erec: *mut error_record = core::ptr::null_mut();
    let mut wildcard: bool = false;
    let mut glob_data: glob_t = unsafe { core::mem::zeroed() };
    let mut i: u32 = 0;
    let mut flags: i32 = 0;
    let mut ret: i32 = 0;
    let mut p: *mut core::ffi::c_char = core::ptr::null_mut();
    /* This function can return four meaningful values:
    	 *
    	 *  -1 means that there was an error.
    	 *   0 means that a single non-wildcard match was done.
    	 *   1 means that there are no wildcards in the pattern and the
    	 *     search can continue.
    	 *   2 means that there are wildcards in the pattern and the search
    	 *     can continue.
    	 *
    	 * The diffrence is needed, because there is a semantic difference
    	 * between patterns with wildcards and no wildcards. Not finding a
    	 * non-wildcard file is an error but not finding any matches for a
    	 * wildcard pattern is not.
    	 */
    /* There shouldn't be a need to use escape characters in include paths.
    	 */
    flags |= GLOB_NOESCAPE;
    /* Mark directories so we can filter them out (also links). */
    flags |= GLOB_MARK;
    /* If there is no match, glob() doesn't set GLOB_MAGCHAR even if there
    	 * are wildcard characters in the pattern. We need to look for (luckily
    	 * well-known and not likely to change) magic characters ourselves. In a
    	 * perfect world, we could use glob() itself to figure out if there are
    	 * wildcards in the pattern.
    	 */
    p = (pattern as *mut core::ffi::c_char);
    while (*p) != 0 {
        if ((((*p) as i32) == 42) || (((*p) as i32) == 63)) || (((*p) as i32) == 91) {
            wildcard = true;
            break;
        }
        p = p.offset(1);
    }
    ret = unsafe { glob(pattern, flags, None, &raw mut glob_data) };
    'g_err: {
        if ret == 0 {
            let mut path: *mut core::ffi::c_char = core::ptr::null_mut();
            let mut len: usize = 0;
            /* reverse alphabetical order due to stack */
            {
                i = glob_data.gl_pathc as u32;
                while i > (0 as u32) {
                    'c1: {
                        path = (*glob_data.gl_pathv.offset((i - (1 as u32)) as isize));
                        /* ignore directories */
                        len = unsafe { strlen((path as *const core::ffi::c_char)) };
                        if (len == (0 as usize)) || (((*path.offset((len - (1 as usize)) as isize)) as i32) == 47) {
                            break 'c1;
                        }
                        ret = unsafe { include_file(nft, scanner, (path as *const core::ffi::c_char), loc, (indesc as *const input_descriptor), 0) };
                        if ret != 0 {
                            break 'g_err;
                        }
                    }
                    i -= 1;
                }
            }
            unsafe { globfree(&raw mut glob_data) };
            /* If no wildcards and we found the file, stop the search (with
    		 * 0). In case of wildcards we need to still continue the
    		 * search, because other matches might be in other include
    		 * directories. We handled the case with a non-wildcard pattern
    		 * and no matches already before.
    		 */
            return (if wildcard { 2 } else { 0 });
        } else if ret == GLOB_NOMATCH {
            unsafe { globfree(&raw mut glob_data) };
            /* We need to tell the caller whether wildcards were used in
    		 * case of no match, because the semantics for handling the
    		 * cases are different.
    		 */
            return (if wildcard { 2 } else { 1 });
        }
        erec = unsafe { erec_create(2, loc, c"Failed to glob the pattern %s".as_ptr(), pattern) };
    }
    if !erec.is_null() {
        unsafe { erec_queue(erec, (*state).msgs) };
    }
    unsafe { globfree(&raw mut glob_data) };
    return -1;
}

unsafe extern "C" fn search_in_include_path(mut filename: *const core::ffi::c_char) -> bool {
    return (((((unsafe { strncmp(filename, c"./".as_ptr(), unsafe { strlen(c"./".as_ptr()) }) }) != 0) && ((unsafe { strncmp(filename, c"../".as_ptr(), unsafe { strlen(c"../".as_ptr()) }) }) != 0)) && (((*filename.offset(0)) as i32) != 47)) as i32) != 0;
}

unsafe extern "C" fn include_path_glob(mut nft: *mut nft_ctx, mut scanner: *mut core::ffi::c_void, mut include_path: *const core::ffi::c_char, mut filename: *const core::ffi::c_char, mut loc: *const location) -> i32 {
    let mut state: *mut parser_state = (unsafe { nft_get_extra(scanner) } as *mut parser_state);
    let mut erec: *mut error_record = core::ptr::null_mut();
    let mut buf: [core::ffi::c_char; 4096] = [0; 4096];
    let mut ret: i32 = 0;
    ret = unsafe { snprintf((buf.as_mut_ptr() as *mut core::ffi::c_char), core::mem::size_of::<[core::ffi::c_char; 4096]>(), c"%s/%s".as_ptr(), include_path, filename) };
    if (ret < 0) || (ret >= 4096) {
        erec = unsafe { erec_create(2, loc, c"Too long file path \"%s/%s\"\n".as_ptr(), include_path, filename) };
        unsafe { erec_queue(erec, (*state).msgs) };
        return -1;
    }
    ret = unsafe { include_glob(nft, scanner, (buf.as_mut_ptr() as *const core::ffi::c_char), loc) };
    /* error was already handled */
    if ret == -1 {
        return -1;
    }
    /* no wildcards and file was processed: break early. */
    if ret == 0 {
        return 0;
    }
    /* else 1 (no wildcards) or 2 (wildcards): keep
    	 * searching.
    	 */
    return ret;
}

unsafe extern "C" fn input_descriptor_destroy(mut indesc: *const input_descriptor) {
    if !(*indesc).name.is_null() {
        unsafe { free(((*indesc).name as *mut core::ffi::c_void)) };
    }
    unsafe { free((indesc as *mut core::ffi::c_void)) };
}

unsafe extern "C" fn input_descriptor_list_destroy(mut state: *mut parser_state) {
    let mut indesc: *mut input_descriptor = core::ptr::null_mut();
    let mut next: *mut input_descriptor = core::ptr::null_mut();
    {
        // C (statement): indesc = list_entry ( ( & state -> indesc_list ) -> next , typeof ( * indesc ) , list ) , next = list_entry ( indesc -> list . next , typeof ( * indesc ) , list ) ;
        todo!();
        while &raw mut (*indesc).list != &raw mut (*state).indesc_list {
            if !(*indesc).f.is_null() {
                unsafe { fclose((*indesc).f) };
                (*indesc).f = core::ptr::null_mut();
            }
            unsafe { list_del(&raw mut (*indesc).list) };
            unsafe { input_descriptor_destroy((indesc as *const input_descriptor)) };
            // C (for step): indesc = next , next = list_entry ( next -> list . next , typeof ( * next ) , list )
            todo!();
        }
    }
}

