#[unsafe(no_mangle)]
pub unsafe extern "C" fn log_level(mut level: u32) -> *const core::ffi::c_char {
    if level > (NFT_LOGLEVEL_MAX as u32) {
        return c"unknown".as_ptr();
    }
    return syslog_level[level as usize];
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn log_level_parse(mut level: *const core::ffi::c_char) -> i32 {
    let mut i: i32 = 0;
    {
        i = 0;
        while i <= NFT_LOGLEVEL_MAX {
            if !syslog_level[i as usize].is_null() && !(unsafe { strcmp(level, syslog_level[i as usize]) } != 0) {
                return i;
            }
            i += 1;
        }
    }
    return -1;
}

