#[unsafe(no_mangle)]
pub unsafe extern "C" fn get_rate(mut byte_rate: u64, mut rate: *mut u64) -> *const core::ffi::c_char {
    let mut i: i32 = 0;
    if !(byte_rate != 0) {
        (*rate) = 0u64;
        return data_unit[0];
    }
    {
        i = 0;
        'b0: while !data_unit[(i + 1) as usize].is_null() {
            if (byte_rate % (1024 as u64)) != 0 {
                break 'b0;
            }
            byte_rate /= ((1024) as u64);
            i += 1;
        }
    }
    (*rate) = byte_rate;
    return data_unit[i as usize];
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn get_unit(mut u: u64) -> *const core::ffi::c_char {
    match u {
        1 => {
            return c"second".as_ptr();
        }
        60 => {
            return c"minute".as_ptr();
        }
        3600 => {
            return c"hour".as_ptr();
        }
        86400 => {
            return c"day".as_ptr();
        }
        604800 => {
            return c"week".as_ptr();
        }
        _ => {}
    }
    return c"error".as_ptr();
}

