unsafe extern "C" fn log_stmt_print(mut stmt: *const stmt, mut octx: *mut output_ctx) {
    unsafe { nft_print(octx, c"log".as_ptr()) };
    if ((*stmt).anon4.log.flags & (STMT_LOG_PREFIX as u32)) != 0 {
        unsafe { nft_print(octx, c" prefix \"%s\"".as_ptr(), (*stmt).anon4.log.prefix) };
    }
    if ((*stmt).anon4.log.flags & (STMT_LOG_GROUP as u32)) != 0 {
        unsafe { nft_print(octx, c" group %u".as_ptr(), ((*stmt).anon4.log.group as i32)) };
    }
    if ((*stmt).anon4.log.flags & (STMT_LOG_SNAPLEN as u32)) != 0 {
        unsafe { nft_print(octx, c" snaplen %u".as_ptr(), (*stmt).anon4.log.snaplen) };
    }
    if ((*stmt).anon4.log.flags & (STMT_LOG_QTHRESHOLD as u32)) != 0 {
        unsafe { nft_print(octx, c" queue-threshold %u".as_ptr(), ((*stmt).anon4.log.qthreshold as i32)) };
    }
    if (((*stmt).anon4.log.flags & (STMT_LOG_LEVEL as u32)) != 0) && ((*stmt).anon4.log.level != (LOG_WARNING as u32)) {
        unsafe { nft_print(octx, c" level %s".as_ptr(), unsafe { log_level((*stmt).anon4.log.level) }) };
    }
    if ((*stmt).anon4.log.logflags & (NF_LOG_MASK as u32)) == (NF_LOG_MASK as u32) {
        unsafe { nft_print(octx, c" flags all".as_ptr()) };
    } else {
        if ((*stmt).anon4.log.logflags & (3 as u32)) != 0 {
            let mut delim: *const core::ffi::c_char = c" ".as_ptr();
            unsafe { nft_print(octx, c" flags tcp".as_ptr()) };
            if ((*stmt).anon4.log.logflags & (NF_LOG_TCPSEQ as u32)) != 0 {
                unsafe { nft_print(octx, c" sequence".as_ptr()) };
                delim = c",".as_ptr();
            }
            if ((*stmt).anon4.log.logflags & (NF_LOG_TCPOPT as u32)) != 0 {
                unsafe { nft_print(octx, c"%soptions".as_ptr(), delim) };
            }
        }
        if ((*stmt).anon4.log.logflags & (NF_LOG_IPOPT as u32)) != 0 {
            unsafe { nft_print(octx, c" flags ip options".as_ptr()) };
        }
        if ((*stmt).anon4.log.logflags & (NF_LOG_UID as u32)) != 0 {
            unsafe { nft_print(octx, c" flags skuid".as_ptr()) };
        }
        if ((*stmt).anon4.log.logflags & (NF_LOG_MACDECODE as u32)) != 0 {
            unsafe { nft_print(octx, c" flags ether".as_ptr()) };
        }
    }
}

