unsafe extern "C" fn limit_stmt_print(mut stmt: *const stmt, mut octx: *mut output_ctx) {
    let mut inv: bool = ((*stmt).anon4.limit.flags & (NFT_LIMIT_F_INV as u32)) != 0;
    let mut data_unit_: *const core::ffi::c_char = core::ptr::null();
    let mut rate: u64 = 0;
    match (*stmt).anon4.limit.type_ {
        NFT_LIMIT_PKTS => {
            unsafe { nft_print(octx, c"limit rate %s%lu/%s".as_ptr(), (if inv { c"over ".as_ptr() } else { c"".as_ptr() }), (*stmt).anon4.limit.rate, unsafe { get_unit((*stmt).anon4.limit.unit) }) };
            unsafe { nft_print(octx, c" burst %u packets".as_ptr(), (*stmt).anon4.limit.burst) };
        }
        NFT_LIMIT_PKT_BYTES => {
            data_unit_ = unsafe { get_rate((*stmt).anon4.limit.rate, &raw mut rate) };
            unsafe { nft_print(octx, c"limit rate %s%lu %s/%s".as_ptr(), (if inv { c"over ".as_ptr() } else { c"".as_ptr() }), rate, data_unit_, unsafe { get_unit((*stmt).anon4.limit.unit) }) };
            if (*stmt).anon4.limit.burst != (0 as u32) {
                let mut burst: u64 = 0;
                data_unit_ = unsafe { get_rate((*stmt).anon4.limit.burst as u64, &raw mut burst) };
                unsafe { nft_print(octx, c" burst %lu %s".as_ptr(), burst, data_unit_) };
            }
        }
        _ => {}
    }
}

