unsafe extern "C" fn reject_stmt_print(mut stmt: *const stmt, mut octx: *mut output_ctx) {
    unsafe { nft_print(octx, c"reject".as_ptr()) };
    'b0: {
        match (*stmt).anon4.reject.type_() {
            NFT_REJECT_TCP_RST => {
                unsafe { nft_print(octx, c" with tcp reset".as_ptr()) };
            }
            NFT_REJECT_ICMPX_UNREACH => {
                if ((*stmt).anon4.reject.icmp_code as i32) == NFT_REJECT_ICMPX_PORT_UNREACH {
                    break 'b0;
                }
                unsafe { nft_print(octx, c" with icmpx ".as_ptr()) };
                unsafe { expr_print(((*stmt).anon4.reject.expr as *const expr), octx) };
            }
            NFT_REJECT_ICMP_UNREACH => {
                'b1: {
                    match (*stmt).anon4.reject.family {
                        NFPROTO_IPV4 => {
                            if !((*stmt).anon4.reject.verbose_print() != 0) && (((*stmt).anon4.reject.icmp_code as i32) == ICMP_PORT_UNREACH) {
                                break 'b1;
                            }
                            unsafe { nft_print(octx, c" with icmp ".as_ptr()) };
                            unsafe { expr_print(((*stmt).anon4.reject.expr as *const expr), octx) };
                        }
                        NFPROTO_IPV6 => {
                            if !((*stmt).anon4.reject.verbose_print() != 0) && (((*stmt).anon4.reject.icmp_code as i32) == ICMP6_DST_UNREACH_NOPORT) {
                                break 'b1;
                            }
                            unsafe { nft_print(octx, c" with icmpv6 ".as_ptr()) };
                            unsafe { expr_print(((*stmt).anon4.reject.expr as *const expr), octx) };
                        }
                        _ => {}
                    }
                }
            }
            _ => {}
        }
    }
}

