unsafe extern "C" fn nat_stmt_print(mut stmt: *const stmt, mut octx: *mut output_ctx) {
    unsafe { nft_print(octx, c"%s".as_ptr(), unsafe { nat_etype2str((*stmt).anon4.nat.type_) }) };
    if !(*stmt).anon4.nat.addr.is_null() || !(*stmt).anon4.nat.proto.is_null() {
        match ((*stmt).anon4.nat.family as i32) {
            NFPROTO_IPV4 => {
                unsafe { nft_print(octx, c" ip".as_ptr()) };
            }
            NFPROTO_IPV6 => {
                unsafe { nft_print(octx, c" ip6".as_ptr()) };
            }
            _ => {}
        }
        if ((*stmt).anon4.nat.type_flags & (STMT_NAT_F_PREFIX as u32)) != 0 {
            unsafe { nft_print(octx, c" prefix".as_ptr()) };
        }
        unsafe { nft_print(octx, c" to".as_ptr()) };
    }
    if !(*stmt).anon4.nat.addr.is_null() {
        unsafe { nft_print(octx, c" ".as_ptr()) };
        if !(*stmt).anon4.nat.proto.is_null() {
            if ((*(*stmt).anon4.nat.addr).etype() == EXPR_VALUE) && ((*(*(*stmt).anon4.nat.addr).dtype).type_ == (TYPE_IP6ADDR as u32)) {
                unsafe { nft_print(octx, c"[".as_ptr()) };
                unsafe { expr_print(((*stmt).anon4.nat.addr as *const expr), octx) };
                unsafe { nft_print(octx, c"]".as_ptr()) };
            } else if ((*(*stmt).anon4.nat.addr).etype() == EXPR_RANGE) && ((*(*(*(*stmt).anon4.nat.addr).anon9.anon12.left).dtype).type_ == (TYPE_IP6ADDR as u32)) {
                unsafe { nft_print(octx, c"[".as_ptr()) };
                unsafe { expr_print(((*(*stmt).anon4.nat.addr).anon9.anon12.left as *const expr), octx) };
                unsafe { nft_print(octx, c"]-[".as_ptr()) };
                unsafe { expr_print(((*(*stmt).anon4.nat.addr).anon9.anon12.right as *const expr), octx) };
                unsafe { nft_print(octx, c"]".as_ptr()) };
            } else {
                unsafe { expr_print(((*stmt).anon4.nat.addr as *const expr), octx) };
            }
        } else {
            unsafe { expr_print(((*stmt).anon4.nat.addr as *const expr), octx) };
        }
    }
    if !(*stmt).anon4.nat.proto.is_null() {
        if !!(*stmt).anon4.nat.addr.is_null() {
            unsafe { nft_print(octx, c" ".as_ptr()) };
        }
        unsafe { nft_print(octx, c":".as_ptr()) };
        unsafe { expr_print(((*stmt).anon4.nat.proto as *const expr), octx) };
    }
    unsafe { print_nf_nat_flags((*stmt).anon4.nat.flags, octx) };
}

