unsafe extern "C" fn tproxy_stmt_print(mut stmt: *const stmt, mut octx: *mut output_ctx) {
    unsafe { nft_print(octx, c"tproxy".as_ptr()) };
    if (((*stmt).anon4.tproxy.table_family as i32) == NFPROTO_INET) && (((*stmt).anon4.tproxy.family as i32) != NFPROTO_UNSPEC) {
        unsafe { nft_print(octx, c" %s".as_ptr(), unsafe { nfproto_family_name((*stmt).anon4.tproxy.family) }) };
    }
    unsafe { nft_print(octx, c" to".as_ptr()) };
    if !(*stmt).anon4.tproxy.addr.is_null() {
        unsafe { nft_print(octx, c" ".as_ptr()) };
        if ((*(*stmt).anon4.tproxy.addr).etype() == EXPR_VALUE) && ((*(*(*stmt).anon4.tproxy.addr).dtype).type_ == (TYPE_IP6ADDR as u32)) {
            unsafe { nft_print(octx, c"[".as_ptr()) };
            unsafe { expr_print(((*stmt).anon4.tproxy.addr as *const expr), octx) };
            unsafe { nft_print(octx, c"]".as_ptr()) };
        } else {
            unsafe { expr_print(((*stmt).anon4.tproxy.addr as *const expr), octx) };
        }
    }
    if !(*stmt).anon4.tproxy.port.is_null() {
        if !!(*stmt).anon4.tproxy.addr.is_null() {
            unsafe { nft_print(octx, c" ".as_ptr()) };
        }
        unsafe { nft_print(octx, c":".as_ptr()) };
        unsafe { expr_print(((*stmt).anon4.tproxy.port as *const expr), octx) };
    }
}

